window.NHZ_YUWEN ={"grammar":{"categories":[{"id":"cilei","items":[{"name":"名词","例子":["老师、北京（人物/处所）","春天、昨天（时间）","上面、中间（方位）","我的书包、小明的生日","三本书、两个人（名词前能加数量词）","花开了、春天来了（名词能作主语）","妈妈在厨房做饭。","小狗在院子里跑来跑去。","秋天，树叶黄了。","书包里装着课本和文具。","桌子上面放着一杯水。","孩子们在操场上踢足球。"],"口诀":"人事物时地，名词要牢记","易错":"方位词常被误认为副词","讲解":"表示人、事物、时间、处所、方位等的词","深讲":"名词是给人、事物、时间、处所、方位起的名字。分五小类：人物（老师、妈妈）、事物（书包、苹果）、时间（春天、昨天）、处所（北京、学校）、方位（上面、中间）。名词一般能做主语和宾语，前面常能加数量词，如“三本书”“两个人”。","分类":[{"类":"人物名词","说明":"给人起的名字。","代表":"老师、妈妈、小明、爷爷","例子":["小明在教室里看书。"]},{"类":"事物名词","说明":"给具体东西起的名字。","代表":"书包、苹果、桌子","例子":["书包放在桌子上。"]},{"类":"时间名词","说明":"表示时间的词。","代表":"春天、昨天、早上","例子":["春天，花开了。"]},{"类":"处所名词","说明":"表示地方的词。","代表":"学校、北京、家里","例子":["我们在学校上课。"]},{"类":"方位名词","说明":"表示上下、前后、里外的词。","代表":"上面、中间、里、外","例子":["书在桌子上面。"]}],"怎么认":["前面能不能加数量词？能加“三本、两个”的，多半是名词。","能不能回答“谁/什么”？能回答“谁来了、什么掉了”的，多半是名词。","前面能不能加“很”？名词一般不能说“很书包、很北京”。"],"辨析":"名词和代词都指人或事物，但代词是“替身”：他、这、那不指具体名字，换了场合指的东西就变了；名词是固定名字，换场合还是它。方位词是名词里的一小类，只表示方向和位置。","例句解析":[{"句":"小明在北京看书。","析":"“北京”是处所名词，说明看书的地方；“书”是事物名词，是“看”的对象。"},{"句":"春天来了，花开了。","析":"“春天”是时间名词，作主语，说明什么时候；“花”是事物名词。"}],"练习":[{"q":"下面哪个词是名词？","options":["跑步","桌子","很快","在"],"answer":1,"解析":"“桌子”是事物名词；“跑步”是动词，“很快”是副词加形容词，“在”是介词。","类":"事物名词"},{"q":"“昨天”是什么词？","options":["动词","时间名词","副词","形容词"],"answer":1,"解析":"“昨天”表示时间，是时间名词。","类":"时间名词"},{"q":"“书在上面”中，“上面”是？","options":["副词","方位名词","动词","连词"],"answer":1,"解析":"“上面”是方位词，属于名词，不要因为它在句末就当成副词。","类":"方位名词"}],"类比":"名词的符号是一座<b>黑色小山</b>▲，稳稳地立在那里——就像万物的名字，稳定、实在。你能摸到、看到、想到的东西，都有名字：桌子、北京、勇气、昨天。","subtitle":"万物的名字「黑三角」","变式表":{"不变":"表示人、事物、时间、处所、方位等的名称","可变":{"小类":["人物名词（老师/妈妈）","事物名词（桌子/书）","时间名词（春天/昨天）","处所名词（北京/学校）","方位词（上面/中间）"],"句中位置":["作主语（老师来了）","作宾语（买书）","作定语（北京人）"]},"边界":"方位词易误判为副词；时间名词、处所名词可以直接作状语（明天见、我们北京见），一般名词作状语要借助介词（在桌子上写）","覆盖已确认":["小类","句中位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"动词","例子":["跑、吃（动作）","喜欢、害怕（心理）","有、在（存在）","我每天跑步上学","会游泳、能跑步（能愿动词）","跑着、吃了、去过（动词后能加着、了、过）","我每天跑步锻炼身体。","小鸟在枝头唱歌。","他认真地思考问题。","妈妈正在洗衣服。","我们明天去公园春游。","同学们热烈地讨论起来。"],"口诀":"动作心理变化，动词来表达","易错":"“是”有时是动词（判断），有时是副词（强调）","讲解":"表示动作、行为、心理活动、存在变化的词","深讲":"动词表示动作、行为、心理活动和存在变化。分动作（跑、吃）、心理（喜欢、害怕）、存在（有、在）、能愿（会、能、要）、趋向（来、去、上、下）。动词一般能作谓语，常常能带宾语，动作动词后面常能加“着、了、过”。","分类":[{"类":"动作动词","说明":"表示具体动作。","代表":"跑、跳、写、吃","例子":["小明在操场上跑步。"]},{"类":"心理动词","说明":"表示心里想、感觉。","代表":"喜欢、害怕、想、爱","例子":["我喜欢画画。"]},{"类":"存在动词","说明":"表示有、在。","代表":"有、在","例子":["教室里有许多书。"]},{"类":"能愿动词","说明":"表示愿意、能够、应该。","代表":"会、能、要、应该","例子":["我会写自己的名字。"]},{"类":"趋向动词","说明":"表示动作的方向。","代表":"来、去、上、下、进、出","例子":["妈妈走进教室。"]}],"怎么认":["能不能带宾语？“吃什么、看什么”能接上宾语的，多半是动词。","后面能不能加“着、了、过”？“跑着、吃了、去过”都通顺的，多半是动词。","前面能不能加“很”？动作动词一般不能说“很跑、很吃”（喜欢这类心理动词是例外）。"],"辨析":"动词和形容词都常作谓语，但动词讲“做什么”，形容词讲“怎么样”；“他跑得快”里“跑”是动词，“快”是形容词，讲跑的样子。动词和副词也别混：副词是修饰动词的“小跟班”，自己不当谓语中心。","例句解析":[{"句":"小狗在草地上跑。","析":"“跑”是动作动词，作谓语；“在草地上”是地点，说明跑的地方。"},{"句":"我喜欢踢足球。","析":"“喜欢”是心理动词，作谓语；“踢足球”是它带的宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个词是动词？","options":["美丽","跳绳","很","的"],"answer":1,"解析":"“跳绳”是动作动词；“美丽”是形容词，“很”是副词，“的”是助词。","类":"动作动词"},{"q":"“害怕”属于哪类动词？","options":["动作动词","心理动词","形容词","副词"],"answer":1,"解析":"“害怕”表示心理活动，是心理动词。","类":"心理动词"},{"q":"“他跑得很快”中，“跑”是？","options":["形容词","副词","动词","名词"],"answer":2,"解析":"“跑”讲做什么，是动词；“快”讲跑的样子，是形容词。","类":"动作动词"}],"类比":"动词的符号是一颗<b>大红太阳</b>●，散发能量——句子没有动词就像汽车没有发动机，跑不起来。跑、吃、喜欢、是，都是动作或状态。","subtitle":"动作的发动机「大红圆」","变式表":{"不变":"表示动作、行为、心理活动、存在、变化","可变":{"小类":["行为动词（跑/吃）","心理动词（喜欢/想）","判断动词（是）","能愿动词（会/能/要）","趋向动词（来/去/上）"],"及物性":["及物（吃+饭）","不及物（跑/睡）"]},"边界":"心理动词不能用于把字句（✗我把他喜欢）；能愿动词后必须接动词（✗我会书）","覆盖已确认":["小类","及物性"],"覆盖缺失":[]},"前置知识":[]},{"name":"形容词","例子":["红、方、大、圆（性质形容词，能说“很红”“很圆”）","雪白、暖洋洋（状态形容词，不说“很雪白”）","善良、勇敢（性质）","今天的太阳暖洋洋的","很红、非常勇敢（形容词前能加很）","花很红（形容词能作谓语）","这朵花真美丽。","湖水清澈见底。","他跑得很快。","夜晚的星空格外明亮。","她的声音很甜美。","这个问题比较复杂。","他很高。（'很'修饰性质形容词'高'）","雪白的床单✗很雪白。（状态形容词一般不受'很'修饰）"],"口诀":"能加“很”的是性质，带着程度的是状态","易错":"副词“很”+形容词是常见搭配，别把“很”当形容词","讲解":"表示人或事物的形状、性质、状态的词","深讲":"形容词表示人或事物的形状、性质和状态，按语法特点分两类：性质形容词（善良、勇敢、大、圆）能受“很、不”修饰；状态形容词（雪白、暖洋洋、整整齐齐）本身带着程度，一般不再受“很”修饰。表示形状的“方、圆、大、小”也是性质形容词。形容词后面一般不能直接带宾语；作定语时常带“的”，作谓语时直接说明主语怎么样，作补语时说明动作的结果或样子。","分类":[{"类":"性质形容词","说明":"表示人或事物的性质（也包括形状、大小），大多能受“很”“不”修饰。","代表":"善良、勇敢、大、圆","例子":["她是一个勇敢的孩子。","桌子是方的。"]},{"类":"状态形容词","说明":"表示事物的样子，本身带着程度，常是叠音或重叠的形式，一般不受“很”修饰。","代表":"雪白、暖洋洋、亮晶晶","例子":["雪白的墙，真好看。"]}],"怎么认":["前面能不能加“很”？“很红、很勇敢”通顺的，多半是性质形容词。","后面能不能直接带宾语？形容词一般不能：不说“红了苹果”“美丽花园”当动宾讲。","能不能回答“怎么样”？能回答主语“怎么样”的，多半是形容词；“雪白、亮晶晶”不加“很”也能回答，是状态形容词。"],"辨析":"形容词和副词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。状态形容词如“雪白、暖洋洋”一般不受“很”修饰，不能说“很雪白”。","例句解析":[{"句":"今天的太阳暖洋洋的。","析":"“暖洋洋”是状态形容词，作谓语，说明太阳的样子。"},{"句":"雪白的墙真干净。","析":"“雪白”是形容词，作定语，修饰“墙”；“干净”也是形容词，作谓语。"}],"练习":[{"q":"下面哪个词是形容词？","options":["跑","美丽","在","把"],"answer":1,"解析":"“美丽”表示性质，是形容词；“跑”是动词，“在”是介词，“把”是介词。","类":"性质形容词"},{"q":"“雪白的墙”中，“雪白”是？","options":["名词","动词","形容词","副词"],"answer":2,"解析":"“雪白”表示墙的样子，作定语，是形容词。","类":"状态形容词"},{"q":"“很”是什么词？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“很”修饰形容词和动词，自己是副词，别把跟班当主角。","类":"综合"}],"subtitle":"名词的化妆师「蓝三角」","类比":"形容词的符号是一座<b>蓝色小山</b>▲，紧挨着名词的黑三角——它是名词的化妆师，专门描述样子：红的花、善良的人、雪白的墙。","变式表":{"不变":"表示人或事物的性质、状态、形状","可变":{"小类":["性质形容词（大/红/好）","状态形容词（雪白/冰凉/笔直）"],"程度修饰":["可受'很/非常'修饰（很大）","一般不受程度修饰（雪白✗很雪白）"]},"边界":"状态形容词（ABB式）一般不受'很'修饰；形容词作状语通常要加'地'（高兴地说）","覆盖已确认":["小类"],"覆盖缺失":["程度修饰"]},"前置知识":[]},{"name":"数词","例子":["一、两、百","第一、初三","我们班有45个同学","一、二、三（基数）","第一、第二（序数）","几、几十、上百（概数）","三个苹果、第一名","两个人、两本书（量词前用两）","二月、第二名（读数和序数用二）","一年有四个季节。","我们班有三十名同学。","他得了第一名。"],"口诀":"数目次序，数词管住","易错":"“两”和“二”用法不同：序数用“二”，量词前多用“两”","讲解":"表示数目和次序的词","深讲":"数词表示数目和次序。分基数（一、二、三……）、序数（第一、第二……）和概数（几、十几、几十、上百、三五）。数词常常和量词一起用，组成数量短语，如“三个苹果”“第一名”。数词本身不指具体东西，要和量词、名词搭在一起才完整。","分类":[{"类":"基数词","说明":"表示数目多少。","代表":"一、二、三、十","例子":["桌上有三个苹果。"]},{"类":"序数词","说明":"表示第几个。","代表":"第一、第二、第三","例子":["他得了第一名。"]},{"类":"概数词","说明":"表示大概的数目。注意：「约、大约」是副词，「许多」不是数词。","代表":"几、十几、几十、上百、三五","例子":["篮子里有十来个苹果。"]}],"怎么认":["是不是表示“几个、第几个”？是的，多半是数词。","后面能不能跟量词？“三只、五本、第一”后面常跟量词或名词。","“二”和“两”要分场合：读数、序数用“二”（二月、第二），量词前面多用“两”（两个人、两本书）。"],"辨析":"数词和量词是一对搭档：数词管“多少”，量词管“用什么单位量”。“三”单独不能说“三书”，要说“三本书”；“只”单独也不能表数，要说“三只”。","例句解析":[{"句":"教室里有三只小猫。","析":"“三”是数词，“只”是量词，“三只”合起来修饰“小猫”，说明数量。"},{"句":"他在比赛中得了第一名。","析":"“第一”是序数词，表示次序，不是数量；“名”是量词。"}],"练习":[{"q":"下面哪个词是数词？","options":["只","三","本","个"],"answer":1,"解析":"“三”表示数目，是数词；“只、本、个”都是量词。","类":"基数词"},{"q":"“两个人”中，为什么不用“二”？","options":["量词前多用“两”","读数用“两”","序数用“两”","都可以"],"answer":0,"解析":"量词前面多用“两”，如两个人、两本书；读数和序数才用“二”。","类":"基数词"},{"q":"“第二名”中，“第二”是？","options":["基数","序数","量词","概数"],"answer":1,"解析":"“第二”表示次序，是序数词。","类":"序数词"}],"类比":"数词是词里的<b>会计</b>，专门管数量：一、二、三、第一、百、千。数一数多少，都靠它。","变式表":{"不变":"表示数目","可变":{"类型":["基数词（一/二/十）","序数词（第一/初一）","概数（几/多/左右）","分数/倍数/百分数"],"组合":["单独（三个）","与量词组合（三本书）"]},"边界":"'两'和'二'分工：读数用二（二十），量词前用两（两个人）；'一'在去声前读阳平是变调不是变词","覆盖已确认":["类型","组合"],"覆盖缺失":[]},"前置知识":[]},{"name":"量词","例子":["个、只、条","米、公斤、次","一本书、三只小猫","个、只、条、本（名量词）","次、遍、回（动量词）","三个苹果、这本书","看三遍、跑两趟","一条鱼、一座山","一本鱼（错：量词搭配不对）","一双筷子","一群孩子在公园玩耍。","一阵风吹过，树叶沙沙响。"],"口诀":"名量（个只条）+动量（次回遍）","易错":"量词重叠表“每一”，如“个个”","讲解":"表示计量单位的词","深讲":"量词表示计量单位，分名量词和动量词。名量词量人或事物（个、只、条、本、张、座），动量词量动作的次数（次、遍、回、趟）。量词前面常有数词或指示代词（这、那），后面跟名词或动词，如“这本书”“看三遍”。","分类":[{"类":"名量词","说明":"量人或事物，后面跟名词。","代表":"个、只、条、本、张、座","例子":["一座桥横在河上。"]},{"类":"动量词","说明":"量动作的次数，后面跟动词。","代表":"次、遍、回、趟","例子":["这篇课文我读了三遍。"]}],"怎么认":["是不是跟在数词或“这、那”后面量东西？“三个、这本”里的“个、本”就是量词。","量的是人或物，还是动作次数？量人或物的是名量词，量次数的是动量词。","换一个量词试试：说“一条鱼”通顺，“一本鱼”就不通顺，量词和名词要搭配。"],"辨析":"量词和名词别混：名词是东西的名字，量词是量的单位。“书”是名词，“本”是量词。量词也不能单独表数，“本”不说“有几本”，要说“有几本书”。","例句解析":[{"句":"桌上有一条鱼。","析":"“条”是名量词，和鱼搭配；换成“本”就不通顺，说明量词要和名词配对。"},{"句":"这篇课文我读了三遍。","析":"“遍”是动量词，量动作“读”的次数，不是量课文本身。"}],"练习":[{"q":"“一座桥”中，量词是？","options":["一","座","桥","的"],"answer":1,"解析":"“座”是量词，量桥；“一”是数词，“桥”是名词。","类":"名量词"},{"q":"下面哪个是动量词？","options":["只","本","遍","条"],"answer":2,"解析":"“遍”量动作的次数，是动量词；其余都是名量词。","类":"动量词"},{"q":"下面哪组搭配不对？","options":["一条鱼","一本书","一座山","一本鱼"],"answer":3,"解析":"鱼用“条”不用“本”，量词要和名词搭配。","类":"名量词"}],"类比":"量词像给名词配的<b>量杯</b>：一<b>本</b>书、三<b>个</b>人、一<b>头</b>牛。没有量杯，数字就端不起来。","变式表":{"不变":"表示计量单位，与数词组合","可变":{"类型":["名量词（个/只/条/张）","动量词（次/遍/趟）","复合量词（人次）"],"搭配":["通用（个）","专用（头牛/匹马/艘船）"]},"边界":"量词不能单独作主宾语（✗个来了）；'一下'是动量词不是时间副词","覆盖已确认":["类型","搭配"],"覆盖缺失":[]},"前置知识":["数词"]},{"name":"代词","例子":["我、你、他（人称）","这、那（指示）","谁、怎么（疑问）","这是我的铅笔，那是你的","这、那、这里（指示）","谁、什么、哪里（疑问）","小明来了，他也来了","这是什么、那是谁","我们、你们、他们","这是谁的书包？","他们明天要去爬山。","大家安静一下，听老师讲。","你这么做不对。（'这么'=这样做，代词代替动词短语）","他长得那么高。（'那么'=那么高，代词代替形容词）"],"口诀":"人称指示疑问，代词三剑客","易错":"“这”“那”+量词+名词是代词性用法","讲解":"代替名词、动词、形容词等的词","深讲":"代词是代替名词、动词、形容词等实词的词，分人称（我、你、他、我们）、指示（这、那、这里、那里）、疑问（谁、什么、哪里、怎么）。代词的好处是不用重复名字：说过“小明”后，后面用“他”代替，句子就简洁了。","分类":[{"类":"人称代词","说明":"代替人的词。","代表":"我、你、他、我们、你们、他们","例子":["小明来了，他也来了。"]},{"类":"指示代词","说明":"指东西、地方的词。","代表":"这、那、这里、那里","例子":["这是我的铅笔，那是你的。"]},{"类":"疑问代词","说明":"用来提问的词。","代表":"谁、什么、哪里、怎么","例子":["这是什么？"]}],"怎么认":["是不是在代替前面出现过的人或事物？是的，多半是代词。","换一个具体名字试试：把“他”换成“小明”，句子意思不变，说明“他”是代词。","是不是在提问？“谁、什么、哪里”提问的，多半是疑问代词。"],"辨析":"代词和名词都能指人指物，但名词是固定名字，代词是“替身”，离开上下文就不知道指谁。“他”在不同句子里可以是小明，也可以是小刚；“小明”永远是小明。","例句解析":[{"句":"小明来了，他手里拿着一本书。","析":"第二个分句的“他”代替前面的“小明”，避免重复。"},{"句":"这是什么？","析":"“这”是指示代词，指眼前这个东西；“什么”是疑问代词，用来提问。"}],"练习":[{"q":"下面哪个词是代词？","options":["桌子","他们","跑步","美丽"],"answer":1,"解析":"“他们”是人称代词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。","类":"人称代词"},{"q":"“谁来了？”中，“谁”是？","options":["名词","疑问代词","动词","副词"],"answer":1,"解析":"“谁”用来提问，是疑问代词。","类":"疑问代词"},{"q":"“他”在不同句子里指的人一样吗？","options":["一样","不一定，要看上下文","永远是小明","不能指人"],"answer":1,"解析":"代词是替身，指谁要看上下文，不能只看词本身。","类":"人称代词"}],"subtitle":"名词的替身「紫三角」","类比":"代词的符号是一座<b>紫色小山</b>▲，和名词的黑三角是亲戚——它是名词的替身演员：我、你、他、这、那、谁，不用每次都喊全名。","变式表":{"不变":"代替名词、动词、形容词、数量词的词","可变":{"小类":["人称代词（我/你/他）","指示代词（这/那）","疑问代词（谁/什么/怎么）"],"所替":["替名词（他=小明）","替动词（这么=这样做）","替形容词（那么=那么高）"]},"边界":"'这/那'作定语是代词（这本书），单独成句是指示；'怎么'问方式，'为什么'问原因，不混","覆盖已确认":["小类"],"覆盖缺失":["所替"]},"前置知识":["名词"]},{"name":"副词","例子":["很、非常（程度）","都、只（范围）","已经、正在（时间）","他跑得非常快","常常、总是（频率）","不、没（否定）","也许、大概（语气）","他非常喜欢读书。","我们都去过北京。","小明也参加了比赛。","天渐渐黑了下来。","妈妈已经做好了晚饭。","他已经走了。（'已经'在动词'走'前面）","这件衣服很好看。（'很'在形容词'好看'前面）"],"口诀":"程度范围时间，副词来限制","易错":"副词一般不能单独做谓语","讲解":"修饰动词、形容词，表示程度、范围、时间等的词","深讲":"副词修饰动词、形容词，表示程度、范围、时间、频率、语气、否定等。分程度（很、非常）、范围（都、只）、时间（已经、正在）、频率（常常、总是）、否定（不、没）、语气（也许、大概）。副词一般放在谓语前面，不能修饰名词，前面一般不能再加“很”。","分类":[{"类":"程度副词","说明":"表示程度深浅。","代表":"很、非常、最、更","例子":["他跑得非常快。"]},{"类":"范围副词","说明":"表示范围大小。","代表":"都、只、也、全","例子":["同学们都来了。"]},{"类":"时间副词","说明":"表示动作的时间。","代表":"已经、正在、马上","例子":["火车已经到了。"]},{"类":"频率副词","说明":"表示动作常常发生。","代表":"常常、总是、有时","例子":["他常常帮妈妈做家务。"]},{"类":"否定副词","说明":"表示否定。","代表":"不、没、别","例子":["我不去，你去吧。"]},{"类":"语气副词","说明":"表示说话人的推测、语气。","代表":"也许、大概、一定","例子":["也许明天会下雨。"]}],"怎么认":["是不是站在动词或形容词前面修饰它？“已经来了、非常快”里的“已经、非常”就是副词。","能不能修饰名词？副词一般不能说“很书包、都桌子”。","删掉它试试：删掉副词，句子主干还在，只是程度、时间、范围的意思弱了。"],"辨析":"副词和形容词都和程度有关，但形容词能作谓语（“花很红”），副词不能单独作谓语，只能修饰别人。“很”本身是副词，不是形容词。","例句解析":[{"句":"他已经写完了作业。","析":"“已经”是时间副词，放在动词“写”前面，说明动作完成了。"},{"句":"同学们都来了。","析":"“都”是范围副词，说明“同学们”一个不落，全都来了。"}],"练习":[{"q":"下面哪个词是副词？","options":["桌子","已经","跑步","美丽"],"answer":1,"解析":"“已经”表示时间，是副词；“桌子”是名词，“跑步”是动词，“美丽”是形容词。","类":"时间副词"},{"q":"“非常快”中，“非常”是？","options":["形容词","副词","动词","名词"],"answer":1,"解析":"“非常”修饰形容词“快”，自己是副词。","类":"程度副词"},{"q":"副词一般不能修饰？","options":["动词","形容词","名词","谓语"],"answer":2,"解析":"副词修饰动词和形容词，一般不能修饰名词。","类":"综合"}],"subtitle":"动词的小跟班「小橙圆」","类比":"副词的符号是一颗<b>小橙圆</b>，紧挨着动词的大红圆——小圆是大圆的跟班，专门给动作加说明：怎么跑（飞快地跑）、多深（很爱）、什么时候（已经走了）。","变式表":{"不变":"修饰动词、形容词，表示程度、范围、时间、语气等","可变":{"小类":["程度副词（很/非常）","范围副词（都/只）","时间副词（已经/正在）","语气副词（难道/究竟）","否定副词（不/没）"],"位置":["动词前（已经走了）","形容词前（很好）"]},"边界":"副词不能修饰名词（✗很桌子）；'不'和'没'分工：'不'表意愿/经常，'没'表完成/客观","覆盖已确认":["小类"],"覆盖缺失":["位置"]},"前置知识":["动词","形容词"]},{"name":"介词","例子":["在、从、向（方向）","把、被（对象）","关于、对于","我在教室里写作业","在教室、从北京（处所）","给妈妈、对他（对象）","向老师请教（方向）","为班级争光（目的）","比他高（比较）","把书放在桌上（处置）","他在北京住。（'在北京'在动词'住'前面）","他住在北京。（'在北京'在动词'住'后面）"],"口诀":"在从把被关于，介词引对象","易错":"“把”字句和“被”字句是中考重点句式","讲解":"用在名词、代词前，组成介词短语，表示方向、对象等的词","深讲":"介词引出时间、处所、对象、方式、原因等，和后面的名词、代词组成介宾短语。常见介词有在、从、向、往、给、对、为、比、跟、把、被。介宾短语常常作状语（“在教室里读书”）、补语（“来自北京”）或定语（“对他的关心”），但介词自己不能单独作谓语中心。","分类":[{"类":"处所方向介词","说明":"表示地方、方向。","代表":"在、向、往、从","例子":["他在教室里读书。"]},{"类":"时间介词","说明":"表示时间。","代表":"从、自、到","例子":["我们从早上读到中午。"]},{"类":"对象介词","说明":"表示动作的对象。","代表":"对、给、为、跟","例子":["妈妈给弟弟讲故事。"]},{"类":"方式介词","说明":"表示用的办法、工具。","代表":"用、按、照","例子":["他用铅笔画画。"]}],"怎么认":["后面是不是跟了一个名词或代词？“在教室、给妈妈、对他”这种结构，多半是介词短语。","能不能单独作谓语？介词自己不能单独作谓语中心，要和后面的词组成短语。","换成动词试试还通不通？介词后面的词不能像动词那样带“着、了、过”。"],"辨析":"介词和连词最容易混，关键看换位：连词“和”连接的“苹果和香蕉”可以换成“香蕉和苹果”，意思不变；介词引出的部分换位置就变味或不通，如“他向老师请教”换成“老师向他请教”，主角就换了人。","例句解析":[{"句":"小明在教室里看书。","析":"“在教室里”是介宾短语，作状语，说明看书的地点；“在”是介词。"},{"句":"妈妈给弟弟讲故事。","析":"“给弟弟”是介宾短语，说明讲故事的对象；这里的“给”引出对象，是介词。"}],"练习":[{"q":"“在教室里”中，“在”是？","options":["动词","介词","副词","连词"],"answer":1,"解析":"“在”引出地点，和“教室里”组成介宾短语，是介词。","类":"处所方向介词"},{"q":"下面哪个是介词短语？","options":["跑得快","在学校","很美丽","三本书"],"answer":1,"解析":"“在学校”是介词加名词组成的介宾短语；其余不是。","类":"处所方向介词"},{"q":"介词一般不能？","options":["跟名词","作状语","单独作谓语中心","组成短语"],"answer":2,"解析":"介词要和后面的词组成短语，不能单独作谓语中心。","类":"综合"}],"subtitle":"方位的月亮「绿新月」","类比":"介词的符号是一弯<b>绿色新月</b>☽，总在名词前面带路：在哪里（在公园）、从哪里（从北京）、向哪里（向南）。它像路标，指引方向。","变式表":{"不变":"引出动作的对象、时间、处所、方式等，与名词组成介宾短语","可变":{"类型":["对象（把/被/对）","时间（在/从/到）","处所（在/往）","方式（用/以）","原因（为/因为）"],"位置":["动词前（在北京住）","动词后（住在北京）"]},"边界":"介词不能单独作谓语（✗我在）；'在'作动词（他在家）vs作介词（在家住）看后接什么","覆盖已确认":["类型"],"覆盖缺失":["位置"]},"前置知识":["名词","动词"]},{"name":"连词","例子":["和、跟（并列）","但是、然而（转折）","因为、所以（因果）","我喜欢画画，也喜欢唱歌","苹果和香蕉（并列）","虽然累，但是坚持（转折）","因为下雨，所以取消（因果）","如果下雨，就回家（假设）","不是苹果，而是香蕉（选择）","老师和同学（可换位）","我喜欢唱歌和跳舞。（'和'连接短语）","他唱歌，而且跳得很好。（'而且'连接分句）"],"口诀":"连接上下，关系靠它","易错":"关联词搭配要完整，如“不仅……而且”不能丢一半","讲解":"连接词、短语、句子，表示并列、转折等关系的词","深讲":"连词连接词、短语或分句，表示并列、转折、因果、假设、选择等关系。常见连词有和、及、或、但是、因为、所以、如果、虽然。连词本身没有实在意义，只起连接作用；它连接的两部分在逻辑上是并列或有关系，不是修饰关系。","分类":[{"类":"并列连词","说明":"连接平等的两部分。","代表":"和、及、以及","例子":["苹果和香蕉都很好吃。"]},{"类":"转折连词","说明":"前后意思转折。","代表":"但是、可是、然而","例子":["他累了，可是还坚持跑。"]},{"类":"因果连词","说明":"表示原因和结果。","代表":"因为、所以、因此","例子":["因为下雨，所以我们没去公园。"]},{"类":"假设连词","说明":"表示假设。","代表":"如果、假如","例子":["如果努力，就会进步。"]},{"类":"选择连词","说明":"表示二选一。","代表":"或者、还是","例子":["你喝水还是喝牛奶？"]}],"怎么认":["是不是在连接两个词、短语或句子？“苹果和香蕉、虽然累但是坚持”里的“和、虽然……但是”就是连词。","连接的两个部分能不能换位置？并列连词连接的部分换位置意思基本不变。","删掉它试试：删掉连词，两部分就散了，关系也看不出来了。"],"辨析":"连词和介词最容易混，关键看换位：连词“和”连接的“老师和同学”可以换成“同学和老师”，意思不变；介词引出的对象换位置意思就变了，如“他向老师请教”不能随便换成“老师向他请教”。","例句解析":[{"句":"老师和同学一起打扫教室。","析":"“和”是连词，连接“老师”和“同学”，两个都是打扫的人，地位平等。"},{"句":"虽然下雨，但是运动会照常进行。","析":"“虽然……但是”是一对连词，连接两个分句，表示转折关系。"}],"练习":[{"q":"下面哪个词是连词？","options":["在","和","的","很"],"answer":1,"解析":"“和”连接两个词，是连词；“在”是介词，“的”是助词，“很”是副词。","类":"并列连词"},{"q":"“苹果和香蕉”换成“香蕉和苹果”，意思？","options":["变了","基本不变","变成介词","不能换"],"answer":1,"解析":"并列连词连接的部分换位置，意思基本不变。","类":"并列连词"},{"q":"“虽然……但是”表示？","options":["因果","转折","并列","选择"],"answer":1,"解析":"“虽然……但是”表示转折关系。","类":"转折连词"}],"类比":"连词像<b>绳子</b>，把词和句子系在一起：和、跟、因为、所以。它是语言里的胶水。","变式表":{"不变":"连接词、短语、分句，表示并列、递进、转折等关系","可变":{"类型":["并列（和/跟）","递进（而且）","转折（但是）","因果（因为）","假设（如果）"],"连接对象":["连词（老师和学生）","连短语","连分句"]},"边界":"'和'连名词是连词（我和他），连动词可能是介词（和他商量）；关联词成对出现不能残缺","覆盖已确认":["类型"],"覆盖缺失":["连接对象"]},"前置知识":["名词","动词"]},{"name":"助词","例子":["的、地、得（结构助词）","了、着、过（动态助词）","吗、呢（语气助词）","妈妈做的饭真好吃","我的书、红红的苹果（的）","快地跑、认真地写（地）","跑得快、写得好（得）","吃了、看着、去过（了、着、过）","好吗、走吧（吗、吧）","的、地、得分工要记牢"],"口诀":"的定地状得后补，时态语气也清楚","易错":"“的地得”用法：“的”定语、“地”状语、“得”补语","讲解":"附着在词、短语后表示语法意义的词","深讲":"助词附着在词、短语或句子后面，起结构、动态或语气作用，本身没有实在意义。分结构助词（的、地、得）、动态助词（了、着、过）、语气助词（吗、呢、吧、啊）。助词不能单独作句子成分，要和前面的词一起看。","分类":[{"类":"结构助词","说明":"放在词后面，起连接、结构作用。","代表":"的、地、得","例子":["红红的苹果真好看。"]},{"类":"动态助词","说明":"表示动作完成、进行、经历。","代表":"了、着、过","例子":["我看过这本书。"]},{"类":"语气助词","说明":"放在句末，表语气。","代表":"吗、呢、吧、啊","例子":["你去吗？"]}],"怎么认":["是不是附在别的词后面？“我的、快地、跑得快、吃了、好吗”里的“的、地、得、了、吗”就是助词。","删掉它试试：删掉助词，句子主干还在，但结构关系或语气就不清楚了。","“的、地、得”分工：的后跟名词，地后跟动词、形容词，得后跟补充说明。"],"辨析":"助词和语气词、叹词别混：语气词是助词里的一小类，只在句末表语气；叹词是独立成句的感叹词，多在句首。助词“了”表完成或变化，“着”表持续，“过”表经历，三者不能互换。","例句解析":[{"句":"红红的苹果真好吃。","析":"“的”是结构助词，连接定语“红红”和名词“苹果”。"},{"句":"他吃过北京烤鸭。","析":"“过”是动态助词，放在动词“吃”后面，表示曾经有过的经历。"}],"练习":[{"q":"“快地跑”中，“地”是？","options":["介词","结构助词","副词","连词"],"answer":1,"解析":"“地”连接状语和动词，是结构助词。","类":"结构助词"},{"q":"“吃了饭”中，“了”表示？","options":["持续","经历","完成","疑问"],"answer":2,"解析":"动词后的“了”表示动作完成。","类":"动态助词"},{"q":"下面哪个是语气助词？","options":["的","着","吗","得"],"answer":2,"解析":"“吗”在句末表示疑问语气，是语气助词。","类":"语气助词"}],"类比":"助词像<b>小跟班</b>，附在词后面帮忙：的、地、得、了、着、过。自己没独立意思，专门辅助别人。","变式表":{"不变":"附着在词、短语后，表示结构关系或语气","可变":{"类型":["结构助词（的/地/得）","动态助词（了/着/过）","语气助词（吗/呢/吧）"],"位置":["词后（书的）","句末（好吗）"]},"边界":"的/地/得：定语用'的'，状语用'地'，补语用'得'；'了'表完成（吃了）vs语气（太好了）","覆盖已确认":["类型","位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"语气词","例子":["吗、呢、吧、啊","明天一起去打球吧！","好吗、吃饭了吗（吗）","一起去吧、走吧（吧）","你呢、他呢（呢）","真美啊、好啊（啊）","走吧是商量、走吗是提问","语气词在句末","你去过长城吗？","多美的风景啊！","我们一起去吧。","你怎么还没来呢？","是啊！","谁啊？","你好啊！","对啊！","快走啊！","多好的天啊！"],"口诀":"句尾表语气，吗呢吧啊","易错":"语气词不重读 “啊”表感叹、疑问、应答，不表平直陈述（✗“我是学生啊。”→“我是学生。”）。","讲解":"表示语气，常用在句尾的词","深讲":"语气词用在句末，表示陈述、疑问、祈使、感叹等语气。常见语气词有吗、呢、吧、啊、呀、么。语气词不表示实在意义，读起来语气不同，意思和态度就不同：说“走吧”是商量，说“走吗”是提问。\n“啊”是最活泼的语气词，有4种常用法：①感叹（多美啊！/多好的天啊！）；②疑问追问（谁啊？/你说什么啊？）；③应答认同（是啊/对啊/好啊）；④催促提醒（快点啊！/小心啊！）。注意：“啊”常跟在别的语气词后（好吧啊），读的时候按前一个字的尾音变读（呀/哇/哪）。","分类":[{"类":"陈述语气词","说明":"句末表平静陈述的语气。","代表":"了、啊","例子":["下雨了。"]},{"类":"疑问语气词","说明":"表提问。","代表":"吗、呢","例子":["你去吗？"]},{"类":"祈使语气词","说明":"表商量、希望对方做。","代表":"吧、啊","例子":["我们一起去吧。"]},{"类":"感叹语气词","说明":"表感叹。","代表":"啊、呀、哇","例子":["多美的花呀！"]}],"怎么认":["是不是在句末？句末的“吗、呢、吧、啊”多半是语气词。","换一个语气词试试：把“好吗”换成“好吧”，句子从提问变成了商量，说明语气词管的是语气。","删掉它试试：删掉语气词，句子意思还在，但语气、态度就没了。"],"辨析":"语气词和叹词都和语气有关，但语气词在句末、附着在句子上；叹词独立成句、多在句首。“啊，真美！”里的“啊”是叹词；“这花真美啊”里的“啊”是语气词。","例句解析":[{"句":"我们一起去公园吧。","析":"句末的“吧”是语气词，表示商量、建议。"},{"句":"你吃饭了吗？","析":"句末的“吗”是语气词，把陈述句变成了疑问句。"}],"练习":[{"q":"“一起去吧”中，“吧”是？","options":["动词","语气词","叹词","名词"],"answer":1,"解析":"句末的“吧”表示商量语气，是语气词。","类":"祈使语气词"},{"q":"语气词一般在？","options":["句首独立","句末","动词前","名词后"],"answer":1,"解析":"语气词用在句末，表示全句的语气。","类":"综合"},{"q":"“好吗”换成“好吧”，变的是？","options":["主语","语气","宾语","时间"],"answer":1,"解析":"换语气词，句子意思基本不变，变的是语气和态度。","类":"综合"},{"q":"“多美啊！”中“啊”表什么语气？","options":["疑问","感叹","祈使","陈述"],"answer":1,"解析":"“多美啊”是感叹：多美！","类":"感叹"},{"q":"哪句的“啊”表追问？","options":["是啊","谁啊？","快点啊","好啊"],"answer":1,"解析":"“谁啊？”是没听清、追问对方。","类":"疑问"}],"类比":"语气词像句尾的<b>表情符号</b>：吗、呢、吧、啊。同样一句话，加不同的语气词，味道完全不同。","变式表":{"不变":"附在句末，表示陈述、疑问、祈使、感叹等语气","可变":{"语气":["陈述（了/呢）","疑问（吗/呢）","祈使（吧）","感叹（啊）"],"位置":["句末（好吗）","句中停顿（我的天啊）"]},"边界":"语气词不表实在意义，去掉不影响基本句意；'呢'表疑问（你呢）vs表持续（看着呢）","覆盖已确认":["语气","位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"叹词","例子":["啊、哎、哦、喂","哎呀，我忘带作业了！","啊，真美（感叹）","喂，你好（呼唤）","嗯，知道了（应答）","哈哈，真有趣（笑声）","哎呀，疼死我了","啊在句首是叹词、在句末是语气词","哎呀，我忘带钥匙了！","嘿，加油啊！","哇，这座山真高！","哼，我才不信呢！"],"口诀":"感叹呼唤应答，叹词来表达","易错":"叹词常独立成句，后用逗号或感叹号","讲解":"表示感叹、呼唤、应答的词","深讲":"叹词表示感叹、呼唤、应答等，独立成句或独立成分，常常在句首，后面常带感叹号或逗号。常见叹词有啊、哎呀、哦、喂、嗯、哈哈。叹词不作句子的主要成分，删掉它，句子主干还在，只是感情色彩弱了。","分类":[{"类":"感叹叹词","说明":"表惊讶、高兴、心疼等感情。","代表":"啊、哎呀、哇","例子":["哎呀，太好了！"]},{"类":"呼唤叹词","说明":"表叫人、引起注意。","代表":"喂、嘿","例子":["喂，你听到了吗？"]},{"类":"应答叹词","说明":"表答应、明白。","代表":"嗯、哦、好","例子":["嗯，我知道了。"]}],"怎么认":["是不是独立在句首、后面有感叹号或逗号？“啊，真美！喂，你好！”里的“啊、喂”就是叹词。","是不是在表示感叹、呼唤或应答？是的，多半是叹词。","删掉它试试：删掉叹词，句子还能成立，只是少了那股感情劲儿。"],"辨析":"叹词和语气词最容易混：叹词独立、多在句首（“啊，真美！”）；语气词附着在句末（“真美啊！”）。同一个“啊”字，位置不同，词类就不同——这正是“看位置、看作用”的好例子。","例句解析":[{"句":"啊，祖国的山河真壮丽！","析":"句首的“啊”是叹词，独立成成分，表达赞叹，后面用逗号隔开。"},{"句":"喂，你听见了吗？","析":"“喂”是叹词，表示呼唤，引起对方注意；句末的“吗”才是语气词。"}],"练习":[{"q":"“哎呀，疼死我了！”中，“哎呀”是？","options":["语气词","叹词","副词","形容词"],"answer":1,"解析":"句首独立的“哎呀”表示感叹，是叹词。","类":"感叹叹词"},{"q":"叹词常常在？","options":["句末","句首独立","动词后","名词前"],"answer":1,"解析":"叹词独立成句或成分，常常在句首。","类":"综合"},{"q":"“真美啊”中，“啊”是？","options":["叹词","语气词","动词","介词"],"answer":1,"解析":"句末的“啊”附着在句子上表语气，是语气词，不是叹词。","类":"综合"}],"类比":"叹词像突然喊出来的<b>一声</b>：啊、哎呀、唉、哼。是情绪的直接出口，不参与句子结构。","变式表":{"不变":"表示感叹、呼唤、应答的感叹声","可变":{"情感":["喜（哈哈）","悲（哎呀）","惊（啊）","应答（嗯/喂）"],"位置":["句首独立（哎呀，迟到了）","句中（我的天啊）"]},"边界":"叹词独立成句不作其他成分；'啊'作叹词（啊，春天）vs作语气词（好啊）看位置","覆盖已确认":["情感","位置"],"覆盖缺失":[]},"前置知识":[]},{"name":"离合词","讲解":"动词和宾语合成一个词，平时合在一起像一个词，用的时候又能分开，中间可以加字。","深讲":"离合词 = 动词 + 宾语，两个字合起来表示一个动作，比如“睡觉”（睡+觉）、“见面”（见+面）。它最大的本事是“能分”：中间可以加“了/过”、数量词（一次、两小时），比如“睡了一觉”“见过面”“开了三小时会”。但它不能再带宾语：“见面他”是错的，要说“跟他见面”。","类比":"离合词像一个汉堡：两片面包（动词+宾语）夹在一起是一个汉堡，但中间能加生菜番茄（了、数量词）；只是你不能再往汉堡外面贴一块肉（不能再加宾语）。","口诀":"动宾合成词，中间能加料；再带宾语错，介词来介绍","例子":["我们见过面。","我睡了一个小时觉。","他结过两次婚。","跟朋友见面（不说“见面朋友”）","帮我一个忙（不说“帮忙我”）","生他的气。","洗了个热水澡。","他生气了（不说“生气他”）"],"易错":"“了/过”要放在中间（见过面✓，见面过✗）；后面不能直接加人或物，要加“跟/给”介绍（跟他见面✓，见面他✗）。","分类":[{"类":"加数量","说明":"中间加数量词，表示次数或时长。","代表":"见一面、睡两小时","例子":["我们见了一面。","我游了两次泳。"]},{"类":"表经历","说明":"中间加“过”，表示曾经做过。","代表":"见过面、结过婚","例子":["我们见过面。","他结过两次婚。"]},{"类":"加修饰","说明":"中间加形容词或动词，细化动作。","代表":"洗热水澡、理个发","例子":["洗了个热水澡。","我理了一次发。"]}],"怎么认":["能不能拆开加“了”？“睡了觉”说得通→是离合词；“喜了欢”说不通→不是。","后面能不能直接加人？“见面他”说不通→是离合词。","是不是“动词+宾语”合成的？睡觉=睡+觉，见面=见+面。"],"辨析":"离合词和一般动词的区别：一般动词后直接加宾语（“喜欢他”✓）；离合词后不能直接加宾语（“见面他”✗，要说“跟他见面”）。记住：离合词肚子里已经有一个宾语了，装不下第二个。","例句解析":[{"句":"我们见过面。","析":"“见面”是离合词，中间加“过”表经历：见+过+面。"},{"句":"帮我一个忙。","析":"“帮忙”是离合词，不能直接说“帮忙我”，用“我”放在中间：帮+我+一个+忙。"}],"练习":[{"q":"“睡了八个小时觉”中，“了”加在哪里？","options":["睡觉后面","睡和觉中间","句末","不能加"],"answer":1,"解析":"离合词的“了”加在中间：睡+了+觉。","类":"结构"},{"q":"哪句是对的？","options":["见面他","跟他见面","帮忙我","结婚她"],"answer":1,"解析":"离合词后不能直接加宾语，要用“跟”介绍：跟他见面。","类":"易错"},{"q":"“喜欢”是不是离合词？","options":["是","不是"],"answer":1,"解析":"“喜了欢”说不通，喜欢不能拆，不是离合词。","类":"辨析"},{"q":"“结过两次婚”中间加了什么？","options":["了","过+数量","的","着"],"answer":1,"解析":"“过”表经历，“两次”表数量，都加在中间。","类":"结构"}],"前置知识":["动词","宾语"]}],"name":"词的分类"},{"id":"duanyu","items":[{"name":"并列式","例子":["老师和同学","又高又大","调查研究","爸爸和妈妈","花草树木","聪明伶俐","吃喝玩乐","风雨雷电","父母兄弟","山川河流","笔墨纸砚","春夏秋冬"],"口诀":"地位平等是并列","易错":"“和”连接的也可能是介词短语，要看语境","讲解":"前后成分地位平等，无主次之分","深讲":"并列式是前后成分地位平等、谁也不修饰谁的短语，中间常有顿号、“和”“又……又……”连接；去掉任何一个成分，剩下的还能说得通，只是意思少了一半。","分类":[{"类":"名词并列","说明":"并列的成分是名词。","代表":"老师和同学、花草","例子":["老师和同学一起去春游。"]},{"类":"动词并列","说明":"并列的成分是动词。","代表":"调查研究、又唱又跳","例子":["同学们调查研究了校园植物。"]},{"类":"形容词并列","说明":"并列的成分是形容词。","代表":"又高又大、又红又香","例子":["苹果又红又香。"]}],"怎么认":["前后换个位置，意思基本不变？是的，多半是并列。","中间有没有顿号、“和”“又……又……”？有，多半是并列。","去掉一个成分，剩下的还能成话？能，说明地位平等。"],"辨析":"并列和偏正的区别：偏正是一个修饰一个（红旗：红修饰旗），并列是谁也不修饰谁（红花绿草：红花和绿草平等）。“又高又大”里高和大谁也不修饰谁，是并列，不是偏正。","例句解析":[{"句":"老师和同学一起去春游。","析":"“老师”和“同学”地位平等，中间用“和”连接，去掉一个，句子还通，只是人少了。"},{"句":"苹果又红又香。","析":"“红”和“香”都说苹果，地位平等，是形容词并列。"}],"练习":[{"q":"下面哪个是并列式短语？","options":["红旗","老师和同学","认真学习","跑得快"],"answer":1,"解析":"老师和同学地位平等，是并列；红旗是偏正，认真学习是偏正，跑得快是补充。","类":"名词并列"},{"q":"“又高又大”中，“高”和“大”的关系是？","options":["修饰关系","并列关系","支配关系","补充关系"],"answer":1,"解析":"高和大都说同一个人或物，地位平等。","类":"形容词并列"},{"q":"“调查研究”属于？","options":["并列式","偏正式","动宾式","主谓式"],"answer":0,"解析":"调查和研究都是动词，地位平等。","类":"动词并列"}],"类比":"并列式像<b>双胞胎肩并肩</b>：花草树木、又唱又跳。谁也不管谁，地位平等。","变式表":{"不变":"两个以上成分并列，同等重要，可互换位置而不改变基本意思","可变":{"成分词性":["名词+名词（老师和学生）","动词+动词（唱歌跳舞）","形容词+形容词（又高又大）"],"连接":["用连词（和/跟）","不用连词（风雨雷电）","用顿号"]},"边界":"互换后意思不变才是并列（'调查研究'✓）；'牛奶面包'是并列，'面包牛奶'意思变了就不是典型并列","覆盖已确认":["成分词性","连接"],"覆盖缺失":[]},"前置知识":["名词","动词","形容词"]},{"name":"偏正式","例子":["红旗（定中）","认真学习（状中）","伟大的祖国","漂亮的新书包","红苹果","三本书","认真学习","飞快地跑","美丽的校园","轻轻地放","新衣服","大声朗读","美丽的花开了。（'美丽'是定语，用'的'）","他高兴地说着。（'高兴'是状语，用'地'）","漂亮的女孩儿","辣的菜","可爱的小宝宝","我喜欢新鲜的果汁。","他常常买便宜的东西。","妈妈做的菜","去北京的火车","你教的学生","老板请的朋友","我画的画","他写的书","妈妈给我买的衣服","客户问的问题"],"口诀":"前偏后正，修饰中心","易错":"定中式的中心是名词，修饰语后用“的”；状中式的中心是动词或形容词，修饰语后用“地”，不要混","讲解":"前偏后正，修饰限制关系","深讲":"偏正式是前偏后正、一个修饰一个的短语：前面的词说明后面的词怎么样、什么样的；后面的词是中心，前面的词去掉，中心还在，只是说得不具体了。单音节形容词作定语常常不加“的”（新书、红花）；双音节形容词作定语多数要加“的”（漂亮的书、高兴的人），但也有能直接组合的（聪明孩子、干净衣服）。“形容词＋的”可以独立使用，代替“什么样的（人/东西）”：你喜欢哪种女孩？——漂亮的。；\"短语＋的＋名词\"：的还能连整个短语，短语多是\"名词＋动词\"，如\"妈妈做的菜\"\"去北京的火车\"\"你教的学生\"；整个短语在\"的\"前面，时态不讲究（过去/现在/将来都行）；\"短语＋的\"还能独立用，代替\"……的东西/人\"：妈妈做的（妈妈做的东西）、我画的、他写的\"短语＋的\"独立用时指代可指\"东西\"也可指\"人\"（\"你教的\"=你教的学生/你教的东西），听话人按语境判断。","分类":[{"类":"定中式","说明":"前面定语修饰后面的中心语，中心语是名词。","代表":"红旗、伟大的祖国","例子":["伟大的祖国真美丽。"]},{"类":"状中式","说明":"前面状语修饰后面的中心语，中心语是动词或形容词。","代表":"认真学习、快快跑","例子":["小明认真学习。"]}],"怎么认":["后面的词是不是中心？是的，前面在修饰它。","前后能不能加“的”（名词中心）或“地”（动词、形容词中心）？能，多半是偏正。","去掉前面的词，句子还通吗？通，只是变笼统了。"],"辨析":"偏正和并列的区别：偏正前偏后正，有主次；并列地位平等，无主次。“红旗”红修饰旗，是偏正；“红花绿草”红花和绿草平等，是并列。","例句解析":[{"句":"伟大的祖国真美丽。","析":"“伟大”修饰“祖国”，祖国是中心，是定中式。"},{"句":"小明认真学习。","析":"“认真”修饰“学习”，学习是中心，是状中式。"}],"练习":[{"q":"下面哪个是偏正式短语？","options":["老师和同学","红旗","祖国繁荣","学习语文"],"answer":1,"解析":"红修饰旗，前偏后正；其他分别是并列、主谓、动宾。","类":"定中式"},{"q":"“认真学习”中，“认真”和“学习”的关系是？","options":["并列","修饰（状中）","支配","补充"],"answer":1,"解析":"认真修饰学习，学习是中心。","类":"状中式"},{"q":"“漂亮的新书包”中，中心语是？","options":["漂亮","新","书包","的"],"answer":2,"解析":"漂亮、新都修饰书包，书包是中心。","类":"定中式"}],"类比":"偏正式像<b>月亮围着地球转</b>：红的花、飞快地跑。前面的修饰后面的，偏+正，中心在后。","变式表":{"不变":"前偏后正，修饰+中心，中心是后一部分","可变":{"偏的类型":["定语+名词（红花）","状语+动词（快跑）","定语用'的'（美丽的花）","状语用'地'（高兴地说）"],"中心词性":["名词（新书）","动词（小跑）","形容词（很好）"]},"边界":"中心在后：'红花'中心是花；与'的/地'配合：定语的、状语地；单音节形容词作定语可不加'的'（新书）","覆盖已确认":["中心词性"],"覆盖缺失":["偏的类型"]},"前置知识":["形容词","名词"]},{"name":"主谓式","例子":["祖国繁荣","他来了","天气晴朗","小鸟唱歌","花开了","天黑了","他笑了","心情好","成绩提高","春天来了","太阳升起来了","我们胜利了","学习语文很有意思。（主语是短语'学习语文'）","我们班获得了冠军。（主语是短语'我们班'）","今天星期一。（谓语是名词'星期一'）","他身体很好。（谓语是主谓短语'身体很好'）"],"口诀":"谁怎么样，主谓来讲","易错":"主谓短语可作主语、宾语、定语","讲解":"陈述关系，前后可加“是”","深讲":"主谓式是陈述关系的短语：前面说谁、什么，后面说他怎么样、是什么；前后中间常常能加“是”来检查，意思不变。","分类":[{"类":"动词谓语","说明":"谓语是动词，说明主语做什么。","代表":"小鸟唱歌、他来了","例子":["小鸟在枝头唱歌。"]},{"类":"形容词谓语","说明":"谓语是形容词，说明主语怎么样。","代表":"天气晴朗、祖国繁荣","例子":["今天天气晴朗。"]}],"怎么认":["能不能分成“谁”+“怎么样”两部分？能，多半是主谓。","中间加“是”意思变不变？不变，多半是主谓。","前面是不是在说后面那个动作、状态是谁做的？是的。"],"辨析":"主谓和动宾的区别：主谓是“谁怎么样”（小鸟唱歌：小鸟是主语），动宾是“动词+受动者”（唱歌：唱是动词，歌是宾语）。一个短语里“小鸟唱歌”是主谓，单看“唱歌”是动宾。","例句解析":[{"句":"小鸟在枝头唱歌。","析":"“小鸟”是主语，“唱歌”是谓语，说小鸟怎么样。"},{"句":"今天天气晴朗。","析":"“天气”是主语，“晴朗”是形容词谓语，说天气怎么样。"}],"练习":[{"q":"下面哪个是主谓式短语？","options":["学习语文","祖国繁荣","红旗","跑得快"],"answer":1,"解析":"祖国是主语，繁荣是谓语；其他是动宾、偏正、补充。","类":"形容词谓语"},{"q":"“他来了”中，“他”是？","options":["宾语","主语","定语","状语"],"answer":1,"解析":"他是陈述对象，是主语。","类":"动词谓语"},{"q":"“小鸟唱歌”中，“唱歌”是？","options":["主语","谓语","宾语","定语"],"answer":1,"解析":"唱歌说明小鸟怎么样，是谓语。","类":"动词谓语"}],"类比":"主谓式像<b>小句子的雏形</b>：太阳升起、我喜欢。陈述+被陈述，天生一对。","变式表":{"不变":"陈述+被陈述，主语+谓语，讲'谁怎么样'","可变":{"主语类型":["名词（他跑）","代词（我来）","短语（学习语文有意思）"],"谓语类型":["动词（吃饭）","形容词（花红）","名词（今天星期一）","主谓短语（他身体好）"]},"边界":"主谓短语作谓语是'大主谓'（他身体好）；'是'字句（他是老师）谓语是名词性，要认出","覆盖已确认":[],"覆盖缺失":["主语类型","谓语类型"]},"前置知识":["名词","动词"]},{"name":"动宾式","例子":["学习语文","打扫教室","热爱祖国","踢足球","读书","写字","吃饭","唱歌","画画","洗衣服","开门"],"口诀":"动词在前，宾语在后","易错":"不及物动词不能带宾语（如“出发”不能直接带宾语）","讲解":"支配关系，动词+受动者","深讲":"动宾式是支配关系的短语：前面是动词，后面是动词管着的人或事物；动词和宾语中间常常能加“什么”来提问，问的就是宾语。","分类":[{"类":"名词宾语","说明":"宾语是名词。","代表":"学习语文、踢足球","例子":["他打扫教室。"]},{"类":"代词宾语","说明":"宾语是代词。","代表":"帮助他、爱护它","例子":["老师帮助他。"]},{"类":"动词宾语","说明":"宾语是动词或动词短语。","代表":"喜欢游泳、开始跑步","例子":["我喜欢游泳。"]}],"怎么认":["前面是不是动词？后面是不是它管着的人或物？是的。","在动词后问“什么”，能问出后面的词吗？能，它就是宾语。","把动词和后面的词换个位置，意思变不变？变了，说明有支配关系，不是并列。"],"辨析":"动宾和主谓的区别：动宾是动词在前、宾语在后（打扫教室）；主谓是主语在前、谓语在后（教室干净）。“学习语文”学习是动词，语文是宾语；“语文难学”语文是主语，难学是谓语。","例句解析":[{"句":"他打扫教室。","析":"“打扫”是动词，“教室”是它管着的对象，是宾语。"},{"句":"我喜欢游泳。","析":"“喜欢”是动词，“游泳”是动词宾语，说明喜欢什么。"}],"练习":[{"q":"下面哪个是动宾式短语？","options":["祖国繁荣","学习语文","红旗","又高又大"],"answer":1,"解析":"学习是动词，语文是宾语；其他是主谓、偏正、并列。","类":"名词宾语"},{"q":"“帮助他”中，“他”是？","options":["主语","宾语","定语","谓语"],"answer":1,"解析":"他是帮助的对象，是代词宾语。","类":"代词宾语"},{"q":"“喜欢游泳”中，“游泳”是？","options":["名词宾语","动词宾语","主语","状语"],"answer":1,"解析":"游泳是动词，作喜欢的宾语。","类":"动词宾语"}],"类比":"动宾式像\"<b>动作+靶子</b>\"：吃饭、看书。动词发出动作，宾语承接动作。","变式表":{"不变":"动词+宾语，动作+对象，讲'做什么'","可变":{"宾语类型":["名词（吃饭）","代词（找他）","短语（学习语文）","双宾语（给我一本书）"],"动词类型":["及物动词（吃/看）"]},"边界":"不及物动词不能带宾语（✗睡觉床）；双宾语：间接（给谁）+直接（给什么），顺序不能反","覆盖已确认":["宾语类型","动词类型"],"覆盖缺失":[]},"前置知识":["动词","名词"]},{"name":"补充式","例子":["写得好","跑得快","热极了","笑得很开心","说清楚","洗干净","长高了","热得满头大汗","写完了","打破了","坐下"],"口诀":"补充说明在后头","易错":"常由“得”字连接","讲解":"后补前，补充说明动作结果/状态","深讲":"补充式是后补前、补充说明的短语：后面的词补充前面的动词或形容词，说明结果怎么样、状态怎么样、方向往哪去；补充部分常常由“得”连接，去掉它，动作还在，只是不具体了。","分类":[{"类":"结果补语","说明":"补充动作的结果。","代表":"写完了、洗干净","例子":["衣服洗干净了。"]},{"类":"状态补语","说明":"补充动作进行时的状态（怎么样），常由“得”连接。","代表":"跑得快、笑得很开心","例子":["他跑得很快。"]},{"类":"程度补语","说明":"跟在形容词后面，表示程度深浅，不用“得”。","代表":"热极了、乐坏了","例子":["天气热极了。"]},{"类":"趋向补语","说明":"补充动作的方向。","代表":"走进来、飞上去","例子":["小鸟飞上去了。"]}],"怎么认":["后面的词是不是在补充前面的动词、形容词？是的。","中间有没有“得”“极了”？有，多半是补充。","去掉后面的词，动作还成立吗？成立，只是结果、状态不清楚了。"],"辨析":"补充和偏正的区别：偏正是前面修饰后面（认真学习：认真在前），补充是后面补充前面（跑得快：快在后，补充跑）。看修饰在前还是补充在后。","例句解析":[{"句":"衣服洗干净了。","析":"“干净”补充“洗”的结果，说明洗成什么样。"},{"句":"他跑得很快。","析":"“快”由“得”连接，补充“跑”时的状态。"}],"练习":[{"q":"下面哪个是补充式短语？","options":["红旗","学习语文","跑得快","老师和同学"],"answer":2,"解析":"快补充跑时的状态；其他是偏正、动宾、并列。","类":"状态补语"},{"q":"“洗干净”中，“干净”是什么补语？","options":["结果补语","状态补语","趋向补语","定语"],"answer":0,"解析":"干净说明洗的结果。","类":"结果补语"},{"q":"“走进来”中，“进来”是什么补语？","options":["结果补语","状态补语","趋向补语","状语"],"answer":2,"解析":"进来说明走的方向。","类":"趋向补语"}],"类比":"补充式像给动作加<b>备注</b>：跑得快、写完了。动词在前，补充说明在后。","变式表":{"不变":"动词/形容词+补语，补充说明结果、状态、程度、趋向","可变":{"补语类型":["结果补语（写完）","状态补语（跑得快）","程度补语（好得很）","趋向补语（走上来）","可能补语（看得见）","数量补语（说三遍）"],"连接":["直接（写完）","用'得'（跑得快）"]},"边界":"补语在后：'写完'补语是完；'得'字补语表状态（跑得快）vs'的'定语（跑的快✗）；可能补语用'得/不'（看得见/看不见）","覆盖已确认":["补语类型","连接"],"覆盖缺失":[]},"前置知识":["动词","形容词"]}],"name":"短语的结构（5种）"},{"id":"juzichengfen","items":[{"name":"主语","例子":["〔他〕来了","〔祖国的明天〕会更好","〔小明〕在踢球","我们班得了第一名。（我们班是主语）","小鸟在天上飞。（小鸟是主语）","春天来了。（春天是主语）","他认真地写作业。（他是主语）","鲜艳的红旗迎风飘扬。（红旗是主语）","勤劳的蜜蜂在花丛中飞舞。（蜜蜂是主语）","这本书很有趣。（书是主语）","外面下起了大雨。（雨是主语）","老师表扬了他。（老师是主语）","学习语文很有意思。（'学习语文'是短语，充当主语）","他身体好。（'他'是代词，充当主语）","我吃饭。（主语'我'在句首）","昨天他没来。（主语'他'在状语'昨天'后面、谓语前面）"],"口诀":"主语回答谁什么","易错":"主语多余或残缺是常见病句","讲解":"谓语陈述的对象，回答“谁/什么”","深讲":"主语是谓语陈述的对象，回答“谁”或“什么”；找主语先找谓语，再问“谁怎么样、什么怎么样”，答的就是主语；主语常常在句首。","分类":[{"类":"名词主语","说明":"主语是名词或名词短语。","代表":"小明、祖国","例子":["小明在踢球。"]},{"类":"代词主语","说明":"主语是代词。","代表":"他、我们","例子":["他来了。"]},{"类":"短语主语","说明":"主语是短语。","代表":"祖国的明天、读书","例子":["祖国的明天会更好。"]}],"怎么认":["先找谓语（说明怎么样的词），再问谁、什么。","主语多在句首。","去掉主语，句子就不知道说谁了。"],"辨析":"主语和宾语都回答谁、什么，区别在位置和关系：主语在谓语前，是陈述对象；宾语在动词后，是动作对象。“我爱妈妈”我主语，妈妈宾语。","例句解析":[{"句":"他来了。","析":"“他”是主语，“来了”是谓语，说他怎么样。"},{"句":"祖国的明天会更好。","析":"“祖国的明天”是主语，“会更好”是谓语，说它怎么样。"}],"练习":[{"q":"“小明在踢球”中，主语是？","options":["小明","在","踢球","球"],"answer":0,"解析":"小明是陈述对象，是名词主语。","类":"名词主语"},{"q":"“他来了”中，主语是？","options":["他","来了","了","来"],"answer":0,"解析":"他是陈述对象，是代词主语。","类":"代词主语"},{"q":"“祖国的明天会更好”中，主语是？","options":["祖国","明天","祖国的明天","更好"],"answer":2,"解析":"祖国的明天整体作主语，是短语主语。","类":"短语主语"}],"类比":"主语就像电影的\"主角\"：一句话讲谁，ta 就是主语。","变式表":{"不变":"谓语陈述的对象，讲'谁/什么'","可变":{"充当":["名词（老师来了）","代词（他跑了）","短语（学习语文有意思）","主谓短语（他身体好）"],"位置":["句首（我吃饭）","谓语前"]},"边界":"主语不一定是施事（'饭吃完了'主语是饭）；无主句（'下雨了'）没有主语；'把'字句主语是处置者","覆盖已确认":[],"覆盖缺失":["充当","位置"]},"前置知识":["名词","代词","主谓式"]},{"name":"谓语","例子":["他〔来了〕","今天〔星期一〕","小狗〔汪汪叫〕","我爱我的祖国。（爱是谓语）","小狗汪汪地叫。（叫是谓语）","他跑得很快。（跑是谓语）","妈妈在做饭。（做饭是谓语）","花儿开了。（开是谓语）","同学们认真听讲。（听讲是谓语）","太阳升起来了。（升是谓语）","我们胜利了。（胜利是谓语）","鸟儿在枝头唱歌。（唱歌是谓语）","花很红。（形容词'红'作谓语，不用'是'）","今天星期一。（名词'星期一'作谓语，表判断）"],"口诀":"谓语说明怎么样","易错":"谓语残缺会导致句子不完整","讲解":"陈述主语，回答“怎么样/是什么/做什么”","深讲":"谓语陈述主语，回答怎么样、是什么、做什么；谓语是句子的中心，没有谓语，句子就不完整；谓语可以是动词、形容词、名词短语。","分类":[{"类":"动词谓语","说明":"谓语是动词，说明主语做什么。","代表":"来了、踢球","例子":["他来了。"]},{"类":"形容词谓语","说明":"谓语是形容词，说明主语怎么样。","代表":"晴朗、美丽","例子":["天气晴朗。"]},{"类":"名词谓语","说明":"名词或数量词直接作谓语，中间不用「是」，多说日期、年龄、籍贯、价钱。","代表":"星期一、八岁、浙江人","例子":["今天星期一。","鲁迅浙江人。"]}],"怎么认":["先找主语，再问它怎么样、是什么、做什么。","谓语多在主语后。","去掉谓语，只剩主语，句子说不完整。"],"辨析":"谓语和宾语：谓语说明主语，宾语是动词的对象。“他学习语文”学习是谓语，语文是宾语；不能把宾语当谓语。","例句解析":[{"句":"他来了。","析":"“来了”是谓语，说明他怎么样。"},{"句":"祖国是花园。","析":"“是花园”是谓语，说明祖国是什么；谓语里的“是”是判断动词，所以这是动词谓语，不是名词谓语（名词谓语像“今天星期一”，不用“是”）。"}],"练习":[{"q":"“小狗汪汪叫”中，谓语是？","options":["小狗","汪汪叫","汪汪","叫"],"answer":1,"解析":"汪汪叫说明小狗怎么样，是动词谓语。","类":"动词谓语"},{"q":"“天气晴朗”中，谓语是？","options":["天气","晴朗","今天","很"],"answer":1,"解析":"晴朗说明天气怎么样，是形容词谓语。","类":"形容词谓语"},{"q":"“祖国是花园”中，谓语是？","options":["祖国","是花园","花园","是"],"answer":1,"解析":"“是花园”说明祖国是什么，是谓语；“是”是判断动词，这是动词谓语。","类":"动词谓语"}],"类比":"谓语就像主角的\"动作戏\"：主角在干什么，谓语就讲什么。","变式表":{"不变":"陈述主语，讲'怎么样/是什么/做什么'","可变":{"充当":["动词（他跑）","形容词（花红）","名词（今天星期一）","主谓短语（他身体好）"],"类型":["动词谓语","形容词谓语","名词谓语"]},"边界":"形容词谓语不用'是'（✗花是红）；名词谓语表判断（今天星期一）；'是'后名词是宾语不是谓语（他是老师：谓语是'是'）","覆盖已确认":["充当"],"覆盖缺失":["类型"]},"前置知识":["动词","形容词","主谓式"]},{"name":"宾语","例子":["学习〔语文〕","热爱〔祖国〕","我爱〔妈妈〕","我喜欢读书。（书是宾语）","妈妈买了苹果。（苹果是宾语）","他踢足球。（足球是宾语）","我们参观了博物馆。（博物馆是宾语）","小明写完了作业。（作业是宾语）","老师表扬了他。（他是宾语）","我喝了一杯牛奶。（牛奶是宾语）","姐姐织毛衣。（毛衣是宾语）","他修好了自行车。（自行车是宾语）","我看书。（单宾语'书'）","老师给我一本书。（双宾语：'我'是间接宾语，'一本书'是直接宾语）"],"口诀":"动词之后找宾语","易错":"及物动词缺宾语是成分残缺","讲解":"动作的对象，回答“谁/什么”","深讲":"宾语是动作的对象，回答谁、什么；宾语在动词后面，动词问“什么”，答的就是宾语；不及物动词不能直接带宾语。","分类":[{"类":"名词宾语","说明":"宾语是名词。","代表":"语文、祖国","例子":["学习语文。"]},{"类":"代词宾语","说明":"宾语是代词。","代表":"他、它","例子":["我喜欢他。"]},{"类":"动词宾语","说明":"宾语是动词或动词短语。","代表":"游泳、跑步","例子":["我喜欢游泳。"]}],"怎么认":["先找动词，再问动词什么。","宾语多在动词后。","去掉宾语，动作就不知道对谁、做什么了。"],"辨析":"宾语和主语：都回答谁、什么，主语在前是陈述对象，宾语在后是动作对象。“妈妈爱我”妈妈主语，我宾语；换位置意思就变了。","例句解析":[{"句":"学习语文。","析":"“语文”是宾语，说明学习什么。"},{"句":"我爱妈妈。","析":"“妈妈”是宾语，说明爱谁。"}],"练习":[{"q":"“学习语文”中，宾语是？","options":["学习","语文","语","文"],"answer":1,"解析":"语文是学习的对象，是名词宾语。","类":"名词宾语"},{"q":"“我喜欢他”中，宾语是？","options":["我","喜欢","他","欢"],"answer":2,"解析":"他是喜欢的对象，是代词宾语。","类":"代词宾语"},{"q":"“我喜欢游泳”中，宾语是？","options":["我","喜欢","游泳","游"],"answer":2,"解析":"游泳是动词，作喜欢的宾语。","类":"动词宾语"}],"类比":"宾语就像动作的\"接球手\"：动词这个球扔出去，砸到谁，谁就是宾语。","变式表":{"不变":"动词支配的对象，讲'什么/谁'","可变":{"充当":["名词（吃饭）","代词（找他）","短语（学习语文）"],"类型":["单宾语（看书）","双宾语（给我书：间接+直接）"]},"边界":"宾语在动词后：'吃饭'宾语是饭；不及物动词无宾语；'把'字句宾语提前（我把饭吃了：宾语是饭）","覆盖已确认":["充当"],"覆盖缺失":["类型"]},"前置知识":["动词","名词","动宾式"],"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%;height:auto\" fill=\"#2c3328\" role=\"img\" aria-label=\"宾语示意图：宾语是动作的对象，在动词后面，动词问什么，答出来的就是宾语\">\n<title>宾语：动作的对象，在动词后面</title>\n<style>text{font-family:'Microsoft YaHei','PingFang SC','Noto Sans SC',sans-serif}</style>\n<!-- 面板一：主语、谓语、宾语的位置 -->\n<text x=\"24\" y=\"36\" font-size=\"24\" font-weight=\"700\">① 宾语在动词后面</text>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"2.0s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"330\" y=\"46\" width=\"200\" height=\"36\" rx=\"18\" fill=\"#f8faf5\" stroke=\"#b85a52\" stroke-width=\"2\"/>\n  <text x=\"430\" y=\"71\" font-size=\"20\" text-anchor=\"middle\" fill=\"#b85a52\">喜欢什么？</text>\n  <path d=\"M 420 82 L 430 92 L 440 82\" fill=\"#f8faf5\" stroke=\"#b85a52\" stroke-width=\"2\"/>\n</g>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"0.2s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"40\" y=\"100\" width=\"120\" height=\"58\" rx=\"12\" fill=\"#d3e5d6\" stroke=\"#4a7a59\" stroke-width=\"2\"/>\n  <text x=\"100\" y=\"140\" font-size=\"28\" text-anchor=\"middle\">我</text>\n  <text x=\"100\" y=\"186\" font-size=\"18\" text-anchor=\"middle\" fill=\"#5b6b5f\">主语</text>\n</g>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"0.6s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"200\" y=\"100\" width=\"120\" height=\"58\" rx=\"12\" fill=\"#4a7a59\"/>\n  <text x=\"260\" y=\"140\" font-size=\"28\" text-anchor=\"middle\" fill=\"#f8faf5\">喜欢</text>\n  <text x=\"260\" y=\"186\" font-size=\"18\" text-anchor=\"middle\" fill=\"#5b6b5f\">谓语</text>\n</g>\n<path d=\"M 322 129 L 352 129\" stroke=\"#4a7a59\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\" stroke-dasharray=\"32\" stroke-dashoffset=\"32\">\n  <animate attributeName=\"stroke-dashoffset\" from=\"32\" to=\"0\" begin=\"1.0s\" dur=\"0.5s\" fill=\"freeze\"/>\n</path>\n<path d=\"M 350 121 L 362 129 L 350 137\" stroke=\"#4a7a59\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" opacity=\"0\">\n  <animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"1.45s\" dur=\"0.2s\" fill=\"freeze\"/>\n</path>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"1.4s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"370\" y=\"100\" width=\"170\" height=\"58\" rx=\"12\" fill=\"#f8faf5\" stroke=\"#4a7a59\" stroke-width=\"3\"/>\n  <text x=\"455\" y=\"140\" font-size=\"28\" text-anchor=\"middle\" font-weight=\"700\">读书</text>\n  <text x=\"455\" y=\"186\" font-size=\"18\" text-anchor=\"middle\" fill=\"#3d5a40\" font-weight=\"700\">宾语</text>\n</g>\n\n<line x1=\"24\" y1=\"214\" x2=\"616\" y2=\"214\" stroke=\"#d5dfd0\" stroke-width=\"2\"/>\n\n<!-- 面板二：怎么找宾语 -->\n<text x=\"24\" y=\"246\" font-size=\"24\" font-weight=\"700\">② 怎么找：先找动词，再问“什么”</text>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"3.0s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"40\" y=\"266\" width=\"120\" height=\"50\" rx=\"10\" fill=\"#d3e5d6\" stroke=\"#4a7a59\" stroke-width=\"2\"/>\n  <text x=\"100\" y=\"299\" font-size=\"26\" text-anchor=\"middle\">妈妈</text>\n  <text x=\"100\" y=\"340\" font-size=\"18\" text-anchor=\"middle\" fill=\"#5b6b5f\">主语</text>\n</g>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"3.4s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"190\" y=\"266\" width=\"120\" height=\"50\" rx=\"10\" fill=\"#4a7a59\"/>\n  <text x=\"250\" y=\"299\" font-size=\"26\" text-anchor=\"middle\" fill=\"#f8faf5\">买了</text>\n  <text x=\"250\" y=\"340\" font-size=\"18\" text-anchor=\"middle\" fill=\"#5b6b5f\">谓语</text>\n</g>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"3.8s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"340\" y=\"266\" width=\"150\" height=\"50\" rx=\"10\" fill=\"#f8faf5\" stroke=\"#4a7a59\" stroke-width=\"3\"/>\n  <text x=\"415\" y=\"299\" font-size=\"26\" text-anchor=\"middle\" font-weight=\"700\">苹果</text>\n  <text x=\"415\" y=\"340\" font-size=\"18\" text-anchor=\"middle\" fill=\"#3d5a40\" font-weight=\"700\">宾语</text>\n</g>\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"4.6s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <text x=\"24\" y=\"376\" font-size=\"20\">买了什么？苹果。答出来的，就是宾语。</text>\n</g>\n\n<!-- 底部提醒：不是所有动词都能带宾语 -->\n<g opacity=\"0\"><animate attributeName=\"opacity\" from=\"0\" to=\"1\" begin=\"5.2s\" dur=\"0.4s\" fill=\"freeze\"/>\n  <rect x=\"24\" y=\"388\" width=\"592\" height=\"28\" rx=\"10\" fill=\"#f2f6ee\" stroke=\"#b85a52\" stroke-width=\"1.5\"/>\n  <text x=\"40\" y=\"408\" font-size=\"18\" fill=\"#b85a52\">✗ 出发北京　　✓ 出发去北京（“出发”不能直接带宾语）</text>\n</g>\n</svg>"},{"name":"定语","例子":["（红色的）旗","（我）的书","（粉色的）铅笔盒","红红的苹果真好看。（红红的是定语）","勤劳的蜜蜂采蜜忙。（勤劳的是定语）","高高的山上有座庙。（高高的是定语）","聪明的孩子爱动脑。（聪明的是定语）","美丽的校园里花香扑鼻。（美丽的是定语）","洁白的雪覆盖了大地。（洁白的是定语）","勇敢的战士冲上前去。（勇敢的是定语）","新买的书包真漂亮。（新买的是定语）","慈祥的奶奶讲故事。（慈祥的是定语）","北京人爱吃烤鸭。（'北京'是名词，充当定语）","木头桌子很结实。（'木头'是名词，充当定语）","新买的书真好看。（'新买的'是短语，充当定语）","刚开的花真香。（'刚开的'是短语，充当定语）","我买了个新书包。（'新'作定语，不用'的'）","红旗飘扬。（'红'作定语，不用'的'）"],"口诀":"定语修饰名词，常带“的”字","易错":"多重定语语序：领属+数量+动词性+形容词性+名词","讲解":"修饰名词，回答“什么样的”","深讲":"定语修饰名词，回答什么样的、谁的、哪一个；定语在名词前面，常带“的”；定语去掉，名词还在，只是说得不具体。","分类":[{"类":"形容词定语","说明":"定语是形容词。","代表":"红色的、粉色的","例子":["红色的旗。"]},{"类":"名词定语","说明":"定语是名词，常表领属、材料。","代表":"我的、木头的","例子":["我的书。"]},{"类":"动词定语","说明":"定语是动词或动词短语。","代表":"刚买的、会唱歌的","例子":["刚买的书真好看。"]}],"怎么认":["看它修饰的是不是名词。","前面有没有“的”。","问“什么样的+名词”，答的就是定语。"],"辨析":"定语和状语：定语修饰名词（红色的旗），状语修饰动词、形容词（认真地学习）；看中心语是名词还是动词、形容词，再看“的”还是“地”。","例句解析":[{"句":"红色的旗。","析":"“红色的”修饰旗，是形容词定语。"},{"句":"我的书。","析":"“我的”修饰书，是名词定语。"}],"练习":[{"q":"“红色的旗”中，定语是？","options":["红色的","旗","飘扬","高"],"answer":0,"解析":"红色的修饰旗，是形容词定语。","类":"形容词定语"},{"q":"“我的书”中，定语是？","options":["我","我的","书","本"],"answer":1,"解析":"我的修饰书，是名词定语。","类":"名词定语"},{"q":"“刚买的书”中，定语是？","options":["刚","刚买的","书","买"],"answer":1,"解析":"刚买的修饰书，是动词定语。","类":"动词定语"}],"类比":"定语就像\"标签\"：贴在名词前面，告诉你这是哪一个。","变式表":{"不变":"修饰名词，讲'什么样的'","可变":{"充当":["形容词（红花）","名词（北京人）","代词（我的书）","短语（新买的书）"],"标志":["用'的'（美丽的花）","不用'的'（新书）"]},"边界":"定语在名词前；'的'是定语标志（区别于'地/得'）；多定语顺序：领属+数量+动词性+形容词性+名词（我的三本新买的中文书）","覆盖已确认":["充当"],"覆盖缺失":["标志"]},"前置知识":["偏正式","形容词"]},{"name":"状语","例子":["〔认真地〕学习","〔在教室里〕读书","〔高兴地〕跳起来","他认真地听讲。（认真地是状语）","同学们在操场上跑步。（在操场上是状语）","妈妈高兴地笑了。（高兴地是状语）","我们明天去春游。（明天是状语）","小鸟快乐地唱歌。（快乐地是状语）","他飞快地跑回家。（飞快地是状语）","老师耐心地讲解。（耐心地是状语）","大家热烈地鼓掌。（热烈地是状语）","我昨天去了公园。（昨天是状语）","他高兴地说。（'高兴地'是形容词加'地'，充当状语）","他昨天来了。（'昨天'是时间名词，充当状语）","他在北京工作。（处所状语'在北京'）","他对我很好。（对象状语'对我'）"],"口诀":"状语修饰动形，常带“地”字","易错":"状语位置一般在谓语前","讲解":"修饰动词/形容词，回答“怎样/何时/何地”","深讲":"状语修饰动词、形容词，回答怎样、何时、何地；状语在谓语前面，常带“地”，也可以是时间、处所短语；去掉状语，句子主干还在，只是不具体。","分类":[{"类":"时间状语","说明":"说明动作的时间。","代表":"昨天、早上","例子":["昨天我们去春游。"]},{"类":"处所状语","说明":"说明动作的地点。","代表":"在教室里、在家里","例子":["在教室里读书。"]},{"类":"方式状语","说明":"说明动作的方式、样子，常带“地”。","代表":"认真地、高兴地","例子":["认真地学习。"]}],"怎么认":["看它修饰的是不是动词、形容词。","在谓语前，有没有“地”或时间、处所词。","问怎样、何时、何地，答的就是状语。"],"辨析":"状语和定语：状语修饰动词、形容词（认真地学习），定语修饰名词（认真的学生）；“地”前是状语，“的”前是定语。","例句解析":[{"句":"认真地学习。","析":"“认真地”修饰学习，是方式状语。"},{"句":"在教室里读书。","析":"“在教室里”修饰读书，说明地点，是处所状语。"}],"练习":[{"q":"“认真地学习”中，状语是？","options":["认真","认真地","学习","地"],"answer":1,"解析":"认真地修饰学习，是方式状语。","类":"方式状语"},{"q":"“在教室里读书”中，状语是？","options":["在","在教室里","读书","教室"],"answer":1,"解析":"在教室里修饰读书，说明地点，是处所状语。","类":"处所状语"},{"q":"“昨天我们去春游”中，状语是？","options":["昨天","我们","去","春游"],"answer":0,"解析":"昨天修饰去，说明时间，是时间状语。","类":"时间状语"}],"类比":"状语就像\"滤镜\"：加在动词/形容词前面，告诉你动作怎么发生的。","变式表":{"不变":"修饰动词、形容词，讲'怎么/何时/何地'","可变":{"充当":["副词（已经走）","形容词+地（高兴地说）","介宾短语（在北京住）","时间名词（昨天来）"],"类型":["时间/处所/方式/程度/对象"]},"边界":"状语在动词/形容词前；'地'是状语标志；'很'是状语不是补语（'很好'：很是状语）；多状语顺序：时间+处所+语气+范围+否定+程度+对象","覆盖已确认":[],"覆盖缺失":["充当","类型"]},"前置知识":["副词","介词"]},{"name":"补语","例子":["写得〔好〕","跑得〔快〕","写得〔很工整〕","他跑得很快。（很快是补语）","作业写完了。（“完”是补语，“了”是助词）","衣服洗干净了。（干净是补语）","她长高了许多。（许多是补语）","热得满头大汗。（满头大汗是补语）","说得清清楚楚。（清清楚楚是补语）","天黑下来了。（下来是补语）","花开得很美。（很美是补语）","他气得说不出话。（说不出话是补语）","他写完了作业。（结果补语'完'，在动词后面）","他走上来了。（趋向补语'上来'，在动词后面）"],"口诀":"补语补充在后头，常带“得”字","易错":"“得”后补语与“地”前状语不要混","讲解":"补充说明谓语，回答“怎么样/结果”","深讲":"补语补充说明谓语，回答怎么样、什么结果、往哪去；补语在谓语后面。“得”的存缺要看补语类型：状态补语和可能补语用“得”连接（他跑得很快、我听得懂），结果补语、趋向补语、数量补语前面不用“得”（衣服洗干净了、小鸟飞上去了、看了三遍）；一旦在结果/趋向补语前加了“得”，就变成可能补语（写得完、走得上去）。结果补语还分两种：自然结果（吃饱了、买累了：动作发生后自然出现的结果）和说话人的评价（买贵了、吃早了：说话人对结果的看法）。常用结果补语词汇表：晚（来晚了）、饱（吃饱了）、坏（玩坏了）、清楚（听清楚了）、干净（洗干净了）、破（撕破了）。“好”表示动作做完、做好（写好了），“错”表示动作做错了（记错了）。否定结果补语用“没”不用“不”：我没吃饱（不能说“我不吃饱”）。少数单音节动词也能做结果补语：到（看到）、见（听见）、懂（看懂）、会（学会）、走（拿走）、掉（忘掉）。结果/可能对照表：做完｜做得完｜做不完；听懂｜听得懂｜听不懂；看清楚｜看得清楚｜看不清楚。去掉补语，动作还在，只是不具体。；结果补语爱把宾语提前当话题：这个字写错了（主语常省略，不说\"我把这个字写错了\"）；趋向补语加\"得\"/\"不\"就变成可能补语：回去→回得去/回不去；过来→过得来/过不来；站起来→站得起来/站不起来本站定名：动词后“得”字结构（跑得快、写得好）称状态补语（朱德熙《语法讲义》9.8）；形容词后的“极了/死了/坏了/得很”（好极了、乐坏了）称程度补语（9.9）。两类不要混","分类":[{"类":"结果补语","说明":"补充动作的结果。结果补语后常跟\"了\"；\"好\"≈\"完\"，都表示\"做完、做好\"；单音节动词补语没几个（到/见/懂/会/走/掉），常被看成一个词。","代表":"完、干净、好","例子":["衣服洗干净了。","我吃饱了。","他买错了东西。","你吃好了吗？","对不起，我记错了时间。","你来晚了，我们已经关门了。","他玩坏了哥哥的玩具。","他还没想好。","我们没听清楚，请再说一遍。","你们都听懂了吗？","你踩到我的脚了。","我不小心撞到墙了。","我女儿学会了数数。","这个字写错了。","杯子摔坏了。","房间打扫干净了吗？","我把杯子摔坏了。","他把我的电脑修好了。","我们把房间打扫干净了。"]},{"类":"状态补语","说明":"补充动作进行时的状态（怎么样），常由“得”连接。动词后不能又跟宾语又跟补语：要么重说动词（你说中文说得很好），要么宾语提前（你的中文说得很好）；\"很\"直接跟在\"得\"后的是状态补语（她说得很清楚），可能补语不能这样。","代表":"快、很工整","例子":["他跑得很快。","他高兴得跳了起来。","你做得不错。","孩子们学得挺快的。","我吃得太饱了。","你们谈得顺利吗？","她长得还可以。","你做菜做得很好。","你的菜做得很好。","你写字写得很漂亮。","你的字写得很漂亮。"]},{"类":"程度补语","说明":"跟在形容词后面，表示程度深浅，不用“得”：极了（味道好极了）、死了（臭死了/可爱死了）、坏了（高兴坏了）、得很（累得很）。","代表":"极了、死了、坏了","例子":["味道好极了。","这里的天气舒服极了。","小狗可爱死了。","我们都高兴坏了。","妈妈急坏了。","累得很。"]},{"类":"趋向补语","说明":"补充动作的方向。关键看说话人在哪：动作朝说话人来用\"来\"，离说话人去用\"去\"；复合趋向补语：\"来\"字组（上来/下来/进来/出来/回来/过来/起来）、\"去\"字组（上去/下去/进去/出去/回去/过去）；一个动词后不能又跟补语又跟宾语：✗回来中国→✓回中国来。自己移动时看语境：跟人约明天见，说\"我来找你\"（朝对方去也用\"来\"，跟英语\"I'll come see you\"一样）。","代表":"进来、上去","例子":["小鸟飞上去了。","他走进来了。","请把书拿上来。","我在楼上，你上来。","我妈不让我出去。","这是我家，进来吧。","你下班了吗？几点回来吃饭？","请站起来。","不要让它跑出去。","从我家走过来要半个小时。","你包里的东西都拿出来了吗？","服务员，请再拿几个碗来。","快点送孩子去吧。","师傅，送两桶水来。","可以带朋友过来吗？","他们带了一些礼物回去。","把书拿出来。","把手举起来。","帮我把这个箱子搬过去。"]},{"类":"可能补语","说明":"表示动作能不能做到、做不做得到，用“得/不”连接。可能补语从别的补语变来：动词＋见/懂/完/形容词/到/趋向，中间插\"得\"（肯定）或\"不\"（否定）；宾语可放补语后，也可提前到句首。","代表":"听得懂、写得完","例子":["我听得懂。","这个字我写不出来。","你没戴眼镜，看得清楚吗？","他这么粗心，做得好吗？","你这么聪明，肯定学得会。","早上五点出发，孩子们起得来吗？","这么高的山，你爬得上去吗？","你的声音太小了，我们听不见。","这里太暗了，我看不清楚。","这个自行车太破了，谁都修不好。","她的腿受伤了，站不起来了。","包太小了，手机放不进去。","你听得懂上海话吗？","她这么小，看得懂这本书吗？","我怕我做不好这份工作。","这种手机现在买不到了。","这本书我一个星期肯定看得完。"]},{"类":"数量补语","说明":"补充动作的次数、持续的时间。动量词三兄弟：次（最常用）、遍、下；动词＋数＋量：看三次、读两遍、拍两下。","代表":"三遍、一会儿","例子":["这本书我看了三遍。","他睡了一会儿。","再说一遍。","你能再读一遍吗？","这个电影我看过两遍。","这个故事我听她说过一百多遍了。","我们去过两次。","我问了他很多次。","这个问题我们讨论过几次。","他轻轻地拍了我两下。","你没听见吗？我敲了好几下。"]}],"怎么认":["看它是不是在谓语后面补充说明。","中间有没有“得”。","问状态、结果、方向，答的就是补语。"],"辨析":"补语和状语：补语在谓语后补充（跑得快：快在后），状语在谓语前修饰（快快跑：快快在前）；“得”后是补语，“地”前是状语。；补语和宾语：宾语是动作涉及的对象（吃什么→饭），补语回答动作“怎么样”（吃得怎么样→饱）。测试法：动词后面问“什么”，得到的是宾语；问“怎么样”，得到的是补语。","例句解析":[{"句":"写得好。","析":"“好”补充写时的状态，是状态补语。"},{"句":"衣服洗干净了。","析":"“干净”补充洗的结果，是结果补语。"}],"练习":[{"q":"“跑得快”中，补语是？","options":["跑","得","快","跑得"],"answer":2,"解析":"快补充跑时的状态，是状态补语。","类":"状态补语"},{"q":"“衣服洗干净了”中，补语是？","options":["衣服","洗","干净","了"],"answer":2,"解析":"干净补充洗的结果，是结果补语。","类":"结果补语"},{"q":"“小鸟飞上去了”中，补语是？","options":["小鸟","飞","上去","了"],"answer":2,"解析":"上去补充飞的方向，是趋向补语。","类":"趋向补语"}],"类比":"补语就像\"赛后采访\"：动作结束了，补一句\"结果如何\"。","变式表":{"不变":"补充说明动词、形容词的结果、状态、程度、趋向等","可变":{"充当":["动词（写完）","形容词（好得很）","短语（走上来）"],"类型":["结果","状态","程度","趋向","可能","数量"]},"边界":"补语在动词/形容词后；'得'是补语标志（跑得快）；区别于状语：状语在前（快跑），补语在后（跑得快）","覆盖已确认":["充当"],"覆盖缺失":["类型"]},"前置知识":["补充式","动词"]},{"name":"趋向补语引申义","讲解":"“起来/下去/出来”不只表示方向，还引申出“开始、继续、有结果”的意思：天气热起来了（开始热），坚持下去（继续）。","深讲":"趋向补语本管方向（站起来=向上站），但常用出引申义：①起来=开始并持续（热起来了、胖起来了）；还表“完成、收拢”（收起来、藏起来）、表“估计”（看起来、听起来）；②下去=继续（说下去、坚持下去）；③出来=有了结果（想出来了、写出来了）；④下来=延续到现在或缓和（坚持下来、冷静下来）。判断方法：按方向讲不通，就是引申义（“热起来”不是往上热）。","类比":"趋向补语的引申义像方向盘打满：本来管方向（上下左右），打满了就拐出新意思（开始、继续）。","口诀":"起来是开始，下去是继续，出来见结果","例子":["天气热起来了。","说起来容易，做起来难。","把玩具收起来。","她看起来很健康。","听起来不错。","坚持下去！","这个故事太无聊，我听不下去了。","我想出来了！","他看起书来就忘了时间。"],"易错":"引申义时别再按方向理解（“热起来”不是往上热）；“下去”表继续时，主语多是人或事。","分类":[{"类":"表开始","说明":"起来：动作或状态开始并持续。","代表":"热起来、胖起来","例子":["天气热起来了。","说起来容易，做起来难。"]},{"类":"表继续","说明":"下去/下来：动作继续下去。","代表":"坚持下去","例子":["坚持下去！","这个故事太无聊，我听不下去了。"]},{"类":"表结果/估计","说明":"出来：有了结果；起来：估计推测。","代表":"想出来、看起来","例子":["我想出来了！","她看起来很健康。"]}],"怎么认":["动词后跟没跟“起来/下去/出来/下来”？跟了→可能是。","按方向讲通不通？“热起来”按方向讲不通→是引申义。","是不是表开始、继续、结果、估计？是→引申义。"],"辨析":"起来方向义 vs 引申义：看主语能不能“位移”。“站起来”（人能向上动）是方向；“热起来”（天气不能位移）是引申。能位移→方向，不能位移→引申。","例句解析":[{"句":"天气热起来了。","析":"“起来”不是方向，是“开始并持续”：天气开始热，而且越来越热。"},{"句":"把玩具收起来。","析":"“起来”表“完成、收拢”：把散着的玩具收好。不是往上收。"}],"练习":[{"q":"“天气热起来了”中“起来”表什么？","options":["方向向上","开始并持续","完成","估计"],"answer":1,"解析":"天气不能位移，“起来”是引申义：开始热并持续。","类":"辨析"},{"q":"哪句的“下去”表“继续”？","options":["走下去","坚持下去","跳下去","滑下去"],"answer":1,"解析":"“坚持下去”是继续坚持；其余是方向（向下）。","类":"辨析"},{"q":"“她看起来很健康”中“起来”表什么？","options":["开始","继续","估计推测","方向"],"answer":2,"解析":"“看起来”是固定搭配，表估计、推测。","类":"分类"},{"q":"“我想出来了”的“出来”表什么？","options":["方向向外","有了结果","开始","继续"],"answer":1,"解析":"“想出来”=想到了办法，“出来”表结果出现。","类":"分类"}],"前置知识":["补语","动词"]}],"name":"单句的成分（7种）"},{"id":"fuju","items":[{"name":"并列复句","例子":["他来了，我也来了","我写作业，弟弟看书","花儿红，草儿绿。","他会唱歌，也会跳舞。","天晴了，风停了。","小明爱读书，小红爱画画。","春天播种，秋天收获。","妈妈做饭，爸爸洗碗。","太阳升起，公鸡打鸣。","教室里安静，操场上热闹。","他个子高，她个子矮。","白天很热，夜里很凉。","他既会唱歌，又会跳舞。（'既…又…'）","她既聪明又勤奋。（'既…又…'）","他一边走路，一边听音乐。（'一边…一边…'）","妈妈一边做饭，一边打电话。（'一边…一边…'）"],"口诀":"关联词：既……又、也、还","易错":"只看有没有关联词：并列句可以没有关联词，要看分句是否平行、谁也不比谁更进一层","讲解":"分句间平等并列","深讲":"并列复句是两个或两个以上分句地位平等、并列在一起的复句；分句间没有主次，谁也不比谁更进一层；判断并列，先看意思是不是平行的，再看有没有既……又、也、还这类关联词。","分类":[{"类":"既……又……式","说明":"用既……又连接两个平行的方面。","代表":"既……又……","例子":["他既会唱歌，又会跳舞。"]},{"类":"也、还式","说明":"后分句用也、还表示同样、并列。","代表":"也、还","例子":["他来了，我也来了。"]},{"类":"一边……一边……式","说明":"两个动作同时进行。","代表":"一边……一边……","例子":["他一边走路，一边唱歌。"]}],"怎么认":["分句间是不是平行的，谁也不比谁更进一层？是的。","有没有既……又、也、还、一边……一边？有，多半是并列。","去掉一个分句，剩下的还能成话？能，说明地位平等。"],"辨析":"并列和递进的区别：并列是平行的（既会唱歌，又会跳舞），递进是后句更进一层（不但会唱歌，而且会作曲）。把“不但……而且”换成“既……又”，意思就变了味，说明不是并列。","例句解析":[{"句":"我写作业，弟弟看书。","析":"两个分句说两件事，地位平等，没有主次，是并列复句。"},{"句":"他既会唱歌，又会跳舞。","析":"既……又连接两个平行的本领，是并列复句。"}],"练习":[{"q":"下面哪个是并列复句？","options":["他不但会唱歌，而且会跳舞","他既会唱歌，又会跳舞","因为努力，所以成功","如果下雨，就不去了"],"answer":1,"解析":"既……又表示平行，是并列；其他是递进、因果、假设。","类":"既……又……式"},{"q":"“他来了，我也来了”中，“也”表示？","options":["递进","并列","转折","因果"],"answer":1,"解析":"也表示同样、并列。","类":"也、还式"},{"q":"“他一边走路，一边唱歌”属于？","options":["并列复句","递进复句","选择复句","条件复句"],"answer":0,"解析":"两个动作同时进行，地位平等，是并列。","类":"一边……一边……式"}],"类比":"并列复句像<b>两条平行线</b>：我唱歌，他跳舞。分句地位平等，谁也不从属于谁。","变式表":{"不变":"分句平等并列，无主次，讲几件事或几方面","可变":{"关联词":["用（既…又…/一边…一边…）","不用（你来，我去）"],"内容":["同向并列（又唱又跳）","对照并列（你来我去）"]},"边界":"分句可互换（'又唱又跳'='又跳又唱'）；与递进区别：递进有轻重（'不但…而且…'），并列没有","覆盖已确认":[],"覆盖缺失":["关联词","内容"]},"前置知识":["主谓式","连词","并列式"]},{"name":"递进复句","例子":["他不但会唱歌，而且会跳舞","她不但画画好，而且字也写得漂亮","这本书不仅有趣，还很有道理。","小明不但聪明，而且勤奋。","她不但跑得快，而且跳得远。","这件事不但重要，而且紧急。","他不仅是学生，还是运动员。","教室不但干净，而且整齐。","妈妈不但会做饭，还会织毛衣。","这个问题不但难，而且很关键。","他不但答对了，而且全对。"],"口诀":"关联词：不但……而且、甚至","易错":"递进顺序不能颠倒","讲解":"后分句比前分句更进一层","深讲":"前句说一层意思，后句再进一层，顺序不能颠倒；常用不但……而且、不仅……还、甚至。","分类":[{"类":"不但……而且……式","说明":"最常用的递进搭配。","代表":"不但……而且……","例子":["他不但会唱歌，而且会跳舞。"]},{"类":"不仅……还……式","说明":"不仅引出前一层，还引出更进一层。","代表":"不仅……还……","例子":["她不仅画画好，还写得一手好字。"]},{"类":"甚至式","说明":"后句用甚至，表示进到出乎意料的一层。","代表":"甚至","例子":["他不但会唱歌，甚至会作曲。"]}],"怎么认":["后句是不是比前句更进一层？是的。","有没有不但……而且、不仅……还、甚至？有，多半是递进。","前后换个位置，意思还顺吗？不顺，说明顺序不能颠倒。"],"辨析":"递进和并列的区别：并列是平行的，递进是进一层的。“不但会唱歌，而且会跳舞”后句是新本领、更进一层；“既会唱歌，又会跳舞”只是平行列举。","例句解析":[{"句":"他不但会唱歌，而且会跳舞。","析":"后句跳舞比前句唱歌更进一层，是递进复句。"},{"句":"她不但画画好，而且字也写得漂亮。","析":"后句字漂亮比前句画画好更进一层，是递进复句。"}],"练习":[{"q":"下面哪个是递进复句？","options":["他既会唱歌，又会跳舞","他不但会唱歌，而且会跳舞","他来了，我也来了","你去还是留"],"answer":1,"解析":"不但……而且表示更进一层，是递进。","类":"不但……而且……式"},{"q":"递进复句前后顺序能颠倒吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"递进是进一层的关系，顺序不能颠倒。","类":"不但……而且……式"},{"q":"“她不仅画画好，还写得一手好字”属于？","options":["并列复句","递进复句","转折复句","因果复句"],"answer":1,"解析":"不仅……还表示更进一层，是递进。","类":"不仅……还……式"}],"类比":"递进复句像<b>上台阶</b>：不但……而且……。后一层比前一层更进一层。","变式表":{"不变":"后一分句比前一分句更进一层","可变":{"关联词":["不但…而且…","不仅…还…","甚至"],"程度":["轻→重（不但会唱，而且会跳）"]},"边界":"后重前轻是关键；'而且'后不能是否定（✗不但好，而且不好）；与并列区别：递进不可互换","覆盖已确认":["关联词","程度"],"覆盖缺失":[]},"前置知识":["主谓式","连词"]},{"name":"选择复句","例子":["是去还是留，你定吧","放学后去打球还是回家，你选吧","你是喝茶，还是喝咖啡？","与其在这里等，不如先回家。","宁可站着死，不肯跪着生。","他不是去北京，就是去上海。","与其抱怨，不如行动。","要么好好学，要么别学了。","你喜欢红色，还是喜欢蓝色？","不是你去，就是我去。","与其空想，不如实干。","他宁可走路，也不坐车。","你要么去，要么不去。（'要么…要么…'）","与其坐车，不如走路去。（'与其…不如…'）","你去还是不去？（'还是'用于疑问选择，任选其一）","或者你去，或者我去。（'或者…或者…'，陈述句中任选）"],"口诀":"关联词：或者……或者、是……还是","易错":"“或者”表选择，“还是”用于问句","讲解":"列出两种情况供选择","深讲":"选择复句是列出两种或两种以上情况，供人选择的复句；分句间是选择关系，不是并列，也不是转折；常用或者……或者、是……还是、要么……要么。","分类":[{"类":"或者……或者……式","说明":"在两种情况中选一种，常用于陈述。","代表":"或者……或者……","例子":["你或者去打球，或者回家。"]},{"类":"是……还是……式","说明":"用于问句，让对方选。","代表":"是……还是……","例子":["是去还是留，你定吧。"]},{"类":"要么……要么……式","说明":"在两种情况中选一种，语气较肯定。","代表":"要么……要么……","例子":["要么去，要么留，你定吧。"]}],"怎么认":["是不是在两种情况中选一种？是的。","有没有或者、还是、要么？有，多半是选择。","是不是在问对方选哪个？是的，多半是是……还是。"],"辨析":"选择和并列的区别：并列是两件事都发生（既唱歌又跳舞），选择是二选一（或者唱歌，或者跳舞）。“或者”表选择，“还是”用于问句，不要混。","例句解析":[{"句":"是去还是留，你定吧。","析":"是……还是让对方在去和留中选，是选择复句。"},{"句":"放学后去打球还是回家，你选吧。","析":"打球和回家二选一，是选择复句。"}],"练习":[{"q":"下面哪个是选择复句？","options":["他既会唱歌，又会跳舞","是去还是留，你定吧","因为努力，所以成功","虽然累，但是坚持"],"answer":1,"解析":"是……还是让对方选，是选择。","类":"是……还是……式"},{"q":"“或者”一般表？","options":["并列","选择","转折","因果"],"answer":1,"解析":"或者列出两种情况供选择。","类":"或者……或者……式"},{"q":"“要么去，要么留”属于？","options":["选择复句","并列复句","假设复句","条件复句"],"answer":0,"解析":"要么……要么是二选一，是选择。","类":"要么……要么……式"}],"类比":"选择复句像<b>岔路口</b>：要么……要么……。非此即彼，必须选一条。","变式表":{"不变":"列出两种以上可能，选其一","可变":{"关联词":["或者…或者…","不是…就是…","与其…不如…"],"选择":["任选（去或不去）","取舍（与其…不如…）"]},"边界":"'还是'用于疑问选择（去还是不去？），'或者'用于陈述；'与其…不如…'表取舍，有褒贬","覆盖已确认":[],"覆盖缺失":["关联词","选择"]},"前置知识":["主谓式","连词"]},{"name":"转折复句","例子":["虽然下雨，但是没耽误","虽然我很累，但是我坚持跑完了","虽然下雨，但是运动会照常举行。","他虽然累，却很开心。","尽管困难很多，我们还是完成了。","虽然他年纪小，但是懂得很多。","这件衣服虽然贵，但是质量好。","虽然天黑了，但是路灯亮了。","他虽然失败了，却没有气馁。","尽管下着大雨，农民还在抢收。","这道题虽然难，但是我做出来了。","虽然他病了，但是坚持上课。","他尽管很累，还是坚持下来了。（'尽管…还是…'）","天气很冷，他却穿得很单薄。（'却'表转折）"],"口诀":"关联词：虽然……但是、尽管……还是","易错":"转折连词不能单独省略后半","讲解":"前后意思相反或相对","深讲":"转折复句是前后意思相反或相对的复句；前句先说一层意思，后句一转，说出相反或相对的意思；常用虽然……但是、尽管……还是。","分类":[{"类":"虽然……但是……式","说明":"最常用的转折搭配。","代表":"虽然……但是……","例子":["虽然下雨，但是没耽误。"]},{"类":"尽管……还是……式","说明":"尽管让步，还是表示转折的结果。","代表":"尽管……还是……","例子":["尽管很累，他还是坚持跑完了。"]},{"类":"转折词单独式","说明":"只用可是、但是、却表示转折。","代表":"可是、但是、却","例子":["他很累，可是还坚持着。"]}],"怎么认":["前后意思是不是相反或相对？是的。","有没有虽然……但是、尽管……还是、可是？有，多半是转折。","去掉后句，前句的意思还完整吗？不完整，说明转折在后句。"],"辨析":"转折和因果的区别：转折是前后相反（虽然下雨，但是没耽误），因果是前因后果（因为下雨，所以没去）。看前后是相反还是因果，不要只看有没有但是。","例句解析":[{"句":"虽然下雨，但是没耽误。","析":"前句下雨，后句没耽误，意思一转，是转折复句。"},{"句":"虽然我很累，但是我坚持跑完了。","析":"累和坚持跑完相对，是转折复句。"}],"练习":[{"q":"下面哪个是转折复句？","options":["因为努力，所以成功","虽然下雨，但是没耽误","如果下雨，就不去了","他既会唱歌，又会跳舞"],"answer":1,"解析":"虽然……但是表示转折。","类":"虽然……但是……式"},{"q":"“尽管很累，他还是坚持跑完了”属于？","options":["转折复句","因果复句","递进复句","并列复句"],"answer":0,"解析":"尽管……还是表示转折。","类":"尽管……还是……式"},{"q":"转折复句前后意思的关系是？","options":["平行","相反或相对","因果","选择"],"answer":1,"解析":"转折是前后相反或相对。","类":"虽然……但是……式"}],"类比":"转折就像\"先扬后抑\"：前面夸一句，后面\"但是\"一转才是真心话。","变式表":{"不变":"前后意思相反或相对，'虽然…但是…'","可变":{"关联词":["虽然…但是…","尽管…还是…","却"],"转折":["轻转（虽然累，但是开心）","重转（虽败犹荣）"]},"边界":"'但是'前可省略'虽然'；转折连词在主语后（'他虽然累，但是…'主语一致时'虽然'在主语后）；与让步区别：让步是'即使…也…'（未然），转折是已然","覆盖已确认":["转折"],"覆盖缺失":["关联词"]},"前置知识":["主谓式","连词"]},{"name":"因果复句","例子":["因为努力，所以成功","因为我生病了，所以没去上学","因为努力，所以他成功了。","由于下雨，比赛推迟了。","他之所以迟到，是因为堵车。","因为天气冷，所以多穿了衣服。","既然你来了，就一起吃饭吧。","因为坚持，他终于学会了游泳。","由于缺水，禾苗枯黄了。","他因为生病，所以请假了。","因为准备充分，考试很顺利。","之所以成功，是因为从不放弃。","由于下雨，运动会取消了。（'由于'）","既然来了，就多住几天。（'既然…就…'，表已然原因）","因为堵车，所以他迟到了。（口语：因为…所以…）","由于天气原因，航班延误。（书面：由于…）"],"口诀":"关联词：因为……所以、由于","易错":"因果倒置会造成逻辑错误","讲解":"前因后果","深讲":"因果复句是前因后果的复句；前句说原因，后句说结果，顺序一般是先因后果，也可以先果后因；常用因为……所以、由于……因此。","分类":[{"类":"因为……所以……式","说明":"最常用的因果搭配，先因后果。","代表":"因为……所以……","例子":["因为努力，所以成功。"]},{"类":"由于……因此……式","说明":"由于引出原因，因此引出结果。","代表":"由于……因此……","例子":["由于下雨，因此我们没去公园。"]},{"类":"先果后因式","说明":"先说结果，后说原因。","代表":"……，因为……","例子":["他没去上学，因为生病了。"]}],"怎么认":["前后是不是原因和结果？是的。","有没有因为……所以、由于……因此？有，多半是因果。","问“为什么”，能问出前句吗？能，说明前句是原因。"],"辨析":"因果和条件的区别：因果是原因已经发生、结果跟着来（因为生病，所以没去）；条件是条件还没发生、结果跟着条件来（只有努力，才能成功）。看原因是不是已经发生了。","例句解析":[{"句":"因为努力，所以成功。","析":"努力是原因，成功是结果，是因果复句。"},{"句":"因为我生病了，所以没去上学。","析":"生病是原因，没去上学是结果，是因果复句。"}],"练习":[{"q":"下面哪个是因果复句？","options":["虽然累，但是坚持","因为努力，所以成功","如果下雨，就不去了","他既会唱歌，又会跳舞"],"answer":1,"解析":"因为……所以表示因果。","类":"因为……所以……式"},{"q":"“他没去上学，因为生病了”中，原因是？","options":["没去上学","生病了","上学","他"],"answer":1,"解析":"生病了是原因，没去上学是结果，先果后因。","类":"先果后因式"},{"q":"因果倒置会造成？","options":["逻辑错误","语气变化","意思不变","变成并列"],"answer":0,"解析":"原因和结果颠倒，逻辑就错了。","类":"因为……所以……式"}],"类比":"因果就像\"多米诺\"：前一张牌倒了（因），后一张跟着倒（果）。","变式表":{"不变":"前因后果，讲为什么","可变":{"关联词":["因为…所以…","由于…因此…","既然…就…"],"语体":["口语（因为…所以…）","书面（由于…因此…）"]},"边界":"'因为…所以…'不与'因此'混搭（✗因为…因此…）；'既然'表已然原因（既然来了，就住下）；因果可倒装（'因为累，所以睡'='睡，因为累'，强调不同）","覆盖已确认":[],"覆盖缺失":["关联词","语体"]},"前置知识":["主谓式","连词"]},{"name":"假设复句","例子":["如果下雨，就不去了","如果周末不下雨，我们就去爬山","如果下雨，我们就不去了。","假如我是鸟，就能自由飞翔。","要是早点出发，就不会迟到了。","如果努力，就一定有收获。","假如下雪，学校就放假了。","如果我是你，就会道歉。","要是没有水，植物会枯死。","假如时光倒流，我会更珍惜。","如果明天晴，就去爬山。","要是认真听，就能听懂。","假如我是鸟，就飞向蓝天。（'假如…就…'）","要是下雨，我们就不去了。（'要是…就…'）"],"口诀":"关联词：如果……就、假如","易错":"假设与条件的区别：假设多为未然","讲解":"假设条件下的结果","深讲":"假设复句是假设条件下的结果的复句；前句假设一种还没发生的情况，后句说在这种情况下会怎么样；常用如果……就、假如……就、要是……就。","分类":[{"类":"如果……就……式","说明":"最常用的假设搭配。","代表":"如果……就……","例子":["如果下雨，就不去了。"]},{"类":"假如……就……式","说明":"假如引出假设。","代表":"假如……就……","例子":["假如明天不下雨，我们就去爬山。"]},{"类":"要是……就……式","说明":"要是引出假设，口语常用。","代表":"要是……就……","例子":["要是努力，就会进步。"]}],"怎么认":["前句是不是在假设一种还没发生的情况？是的。","有没有如果、假如、要是？有，多半是假设。","后句是不是在说假设成立会怎么样？是的。"],"辨析":"假设和条件的区别：假设多为未然（如果下雨，就不去了：雨还没下）；条件多为必要或充分（只有努力，才能成功：努力是必要条件）。看前句是假设还是条件。","例句解析":[{"句":"如果下雨，就不去了。","析":"下雨是假设，还没发生；不去了是假设下的结果。"},{"句":"如果周末不下雨，我们就去爬山。","析":"周末不下雨是假设，去爬山是假设下的结果。"}],"练习":[{"q":"下面哪个是假设复句？","options":["因为努力，所以成功","虽然累，但是坚持","如果下雨，就不去了","只有努力，才能成功"],"answer":2,"解析":"如果……就表示假设。","类":"如果……就……式"},{"q":"假设复句前句的情况一般是？","options":["已经发生","还没发生","正在发生","不会发生"],"answer":1,"解析":"假设多为未然，还没发生。","类":"如果……就……式"},{"q":"“假如明天不下雨，我们就去爬山”属于？","options":["假设复句","条件复句","因果复句","选择复句"],"answer":0,"解析":"假如……就表示假设。","类":"假如……就……式"}],"类比":"假设复句像\"<b>如果</b>\"游戏：如果下雨，就不去。前面是假想条件，后面是结果。","变式表":{"不变":"假设一种情况，讲'如果…就…'（未然）","可变":{"关联词":["如果…就…","假如…就…","要是…就…"],"假设":["与事实相反（如果我是鸟）","可能实现（如果下雨）"]},"边界":"假设是未然（还没发生）；与条件区别：条件是已然/规律（'只有…才…'），假设是设想；'即使…也…'是让步假设","覆盖已确认":["假设"],"覆盖缺失":["关联词"]},"前置知识":["主谓式","连词"]},{"name":"条件复句","例子":["只有努力，才能成功","只有多练习，才能写好字","只要下雨，地就会湿。","无论多难，我们都不放弃。","不管刮风下雨，他都坚持跑步。","只有团结，才能战胜困难。","只要有信心，就没有办不成的事。","无论走到哪里，都要诚实。","不管多晚，妈妈都等我回家。","只有多读多写，作文才能进步。","只要肯动脑，就没有难题。","除非你去，否则我不去。（'除非…才…'）","无论多难，我们都要坚持。（'无论…都…'，无条件）","只有努力，才能成功。（'只有…才…'，唯一条件）","只要下雨，地就湿。（'只要…就…'，充分条件）"],"口诀":"关联词：只有……才、只要……就","易错":"“只有……才”表必要条件，“只要……就”表充分条件","讲解":"条件与结果","深讲":"条件复句是条件与结果的复句；前句说条件，后句说在这个条件下会怎么样；条件分必要条件和充分条件，还有无条件。","分类":[{"类":"只有……才……式","说明":"必要条件：缺了这个条件就不行。","代表":"只有……才……","例子":["只有努力，才能成功。"]},{"类":"只要……就……式","说明":"充分条件：有了这个条件就够了。","代表":"只要……就……","例子":["只要多练习，就能写好字。"]},{"类":"无论……都……式","说明":"无条件：不管什么条件，结果都一样。","代表":"无论……都……","例子":["无论多难，我们都要坚持。"]}],"怎么认":["前句是不是在说条件？是的。","有没有只有……才、只要……就、无论……都？有，多半是条件。","问“在什么条件下”，能问出前句吗？能，说明前句是条件。"],"辨析":"只有……才和只要……就的区别：只有……才是必要条件（缺了不行：只有努力，才能成功）；只要……就是充分条件（有了就够：只要多练习，就能写好字）。不要混。","例句解析":[{"句":"只有努力，才能成功。","析":"努力是必要条件，缺了不行，是条件复句。"},{"句":"只有多练习，才能写好字。","析":"多练习是必要条件，是条件复句。"}],"练习":[{"q":"下面哪个是条件复句？","options":["因为努力，所以成功","如果下雨，就不去了","只有努力，才能成功","虽然累，但是坚持"],"answer":2,"解析":"只有……才表示必要条件，是条件。","类":"只有……才……式"},{"q":"“只有……才”表？","options":["充分条件","必要条件","假设","因果"],"answer":1,"解析":"只有……才表示缺了这个条件就不行。","类":"只有……才……式"},{"q":"“只要多练习，就能写好字”中，“只要……就”表？","options":["必要条件","充分条件","假设","转折"],"answer":1,"解析":"只要……就表示有了这个条件就够了。","类":"只要……就……式"}],"类比":"条件复句像开门的<b>钥匙</b>：只有努力，才能成功。条件是门，结果是门后的房间。","变式表":{"不变":"前一分句是后一分句的条件","可变":{"关联词":["只有…才…","只要…就…","无论…都…","除非…才…"],"条件":["唯一（只有…才…）","充分（只要…就…）","无条件（无论…都…）"]},"边界":"'只有…才…'表唯一条件（只有努力，才成功）；'只要…就…'表充分条件；与假设区别：条件多是规律/已然，假设是设想/未然","覆盖已确认":[],"覆盖缺失":["关联词","条件"]},"前置知识":["主谓式","连词"]}],"name":"复句的类型（7种）"},{"id":"guanlianci","name":"关联词（13组）","items":[{"name":"因为…所以…","讲解":"表示因果关系：前因后果。","深讲":"因为……所以……表示因果关系：前句说原因，后句说结果；前后主语相同，关联词放主语后；主语不同，关联词放主语前；因为和但是不能配对，不能说“因为……但是……”。","分类":[{"类":"因为……所以……式","说明":"最常用的因果搭配，先因后果。","代表":"因为……所以……","例子":["因为下雨，所以运动会取消了。"]},{"类":"由于……因此……式","说明":"由于引出原因，因此引出结果。","代表":"由于……因此……","例子":["由于生病，因此他没去上学。"]},{"类":"先果后因式","说明":"先说结果，后说原因。","代表":"……，因为……","例子":["他没去上学，因为生病了。"]}],"怎么认":["前后是不是原因和结果？是的。","有没有因为、由于这类表原因的词？有。","问“为什么”，能问出前句吗？能，说明前句是原因。"],"辨析":"因为……所以……不能和但是配对。“因为下雨，但是没耽误”是错的：因为表原因，但是表转折，两者不能混用。想表转折，用虽然……但是。","例句解析":[{"句":"因为下雨，所以运动会取消了。","析":"下雨是原因，运动会取消是结果，是因果关系。"},{"句":"因为他努力，所以考了第一。","析":"努力是原因，考第一是结果；前后主语不同，关联词在句首。"}],"练习":[{"q":"下面哪个搭配是对的？","options":["因为……但是……","因为……所以……","因为……而且……","因为……还是……"],"answer":1,"解析":"因为配所以表因果，不能配但是。","类":"因为……所以……式"},{"q":"“他没去上学，因为生病了”属于？","options":["先因后果","先果后因","转折","假设"],"answer":1,"解析":"先说结果没去上学，后说原因生病了。","类":"先果后因式"},{"q":"“由于生病，因此他没去上学”中，原因是？","options":["没去上学","生病","他","因此"],"answer":1,"解析":"由于引出原因生病，因此引出结果。","类":"由于……因此……式"}],"例子":["因为下雨，所以运动会取消了","因为他努力，所以考了第一","因为下雨，所以地面湿了。","因为生病，所以他请假了。","因为坚持锻炼，所以身体很好。","因为粗心，所以他算错了题。","因为天黑，所以打开了路灯。","因为缺水，所以禾苗枯了。","因为准备充分，所以考得很好。","因为帮助别人，所以大家喜欢他。","因为起得早，所以赶上了火车。","因为爱读书，所以知识丰富。"],"口诀":"前因后果","易错":"不能说“因为…但是…”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["因为…所以…","含义：表因果（原因→结果）；用法：前因后果连用；例句：因为下雨，所以运动会取消了；误用：❌“因为下雨，但是没耽误”（“因为”不能和“但是”配对）→ ✅“虽然下雨，但是没耽误”"],["虽然…但是…","含义：表转折（让步→转折）；用法：前让后转连用；例句：虽然下雨了，但是我们照常上课；误用：❌“因为……但是……”"]]},"前置知识":["因果复句"],"类比":"像一座桥：<b>因为</b>是桥这头的原因，<b>所以</b>是桥那头的结果，原因过去了，结果才过来。下雨是原因，运动会取消是结果；桥不能搭到“但是”那边去，因果不能配转折。"},{"name":"如果…就…","讲解":"表示假设：假设条件下的结果。","深讲":"如果……就……表示假设：前句假设一种还没发生的情况，后句说在这种情况下会怎么样；前后主语相同，关联词放主语后；不同，放主语前。","分类":[{"类":"如果……就……式","说明":"最常用的假设搭配。","代表":"如果……就……","例子":["如果明天下雨，我们就不去春游了。"]},{"类":"假如……就……式","说明":"假如引出假设。","代表":"假如……就……","例子":["假如你来，我就告诉你。"]},{"类":"要是……就……式","说明":"要是引出假设，口语常用。","代表":"要是……就……","例子":["要是努力，就会进步。"]}],"怎么认":["前句是不是在假设还没发生的情况？是的。","有没有如果、假如、要是？有。","后句是不是在说假设成立会怎么样？是的。"],"辨析":"如果……就……和只有……才……的区别：如果表假设（如果下雨，就不去了），只有表必要条件（只有努力，才能成功）。看前句是假设还是必要条件。","例句解析":[{"句":"如果明天下雨，我们就不去春游了。","析":"明天下雨是假设，不去春游是假设下的结果。"},{"句":"如果你来，我就告诉你。","析":"你来是假设，告诉你是假设下的结果；前后主语不同，关联词在主语前。"}],"练习":[{"q":"下面哪个是假设关系？","options":["因为努力，所以成功","如果下雨，就不去了","只有努力，才能成功","虽然累，但是坚持"],"answer":1,"解析":"如果……就表示假设。","类":"如果……就……式"},{"q":"“假如你来，我就告诉你”属于？","options":["假设","条件","因果","转折"],"answer":0,"解析":"假如……就表示假设。","类":"假如……就……式"},{"q":"假设的情况一般是？","options":["已经发生","还没发生","正在发生","不会发生"],"answer":1,"解析":"假设多为未然，还没发生。","类":"如果……就……式"}],"例子":["如果明天下雨，我们就不去春游了","如果你来，我就告诉你","如果明天下雨，我们就待在家里。","如果你有困难，就告诉我。","如果努力学习，就能取得好成绩。","如果他来了，就一起出发。","如果不抓紧，就来不及了。","如果你同意，我们就签约。","如果天晴，我们就去放风筝。","如果累了，就休息一会儿。","如果遇到难题，就问老师。","如果我是你，就会接受。"],"口诀":"假设条件","易错":"假设多为还没发生的事","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["如果…就…","含义：表假设；用法：假设成立，结果才来；例句：如果明天下雨，我们就不去春游了；误用：混淆假设与必要条件：看前句是假设还是必要条件"],["只有…才…","含义：表必要条件；用法：缺了不行；例句：只有努力，才能成功；误用：❌“如果努力，才能成功”"]]},"前置知识":["假设复句"],"类比":"像一场“如果”游戏：前面按下<b>如果</b>这个假想开关，后面<b>就</b>亮起结果。明天下雨还没发生，只是先假设；假设成立了，不去春游这个结果才跟着来。"},{"name":"虽然…但是…","讲解":"表示转折：前后意思相反或相对。","深讲":"虽然……但是……表示转折：前句先让一步，后句一转，说出相反或相对的意思；前后主语相同，关联词放主语后；不同，放主语前；转折的后句不能省；小学阶段用了「虽然」，后句要用「但是」「可是」「却」来呼应。","分类":[{"类":"虽然……但是……式","说明":"最常用的转折搭配。","代表":"虽然……但是……","例子":["虽然下雨了，但是我们照常上课。"]},{"类":"尽管……还是……式","说明":"尽管让步，还是表示转折的结果。","代表":"尽管……还是……","例子":["尽管他很累，还是坚持跑完了。"]},{"类":"虽然……却……式","说明":"后一分句用「却」呼应「虽然」，「却」放在后一分句的主语后面。","代表":"虽然……却……","例子":["虽然下着雨，运动会却照常举行。"]}],"怎么认":["前后意思是不是相反或相对？是的。","有没有虽然、尽管这类让步词？有。","去掉后句，前句的意思还完整吗？不完整，说明转折在后句。"],"辨析":"虽然……但是……和因为……所以……的区别：虽然表转折（虽然下雨，但是照常上课），因为表因果（因为下雨，所以取消）。不能说“因为……但是……”。","例句解析":[{"句":"虽然下雨了，但是我们照常上课。","析":"下雨和照常上课相对，是转折关系。"},{"句":"虽然他很累，但是坚持跑完了。","析":"累和坚持跑完相对，是转折关系；前后主语相同，关联词在主语后。"}],"练习":[{"q":"下面哪个是转折关系？","options":["因为努力，所以成功","虽然下雨，但是照常上课","如果下雨，就不去了","只有努力，才能成功"],"answer":1,"解析":"虽然……但是表示转折。","类":"虽然……但是……式"},{"q":"“尽管他很累，还是坚持跑完了”属于？","options":["转折","因果","递进","并列"],"answer":0,"解析":"尽管……还是表示转折。","类":"尽管……还是……式"},{"q":"“因为……但是……”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"因为表原因，但是表转折，不能配对。","类":"虽然……但是……式"}],"例子":["虽然下雨了，但是我们照常上课","虽然他很累，但是坚持跑完了","虽然天气很冷，但是他坚持跑步。","虽然作业很多，但是他很快写完了。","虽然失败了，但是他不灰心。","虽然年纪小，但是他很懂事。","虽然路很远，但是我们走到了。","虽然很累，但是妈妈还在做饭。","虽然下雨，但是比赛继续进行。","虽然他病了，但是坚持上学。","虽然时间紧，但是任务完成了。","虽然贵了点，但是很实用。"],"口诀":"先让后转","易错":"前后意思要相反或相对","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["虽然…但是…","含义：表转折；用法：前让后转连用；例句：虽然下雨了，但是我们照常上课；误用：❌“因为……但是……”"],["因为…所以…","含义：表因果；用法：前因后果连用；例句：因为下雨，所以运动会取消了；误用：❌“虽然……所以……”"]]},"前置知识":["转折复句"],"类比":"像先退一步再转身：<b>虽然</b>先让一步，下雨了；<b>但是</b>猛地一转，照常上课才是真心话。前后意思相反相对，转折在后句，后句不能省。"},{"name":"不但…而且…","讲解":"表示递进：后分句比前分句更进一层。","深讲":"不但……而且……表示递进：后句比前句更进一层，顺序不能颠倒；前后主语相同，关联词放主语后；不同，放主语前。","分类":[{"类":"不但……而且……式","说明":"最常用的递进搭配。","代表":"不但……而且……","例子":["他不但学习好，而且爱运动。"]},{"类":"不仅……还……式","说明":"不仅引出前一层，还引出更进一层。","代表":"不仅……还……","例子":["她不仅画画好，还写得一手好字。"]},{"类":"不但……，甚至……式","说明":"后句用甚至，表示进到出乎意料的一层。","代表":"不但……，甚至……","例子":["他不但会唱歌，甚至会作曲。"]}],"怎么认":["后句是不是比前句更进一层？是的。","有没有不但、不仅、甚至？有。","前后换个位置，意思还顺吗？不顺，说明顺序不能颠倒。"],"辨析":"不但……而且……和既……又……的区别：不但表递进（更进一层），既表并列（平行）。“不但学习好，而且爱运动”是递进；“既聪明又勤奋”是并列。","例句解析":[{"句":"他不但学习好，而且爱运动。","析":"爱运动比学习好更进一层，是递进关系。"},{"句":"她不但画画好，而且字也写得漂亮。","析":"字漂亮比画画好更进一层，是递进关系。"}],"练习":[{"q":"下面哪个是递进关系？","options":["他既聪明又勤奋","他不但学习好，而且爱运动","他来了，我也来了","因为努力，所以成功"],"answer":1,"解析":"不但……而且表示更进一层。","类":"不但……而且……式"},{"q":"递进关系前后顺序能颠倒吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"递进是进一层的关系，顺序不能颠倒。","类":"不但……而且……式"},{"q":"“她不仅画画好，还写得一手好字”属于？","options":["并列","递进","转折","因果"],"answer":1,"解析":"不仅……还表示更进一层。","类":"不仅……还……式"}],"例子":["他不但学习好，而且爱运动","她不但画画好，而且字也写得漂亮","他不但学习好，而且体育好。","这家店不但便宜，而且质量好。","小明不但聪明，而且勤奋。","春天不但温暖，而且多彩。","她不但会唱歌，而且会弹琴。","这本书不但有趣，而且有用。","他不但跑得快，而且跳得高。","妈妈不但会做饭，而且会织毛衣。","这个问题不但重要，而且紧急。","教室不但干净，而且明亮。"],"口诀":"层层递进","易错":"递进顺序不能颠倒","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["不但…而且…","含义：表递进（更进一层）；用法：后句比前句更进一层；例句：他不但学习好，而且爱运动；误用：❌“他既学习好，而且爱运动”（混用）"],["既…又…","含义：表并列（平行）；用法：前后平行；例句：他既聪明又勤奋；误用：❌“他不但聪明，又勤奋”"]]},"前置知识":["递进复句"],"类比":"像上台阶：<b>不但</b>是一级台阶，学习好；<b>而且</b>是更高一级，爱运动。一步比一步高，顺序不能颠倒，倒过来台阶就塌了。"},{"name":"只有…才…","讲解":"表示必要条件：缺了这个条件就不行。","深讲":"只有……才……表示必要条件：缺了这个条件就不行；别和只要……就……搞混，那是充分条件，有了就够了。","分类":[{"类":"只有……才……式","说明":"最常用的必要条件搭配。","代表":"只有……才……","例子":["只有努力，才能成功。"]},{"类":"唯有……才……式","说明":"唯有和只有意思一样，语气较正式。","代表":"唯有……才……","例子":["唯有努力，才有收获。"]},{"类":"除非……才……式","说明":"除非引出必要条件，意思和只有一样。","代表":"除非……才……","例子":["除非努力，才会成功。"]}],"怎么认":["前句是不是缺了就不行的条件？是的。","有没有只有、唯有、除非？有。","把前句去掉，后句还能成立吗？不能，说明前句是必要条件。"],"辨析":"只有……才……和只要……就……的区别：只有是必要条件（缺了不行：只有努力，才能成功），只要是充分条件（有了就够：只要多练习，就能写好字）。","例句解析":[{"句":"只有努力，才能成功。","析":"努力是必要条件，缺了不行，是条件关系。"},{"句":"只有多练习，才能写好字。","析":"多练习是必要条件，是条件关系。"}],"练习":[{"q":"下面哪个是必要条件？","options":["只要多练习，就能写好字","只有努力，才能成功","如果下雨，就不去了","因为努力，所以成功"],"answer":1,"解析":"只有……才表示缺了不行。","类":"只有……才……式"},{"q":"“除非努力，才会成功”属于？","options":["必要条件","充分条件","假设","因果"],"answer":0,"解析":"除非……才和只有……才一样，表必要条件。","类":"除非……才……式"},{"q":"“唯有努力，才有收获”中，“唯有”的意思是？","options":["只要","只有","如果","因为"],"answer":1,"解析":"唯有和只有意思一样，表必要条件。","类":"唯有……才……式"}],"例子":["只有努力，才能成功","只有多练习，才能写好字","只有努力学习，才能考上好学校。","只有团结一心，才能战胜困难。","只有诚实，才能赢得信任。","只有坚持，梦想才能实现。","只有爱护环境，家园才更美丽。","只有认真听讲，才能真正学会。","只有付出，才有回报。","只有经历风雨，才能见彩虹。","只有打好基础，才能走得更远。"],"口诀":"必要条件","易错":"别和“只要…就…”搞混（那是充分条件）","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["只有…才…","含义：表必要条件（缺了不行）；用法：只有+条件，才+结果；例句：只有努力，才能成功；误用：❌“只要努力，才能成功”（前后不配套）"],["只要…就…","含义：表充分条件（有了就够）；用法：只要+条件，就+结果；例句：只要多练习，就能写好字；误用：❌“只有多练习，就能写好字”"]]},"前置知识":["条件复句"],"类比":"像一把钥匙开一把锁：<b>只有</b>是缺了就不行的钥匙，努力；<b>才</b>开得了成功这把锁。没有钥匙，门打不开；这和“只要…就…”不同，那是有了就够了。"},{"name":"无论…都…","讲解":"表示无条件：不管什么情况，结果都一样。","深讲":"无论……都……表示无条件：不管什么情况，结果都一样；无论后面常跟疑问词，如谁、哪儿、什么。","分类":[{"类":"无论……都……式","说明":"最常用的无条件搭配。","代表":"无论……都……","例子":["无论刮风下雨，他都按时到校。"]},{"类":"不管……都……式","说明":"不管和无论意思一样，口语常用。","代表":"不管……都……","例子":["不管多难，我们都要坚持。"]},{"类":"无论+疑问词式","说明":"无论后跟疑问词，表示任何情况都一样。","代表":"无论谁、哪儿、什么……都……","例子":["无论谁问，他都不说。"]}],"怎么认":["不管什么情况，结果是不是都一样？是的。","有没有无论、不管？有。","无论后是不是跟了疑问词（谁、哪儿、什么）？是的，多半是无条件。"],"辨析":"无论……都……和如果……就……的区别：无论表无条件（不管怎样结果都一样），如果表假设（假设成立结果才来）。看结果是不是不依赖条件。","例句解析":[{"句":"无论刮风下雨，他都按时到校。","析":"刮风下雨与否，结果都一样按时到校，是无条件。"},{"句":"无论谁问，他都不说。","析":"谁问都一样不说，是无条件；无论后跟疑问词谁。"}],"练习":[{"q":"下面哪个是无条件关系？","options":["如果下雨，就不去了","无论刮风下雨，他都按时到校","只有努力，才能成功","因为努力，所以成功"],"answer":1,"解析":"无论……都表示不管怎样结果都一样。","类":"无论……都……式"},{"q":"“无论谁问，他都不说”中，“无论”后跟的是？","options":["名词","疑问词","动词","形容词"],"answer":1,"解析":"无论后可跟疑问词谁。","类":"无论+疑问词式"},{"q":"“不管多难，我们都要坚持”属于？","options":["无条件","假设","必要条件","因果"],"answer":0,"解析":"不管……都和无论……都一样，表无条件。","类":"不管……都……式"}],"例子":["无论刮风下雨，他都按时到校","无论谁问，他都不说","无论多么困难，我们都不放弃。","无论走到哪里，我都想念家乡。","无论多忙，妈妈都记得我的生日。","无论结果如何，我们都尽力了。","无论多晚，他都坚持把作业写完。","无论谁问起，他都实话实说。","无论天气怎样，运动会都照常举行。","无论多累，战士们都不停下脚步。","无论遇到什么，都要勇敢面对。"],"口诀":"条件再多都不怕","易错":"“无论”后可跟疑问词：无论谁/哪儿/什么","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["无论…都…","含义：表无条件（不管怎样结果都一样）；用法：结果不依赖条件；例句：无论刮风下雨，他都按时到校；误用：❌“无论下雨，我们就不去了”（“无论”后不能接单一假设结果）"],["如果…就…","含义：表假设；用法：假设成立结果才来；例句：如果明天下雨，我们就不去春游了；误用：看结果是不是不依赖条件：是→用“无论”，否→用“如果”"]]},"前置知识":["条件复句"],"类比":"像风雨里的定盘星：<b>无论</b>刮风下雨、无论谁问，结果都纹丝不动——都按时到校、都不说。情况换来换去，结果一个样，这就是无条件。"},{"name":"既…又…","讲解":"表示并列：两个方面同时成立。","深讲":"既……又……表示并列：两个方面同时成立，地位平等；前后感情色彩要一致，不能既好又坏。","分类":[{"类":"品格并列式","说明":"并列的两个方面都是人的品格、优点。","代表":"既……又……","例子":["他既聪明又勤奋。"]},{"类":"特点并列式","说明":"并列的两个方面都是事物的特点。","代表":"既……又……","例子":["这件衣服既好看又便宜。"]}],"怎么认":["两个方面是不是同时成立、地位平等？是的。","有没有既……又……？有。","前后感情色彩一致吗？一致，才是规范的既……又……。"],"辨析":"既……又……和不但……而且……的区别：既表并列（平行：既聪明又勤奋），不但表递进（更进一层：不但聪明，而且勤奋得出了名）。看后句是不是更进一层。","例句解析":[{"句":"他既聪明又勤奋。","析":"聪明和勤奋同时成立、地位平等，是并列关系。"},{"句":"这件衣服既好看又便宜。","析":"好看和便宜都是这件衣服的特点，地位平等，是并列关系。"}],"练习":[{"q":"下面哪个是并列关系？","options":["他不但聪明，而且勤奋","他既聪明又勤奋","因为聪明，所以成功","如果聪明，就成功"],"answer":1,"解析":"既……又表示平行并列。","类":"品格并列式"},{"q":"“既……又……”前后感情色彩要？","options":["相反","一致","无关","递进"],"answer":1,"解析":"前后感情色彩要一致，不能既好又坏。","类":"品格并列式"},{"q":"“这件衣服既好看又便宜”属于？","options":["并列","递进","转折","因果"],"answer":0,"解析":"好看和便宜平行，是并列。","类":"特点并列式"}],"例子":["他既聪明又勤奋","这件衣服既好看又便宜","这苹果既大又甜。","教室里既干净又安静。","她既会唱歌又会跳舞。","小狗既可爱又听话。","秋天既凉爽又美丽。","他既是班长又是课代表。","这个问题既有趣又有意义。","湖水既清又静。"],"口诀":"两个优点一起夸","易错":"前后感情色彩要一致（不能既好又坏）","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["既…又…","含义：表并列（平行）；用法：前后平行；例句：他既聪明又勤奋；误用：❌“他既学习好，而且爱运动”"],["不但…而且…","含义：表递进（更进一层）；用法：后句更进一层；例句：他不但学习好，而且爱运动；误用：看后句是不是更进一层：是→用“不但”，否→用“既”"]]},"前置知识":["并列复句"],"类比":"像双胞胎肩并肩：既聪明又勤奋，两个优点同时成立、地位平等，谁也不压谁；但双胞胎得穿同色衣服，前后感情色彩要一致，不能一个好一个坏。"},{"name":"不是…而是…","讲解":"表示选择：否定前者，肯定后者。","深讲":"不是……而是……表示选择：否定前者，肯定后者；前后要是同一类事物才能这样选，不能拿不同类的东西比。","分类":[{"类":"否定原因式","说明":"否定一个原因，肯定另一个原因。","代表":"不是……而是……","例子":["他不是不认真，而是方法不对。"]},{"类":"否定事物式","说明":"否定一个事物，肯定另一个事物。","代表":"不是……而是……","例子":["这不是苹果，而是梨子。"]}],"怎么认":["是不是先否定一个，再肯定一个？是的。","有没有不是……而是……？有。","前后是不是同一类事物？是的，才能这样选。"],"辨析":"不是……而是……和是……还是……的区别：不是……而是……是说话人自己选定后者（不是苹果，而是梨子）；是……还是……是让对方选（是苹果还是梨子）。","例句解析":[{"句":"他不是不认真，而是方法不对。","析":"否定不认真，肯定方法不对，是选择关系。"},{"句":"我不是不想去，而是有事。","析":"否定不想去，肯定有事，是选择关系。"}],"练习":[{"q":"下面哪个是“不是……而是……”关系？","options":["是去还是留","他不是不认真，而是方法不对","因为认真，所以成功","虽然累，但是坚持"],"answer":1,"解析":"先否定不认真，再肯定方法不对。","类":"否定原因式"},{"q":"“这不是苹果，而是梨子”属于？","options":["选择","并列","因果","转折"],"answer":0,"解析":"否定苹果，肯定梨子，是选择。","类":"否定事物式"},{"q":"“不是……而是……”前后要是？","options":["不同类事物","同一类事物","无关事物","相反事物"],"answer":1,"解析":"前后要是同一类事物才能这样选。","类":"否定事物式"}],"例子":["他不是不认真，而是方法不对","我不是不想去，而是有事","他不是不努力，而是方法不对。","这不是失败，而是新的开始。","成功不是偶然，而是坚持的结果。","他不是生病，而是有事出去了。","这不是批评，而是真诚的建议。","爱不是占有，而是付出。","他不是不想去，而是没时间。","这道题不是不会，而是有点难。","真正的朋友不是锦上添花，而是雪中送炭。","学习不是为了分数，而是为了成长。"],"口诀":"否定一个，肯定一个","易错":"前后要是同一类事物才能这样选","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["不是…而是…","含义：说话人自己选定后者；用法：否定前者、肯定后者；例句：他不是不认真，而是方法不对；误用：❌“他是认真还是不认真？”（想表达选定后者时不用“还是”）"],["是…还是…","含义：让对方选；用法：提出选项问对方；例句：你喝水还是喝牛奶？；误用：自己已选定时不用“还是”"]]},"前置知识":["并列复句"],"类比":"像岔路口自己选一条路：<b>不是</b>先把一条路叉掉，苹果；<b>而是</b>走上另一条，梨子。选定的是后者，不是问对方；前后还得是同一类东西才能这样选。"},{"name":"先…然后…","讲解":"表示承接：按顺序做事情。","深讲":"先……然后……表示承接：按顺序做事情，先做的放前面，后做的放后面，顺序不能乱；这是承接关系，在复句7种里没有单列，在关联词里学。","分类":[{"类":"先……然后……式","说明":"最常用的承接搭配。","代表":"先……然后……","例子":["先洗手，然后吃饭。"]},{"类":"先……，再……式","说明":"再和然后意思一样，表接着做。","代表":"先……，再……","例子":["先洗手，再吃饭。"]},{"类":"先……，接着……式","说明":"接着表示紧接着做下一步。","代表":"先……，接着……","例子":["先写作业，接着看电视。"]}],"怎么认":["是不是按顺序做事情？是的。","有没有先……然后、先……再？有。","前后换个位置，顺序还对吗？不对，说明顺序不能乱。"],"辨析":"先……然后……和一……就……的区别：先然后表顺序（先洗手，然后吃饭：两件事有先后），一就表紧接（我一回家就写作业：两件事挨得很紧）。","例句解析":[{"句":"先洗手，然后吃饭。","析":"洗手在前，吃饭在后，按顺序做，是承接关系。"},{"句":"先写作业，然后才能看电视。","析":"写作业在前，看电视在后，是承接关系。"}],"练习":[{"q":"下面哪个是承接关系？","options":["我一回家就写作业","先洗手，然后吃饭","因为累，所以休息","虽然累，但是坚持"],"answer":1,"解析":"先……然后表示按顺序做事情。","类":"先……然后……式"},{"q":"承接关系前后顺序能乱吗？","options":["能","不能","有时能","看情况"],"answer":1,"解析":"先做的放前面，顺序不能乱。","类":"先……然后……式"},{"q":"“先洗手，再吃饭”属于？","options":["承接","紧接","因果","并列"],"answer":0,"解析":"先……再……和先……然后……一样，表承接。","类":"先……，再……式"}],"例子":["先洗手，然后吃饭","先写作业，然后才能看电视","先读题目，然后再下笔。","先穿上外套，然后再出门。","做数学题要先审题，然后计算。","先把桌子擦干净，然后摆好书本。","他先跑完步，然后去洗澡。","先听老师讲，然后自己练习。","做饭要先洗菜，然后切菜。","先完成作业，然后才能玩。","他先道歉，然后解释了原因。"],"口诀":"事情有先后","易错":"顺序不能乱，先做的放前面","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["先…然后…","含义：表顺序（有先后）；用法：两件事有先后，不一定紧接；例句：先洗手，然后吃饭；误用：❌“我先回家然后就写作业”（混用两种格式）"],["一…就…","含义：表紧接（挨得很紧）；用法：两件事挨得很紧；例句：我一回家就写作业；误用：❌“先回家就写作业”"]]},"前置知识":["并列复句"],"类比":"像排队上车：<b>先</b>洗手排在前面，<b>然后</b>吃饭跟在后面，顺序不能乱，插队、掉头都不行；先做的放前面，后做的放后面。"},{"name":"一…就…","讲解":"表示紧接：两个动作挨得很紧。","深讲":"一……就……表示紧接：两个动作挨得很紧，前一个动作一发生，后一个动作马上跟着发生；一……就……中间别加太多字。","分类":[{"类":"一……就……式","说明":"最常用的紧接搭配。","代表":"一……就……","例子":["我一回家就写作业。"]},{"类":"刚……就……式","说明":"刚表示刚刚发生，就表示马上跟着。","代表":"刚……就……","例子":["他刚回家就写作业。"]},{"类":"一听一看就……式","说明":"一听、一看这类感官动作一发生，反应马上来。","代表":"一……就……","例子":["他一听音乐就开心。"]}],"怎么认":["两个动作是不是挨得很紧？是的。","有没有一……就、刚……就？有。","前一个动作一发生，后一个是不是马上跟着？是的。"],"辨析":"一……就……和先……然后……的区别：一就表紧接（我一回家就写作业：挨得很紧），先然后表顺序（先洗手，然后吃饭：有先后，不一定紧接）。","例句解析":[{"句":"我一回家就写作业。","析":"回家一发生，写作业马上跟着，是紧接关系。"},{"句":"他一听音乐就开心。","析":"一听音乐，开心马上来，是紧接关系。"}],"练习":[{"q":"下面哪个是紧接关系？","options":["先洗手，然后吃饭","我一回家就写作业","因为累，所以休息","虽然累，但是坚持"],"answer":1,"解析":"一……就表示两个动作挨得很紧。","类":"一……就……式"},{"q":"“他刚回家就写作业”属于？","options":["紧接","承接","因果","并列"],"answer":0,"解析":"刚……就和一……就一样，表紧接。","类":"刚……就……式"},{"q":"“一……就……”中间别加？","options":["太多字","关联词","主语","谓语"],"answer":0,"解析":"一……就……中间别加太多字。","类":"一……就……式"}],"例子":["我一回家就写作业","他一听音乐就开心","他一看到我就笑了。","天一黑，路灯就亮了。","妈妈一回来，小狗就摇尾巴。","他一上车就睡着了。","春天一到，花儿就开了。","铃声一响，同学们就进教室了。","我一打开书，就被吸引住了。","他一听说，就赶来了。","雨一停，孩子们就跑出去玩了。"],"口诀":"紧接着发生","易错":"“一…就…”中间别加太多字","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["一…就…","含义：表紧接（挨得很紧）；用法：两件事挨得很紧；例句：我一回家就写作业；误用：❌“先回家就写作业”"],["先…然后…","含义：表顺序（有先后）；用法：有先后，不一定紧接；例句：先洗手，然后吃饭；误用：❌“我一洗手然后吃饭”"]]},"前置知识":["条件复句"],"类比":"像开关一按灯就亮：我<b>一</b>回家，写作业<b>就</b>马上跟着到，前一个动作一发生，后一个紧贴着来；中间别塞太多字，塞多了就贴不紧了。"},{"name":"既然…就…","讲解":"表示“既然事实是这样，那就…”：前句摆一个已知的事实，后句给出建议或推断。","深讲":"结构：既然 + 事实，（那/就/那就）+ 建议或推断。比如“既然来了，就一起吃饭吧”：来是事实，一起吃饭是建议。注意三点：①前句必须是已知事实（假设用“如果”）；②后句不说结果，说“该怎么办”或“能推出什么”；③前后主语相同时，“既然”多放在主语后（“你既然不想说，那就别说了”）。后句也可以是反问（“你既然不喜欢他，为什么还想跟他出去？”）。","类比":"“既然”像顺水推舟：水（事实）已经在那儿了，顺着推一把（建议），船就走了。","口诀":"既然摆事实，就来给建议","例子":["既然来了，就一起吃饭吧！","既然你不舒服，就回家休息吧。","你既然不想说，那就别说了。","既然你那么喜欢，那就买吧。","她既然刚分手，那现在应该是单身吧。","你既然不喜欢他，为什么还想跟他出去？","既然下雨了，我们就在家看电影吧。"],"易错":"✗“既然…所以…”（后句用“就/那”，不用“所以”）；“既然”是已知事实，“如果”是假设，别混。","分类":[{"类":"表建议","说明":"由事实推出该怎么做。","代表":"既然来了就吃吧","例子":["既然来了，就一起吃饭吧！","既然下雨了，我们就在家看电影吧。"]},{"类":"表推断","说明":"由事实推出是什么情况。","代表":"既然分手那就是单身","例子":["她既然刚分手，那现在应该是单身吧。"]},{"类":"带反问","说明":"后句用反问表建议，“那”可省。","代表":"既然不喜欢为什么还去","例子":["你既然不喜欢他，为什么还想跟他出去？"]}],"怎么认":["前句是不是已知事实？是→可能是既然。","后句是不是“该怎么办/能推出什么”？是→更像既然。","能不能换成“如果”？能换→是假设不是既然。"],"辨析":"既然 vs 因为：因为解释“为什么会这样”（因为下雨，比赛取消了）；既然由已知事实推出“该怎么办”（既然下雨了，我们就在家看电影吧）。一个讲原因，一个给建议。既然 vs 如果：如果表还没发生的假设，既然表已发生的事实。","例句解析":[{"句":"既然来了，就一起吃饭吧！","析":"“来了”是已知事实，“一起吃饭吧”是建议。不是结果，是“那就这么办”。"},{"句":"你既然不想说，那就别说了。","析":"前后主语都是“你”，“既然”放在主语后更自然。后句“那就别说了”是建议。"}],"练习":[{"q":"“既然下雨了，我们____在家看电影吧”填哪个？","options":["所以","就","但是","而且"],"answer":1,"解析":"既然后句用“就/那”，不用“所以”。","类":"搭配"},{"q":"哪句的“既然”用对了？","options":["既然明天下雨，我们就去","既然你来了，就一起吃吧","既然他会来，所以我等","既然下雨，但是去"],"answer":1,"解析":"“你来了”是已知事实，后句是建议。用“如果”表假设，用“所以/但是”搭配错。","类":"辨析"},{"q":"“既然”和“如果”最大的区别是？","options":["没区别","既然表已知事实，如果表假设","既然表假设，如果表事实","既然只能书面"],"answer":1,"解析":"既然的前提是已发生的事实，如果的前提是还没发生的假设。","类":"辨析"},{"q":"“你既然不想说，那就别说了”中“既然”放哪？","options":["句首","主语后","句末","动词后"],"answer":1,"解析":"前后主语相同时，“既然”多放在主语后面。","类":"位置"}],"前置知识":["因果复句","条件复句"]},{"name":"即使…也…","讲解":"表示让步：“哪怕…，也…”：前句先假设一个情况，后句说“即使这样，结果仍然不变”。","深讲":"结构：即使 + 假设，也 + 结果。比如“即使下雨，我们也去”：下雨是假设（不一定真下），去是决心。注意三点：①前句必须是假设（事实用“虽然”）；②后句的“也”放在主语后（“我也要去”✓，“也要我去”✗）；③搭“也”，不搭“但是”（✗即使…但是…）。近义词：就算、哪怕、就是…也。","类比":"“即使”像打预防针：先假设最坏的情况（下雨），再说针照打（也去）——结果不改。","口诀":"即使摆假设，也字表仍然","例子":["即使下雨，我们也去。","即使你不想让我去，我也要去。","即使冬天很冷，杰克也不穿外套。","即使他没钱，我也要嫁给他。","即使明天下雨，我们也要训练。","即使很贵，我也要买。","即使你不说，我也知道。"],"易错":"前句是事实时用“虽然”（✗“现在即使很忙”→“现在虽然很忙”）；✗“即使…但是…”（→“即使…也…”）。","分类":[{"类":"表决心","说明":"让步之后，决心不变。","代表":"即使…也要","例子":["即使下雨，我们也去。","即使很贵，我也要买。"]},{"类":"表反差","说明":"假设与结果形成反差。","代表":"即使…也不","例子":["即使冬天很冷，杰克也不穿外套。","即使他没钱，我也要嫁给他。"]}],"怎么认":["前句是不是“万一、哪怕”？是→可能是即使。","后句有没有“也/还”表“仍然”？有→更像即使。","前句是事实还是假设？事实→用虽然，假设→用即使。"],"辨析":"即使 vs 虽然：虽然 + 事实（“虽然下雨了，我们还是去了”——雨真的下了）；即使 + 假设（“即使下雨，我们也去”——不一定下）。看前句真假。即使 vs 如果：如果只表假设，即使还多一层“让步、转折”的味道。","例句解析":[{"句":"即使下雨，我们也去。","析":"“下雨”是假设（还没下），“也去”表决心不变。不能换成“虽然”，因为雨还没下。"},{"句":"现在即使很忙，我们也抽时间陪孩子。","析":"这句是错的：“现在很忙”是事实，该用“虽然”：现在虽然很忙，我们也抽时间陪孩子。"}],"练习":[{"q":"“即使明天下雨，我们____要训练”填哪个？","options":["但是","也","所以","而且"],"answer":1,"解析":"即使搭“也”，不搭“但是”。","类":"搭配"},{"q":"哪句该用“虽然”而不是“即使”？","options":["即使下雨，我们也去","现在很忙，我们也陪孩子","即使很贵，我也要买","即使他不来，我也去"],"answer":1,"解析":"“现在很忙”是事实，让步事实用“虽然”。","类":"辨析"},{"q":"“即使你不想让我去，我____要去”中“也”放哪？","options":["我前面","我后面","句首","句末"],"answer":1,"解析":"“也”放在后句主语后面：我也要去。","类":"位置"},{"q":"“即使”的近义词不包括？","options":["就算","哪怕","如果","就是"],"answer":2,"解析":"就算、哪怕、就是…也都表让步；“如果”只表假设，没有让步味。","类":"辨析"}],"前置知识":["假设复句","转折复句"]},{"name":"除非…才…","讲解":"表示“唯一条件”：除非A，才B = 只有A，B才成立。A是唯一的门槛。","深讲":"“除非”有三式：①除非A，才B（唯一条件：“除非你去，他才会去”）；②除非A，否则/不然B（“除非你是会员，否则不能进去”——否则=不这样就…）；③结果，除非A（倒装强调：“我不去，除非你也去”）。注意别和“除了”搞混：除了=除开（除了他，都来了），除非=条件。","类比":"“除非”像门禁卡：没刷卡（条件），门（结果）就不开——唯一的钥匙。","口诀":"除非定条件，才字锁结果","例子":["除非你去，他才会去。","除非你有员工卡，才能用这台打印机。","除非你是会员，否则不能进去。","除非下大雨，否则比赛照常进行。","我不去，除非你也去。","你不会这么快升职，除非你表现很好。"],"易错":"✗“除非…所以…”；“除非”是条件，“除了”是除外，别混（“除了他都来了”≠“除非他都来了”）。","分类":[{"类":"唯一条件式","说明":"除非A，才B：B只在A成立时成立。","代表":"除非你去我才去","例子":["除非你去，他才会去。","除非你有员工卡，才能用这台打印机。"]},{"类":"除非否则式","说明":"除非A，否则B：不满足A就会B。","代表":"除非会员否则不进","例子":["除非你是会员，否则不能进去。","除非下大雨，否则比赛照常进行。"]},{"类":"倒装强调式","说明":"先说结果，再用除非补条件。","代表":"我不去除非你去","例子":["我不去，除非你也去。"]}],"怎么认":["是不是“只有…才”的意思？是→可能是除非。","后句有没有“才/否则/不然”？有→更像除非。","能不能换成“除了”？能换→是除外不是条件。"],"辨析":"除非 vs 只有：意思接近（“只有你去，我才去”），除非更口语、更强调“排他、唯一”。除非 vs 除了：除了表“除外”（除了他，大家都来了）；除非表“条件”（除非他来，我才去）。看后面跟的是名词还是条件句。","例句解析":[{"句":"除非你去，他才会去。","析":"“你去”是唯一条件，“他才去”是结果。= 只有你去，他才会去。"},{"句":"除非下大雨，否则比赛照常进行。","析":"“下大雨”是条件，“否则”引出不满足条件的结果：不下大雨→照常进行。"}],"练习":[{"q":"“除非你是会员，____不能进去”填哪个？","options":["所以","否则","但是","而且"],"answer":1,"解析":"除非A，否则B：不满足条件就会B。","类":"搭配"},{"q":"“除非”最接近哪个词的意思？","options":["除了","只有","如果","虽然"],"answer":1,"解析":"除非A才B = 只有A才B，表唯一条件。","类":"辨析"},{"q":"哪句的“除非”用错了？","options":["除非你去，我才去","除了他，大家都来了","除非下雨，否则取消","除非他来，所以我去"],"answer":3,"解析":"“除非…所以…”搭配错，该用“才/否则”。注意第2句是“除了”，表除外，用对了。","类":"易错"},{"q":"“我不去，除非你也去”是哪种句式？","options":["正常语序","倒装强调","疑问句","感叹句"],"answer":1,"解析":"先说结果“我不去”，再用“除非”补条件，是倒装强调式。","类":"结构"}],"前置知识":["条件复句"]}]},{"id":"xiuci","items":[{"name":"比喻","例子":["他像豹子一样快","天上的云像棉花糖","天上的云像棉花糖一样白。","他跑得像豹子一样快。","月亮像玉盘挂在天上。","老师的爱像春雨滋润心田。","西湖像一面明镜。","她的脸红得像苹果。","时间像流水一去不回。","柳条像姑娘的长发随风飘。","雪花像鹅毛纷纷落下。","他高兴得像吃了蜜一样甜。","云像棉花糖。（本体'云'具体，喻体'棉花糖'具体）","时间像流水。（本体'时间'抽象，喻体'流水'具体）"],"口诀":"甲像乙，不同类；找本体、喻体、喻词","易错":"有“像”不一定是比喻（如表示举例）","讲解":"打比方，生动形象","深讲":"比喻是打比方：把一个事物比作另一个事物，让人一听就明白、一想就形象；本体和喻体必须是不同类的事物，否则就不是比喻，只是比较。","分类":[{"类":"明喻","说明":"有像、如、似这类喻词，本体、喻体都出现。","代表":"像、如、似","例子":["天上的云像棉花糖。"]},{"类":"暗喻","说明":"用是、变成连接，本体、喻体都出现，没有像。","代表":"是、变成","例子":["老师是辛勤的园丁。"]},{"类":"借喻","说明":"只出现喻体，本体不出现，借喻体来说本体。","代表":"只说喻体","例子":["一群花朵走进了教室。"]}],"怎么认":["句子里有没有把甲说成乙？有。","甲和乙是不是不同类的事物？是的，才是比喻。","有没有像、是这类喻词？有，帮助判断是明喻还是暗喻。"],"辨析":"有“像”不一定是比喻。表示举例、比较的“像”不是比喻：他像他爸爸一样高，是比较（人和人同类），不是比喻；天上的云像棉花糖，是比喻（云和棉花糖不同类）。","例句解析":[{"句":"天上的云像棉花糖。","析":"云是本体，棉花糖是喻体，像是喻词，是明喻。"},{"句":"他像豹子一样快。","析":"他是本体，豹子是喻体，像是喻词，是明喻。"}],"练习":[{"q":"下面哪个是比喻？","options":["他像他爸爸一样高","天上的云像棉花糖","他比我高","他和我一样大"],"answer":1,"解析":"云和棉花糖不同类，是比喻；他和爸爸同类，是比较。","类":"明喻"},{"q":"“老师是辛勤的园丁”属于？","options":["明喻","暗喻","借喻","拟人"],"answer":1,"解析":"用是连接，没有像，是暗喻。","类":"暗喻"},{"q":"“一群花朵走进了教室”属于？","options":["明喻","暗喻","借喻","夸张"],"answer":2,"解析":"只出现喻体花朵，本体孩子不出现，是借喻。","类":"借喻"}],"类比":"比喻像给事物<b>穿上别人的衣服</b>：月亮像玉盘。用熟悉的东西解释陌生的东西，一下就懂了。","变式表":{"不变":"打比方，用甲事物说明乙事物，生动形象","可变":{"类型":["明喻（像/如：云像棉花糖）","暗喻（是：他是小老虎）","借喻（不出现本体：棉花糖飘来了）"],"本体喻体":["具体（云→棉花糖）","抽象（时间→流水）"]},"边界":"有'像'不一定是比喻：表举例（像苹果、香蕉）不是；同类比较（他像他爸）不是；本体喻体须不同类","覆盖已确认":["类型"],"覆盖缺失":["本体喻体"]},"前置知识":["名词"]},{"name":"拟人","例子":["小草向我点头","风儿轻轻地抚摸着我的脸","小鸟在枝头唱歌跳舞。","花儿向我们点头微笑。","小溪唱着歌流向远方。","月亮悄悄地爬上了树梢。","柳树姑娘甩着长辫子。","太阳公公露出了笑脸。","小草从土里探出头来。","星星眨着眼睛看我们。","秋风温柔地拥抱着大地。","柳枝在风中跳舞。（直接拟人：'跳舞'是人的动作）","春风又绿江南岸。（间接拟人：'绿'字有人情味）"],"口诀":"赋予情感","易错":"拟人与比喻可兼用","讲解":"把物当人写","深讲":"拟人是把物当人写：让花草、风雨、小动物像人一样动作、说话、有感情；拟人让没有生命的东西活起来，读起来亲切。","分类":[{"类":"动作拟人","说明":"让物像人一样做动作。","代表":"点头、跑、跳","例子":["小草向我点头。"]},{"类":"情感拟人","说明":"让物像人一样有感情。","代表":"笑、哭、高兴","例子":["花儿笑了。"]},{"类":"语言拟人","说明":"让物像人一样说话。","代表":"说、唱、叫","例子":["小鸟对我说：“早上好。”"]}],"怎么认":["主语是不是没有生命的东西？是的。","它做的是不是只有人才做的事（说话、点头、笑）？是的。","把主语换成人，句子还通吗？通，说明是拟人。"],"辨析":"拟人和比喻可兼用，但不一样：拟人是把物当人（小草点头），比喻是把甲比作乙（云像棉花糖）。“风儿抚摸着我的脸”是拟人，不是比喻，因为没有比作什么。","例句解析":[{"句":"小草向我点头。","析":"小草不会点头，点头是人的动作，是拟人。"},{"句":"风儿轻轻地抚摸着我的脸。","析":"抚摸是人的动作，风儿被当成人写，是拟人。"}],"练习":[{"q":"下面哪个是拟人？","options":["天上的云像棉花糖","小草向我点头","他跑得很快","白发三千丈"],"answer":1,"解析":"小草点头是人的动作，是拟人。","类":"动作拟人"},{"q":"“花儿笑了”属于？","options":["动作拟人","情感拟人","语言拟人","比喻"],"answer":1,"解析":"笑是感情，花儿被写出了感情。","类":"情感拟人"},{"q":"“小鸟对我说：早上好”属于？","options":["动作拟人","情感拟人","语言拟人","夸张"],"answer":2,"解析":"小鸟说话，是语言拟人。","类":"语言拟人"}],"类比":"拟人像给万物<b>装上人心</b>：小草在微笑。把人的动作表情借给不会说话的东西。","变式表":{"不变":"把物当人写，赋予人的动作/情感","可变":{"拟":["拟人（花儿笑了）","拟物（把人当物，较少）"],"方式":["直接（柳枝跳舞）","间接（春风又绿江南岸的'绿'有人味）"]},"边界":"须有人的特征（笑/哭/说话）；'像人一样'是比喻不是拟人；拟人+比喻可兼格（'他像小老虎一样扑来'）","覆盖已确认":["拟"],"覆盖缺失":["方式"]},"前置知识":["名词","动词"]},{"name":"夸张","例子":["白发三千丈","教室里安静得连针掉地上都听得见","他跑得比风还快。","这间屋子大得能装下一头大象。","我饿得能吃下一头牛。","教室里静得连针掉在地上都听得见。","他高兴得一蹦三尺高。","飞流直下三千尺，疑是银河落九天。","白发三千丈，缘愁似个长。","这道题难得比登天还难。","他气得火冒三丈。","操场上的人山人海一眼望不到边。","教室里静得连针掉地上都听得见。（合理夸张，突出安静）","他一顿能吃三百个馒头。（过度夸张，失真）"],"口诀":"突出强调","易错":"夸张要合理，不能失真","讲解":"故意夸大或缩小","深讲":"夸张是故意夸大或缩小：把事物说得比实际更大、更小、更多、更少，用来突出强调；夸张要合理，不能失真，让人一听就知道是夸张，不是真的。","分类":[{"类":"扩大夸张","说明":"把事物说得比实际大得多。","代表":"三千丈、飞流直下","例子":["白发三千丈。"]},{"类":"缩小夸张","说明":"把事物说得比实际小得多。","代表":"巴掌大、一根针","例子":["教室只有巴掌大。"]}],"怎么认":["句子里的数目、程度是不是大得或小得不可能？是的。","去掉夸张，事物本身还成立吗？成立，只是没那么突出。","作者是不是在强调、突出？是的。"],"辨析":"夸张和说谎不一样：夸张是故意夸大、让人一听就知道是夸张（白发三千丈）；说谎是想让人当真。夸张要合理，不能失真。","例句解析":[{"句":"白发三千丈。","析":"白发不可能真有三千丈，是扩大夸张，突出愁得多。"},{"句":"教室里安静得连针掉地上都听得见。","析":"安静被夸大到针掉地上都听得见，是扩大夸张。"}],"练习":[{"q":"下面哪个是夸张？","options":["天上的云像棉花糖","白发三千丈","小草向我点头","他跑得很快"],"answer":1,"解析":"白发不可能真有三千丈，是夸张。","类":"扩大夸张"},{"q":"“教室只有巴掌大”属于？","options":["扩大夸张","缩小夸张","比喻","拟人"],"answer":1,"解析":"教室被说得比实际小得多，是缩小夸张。","类":"缩小夸张"},{"q":"夸张要？","options":["让人当真","合理，不能失真","越大越好","越小越好"],"answer":1,"解析":"夸张要合理，不能失真。","类":"扩大夸张"}],"类比":"夸张像拿<b>放大镜</b>看东西：白发三千丈。故意说大说小，让印象更深刻。","变式表":{"不变":"故意夸大或缩小，突出特征","可变":{"方向":["夸大（飞流直下三千尺）","缩小（针尖大的地方）","超前（未饮先醉）"],"程度":["合理夸张（突出）","过度（失真就成病句）"]},"边界":"夸张须有度（'三千尺'是夸张，'三万尺'就离谱）；与比喻区别：夸张是数量/程度，喻是类比；'非常/极'是程度副词不是夸张","覆盖已确认":["方向"],"覆盖缺失":["程度"]},"前置知识":[]},{"name":"排比","例子":["爱心是春风，是夏雨，是秋月","春天是花朵，是绿叶，是暖阳","读书使人充实，讨论使人机智，写作使人精确。","爱心是一盏灯，照亮别人，也温暖自己；爱心是一首歌，唱出希望，也带来快乐。","春天来了，花儿开了，草儿绿了，鸟儿叫了。","他爱学习，爱劳动，爱帮助人。","我们要讲文明，讲礼貌，讲卫生。","海是蓝的，天是蓝的，人的心也应该是蓝的。","理想是灯，照亮夜行的路；理想是火，点燃熄灭的灯。","红的花，绿的草，高大的树，构成了一幅美景。","学习要专心，吃饭要专心，做事要专心。","燕子去了，有再来的时候；杨柳枯了，有再青的时候。","我爱祖国，我爱人民，我爱家乡。（句排比）","盼望着，盼望着，东风来了，春天的脚步近了。（段排比）","爱学习，爱劳动，爱运动。（结构相同）","他性格开朗，她待人热情，他做事认真。（结构相似）"],"口诀":"增强气势","易错":"排比项数一般三项以上","讲解":"三个以上结构相似的句子","深讲":"排比是由三个或三个以上结构相同或相似、语气一致的短语或句子排列在一起，用来增强气势；排比项一般三项以上，少了就不成排比。","分类":[{"类":"句子排比","说明":"由三个以上结构相同的句子组成。","代表":"是……，是……，是……","例子":["爱心是春风，是夏雨，是秋月。"]},{"类":"短语排比","说明":"由三个以上结构相同的短语组成。","代表":"又高、又壮、又结实","例子":["他长得又高、又壮、又结实。"]}],"怎么认":["有没有三个以上结构相同的短语或句子？有。","它们的语气是不是一致的？是的。","读起来是不是气势越来越强？是的。"],"辨析":"排比和反复的区别：排比是结构相同、内容不同（春风、夏雨、秋月）；反复是同一内容重复（盼望着，盼望着）。看内容是不是换了。","例句解析":[{"句":"爱心是春风，是夏雨，是秋月。","析":"三个句子结构相同，语气一致，是句子排比。"},{"句":"春天是花朵，是绿叶，是暖阳。","析":"三个句子结构相同，是句子排比。"}],"练习":[{"q":"下面哪个是排比？","options":["盼望着，盼望着，春天来了","爱心是春风，是夏雨，是秋月","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"三个句子结构相同，是排比；盼望着是反复。","类":"句子排比"},{"q":"排比项数一般？","options":["一项","两项","三项以上","不限"],"answer":2,"解析":"排比项数一般三项以上。","类":"句子排比"},{"q":"“他长得又高、又壮、又结实”属于？","options":["句子排比","短语排比","反复","对偶"],"answer":1,"解析":"三个结构相同的短语排列，是短语排比。","类":"短语排比"}],"类比":"排比像<b>台阶一级一级往上</b>：山是高大的，水是清澈的，天是蔚蓝的。结构相同，气势叠加。","变式表":{"不变":"三个以上结构相同/相似的句子并列，气势强","可变":{"类型":["句排比（爱…爱…爱…）","段排比"],"结构":["相同（我爱…我爱…）","相似（有人…有人…）"]},"边界":"须三项以上（两项是对偶）；结构须一致（'爱祖国、爱人民、爱劳动'✓）；与反复区别：反复是同一词语重复，排比是结构重复","覆盖已确认":[],"覆盖缺失":["类型","结构"]},"前置知识":["主谓式"]},{"name":"对偶","例子":["横眉冷对千夫指，俯首甘为孺子牛","书山有路勤为径，学海无涯苦作舟","明月松间照，清泉石上流。","两个黄鹂鸣翠柳，一行白鹭上青天。","海内存知己，天涯若比邻。","感时花溅泪，恨别鸟惊心。","大漠孤烟直，长河落日圆。","几处早莺争暖树，谁家新燕啄春泥。","白日依山尽，黄河入海流。","野火烧不尽，春风吹又生。","举头望明月，低头思故乡。","海内存知己，天涯若比邻。（流水对：上下句意思连贯）"],"口诀":"整齐凝练","易错":"修辞里的对偶只要求字数相等、结构相同，不要求平仄；律诗里的“对仗”才讲平仄","讲解":"字数相等、结构相同、意义相关","深讲":"用来显得整齐凝练；对偶是两句，排比是三句以上，不要混。","分类":[{"类":"正对","说明":"上下句意思相近、互补。","代表":"书山有路勤为径，学海无涯苦作舟","例子":["书山有路勤为径，学海无涯苦作舟。"]},{"类":"反对","说明":"上下句意思相反、相对。","代表":"横眉冷对千夫指，俯首甘为孺子牛","例子":["横眉冷对千夫指，俯首甘为孺子牛。"]},{"类":"流水对","说明":"上下句意思连贯、承接，像流水一样。","代表":"欲穷千里目，更上一层楼","例子":["欲穷千里目，更上一层楼。"]}],"怎么认":["是不是两个句子？是的。","字数是不是相等、结构是不是相同？是的。","上下句意思是不是相关（相近、相反或承接）？是的。"],"辨析":"对偶和排比的区别：对偶是两句，字数相等、结构相同；排比是三句以上，结构相同、语气一致。数一数有几句，再看字数是不是相等。","例句解析":[{"句":"横眉冷对千夫指，俯首甘为孺子牛。","析":"两句字数相等、结构相同，意思相反，是反对。"},{"句":"书山有路勤为径，学海无涯苦作舟。","析":"两句字数相等、结构相同，意思相近互补，是正对。"}],"练习":[{"q":"下面哪个是对偶？","options":["爱心是春风，是夏雨，是秋月","横眉冷对千夫指，俯首甘为孺子牛","盼望着，盼望着，春天来了","天上的云像棉花糖"],"answer":1,"解析":"两句字数相等、结构相同、意思相反，是对偶。","类":"反对"},{"q":"对偶是几句？","options":["一句","两句","三句以上","不限"],"answer":1,"解析":"对偶是两个句子相对成文。","类":"正对"},{"q":"“欲穷千里目，更上一层楼”属于？","options":["正对","反对","流水对","排比"],"answer":2,"解析":"上下句意思连贯承接，是流水对。","类":"流水对"}],"类比":"对偶像<b>对联的两边</b>：明月松间照，清泉石上流。字数相等，意思相对，工工整整。","变式表":{"不变":"两句字数相等、结构相同、意思相关","可变":{"类型":["正对（意思相近：明月松间照，清泉石上流）","反对（意思相反：横眉冷对千夫指，俯首甘为孺子牛）","流水对（也叫串对，意思承接：才饮长江水，又食武昌鱼）"],"工整":["工对（词性相对）","宽对（大意相对）"]},"边界":"须两句（多句是排比）；字数须相等；与对联区别：对联是应用，对偶是修辞；'对仗'是格律术语，指律诗中的对偶","覆盖已确认":["类型"],"覆盖缺失":["工整"]},"前置知识":["名词","动词","形容词"]},{"name":"反复","例子":["盼望着，盼望着，春天来了","加油，加油，我们一定能赢！","盼望着，盼望着，东风来了，春天的脚步近了。","大山无言，小草无言，土地无言。","他说好，好，好，就这么办。","沉默啊，沉默啊，不在沉默中爆发，就在沉默中灭亡。","我们是光荣的少先队员，我们是祖国的未来。","学，学，再学；练，练，再练。","风啊，你轻轻地吹吧，吹吧。","走啊走啊，终于走到了山顶。","他笑了，笑了，开心地笑了。","雨，下吧，下吧，滋润干渴的大地吧。","盼望着，盼望着，春天来了。（词语反复：'盼望着'）","他说得对，他说得对极了。（句子反复）"],"口诀":"强调加深","易错":"与排比区别：反复是重复同一内容","讲解":"重复词语/句子强调","深讲":"反复是重复词语或句子，用来强调、加深印象；反复重复的是同一内容，排比换的是内容，不要混。","分类":[{"类":"词语反复","说明":"重复同一个词语。","代表":"盼望着，盼望着","例子":["盼望着，盼望着，春天来了。"]},{"类":"句子反复","说明":"重复同一个句子。","代表":"春天来了！春天来了！","例子":["春天来了！春天来了！花儿都开了。"]}],"怎么认":["有没有同一个词语或句子重复出现？有。","重复是不是为了强调？是的。","去掉重复，意思还在吗？在，只是强调弱了。"],"辨析":"反复和排比的区别：反复是同一内容重复（盼望着，盼望着），排比是结构相同、内容不同（春风、夏雨、秋月）。看重复的是不是同一个内容。","例句解析":[{"句":"盼望着，盼望着，春天来了。","析":"盼望着重复出现，是词语反复，用来强调盼望。"},{"句":"加油，加油，我们一定能赢！","析":"加油重复出现，是词语反复，用来强调鼓励。"}],"练习":[{"q":"下面哪个是反复？","options":["爱心是春风，是夏雨，是秋月","盼望着，盼望着，春天来了","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"盼望着重复，是反复；春风夏雨秋月是排比。","类":"词语反复"},{"q":"反复和排比的区别是？","options":["反复换内容，排比重复内容","反复重复同一内容，排比换内容","没有区别","反复是两句"],"answer":1,"解析":"反复重复同一内容，排比结构相同、内容不同。","类":"词语反复"},{"q":"“春天来了！春天来了！花儿都开了”属于？","options":["词语反复","句子反复","排比","对偶"],"answer":1,"解析":"同一个句子重复出现，是句子反复。","类":"句子反复"}],"类比":"反复像<b>敲鼓重击</b>：盼望着，盼望着。重要的话说两遍，感情更浓。","变式表":{"不变":"同一词语/句子重复出现，强调感情","可变":{"类型":["连续反复（盼望着，盼望着）","间隔反复（……啊，……啊）"],"重复":["词语（大山啊，大山啊）","句子"]},"边界":"须有强调意图（无意的重复是啰嗦）；与排比区别：反复是词语重复，排比是结构重复；与叠词区别：叠词是构词（红红的），反复是修辞","覆盖已确认":["类型"],"覆盖缺失":["重复"]},"前置知识":[]},{"name":"设问","例子":["是谁创造了世界？是我们劳动群众","谁是班上跑得最快的？是小明","是谁创造了人类世界？是我们劳动群众。","什么叫自律？自律就是自我约束、自我管理。","幸福是什么？幸福是帮助别人后的快乐。","谁是最可爱的人？是我们的战士。","怎样才能学好语文？多读、多写、多思考。","什么是勇敢？勇敢不是不害怕，而是害怕也向前。","春天在哪里？春天在枝头，在花间，在人们的心里。","为什么要读书？因为书是进步的阶梯。","谁言寸草心，报得三春晖？是说子女难报父母恩。","学而不思则罔，思而不学则殆，是什么意思？是说只学不想、只想不学都不行。","什么是幸福？是清晨的一缕阳光，是家人的一句问候，是朋友的一个微笑。（问一句，答多句）","谁是最可爱的人？是医生，是老师，是每一个平凡岗位上的劳动者。（问一句，答多句）"],"口诀":"引起注意","易错":"设问后一定要回答","讲解":"自问自答","深讲":"设问是自问自答：先提出问题，再自己回答，用来引起注意、引出下文；设问后一定要回答，不回答就不是设问。","分类":[{"类":"句首设问","说明":"在开头提问，引起注意。","代表":"是谁……？是……","例子":["是谁创造了世界？是我们劳动群众。"]},{"类":"句中设问","说明":"在中间提问，引出下文。","代表":"……是什么？……是……","例子":["祖国是什么？祖国是我们的家。"]}],"怎么认":["是不是先问后答？是的。","问句后面有没有回答？有，才是设问。","提问是不是为了引起注意、引出下文？是的。"],"辨析":"设问和反问的区别：设问自问自答（是谁创造了世界？是我们劳动群众）；反问不回答，答案隐含在问句里（这不是很清楚吗？）。看后面有没有回答。","例句解析":[{"句":"是谁创造了世界？是我们劳动群众。","析":"先问是谁创造了世界，再回答是劳动群众，是设问。"},{"句":"谁是班上跑得最快的？是小明。","析":"先问谁最快，再回答是小明，是设问。"}],"练习":[{"q":"下面哪个是设问？","options":["这不是很清楚吗？","是谁创造了世界？是我们劳动群众","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"自问自答，是设问；这不是很清楚吗是反问。","类":"句首设问"},{"q":"设问后一定要？","options":["不回答","回答","再问一次","换话题"],"answer":1,"解析":"设问后一定要回答。","类":"句首设问"},{"q":"“祖国是什么？祖国是我们的家”属于？","options":["句首设问","句中设问","反问","排比"],"answer":1,"解析":"在中间提问引出下文，是句中设问。","类":"句中设问"}],"类比":"设问像<b>自问自答</b>：是谁创造了人类世界？是我们劳动群众。先抛问题，再给答案，引起注意。","变式表":{"不变":"自问自答，引起注意","可变":{"形式":["问一句答一句（谁是最可爱的人？是战士）","问多句答一句"],"作用":["引起注意","突出强调","承上启下"]},"边界":"须自问自答（只问不答是疑问句）；与反问区别：设问有答案，反问答案在问中（'难道不是吗？'=是的）；问号后须有答句","覆盖已确认":[],"覆盖缺失":["形式","作用"]},"前置知识":[]},{"name":"反问","例子":["这不是很清楚吗？","这么简单的题，你不会做吗？","难道我们不该好好学习吗？","这么冷的天，你怎么能穿这么少？","这件事难道不是他做的吗？","浪费粮食，难道不觉得可惜吗？","这么好的机会，怎能错过？","诚信是做人之本，难道不应该坚守吗？","你自己不努力，难道还怪别人？","这么简单的题，难道你不会做？","父母为我们付出这么多，难道不值得感恩吗？","现在不努力，更待何时？","难道他不知道吗？（形式：'难道…吗'）","你怎能半途而废？（形式：'怎能'）","这难道不是你的错吗？（表肯定：是你的错）","我怎么会骗你呢？（表否定：不会骗你）"],"口诀":"加强语气","易错":"反问后不回答，答案隐含其中","讲解":"用问句表肯定/否定，加强语气","深讲":"反问是用问句表示肯定或否定，用来加强语气；反问后不回答，答案隐含在问句里，听的人一听就明白。","分类":[{"类":"肯定式反问","说明":"用否定问句表示肯定。","代表":"不是……吗？","例子":["这不是很清楚吗？"]},{"类":"否定式反问","说明":"用肯定问句表示否定。","代表":"……吗？（表否定）","例子":["这么简单的题，你不会做吗？"]}],"怎么认":["是不是问句形式，但意思不是真的在问？是的。","问句后面有没有回答？没有，答案隐含其中。","把问句换成陈述句，意思是不是更直接？是的，说明是反问。"],"辨析":"反问和设问的区别：反问不回答（这不是很清楚吗？答案就是很清楚），设问自问自答（是谁创造了世界？是我们劳动群众）。看后面有没有回答。","例句解析":[{"句":"这不是很清楚吗？","析":"用否定问句表示肯定：很清楚，是反问。"},{"句":"这么简单的题，你不会做吗？","析":"用肯定问句表示否定：你应该会做，是反问。"}],"练习":[{"q":"下面哪个是反问？","options":["是谁创造了世界？是我们劳动群众","这不是很清楚吗？","天上的云像棉花糖","小草向我点头"],"answer":1,"解析":"不回答，答案隐含其中，是反问。","类":"肯定式反问"},{"q":"“这么简单的题，你不会做吗？”的意思是？","options":["你不会做","你应该会做","题很难","不知道"],"answer":1,"解析":"用肯定问句表示否定：你应该会做。","类":"否定式反问"},{"q":"反问后要不要回答？","options":["要","不要，答案隐含其中","有时要","看情况"],"answer":1,"解析":"反问后不回答，答案隐含在问句里。","类":"肯定式反问"}],"类比":"反问像<b>明知故问</b>：难道这不是奇迹吗？用问句表达肯定的意思，语气更强烈。","变式表":{"不变":"用疑问形式表肯定/否定，答案在问中，语气强","可变":{"形式":["用'难道/岂'（难道这不是吗？）","用'怎么/怎能'（怎能忘记？）"],"表意":["肯定（难道不是=是）","否定（怎能=不能）"]},"边界":"答案自明，不需回答；与设问区别：反问无答句，设问有答句；'吗'结尾多是真疑问（'好吗？'），反问多用'呢/吧/难道'","覆盖已确认":[],"覆盖缺失":["形式","表意"]},"前置知识":["设问"]}],"name":"常见修辞格（8种）"},{"id":"bingju","items":[{"name":"语序不当","例子":["病：我把作业昨天晚上写完了→改：我昨天晚上把作业写完了（时间状语放到“把”前面）","病：我们在学校昨天开了运动会→改：我们昨天在学校开了运动会（先说时间，再说地点）","病：一位优秀的我们班的学生→改：我们班的一位优秀的学生（领属定语放最前）","病：一件红色的妈妈的毛衣→改：妈妈的一件红色的毛衣","病：我们要认真克服并发现缺点→改：我们要发现并认真克服缺点（先发现，后克服）","病：同学们讨论并听取了老师的报告→改：同学们听取并讨论了老师的报告（先听，后讨论）"],"口诀":"先找主干，再看修饰","易错":"多重定语顺序（领属在最前）、时间和地点状语的先后、动作的先后","讲解":"词语或分句顺序颠倒","深讲":"语序不当是词语或分句顺序颠倒：先找主干，再看修饰；多重定语、状语是重灾区。改法是：一读句子，二找主干，三看修饰语顺序，四调换位置。","分类":[{"类":"定语语序不当","说明":"多重定语排列顺序错了。","代表":"领属＋数量＋形容词＋名词","例子":["一位优秀的我们班的学生。"]},{"类":"状语语序不当","说明":"状语放错了位置：表示时间的词一般放在地点、「把」字短语前面。","代表":"时间＋地点／把＋动词","例子":["我把作业昨天晚上写完了。"]}],"怎么认":["先压缩主干，看主谓宾齐不齐？齐。","再看修饰语：定语、状语的顺序对不对？不对。","调换修饰语位置，句子是不是顺了？顺了，说明是语序不当。"],"辨析":"语序不当和结构混乱的区别：语序不当是顺序颠倒，调换位置就顺了；结构混乱是两种句式纠缠，要删掉一种句式。看调换位置能不能修好。","例句解析":[{"句":"一位优秀的我们班的学生。","析":"领属定语我们班应在最前，改为：我们班的一位优秀的学生。"},{"句":"我把作业昨天晚上写完了。","析":"表示时间的「昨天晚上」要放在「把作业」前面，改为：我昨天晚上把作业写完了。"}],"练习":[{"q":"“一位优秀的我们班的学生”错在哪？","options":["缺主语","定语语序不当","搭配不当","表意不明"],"answer":1,"解析":"领属定语我们班应在最前。","类":"定语语序不当"},{"q":"“我把作业昨天晚上写完了”怎么改？","options":["我把作业写完了昨天晚上","我昨天晚上把作业写完了","我把昨天晚上作业写完了","昨天晚上作业我把写完了"],"answer":1,"解析":"表示时间的「昨天晚上」要放在「把作业」前面。","类":"状语语序不当"},{"q":"多重定语的正确顺序是？","options":["形容词＋领属＋数量＋名词","领属＋数量＋形容词＋名词","数量＋形容词＋领属＋名词","名词＋领属＋数量＋形容词"],"answer":1,"解析":"领属在最前，再是数量、形容词，最后是名词。","类":"定语语序不当"}],"类比":"语序不当就像\"穿反了衣服\"：每件都在，但位置错了。","决策树":"①压缩主干：主谓宾齐吗？→不齐：不是语序问题，转查成分残缺→②齐：看修饰语——定语在名词前吗？→不在：移到名词前，顺了吗？→顺了：定语语序不当→③状语在动词前吗？→不在：移到动词前→顺了：状语语序不当→④分句顺序符合逻辑先后吗？→否：调换分句","前置知识":["定语","状语"]},{"name":"搭配不当","例子":["病：他怀着崇高的心情→改：怀着激动的心情","病：同学们都很爱护 → 改：同学们都很爱护公物","病：我们要养成良好的学习态度→改：养成良好的学习习惯（养成与习惯搭配）","病：他对自己很有信心，学习成绩很优异→改：删去“很优异”或改为“学习成绩优异”","病：经过努力，他的错别字大大进步了→改：错别字大大减少了（进步与减少搭配）","病：我们要端正学习目的→改：端正学习态度（端正与态度搭配）","病：他的写作水平有了很大的提高→改：正确（示例：提高与水平搭配恰当）","病：同学们都认真地完成了作业→改：正确（完成与作业搭配恰当）","病：他发扬了艰苦奋斗的精神→改：正确（发扬与精神搭配恰当）"],"口诀":"主谓动宾，一一对应","易错":"“怀着……心情”不能配“崇高”","讲解":"主谓、动宾、修饰语与中心词不搭配","深讲":"搭配不当是主谓、动宾、修饰语与中心词对不上号：主谓动宾一一对应，修饰语也要配中心词。改法是：压缩主干，检查每一对搭配。","分类":[{"类":"主谓搭配不当","说明":"主语和谓语对不上号。","代表":"人口是国家","例子":["我国的人口是世界上最多的国家。"]},{"类":"动宾搭配不当","说明":"动词和宾语对不上号。","代表":"端正学习","例子":["我们要端正学习。"]},{"类":"修饰搭配不当","说明":"修饰语和中心词对不上号。","代表":"怀着崇高的心情","例子":["他怀着崇高的心情。"]}],"怎么认":["压缩主干，主谓宾齐不齐？齐。","主语配谓语、动词配宾语、修饰语配中心词，一一检查。","有一对对不上，就是搭配不当。"],"辨析":"搭配不当和成分残缺的区别：搭配不当是成分齐了但配错了（端正学习）；成分残缺是成分缺了（同学们都很爱护，缺宾语）。看成分齐不齐。","例句解析":[{"句":"他怀着崇高的心情。","析":"崇高配精神、理想，不配心情，改为：怀着激动的心情。"},{"句":"我国的人口是世界上最多的国家。","析":"人口不能是国家，改为：我国是世界上人口最多的国家。"}],"练习":[{"q":"“他怀着崇高的心情”错在哪？","options":["缺宾语","修饰搭配不当","语序不当","表意不明"],"answer":1,"解析":"崇高不配心情，应配激动的心情。","类":"修饰搭配不当"},{"q":"“我们要端正学习”怎么改？","options":["我们要端正学习态度","我们要学习端正","我们要端正地学习","我们要学习"],"answer":0,"解析":"端正配态度，不配学习。","类":"动宾搭配不当"},{"q":"“我国的人口是世界上最多的国家”错在哪？","options":["动宾搭配不当","主谓搭配不当","语序不当","结构混乱"],"answer":1,"解析":"人口不能是国家，改为：我国是世界上人口最多的国家。","类":"主谓搭配不当"}],"类比":"搭配不当就像\"左脚穿右脚的鞋\"：单个看都对，放一起别扭。","决策树":"①压缩主干：主谓宾齐吗？→不齐：先查残缺→②齐：一一配对——主语配谓语，语义通吗？→不通：主谓搭配不当，换谓语→③动词配宾语，语义通吗？→不通：动宾搭配不当，换动词或宾语→④修饰语配中心词，通吗？→不通：修饰搭配不当→⑤全通：不是搭配问题","前置知识":["主语","谓语","宾语","定语"]},{"name":"成分残缺或赘余","例子":["病：通过学习，使我进步（缺主语）→删“使”","病：不约而同异口同声（赘余）","病：通过努力，取得了进步 → 改：通过努力，我取得了进步","病：看了这部电影，受到了深刻的教育→改：我看了这部电影，受到了深刻的教育（缺主语）","病：通过这次活动，使我明白了道理→改：这次活动使我明白了道理（删“通过”或“使”）","病：他把今天的任务→改：他把今天的任务完成了（缺谓语）","病：我们要学习雷锋同志全心全意为人民服务的→改：我们要学习雷锋同志全心全意为人民服务的精神（缺宾语）","病：他非常非常特别的高兴→改：他非常高兴（“非常非常特别”赘余）","病：大约有三百人左右参加了会议→改：大约有三百人参加了会议（“大约”与“左右”重复）","病：他亲眼目睹了这件事的经过→改：他目睹了这件事的经过（“亲眼”与“目睹”重复）"],"口诀":"压缩主干，残缺立现","易错":"“通过……使”句式最易缺主语","讲解":"缺主/谓/宾，或词语重复多余","深讲":"成分残缺或赘余是缺主、谓、宾，或词语重复多余：压缩主干，残缺立现；意思重复，赘余立现。改法是：缺了补上，多了删去。","分类":[{"类":"主语残缺式","说明":"缺主语，话没了头。","代表":"通过……使……","例子":["通过学习，使我进步。"]},{"类":"宾语残缺式","说明":"缺宾语，动作没着落。","代表":"爱护后空着","例子":["同学们都很爱护。"]},{"类":"成分赘余式","说明":"词语意思重复，多余。","代表":"不约而同异口同声","例子":["不约而同异口同声。"]}],"怎么认":["压缩主干，主谓宾齐不齐？不齐，就是残缺。","有没有意思重复的词？有，就是赘余。","“通过……使……”句式最易缺主语，重点查。"],"辨析":"成分残缺和搭配不当的区别：残缺是缺了成分（通过学习，使我进步，缺主语）；搭配不当是成分齐了但配错了（端正学习）。看成分齐不齐。","例句解析":[{"句":"通过学习，使我进步。","析":"通过和使同时出现，主语被吃掉，删去使。"},{"句":"不约而同异口同声。","析":"不约而同和异口同声意思重复，删去一个。"}],"练习":[{"q":"“通过学习，使我进步”错在哪？","options":["搭配不当","主语残缺","语序不当","表意不明"],"answer":1,"解析":"通过和使同时出现，主语被吃掉。","类":"主语残缺式"},{"q":"“不约而同异口同声”错在哪？","options":["缺主语","缺宾语","成分赘余","结构混乱"],"answer":2,"解析":"两个词意思重复，多余。","类":"成分赘余式"},{"q":"“通过努力，取得了进步”怎么改？","options":["通过努力，使取得了进步","通过努力，我取得了进步","努力，取得了进步","通过努力，进步取得了"],"answer":1,"解析":"补上主语我。","类":"主语残缺式"}],"决策树":"①压缩主干：主/谓/宾缺吗？→缺：成分残缺，补上所缺→②齐：看句式——有\"通过/经过/由于……使/让\"吗？→有：删\"使/让\"或补主语→③有意思重复的词吗？→有：成分赘余，删一留一→④无：成分完整，查别类","前置知识":["主语","谓语","宾语"],"类比":"像给句子看医生量身高体重：缺主语、谓语、宾语是少了零件，话没了头、动作没着落；赘余是穿了两件一样的衣服，不约而同异口同声。缺了补上，多了脱掉。"},{"name":"结构混乱","例子":["病：原因是由于他努力→改：原因是他努力","病：这次活动是受到了大家的欢迎造成的 → 改：这次活动受到了大家的欢迎","病：我们来到山间，听见鸟叫，看见花开，感到心旷神怡的原因是景色太美了→改：我们来到山间，听见鸟叫，看见花开，感到心旷神怡（删“的原因是…”）","病：他的写作水平有了很大的提高是勤奋的结果→改：他的写作水平有了很大提高，这是勤奋的结果","病：这部电影，我看了三遍，很受感动的原因是剧情真实→改：这部电影我看了三遍，很受感动，因为剧情真实","病：老师对我们要求很严格是希望我们成才→改：老师对我们要求很严格，是希望我们成才","病：他之所以成功，是因为努力的结果→改：他之所以成功，是因为努力（删“的结果”）","病：问题的关键在于态度是否端正上→改：问题的关键在于态度是否端正（删“上”）","病：这件事的成败，在于大家齐心协力与否是关键→改：这件事的成败，在于大家是否齐心协力","病：关于这个问题，我的看法是认为应该慎重→改：关于这个问题，我认为应该慎重（删“的看法是”）"],"口诀":"两种句式，留一去一","易错":"“原因是由于”“是由于……造成的”典型杂糅","讲解":"句式杂糅，两种结构纠缠","深讲":"结构混乱是句式杂糅：两种结构纠缠在一起。改法是：两种句式，留一去一，认清一句话只能用一种结构。","分类":[{"类":"原因是由于式","说明":"原因和由于重复用了。","代表":"原因是由于……","例子":["原因是由于他努力。"]},{"类":"是……造成的式","说明":"是和受到……造成的纠缠。","代表":"是受到了……造成的","例子":["这次活动是受到了大家的欢迎造成的。"]}],"怎么认":["一句话里有没有两种句式？有。","删掉一种，句子是不是顺了？顺了。","“原因是由于”“是由于……造成的”是典型杂糅，重点查。"],"辨析":"结构混乱和语序不当的区别：结构混乱是两种句式纠缠，要删一种；语序不当是顺序颠倒，调换位置就好。看删能不能修好。","例句解析":[{"句":"原因是由于他努力。","析":"原因和由于重复，改为：原因是他努力。"},{"句":"这次活动是受到了大家的欢迎造成的。","析":"是……造成的和受到了……纠缠，改为：这次活动受到了大家的欢迎。"}],"练习":[{"q":"“原因是由于他努力”怎么改？","options":["原因是由于他努力的","原因是他努力","由于是他努力","原因是他努力的由于"],"answer":1,"解析":"原因和由于留一个。","类":"原因是由于式"},{"q":"“这次活动是受到了大家的欢迎造成的”错在哪？","options":["语序不当","结构混乱","搭配不当","表意不明"],"answer":1,"解析":"两种句式纠缠，删一种。","类":"是……造成的式"},{"q":"句式杂糅的改法是？","options":["调换位置","留一去一","补上成分","换关联词"],"answer":1,"解析":"两种句式，留一去一。","类":"原因是由于式"}],"决策树":"①一句中有两套主谓吗？→有：句式杂糅，拆成两句或删一套→②前半说A、后半说B（中途易辙）吗？→是：前后分开各成一句→③暗换主语了吗？→是：补出后句主语或拆句→④否：结构没问题，查别类","前置知识":["主语","谓语","并列复句"],"类比":"像两件衣服穿成了一件：原因是由于、是受到……造成的，两种句式纠缠在一起。医生的办法是留一套、脱一套，一句话只能穿一种结构。"},{"name":"表意不明","例子":["病：他背着总经理和副总喝酒（谁喝？）","病：小红的妈妈说她病了（谁病了？）","病：他背着总经理去开会→改：总经理背着他去开会（或：他陪总经理去开会），消除歧义","病：数理化学习经验→改：数理化的学习经验（加“的”消除歧义）","病：鸡不吃了→改：鸡不吃食了（或：我们不吃鸡了），说清谁吃谁","病：我想起来了→改：我想起这件事了（说清宾语）","病：开刀的是他父亲→改：给他开刀的是他父亲的同事（说清施事）","病：这辆车没有锁→改：这辆车没有上锁（说清“锁”的含义）","病：他在火车上写字→改：他在火车上写了一封信（补宾语）","病：雨天没有晴天多→改：下雨天没有晴天多（说清比较对象）"],"口诀":"代词指代要明确","易错":"多重定语易生歧义","讲解":"歧义或指代不清","深讲":"表意不明是歧义或指代不清：代词指代要明确，多重定语易生歧义。改法是：代词换成名字，歧义的句子拆开说。","分类":[{"类":"代词指代不明","说明":"代词不知道指谁。","代表":"她病了（谁？）","例子":["小红的妈妈说她病了。"]},{"类":"句子歧义","说明":"一句话有两种理解。","代表":"背着……喝酒（谁喝？）","例子":["他背着总经理和副总喝酒。"]}],"怎么认":["句子里的代词（他、她、它）指谁？说不清，就是指代不明。","一句话能不能有两种理解？能，就是歧义。","两个人以上时，少用他，直接叫名字。"],"辨析":"表意不明和不合逻辑的区别：表意不明是意思说不清（谁病了？）；不合逻辑是意思说得清但不合理（七点起床，六点半出门）。看意思清不清。","例句解析":[{"句":"他背着总经理和副总喝酒。","析":"不知道是谁喝酒，是和副总一起喝，还是背着他们喝，有歧义。"},{"句":"小红的妈妈说她病了。","析":"她不知道指小红还是妈妈，指代不明。"}],"练习":[{"q":"“小红的妈妈说她病了”错在哪？","options":["搭配不当","代词指代不明","语序不当","结构混乱"],"answer":1,"解析":"她不知道指小红还是妈妈。","类":"代词指代不明"},{"q":"“他背着总经理和副总喝酒”错在哪？","options":["缺主语","句子歧义","搭配不当","不合逻辑"],"answer":1,"解析":"不知道是谁喝酒，有两种理解。","类":"句子歧义"},{"q":"“小明和小刚说，他赢了”怎么改最清楚？","options":["小明和小刚说，他赢了","小明对小刚说：“我赢了”","他们说，他赢了","小明说，他赢了"],"answer":1,"解析":"直接叫名字、用第一人称，指代就清楚了。","类":"代词指代不明"}],"决策树":"①有代词（他/这/那）吗？→有：上文可指对象唯一吗？→不唯一：指代不明，改用具体名词→②有歧义停顿吗？→有：加标点或改句式断开→③一句话有两种理解吗？→有：换一种说法→④否：表意明确","前置知识":["歧义句"],"类比":"像医生听不清病人说哪儿疼：她病了不知是谁病，背着喝酒不知谁喝。代词换成名字、歧义的句子拆开说，疼的地方指清楚了，病才看得明白。"},{"name":"不合逻辑","例子":["病：三月的南京是美丽的季节（主谓不合逻辑）","病：他七点起床洗漱，然后六点半出门（时间倒流了！）","病：他是众多死难者中幸免的一个→改：他是众多遇难者中幸免的一个（死难者不能幸免）","病：我断定他大概是生病了→改：我断定他是生病了（断定与大概矛盾）","病：全体同学都参加了，只有小明没来→改：除小明外，全体同学都参加了","病：他是唯一一个女同学→改：她是唯一的女同学（唯一与一个重复且搭配不当）","病：这道题我做了三遍，终于做对了一半→改：这道题我做了三遍，终于做对了","病：他的年龄大约十六七岁左右→改：他的年龄十六七岁（约数矛盾）","病：我们一定要发扬光大革命传统→改：我们一定要发扬革命传统（删“光大”或改为“把…发扬光大”）","病：这家店的商品物美价廉，服务态度好→改：正确（并列得当）"],"口诀":"概念关系要理清","易错":"“美”和“季节”不能搭配","讲解":"自相矛盾、概念并列不当等","深讲":"改法是：一读前后，二查概念，三改说法。","分类":[{"类":"前后矛盾式","说明":"前后说法自己打自己。","代表":"七点起床，六点半出门","例子":["他七点起床洗漱，然后六点半出门。"]},{"类":"并列概念不当式","说明":"并列的概念有交叉或包含。","代表":"水果、苹果和香蕉","例子":["水果、苹果和香蕉都很好吃。"]},{"类":"主谓不合逻辑式","说明":"主语和谓语在逻辑上对不上。","代表":"南京是季节","例子":["三月的南京是美丽的季节。"]}],"怎么认":["前后说法打不打架？打架，就是前后矛盾。","并列的词有没有包含关系？有，就是并列不当。","主语和谓语在逻辑上配不配？不配，就是主谓不合逻辑。"],"辨析":"不合逻辑和表意不明的区别：不合逻辑是意思清楚但不合理（时间倒流）；表意不明是意思说不清（谁病了？）。看意思清不清、合理不合理。","例句解析":[{"句":"三月的南京是美丽的季节。","析":"南京是城市，不能是季节，主谓不合逻辑。"},{"句":"他七点起床洗漱，然后六点半出门。","析":"六点半比七点早，时间倒流了，前后矛盾。"}],"练习":[{"q":"“他七点起床洗漱，然后六点半出门”错在哪？","options":["语序不当","前后矛盾","搭配不当","表意不明"],"answer":1,"解析":"六点半比七点早，时间倒流了。","类":"前后矛盾式"},{"q":"“水果、苹果和香蕉都很好吃”错在哪？","options":["并列概念不当","语序不当","缺宾语","结构混乱"],"answer":0,"解析":"水果包含了苹果，不能并列。","类":"并列概念不当式"},{"q":"“三月的南京是美丽的季节”错在哪？","options":["主谓不合逻辑","缺主语","语序不当","搭配不当"],"answer":0,"解析":"南京是城市，不能是季节。","类":"主谓不合逻辑式"}],"决策树":"①有并列词语吗？→有：概念交叉或从属吗？→是：删交叉项或改并列为包含→②有数量词吗？→有：约数词+确数并存吗？→是：删约数词或确数→③有否定词吗？→是：语义反了吗？→反了：删多余否定→④有\"大约/左右\"+确数吗？→有：删一→⑤否：逻辑没问题","前置知识":["概念：定义与划分"],"类比":"像一座走反了的挂钟：七点起床、六点半出门，意思说得清却不合理。看病的办法是一读前后、二查概念，钟走反了就得拨回来。"},{"name":"主语残缺","讲解":"滥用介词（通过/使/令）导致主语丢失，话没了“头”。","深讲":"主语残缺是滥用介词（通过、使、令）导致主语丢失，话没了头。改法是：通过、使、令，删一留一，把主语留下来。","分类":[{"类":"通过使式","说明":"通过和使同时出现，主语被吃掉。","代表":"通过……使……","例子":["通过这次春游，使我增长了见识。"]},{"类":"介词开头式","说明":"介词开头，主语被介词吃掉。","代表":"看了……，受到了……","例子":["看了这部电影，受到了教育。"]}],"怎么认":["句子开头是不是通过、使、令这类介词？是的。","压缩主干，有没有主语？没有，就是主语残缺。","删掉通过或使，主语是不是回来了？回来了。"],"辨析":"主语残缺和谓语残缺的区别：主语残缺是缺头（通过学习，使我进步）；谓语残缺是缺动作（他昨天）。看缺的是头还是动作。","例句解析":[{"句":"通过这次春游，使我增长了见识。","析":"通过和使同时出现，删去使：通过这次春游，我增长了见识。"},{"句":"看了这部电影，受到了教育。","析":"主语被介词吃掉，补上主语：我受到了教育。"}],"练习":[{"q":"“通过这次春游，使我增长了见识”怎么改？","options":["通过这次春游，使我增长了见识了","通过这次春游，我增长了见识","这次春游，使我增长了见识","通过春游，使我增长见识"],"answer":1,"解析":"删去使，主语我就回来了。","类":"通过使式"},{"q":"“看了这部电影，受到了教育”错在哪？","options":["缺谓语","主语残缺","缺宾语","语序不当"],"answer":1,"解析":"主语被介词吃掉了。","类":"介词开头式"},{"q":"“通过……使……”是哪个病句的重灾区？","options":["谓语残缺","主语残缺","宾语残缺","搭配不当"],"answer":1,"解析":"通过和使同时出现，最易缺主语。","类":"通过使式"}],"例子":["病：通过这次春游，使我增长了见识 → 改：删去“使”","病：看了这部电影，受到了教育 → 改：我受到了教育","病：通过这次春游，使我增长了见识→改：通过这次春游，我增长了见识（删“使”）","病：看了这部电影，受到了教育→改：我看了这部电影，受到了教育（补主语“我”）","病：由于他努力学习，因而取得了好成绩→改：由于他努力学习，他取得了好成绩（删“因而”或补主语）","病：经过老师的教育，让我明白了道理→改：经过老师的教育，我明白了道理（删“让”）","病：从这件事中，懂得了诚实的重要→改：从这件事中，我懂得了诚实的重要（补“我”）","病：在老师的帮助下，他的成绩有了提高→改：正确（“他的成绩”作主语）","病：听了这个故事，受到很大启发→改：我听了这个故事，受到很大启发","病：通过讨论，使我们的认识提高了→改：通过讨论，我们的认识提高了"],"口诀":"通过使令，删一留一","易错":"“通过……使……”是重灾区","类比":"主语残缺就像“没头的话”：说了半天，不知道谁干的。","决策树":"①找主语：有吗？→有：不是主语残缺→②无：看句式——\"通过/由于/经过……使/让\"型吗？→是：删\"使/让\"，原宾语升为主语，或补主语→③介词开头（在/对/对于/通过）吗？→是：删介词，主语自然出现，或补主语→④否：另找缺主原因","前置知识":["主语"]},{"name":"谓语残缺","讲解":"只有主语没有谓语，话没说完。","深讲":"改法是：主语有了，动作要有，补上谓语。","分类":[{"类":"主语独存式","说明":"只有主语，谓语全缺。","代表":"他昨天","例子":["他昨天。"]},{"类":"谓语不全式","说明":"谓语说了半截，没说完。","代表":"同学都很","例子":["我们班的同学都很。"]}],"怎么认":["压缩句子后只剩主语吗？是的，就是谓语残缺。","主语后面有没有动作或状态？没有，就是缺谓语。","补上动作，句子是不是完整了？完整了。"],"辨析":"谓语残缺和主语残缺的区别：谓语残缺是缺动作（他昨天）；主语残缺是缺头（通过学习，使我进步）。看缺的是头还是动作。","例句解析":[{"句":"他昨天。","析":"只有主语和时间，缺谓语，改为：他昨天来了。"},{"句":"我们班的同学都很。","析":"都很后面缺形容词，改为：我们班的同学都很好学。"}],"练习":[{"q":"“他昨天”错在哪？","options":["主语残缺","谓语残缺","宾语残缺","语序不当"],"answer":1,"解析":"只有主语，缺谓语。","类":"主语独存式"},{"q":"“我们班的同学都很”怎么改？","options":["我们班的同学都很学","我们班的同学都很好学","我们班的同学很","我们班的同学都"],"answer":1,"解析":"补上谓语好学。","类":"谓语不全式"},{"q":"压缩句子后只剩主语，说明？","options":["主语残缺","谓语残缺","宾语残缺","搭配不当"],"answer":1,"解析":"只剩主语，就是谓语残缺。","类":"主语独存式"}],"例子":["病：他昨天 → 改：他昨天来了","病：我们班的同学都很 → 改：我们班的同学都很好学","病：他把今天的任务→改：他把今天的任务完成了（补谓语“完成”）","病：我们正在努力→改：我们正在努力学习（补宾语/谓语中心）","病：小明把门→改：小明把门关上了（补谓语“关上”）","病：他对这件事的关心→改：他对这件事很关心（补谓语“关心”）","病：妈妈把饭→改：妈妈把饭做好了（补谓语“做好”）","病：我们要学习雷锋的→改：我们要学习雷锋的精神（补宾语）","病：老师要求我们→改：老师要求我们认真读书（补谓语）","病：他把球→改：他把球踢进了球门（补谓语）"],"口诀":"主语有了，动作要有","易错":"压缩句子后只剩主语，就是谓语残缺","决策树":"①找谓语：有吗？→有：不是谓语残缺→②无：主语后直接跟宾语吗？→是：按宾语语义补谓语→③\"是\"字句缺\"是\"吗？→是：补\"是\"→④长定语后缺谓语吗？→是：补谓语→⑤否：不是谓语残缺","前置知识":["谓语"],"类比":"像只报了名字没说干什么：他昨天，话说了一半就停了。主语是头，谓语是动作，补上来、很好学，句子才算说完。"},{"name":"宾语残缺","讲解":"及物动词后缺宾语，动作没“着落”。","深讲":"宾语残缺是及物动词后缺宾语，动作没着落。改法是：动词之后，宾语莫丢，补上宾语。","分类":[{"类":"宾语空缺式","说明":"动词后宾语全空着。","代表":"大家都喜欢","例子":["大家都喜欢。"]},{"类":"宾语不全式","说明":"宾语说了半截，不完整。","代表":"养成的好习惯","例子":["我们要养成的好习惯。"]}],"怎么认":["动词后面有没有宾语？没有，就是宾语残缺。","“养成”“喜欢”后不能空着，重点查。","补上宾语，句子是不是完整了？完整了。"],"辨析":"宾语残缺和主语残缺的区别：宾语残缺是动作没着落（大家都喜欢）；主语残缺是话没头（通过学习，使我进步）。看缺的是头还是尾。","例句解析":[{"句":"我们要养成的好习惯。","析":"养成后缺完整的宾语，改为：养成讲卫生的好习惯。"},{"句":"大家都喜欢。","析":"喜欢后空着，改为：大家都喜欢这本书。"}],"练习":[{"q":"“大家都喜欢”错在哪？","options":["主语残缺","谓语残缺","宾语残缺","语序不当"],"answer":2,"解析":"喜欢后缺宾语。","类":"宾语空缺式"},{"q":"“我们要养成的好习惯”怎么改？","options":["我们要养成好习惯","我们要养成讲卫生的好习惯","我们要好习惯养成","我们要养成习惯"],"answer":1,"解析":"补上讲卫生，宾语就完整了。","类":"宾语不全式"},{"q":"“养成”“喜欢”后不能？","options":["加宾语","空着","加定语","加状语"],"answer":1,"解析":"及物动词后不能空着。","类":"宾语空缺式"}],"例子":["病：我们要养成的好习惯 → 改：养成讲卫生的好习惯","病：大家都喜欢 → 改：大家都喜欢这本书","病：我们要学习雷锋同志全心全意为人民服务的→改：…服务的精神（补宾语“精神”）","病：他正在看→改：他正在看书（补宾语“书”）","病：妈妈在洗→改：妈妈在洗衣服（补宾语“衣服”）","病：老师表扬了→改：老师表扬了他（补宾语“他”）","病：我喜欢→改：我喜欢画画（补宾语“画画”）","病：他把作业→改：他把作业写完了（补谓语和宾语完整）","病：我们参观了→改：我们参观了博物馆（补宾语）","病：小明正在写→改：小明正在写作文（补宾语）"],"口诀":"动词之后，宾语莫丢","易错":"“养成”“喜欢”后不能空着","决策树":"①动词后有宾语吗？→有：不是宾语残缺→②无：动词是及物动词吗？→是：按语境补宾语→③\"把\"字句缺中心词吗？→是：补中心词→④不及物动词误带宾语吗？→是：删宾语→⑤否：查别类","前置知识":["宾语","动词"],"类比":"像扔球没人接：大家都喜欢，喜欢什么没着落。动词这个球扔出去，得有个接球手，补上这本书、书、衣服，动作才落地。"},{"name":"定语语序不当","讲解":"多重定语排列顺序错误。","深讲":"顺序是：领属＋数量＋动词性＋形容词性＋名词，依次排好，不能乱。","分类":[{"类":"领属错位式","说明":"领属定语没放在最前。","代表":"一位优秀的我们班的学生","例子":["一位优秀的我们班的学生。"]},{"类":"多重定语错位式","说明":"多个定语顺序全乱了。","代表":"优秀的我们班的一位学生","例子":["优秀的我们班的一位学生。"]}],"怎么认":["定语有几个？多个，就要查顺序。","按领属、数量、动词性、形容词性、名词排一排。","排好后句子是不是顺了？顺了。"],"辨析":"定语语序不当和状语语序不当的区别：定语错位是名词前的修饰语排错了（我们班的一位优秀的学生）；状语错位是动词前的修饰语放错了（把作业昨天晚上写完了，应为昨天晚上把作业写完了）。看修饰的是名词还是动词。","例句解析":[{"句":"一位优秀的我们班的学生。","析":"领属我们班应在最前，改为：我们班的一位优秀的学生。"},{"句":"优秀的我们班的一位学生。","析":"按领属、数量、形容词排，改为：我们班的一位优秀的学生。"}],"练习":[{"q":"“一位优秀的我们班的学生”怎么改？","options":["一位我们班的优秀的学生","我们班的一位优秀的学生","优秀的我们班的一位学生","我们班优秀的一位学生"],"answer":1,"解析":"领属我们班在最前。","类":"领属错位式"},{"q":"多重定语的正确顺序是？","options":["形容词＋领属＋数量＋名词","领属＋数量＋动词性＋形容词性＋名词","数量＋领属＋形容词性＋名词","名词＋领属＋数量＋形容词"],"answer":1,"解析":"领属、数量、动词性、形容词性、名词依次排。","类":"多重定语错位式"},{"q":"“我们班的一位优秀的学生”中，领属定语是？","options":["一位","优秀的","我们班的","学生"],"answer":2,"解析":"我们班的是领属定语，在最前。","类":"领属错位式"}],"例子":["病：一位优秀的我们班的学生 → 改：我们班的一位优秀的学生","病：一位优秀的我们班的学生→改：我们班的一位优秀的学生（领属在前）","病：红的我的书包→改：我的红书包（领属+颜色顺序）","病：三本他的新书→改：他的三本新书（领属+数量+形容）","病：美丽的祖国的花朵→改：祖国美丽的花朵（领属在前）","病：两个可爱的小明的弟弟→改：小明的两个可爱的弟弟","病：昨天的一场大雨→改：正确（时间定语在前）","病：学校的我们的老师→改：我们学校的老师","病：高兴的他的消息→改：他的好消息（或：令他高兴的消息）","病：五个班里的同学→改：班里的五个同学"],"口诀":"谁的、多少、干啥、啥样，依次排好","易错":"顺序：领属＋数量＋动词性＋形容词性＋名词","决策树":"①找定语：在中心词前吗？→不在：移到中心词前→②多个定语：按\"领属→数量→动词性→形容词性→名词性\"排，顺序对吗？→不对：按序重排→③定语+中心语语义通吗？→不通：调换或改定语→④通：不是定语语序问题","前置知识":["定语","语序不当"],"类比":"像排队站错了位置：领属、数量、动词性、形容词性、名词要依次排好。我们班的一位优秀的学生才是队形，一位优秀的我们班的学生就是站乱了队。"},{"name":"关联词误用","讲解":"关联词前后不搭配，张冠李戴。","深讲":"改法是：因果转折，配对要准，因为配所以，虽然配但是，别串门。","分类":[{"类":"因果误配转折式","说明":"因果词配了转折词。","代表":"因为……但是……","例子":["因为他很努力，但是没考好。"]},{"类":"条件误配式","说明":"条件词配错了。","代表":"只有……就……","例子":["只有下雨，就不去。"]}],"怎么认":["前后分句是什么关系？先定关系。","关联词配不配这个关系？不配，就是误用。","因为配所以，虽然配但是，查一查配对表。"],"辨析":"关联词误用和关联词残缺的区别：误用是配错了（因为……但是……）；残缺是只说一半（一边跑步，听音乐）。看是配错还是缺一半。","例句解析":[{"句":"因为他很努力，但是没考好。","析":"因为配但是是错的，改为：虽然他很努力，但是没考好。"},{"句":"只有下雨，就不去。","析":"只有是必要条件，就不去是充分结果，配错了，改为：只要下雨，就不去。"}],"练习":[{"q":"“因为他很努力，但是没考好”怎么改？","options":["因为他很努力，所以没考好","虽然他很努力，但是没考好","因为他很努力，而且没考好","如果他很努力，但是没考好"],"answer":1,"解析":"转折关系用虽然配但是。","类":"因果误配转折式"},{"q":"“只有下雨，就不去”怎么改？","options":["只有下雨，才不去","只要下雨，就不去","如果下雨，才不去","因为下雨，就不去"],"answer":1,"解析":"只要配就，表充分条件。","类":"条件误配式"},{"q":"“因为”配？","options":["但是","所以","而且","还是"],"answer":1,"解析":"因为配所以，别串门。","类":"因果误配转折式"}],"例子":["病：因为他很努力，但是没考好 → 改：虽然他很努力，但是没考好","病：只有下雨，就不去 → 改：只要下雨，就不去","病：因为他努力，所以他虽然成功了→改：因为他努力，所以他成功了（删“虽然”）","病：即使困难再大，我们也要不但完成→改：即使困难再大，我们也要完成（删“不但”）","病：他不但学习好，但是体育不好→改：他不但学习好，而且体育也好（“不但”配“而且”）","病：虽然他病了，所以没来上课→改：因为他病了，所以没来上课（因果用“因为…所以”）","病：如果努力，就不但能成功→改：如果努力，就能成功（删“不但”）","病：不是他不努力，而是因为方法不对→改：他不是不努力，而是方法不对（“不是…而是”位置）","病：只有你来，我才不去→改：如果你来，我就不去（条件关系用“如果…就”）","病：尽管下雨，但是却照常进行→改：尽管下雨，但是照常进行（删“却”）"],"口诀":"因果转折，配对要准","易错":"“因为”配“所以”，“虽然”配“但是”，别串门","决策树":"①有复句吗？→单句：不用关联词，删→②有关联词吗？→无：该用未用，补→③判断分句关系（因果/转折/递进/假设/条件）：关联词表意对吗？→不对：换表意相符的→④位置对吗（前后主语相同放后、不同放前）？→不对：调位置→⑤对：关联词没问题","前置知识":["转折复句","因果复句"],"类比":"像钥匙插错了锁：因为配所以、虽然配但是，串了门就打不开。因为他很努力却配了但是，就像因果的钥匙插进了转折的锁，得换回虽然。"},{"name":"关联词残缺","讲解":"关联词只说一半，另一半丢了。","深讲":"改法是：关联成双，缺一不可，把另一半补上。","分类":[{"类":"关联词缺一半","说明":"必须成对用的关联词（一边……一边……、只有……才……、既……又……、无论……都……、只要……就……、不但……而且……）只用了一半。","代表":"只有努力学习，取得好成绩","例子":["他一边跑步，听音乐。","只有努力学习，取得好成绩。"]},{"类":"虽然残缺式","说明":"用了「虽然」，后一分句没有「但是」「可是」「却」来呼应。","代表":"虽然天气冷，他坚持锻炼","例子":["虽然天气冷，他坚持锻炼。"]}],"怎么认":["句子里有没有必须成对用的关联词（一边、只有、既、无论、只要、不但、虽然）？","有的话，后面有没有配对的另一半（一边、才、又、都、就、而且、但是）？没有，就是残缺。","注意：意思本来就连得上的句子，不用关联词也通顺，不算病句。比如「他努力学习，取得了好成绩」「天黑了，我们回家吧」。"],"辨析":"关联词残缺和关联词误用的区别：残缺是缺一半（一边跑步，听音乐）；误用是配错了（因为……但是……）。看是缺了还是配错了。","例句解析":[{"句":"他一边跑步，听音乐。","析":"「一边」只说了一个，改为：他一边跑步，一边听音乐。"},{"句":"只有努力学习，取得好成绩。","析":"有「只有」没有「才」，改为：只有努力学习，才能取得好成绩。"},{"句":"虽然天气冷，他坚持锻炼。","析":"有「虽然」没有和它呼应的「但是」，改为：虽然天气冷，但是他坚持锻炼。"}],"练习":[{"q":"“他一边跑步，听音乐”怎么改？","options":["他一边跑步，一边听音乐","他跑步，听音乐","他一边跑步，听着音乐","他跑步一边，听音乐一边"],"answer":0,"解析":"一边要成双。","类":"关联词缺一半"},{"q":"“虽然天气冷，他坚持锻炼”缺什么？","options":["一边","但是","所以","而且"],"answer":1,"解析":"虽然配但是，缺了但是。","类":"虽然残缺式"},{"q":"关联词残缺的改法是？","options":["留一去一","关联成双，缺一不可","调换位置","删去一个"],"answer":1,"解析":"关联成双，缺一不可。","类":"关联词缺一半"}],"例子":["病：他一边跑步，听音乐 → 改：他一边跑步，一边听音乐","病：虽然天气冷，他坚持锻炼 → 改：虽然天气冷，但是他坚持锻炼","病：只有努力学习，取得好成绩 → 改：只有努力学习，才能取得好成绩","病：无论天气多冷，他坚持晨跑 → 改：无论天气多冷，他都坚持晨跑","病：她既会唱歌，会跳舞 → 改：她既会唱歌，又会跳舞","病：只要你肯努力，能学好 → 改：只要你肯努力，就能学好","病：他不但会游泳，会滑冰 → 改：他不但会游泳，而且会滑冰","对：他努力学习，取得了好成绩（意思连得上，不用关联词也通顺，不是病句）"],"口诀":"关联成双，缺一不可","易错":"成对的关联词要说全（一边…一边…、只有…才…、虽然…但是…）；但不用关联词、意思本来连得上的句子不是病句","决策树":"①有必须成对用的关联词（一边/只有/既/无论/只要/不但/虽然）吗？→无：不是关联词残缺（意思连得上的句子不用关联词也通顺）→②有：配对的另一半在吗？→不在：补全→③在：不是残缺，查是否配错（关联词误用）","前置知识":["因果复句","假设复句"],"类比":"像一双筷子只剩一根：一边跑步少了一边听音乐，虽然天气冷少了但是。成对的关联词要说全，单根筷子夹不起菜；但意思本来连得上的句子不用关联词也不算病。"},{"name":"指代不明","讲解":"代词指代对象不明确，不知道说的是谁。","深讲":"改法是：两个人以上时，少用他，直接叫名字。","分类":[{"类":"人物指代不明","说明":"代词不知道指哪个人。","代表":"他赢了（谁？）","例子":["小明和小刚说，他赢了。"]},{"类":"事物指代不明","说明":"代词不知道指哪个事物。","代表":"它不见了（什么？）","例子":["他把书放在桌子上，它不见了。"]}],"怎么认":["句子里有几个人、几个物？两个以上，就要查代词。","代词（他、她、它）指谁？说不清，就是指代不明。","换成名字，句子是不是清楚了？清楚了。"],"辨析":"指代不明和句子歧义的区别：指代不明是代词不知道指谁（她病了）；句子歧义是一句话有两种理解（背着……喝酒）。看问题在代词还是整句话。","例句解析":[{"句":"小明和小刚说，他赢了。","析":"他不知道指小明还是小刚，改为：小明对小刚说：“我赢了”。"},{"句":"他把书放在桌子上，它不见了。","析":"它指代不清，改为：书不见了。"}],"练习":[{"q":"“小明和小刚说，他赢了”错在哪？","options":["语序不当","人物指代不明","搭配不当","结构混乱"],"answer":1,"解析":"他不知道指小明还是小刚。","类":"人物指代不明"},{"q":"“他把书放在桌子上，它不见了”怎么改最清楚？","options":["他把书放在桌子上，它不见了","书不见了","他把书放在桌子上，书不见了","它把书放在桌子上，不见了"],"answer":1,"解析":"直接说书不见了，指代就清楚了。","类":"事物指代不明"},{"q":"两个人以上时，代词的改法是？","options":["多用他","少用他，直接叫名字","删去代词","换成它"],"answer":1,"解析":"少用他，直接叫名字。","类":"人物指代不明"}],"例子":["病：小明和小刚说，他赢了 → 改：小明对小刚说：“我赢了”","病：他把书放在桌子上，它不见了 → 改：书不见了","病：小明对小红说，他明天要去北京→改：小明对小红说：“我明天要去北京”（说清“他”指谁）","病：老师把书给了他，他很高兴→改：老师把书给了小明，小明很高兴","病：妈妈叫姐姐，她答应了→改：妈妈叫姐姐，姐姐答应了","病：他把这件事告诉了他→改：他把这件事告诉了小刚","病：老师批评了他，他很不服气→改：老师批评了小明，小明很不服气","病：小红和小丽是好朋友，她学习很好→改：小红和小丽是好朋友，小红学习很好","病：爸爸对儿子说，你要好好学习→改：爸爸对儿子说：“你要好好学习”（加引号明确）","病：他把自行车借给了他→改：他把自行车借给了弟弟"],"口诀":"他她它，谁是谁","易错":"两个人以上时，少用“他”，直接叫名字","决策树":"①有\"他/她/它/这/那/其\"吗？→无：不是指代问题→②有：上文有几个可指对象？→多个：指代不明，改用具体名词点明→③一个：指代唯一，OK→④\"这/那\"指代事件还是词语？→模糊：改写点明","前置知识":["代词"],"类比":"像教室里喊“他”却有两个他：小明和小刚都在，他赢了不知是谁赢。看病的办法是少用他、直接叫名字，名字一喊，指向就清楚了。"},{"name":"前后矛盾","讲解":"前后说法自相矛盾，自己打自己。","深讲":"改法是：断定别大概，前后别打架，语气、时间都要一致。","分类":[{"类":"语气矛盾式","说明":"断定词和大概词打架。","代表":"断定……大概……","例子":["他断定这次大概能考第一。"]},{"类":"时间矛盾式","说明":"时间前后打架。","代表":"昨天上午……下午……","例子":["昨天上午，我亲眼看见他下午在打球。"]}],"怎么认":["前后说法打不打架？打架，就是前后矛盾。","断定、肯定后有没有大概、可能？有，就是语气矛盾。","时间顺序对不对？不对，就是时间矛盾。"],"辨析":"前后矛盾和并列概念不当的区别：前后矛盾是说法打架（断定大概）；并列概念不当是词并列错了（水果、苹果）。看是说法打架还是词并列错了。","例句解析":[{"句":"他断定这次大概能考第一。","析":"断定和大概打架，改为：他估计这次能考第一。"},{"句":"昨天上午，我亲眼看见他下午在打球。","析":"上午和下午打架，时间矛盾。"}],"练习":[{"q":"“他断定这次大概能考第一”错在哪？","options":["语序不当","语气矛盾","搭配不当","表意不明"],"answer":1,"解析":"断定后不能跟大概。","类":"语气矛盾式"},{"q":"“昨天上午，我亲眼看见他下午在打球”错在哪？","options":["时间矛盾","语序不当","缺主语","搭配不当"],"answer":0,"解析":"上午和下午时间打架了。","类":"时间矛盾式"},{"q":"“断定”“肯定”后不能跟？","options":["一定","大概、可能","确实","真的"],"answer":1,"解析":"断定别大概。","类":"语气矛盾式"}],"例子":["病：他断定这次大概能考第一 → 改：他估计这次能考第一","病：昨天上午，我亲眼看见他下午在打球（时间打架了！）","病：他大约十六七岁左右→改：他十六七岁（删“大约”“左右”）","病：这道题我断定大概做对了→改：这道题我断定做对了（删“大概”）","病：全体同学都到了，只有小明没来→改：除了小明，全体同学都到了","病：他是唯一的三个获奖者之一→改：他是三个获奖者之一（删“唯一的”）","病：我亲眼目睹了他亲手做这件事→改：我目睹了他做这件事（删重复强调）","病：这个星期天，我肯定一定去→改：这个星期天，我一定去（删“肯定”）","病：他差不多把作业全部做完了→改：他把作业全部做完了（删“差不多”）","病：将近有三百多人参加→改：将近有三百人参加（“将近”是不到，“多”是超过，删去“多”）"],"口诀":"断定别大概，前后别打架","易错":"“断定”“肯定”后不能跟“大概”“可能”","决策树":"①找时间词：前后一致吗？→不一致：删改统一→②找数量词：约数+确数并存吗？→是：删一→③找判断词（是/不是、能/不能）：前后打架吗？→打架：统一说法→④找\"都/全\"+\"部分\"：冲突吗？→冲突：改→⑤否：前后一致","前置知识":["转折复句","概念：定义与划分"],"类比":"像自己跟自己吵架：断定和大概打架，昨天上午亲眼看见下午打球。语气、时间都要一致，自己打自己的话站不住。"},{"name":"并列概念交叉","讲解":"并列的概念有交叉或包含关系，不能放一排。","深讲":"改法是：大概念小概念，别放一排，去掉大概念或小概念。","分类":[{"类":"包含并列式","说明":"大概念包含了小概念，还并列。","代表":"水果、苹果和香蕉","例子":["水果、苹果和香蕉都很好吃。"]},{"类":"类别交叉式","说明":"类别词和小类词并列。","代表":"球类、足球和音乐","例子":["他喜欢球类、足球和音乐。"]}],"怎么认":["并列的词有没有包含关系？有，就是并列不当。","大概念和小概念放一排了吗？放了，就是错的。","去掉大概念，句子是不是顺了？顺了。"],"辨析":"并列概念交叉和前后矛盾的区别：并列不当是词并列错了（水果、苹果）；前后矛盾是说法打架（断定大概）。看是词并列还是说法打架。","例句解析":[{"句":"水果、苹果和香蕉都很好吃。","析":"水果包含了苹果，改为：苹果和香蕉都很好吃。"},{"句":"他喜欢球类、足球和音乐。","析":"球类包含了足球，改为：他喜欢足球和音乐。"}],"练习":[{"q":"“水果、苹果和香蕉都很好吃”怎么改？","options":["水果、苹果和香蕉都好吃","苹果和香蕉都很好吃","水果和苹果都很好吃","水果、香蕉都很好吃"],"answer":1,"解析":"去掉大概念水果。","类":"包含并列式"},{"q":"“他喜欢球类、足球和音乐”错在哪？","options":["语序不当","类别交叉并列","缺宾语","结构混乱"],"answer":1,"解析":"球类包含了足球，不能并列。","类":"类别交叉式"},{"q":"“水果”包含了“苹果”，所以不能？","options":["并列","分开说","一起吃","比较"],"answer":0,"解析":"大概念小概念，别放一排。","类":"包含并列式"}],"例子":["病：水果、苹果和香蕉都很好吃 → 改：苹果和香蕉都很好吃","病：他喜欢球类、足球和音乐 → 改：他喜欢足球和音乐","病：我国的粮食、棉花、油料都增产了→改：我国的粮食作物、棉花、油料作物都增产了（并列得当）","病：他喜欢唱歌、跳舞和文艺→改：他喜欢唱歌、跳舞（删“文艺”，概念包含）","病：商店里有水果、苹果、香蕉→改：商店里有苹果、香蕉等水果（苹果香蕉属水果）","病：他爱好体育、篮球、足球→改：他爱好篮球、足球等体育项目","病：我们参观了工厂、学校和教育→改：我们参观了工厂、学校（删“教育”）","病：动物园里有老虎、狮子和动物→改：动物园里有老虎、狮子等动物","病：他买了文具、铅笔和橡皮→改：他买了铅笔、橡皮等文具","病：会上讨论了学习、纪律和思想问题→改：正确（并列得当）"],"口诀":"大概念小概念，别放一排","易错":"“水果”包含了“苹果”，不能并列","决策树":"①有顿号/和/与/及/以及吗？→无：不是并列问题→②有：并列项概念交叉吗？→交叉：删交叉项→③有从属关系吗？（如\"水果和苹果\"）→有：改并列为包含（\"水果，如苹果\"）或删从属项→④词性/类别一致吗？→不一致：改一致→⑤OK","前置知识":["并列式","概念：定义与划分"],"类比":"像把大筐和小筐并排放一排数：水果已经装着苹果和香蕉，还把三者并列，数来数去就重复了。去掉大概念，苹果和香蕉一排才数得清。"},{"name":"重复啰嗦","讲解":"词语意思重复，多余。","深讲":"改法是：意思重复，删去一个。","分类":[{"类":"意思重复式","说明":"两个词意思一样，重复了。","代表":"凯旋归来","例子":["他凯旋归来了。"]},{"类":"程度叠用式","说明":"程度词叠用，多余。","代表":"非常十分开心","例子":["非常十分开心。"]}],"怎么认":["有没有意思一样的词？有，就是重复。","程度词（非常、十分）叠用了吗？叠用了，就是多余。","删去一个，意思变不变？不变，就是啰嗦。"],"辨析":"重复啰嗦和成分赘余的区别：其实是一回事，重复啰嗦是成分赘余的一种；成分赘余还包括不约而同异口同声这类。看重复的是词还是成分。","例句解析":[{"句":"他凯旋归来了。","析":"旋就是归来，改为：他凯旋了。"},{"句":"非常十分开心。","析":"非常和十分叠用，改为：非常开心。"}],"练习":[{"q":"“他凯旋归来了”怎么改？","options":["他凯旋归来","他凯旋了","他归来了","他凯旋归来了啊"],"answer":1,"解析":"旋就是归来，删去归来。","类":"意思重复式"},{"q":"“非常十分开心”怎么改？","options":["十分开心","非常开心","非常十分地开心","开心"],"answer":1,"解析":"程度词留一个就够。","类":"程度叠用式"},{"q":"“凯旋”本身就含什么意？","options":["胜利","归来","开心","回来"],"answer":1,"解析":"旋就是归来。","类":"意思重复式"}],"例子":["病：他凯旋归来了 → 改：他凯旋了（“旋”就是归来）","病：非常十分开心 → 改：非常开心","病：他亲眼目睹了这件事→改：他目睹了这件事（亲眼与目睹重复）","病：这件事的经过大概→改：这件事的经过（删“大概”或保留一处）","病：他非常非常高兴→改：他非常高兴（删重复）","病：大约三百多人左右→改：三百多人（删“大约”“左右”）","病：他回到了他的家乡→改：他回到了家乡（删“他的”）","病：这是一个非常极好的消息→改：这是一个极好的消息（删“非常”）","病：他首先第一个发言→改：他第一个发言（首先与第一重复）","病：我们共同一起努力→改：我们共同努力（删“一起”）"],"口诀":"意思重复，删去一个","易错":"“凯旋”本身就含“归来”意","决策树":"①有意思相近的词并存吗？→有：删一留一→②有\"的原因是因为/目的是为了\"类杂糅吗？→有：删杂糅部分→③有\"十分非常/大约左右\"类同义叠加吗？→有：留一个→④有\"凯旋归来/亲眼目睹\"类语义重复吗？→有：删重复义素→⑤无：不啰嗦","前置知识":[],"类比":"像穿了两件一样的毛衣：凯旋本身就含归来意，非常十分叠着穿。删去一件，意思一点不变，身上轻了，句子也干净了。"},{"name":"约数矛盾","讲解":"表示估计的词叠在一起用，意思重复或自相矛盾。","深讲":"「大约」「左右」「上下」都表示估计，同一个数只用一个：说了「大约」就不再说「左右」。「将近」表示不到这个数，「多」表示超过这个数，放在一起自相矛盾。注意：「大约三十多人」「至少有十多个」可以说，「三十多」「十多个」本身就是一个大概的数，不算病句。","分类":[{"类":"大约左右式","说明":"「大约」和「左右」（或「上下」）叠用。","代表":"大约有30人左右","例子":["大约有30人左右。"]},{"类":"将近……多式","说明":"「将近」（不到）和「多」（超过）叠用，前后矛盾。","代表":"将近有二十多人","例子":["将近有二十多人参加了比赛。"]}],"怎么认":["找表示估计的词：大约、左右、上下、将近、多。","「大约」和「左右/上下」同时出现，就是叠用。","「将近」和「多」同时出现，一个说不到、一个说超过，就是矛盾。"],"辨析":"约数矛盾和重复啰嗦的区别：约数矛盾是表示估计的词叠用（大约……左右）或互相矛盾（将近……多）；重复啰嗦是意思重复（凯旋归来）。","例句解析":[{"句":"大约有30人左右。","析":"「大约」和「左右」都表示估计，留一个：大约有30人。"},{"句":"将近有二十多人参加了比赛。","析":"「将近」是不到二十，「多」是超过二十，自相矛盾，改为：将近有二十人参加了比赛。"}],"练习":[{"q":"“大约有30人左右”怎么改？","options":["大约有30人左右啊","大约有30人","有30人左右","大约左右有30人"],"answer":1,"解析":"约数留一个就够。","类":"大约左右式"},{"q":"“将近有二十多人参加了比赛”怎么改？","options":["将近有二十多人左右参加了比赛","将近有二十人参加了比赛","大约将近有二十多人参加了比赛","将近有二十多人参加比赛了"],"answer":1,"解析":"「将近」和「多」矛盾，去掉「多」。","类":"将近……多式"},{"q":"下面哪个是约数词？","options":["一定","大约","确实","真的"],"answer":1,"解析":"大约是约数词。","类":"大约左右式"}],"例子":["病：大约有30人左右 → 改：大约有30人","病：将近有二十多人参加了比赛 → 改：将近有二十人参加了比赛","病：他的年龄大约十六七岁左右 → 改：他的年龄大约十六七岁","病：这条路大约长约五公里 → 改：这条路长约五公里","病：这个水池大约深两米左右 → 改：这个水池深约两米","病：大约有五六十人上下 → 改：大约有五六十人","病：这本书将近有三百多页 → 改：这本书将近有三百页","对：大约有三百多人参加（「三百多」本身是约数，可以说）"],"口诀":"大约左右留一个，将近和多不同坐","易错":"「大约」不和「左右」「上下」叠用；「将近」不和「多」叠用；「大约三十多人」可以说","决策树":"①有表示估计的词（大约/左右/上下/将近/多）吗？→无：不是约数问题→②「大约」和「左右/上下」同时出现吗？→是：留一个→③「将近」和「多」同时出现吗？→是：矛盾，删一个→④都不是：OK（「大约三十多」可以说）","前置知识":["数词"],"类比":"像一把尺子两头各报一个数：大约和左右叠用，等于估计了两遍；将近说不到，多说超过，两头一拉就扯断了。同一个数只用一个估计词。"},{"name":"否定失当","讲解":"多重否定算错了账，表意正好相反。","深讲":"改法是：否定加否定，意思要算清；避免、切忌、防止后不再加不。","分类":[{"类":"避免否定式","说明":"避免后又加不，意思反了。","代表":"避免不再犯错","例子":["为了避免不再犯错，我们要认真。"]},{"类":"切忌否定式","说明":"切忌后又加不，意思反了。","代表":"切忌不要骄傲","例子":["切忌不要骄傲。"]}],"怎么认":["否定词有几个？数一数。","避免、切忌、防止后有没有不？有，就是多余否定。","算一算否定，意思是不是反了？反了，就是否定失当。"],"辨析":"否定失当和前后矛盾的区别：否定失当是否定算错了账（避免不再犯错）；前后矛盾是说法打架（断定大概）。看问题在否定还是说法。","例句解析":[{"句":"为了避免不再犯错，我们要认真。","析":"避免后不再加不，改为：为了避免犯错。"},{"句":"切忌不要骄傲。","析":"切忌后不再加不，改为：切忌骄傲。"}],"练习":[{"q":"“为了避免不再犯错，我们要认真”怎么改？","options":["为了避免不再犯错","为了避免犯错","为了不再犯错","为了避免不犯错"],"answer":1,"解析":"避免后不再加不。","类":"避免否定式"},{"q":"“切忌不要骄傲”怎么改？","options":["切忌要骄傲","切忌骄傲","不要切忌骄傲","切忌不要不骄傲"],"answer":1,"解析":"切忌后不再加不。","类":"切忌否定式"},{"q":"“避免”“切忌”“防止”后不再加？","options":["不","要","会","能"],"answer":0,"解析":"避免、切忌、防止后不再加不。","类":"避免否定式"}],"例子":["病：为了避免不再犯错，我们要认真 → 改：为了避免犯错","病：切忌不要骄傲 → 改：切忌骄傲","病：我们要防止不再犯错→改：我们要防止犯错（删“不”）","病：他无时无刻不忘学习→改：正确（双重否定表肯定）","病：没有人不说他不好→改：没有人不说他好（删多余否定）","病：难道他不想不去吗→改：难道他不想去吗（删多余否定）","病：我们切忌不要骄傲→改：我们切忌骄傲（删“不要”）","病：他不禁忍不住笑了→改：他忍不住笑了（删“不禁”）","病：避免不发生事故→改：避免发生事故","病：我不会不帮你→改：正确（双重否定表一定帮）"],"口诀":"否定加否定，意思要算清","易错":"“避免”“切忌”“防止”后不再加“不”","决策树":"①数否定词：几个？→0-1个：一般没问题→②≥2个：连起来读，语义反了吗？→反了：删多余否定→③有\"避免/防止/忌/以免\"后加否定吗？→有：删否定（本身已含否定义）→④有\"无时无刻不\"类双重否定表肯定吗？→语义需要：保留→⑤否：否定没问题","前置知识":["副词","双重否定"],"类比":"像算账多算了一个负号：避免、切忌、防止后面再加不，意思正好翻了个面。为了避免不再犯错，算下来竟成了希望犯错，删掉多余的不，账才算对。"},{"name":"主谓搭配不当","讲解":"主语和谓语搭配不起来，对不上号。","深讲":"改法是：谁是什么，对号入座，人口不能是国家。","分类":[{"类":"主语谓语错位式","说明":"主语和谓语在概念上错位。","代表":"人口是国家","例子":["我国的人口是世界上最多的国家。"]},{"类":"概念错配式","说明":"主语概念和谓语概念不配。","代表":"南京是季节","例子":["三月的南京是美丽的季节。"]}],"怎么认":["压缩主干，主语是谁？谓语是什么？","主语和谓语配不配？不配，就是主谓搭配不当。","人口不能是国家，城市不能是季节，查概念。"],"辨析":"主谓搭配不当和动宾搭配不当的区别：主谓不当是主语配谓语错了（人口是国家）；动宾不当是动词配宾语错了（端正学习）。看错的是主谓还是动宾。","例句解析":[{"句":"我国的人口是世界上最多的国家。","析":"人口不能是国家，改为：我国是世界上人口最多的国家。"},{"句":"三月的南京是美丽的季节。","析":"南京不能是季节，主谓不合逻辑，也是主谓搭配不当。"}],"练习":[{"q":"“我国的人口是世界上最多的国家”怎么改？","options":["我国的人口是世界上最多的","我国是世界上人口最多的国家","我国的人口是最多的国家","我国是人口最多的国家"],"answer":1,"解析":"主语换成我国，人口作定语。","类":"主语谓语错位式"},{"q":"“三月的南京是美丽的季节”错在哪？","options":["缺宾语","主谓搭配不当","语序不当","结构混乱"],"answer":1,"解析":"南京不能是季节。","类":"概念错配式"},{"q":"主谓搭配的口诀是？","options":["动词宾语，手拉手配对","谁是什么，对号入座","通过使令，删一留一","关联成双，缺一不可"],"answer":1,"解析":"谁是什么，对号入座。","类":"主语谓语错位式"}],"例子":["病：我国的人口是世界上最多的国家 → 改：我国是世界上人口最多的国家","病：他的写作水平有了很大提高→改：正确（水平与提高搭配）","病：同学们都认真地完成了作业→改：正确（完成与作业搭配）","病：他的学习成绩很优异→改：他的学习成绩优异（删“很”）","病：我们要发扬光大革命传统→改：我们要发扬革命传统","病：他的声音很宏亮→改：正确（声音与宏亮搭配）","病：这场雨下得很及时→改：正确（雨与及时搭配）","病：他的态度很端正→改：正确（态度与端正搭配）","病：我们要养成良好的学习态度→改：我们要养成良好的学习习惯"],"口诀":"谁是什么，对号入座","易错":"“人口”不能是“国家”，主语谓语要门当户对","决策树":"①抽主语+谓语：语义通吗？→通：不是主谓搭配问题→②不通：主语是事物、谓语是动作吗？→是：换能发此动作的主语，或换谓语→③主谓褒贬/大小/范围一致吗？→不一致：换一端→④\"是\"字句两边等值吗？→不等：改","前置知识":["主语","谓语","搭配不当"],"类比":"像鞋子穿错了脚：人口不能是国家，南京不能是季节。主语和谓语要门当户对、对号入座，概念对不上，句子就站不稳。"},{"name":"动宾搭配不当","讲解":"动词和宾语不搭配。","深讲":"动宾搭配不当是动词和宾语不搭配。改法是：动词宾语，手拉手配对，端正配态度，提高配水平，别拉错手。","分类":[{"类":"端正配态度式","说明":"端正要配态度，不配学习。","代表":"端正学习","例子":["我们要端正学习。"]},{"类":"提高配水平式","说明":"提高要配水平、球技，不配发扬。","代表":"发扬了球技","例子":["他发扬了球技。"]}],"怎么认":["动词后面跟的是什么宾语？","动词和宾语配不配？不配，就是动宾搭配不当。","端正配态度，提高配水平，查一查固定搭配。"],"辨析":"动宾搭配不当和主谓搭配不当的区别：动宾不当是动词配宾语错了（端正学习）；主谓不当是主语配谓语错了（人口是国家）。看错的是动宾还是主谓。","例句解析":[{"句":"我们要端正学习。","析":"端正配态度，改为：端正学习态度。"},{"句":"他发扬了球技。","析":"发扬配精神，球技配提高，改为：他提高了球技。"}],"练习":[{"q":"“我们要端正学习”怎么改？","options":["我们要端正学习态度","我们要学习端正","我们要端正地学习","我们要学习"],"answer":0,"解析":"端正配态度。","类":"端正配态度式"},{"q":"“他发扬了球技”怎么改？","options":["他发扬了球技水平","他提高了球技","他发扬球技","他提高发扬球技"],"answer":1,"解析":"球技配提高，不配发扬。","类":"提高配水平式"},{"q":"“提高”配？","options":["态度","水平","精神","学习"],"answer":1,"解析":"提高配水平。","类":"提高配水平式"}],"例子":["病：我们要端正学习 → 改：端正学习态度","病：他发扬了球技 → 改：他提高了球技","病：我们要端正学习目的→改：我们要端正学习态度","病：他打碎了信心→改：他失去了信心（打碎与信心不搭配）","病：同学们完成了任务→改：正确（完成与任务搭配）","病：我们要提高学习→改：我们要提高学习成绩（补宾语中心）","病：他改正了缺点→改：正确（改正与缺点搭配）","病：老师提出了希望→改：正确（提出与希望搭配）","病：我们要爱护时间→改：我们要珍惜时间（爱护与时间不搭配）","病：他发挥了水平→改：正确（发挥与水平搭配）"],"口诀":"动词宾语，手拉手配对","易错":"“端正”配“态度”，“提高”配“水平”，别拉错手","决策树":"①抽动词+宾语：能搭配吗？→能：不是动宾搭配问题→②不能：看宾语语义，换能带此宾语的动词→③一动多宾：动词能管住每个宾语吗？→不能：拆开各配动词→④\"进行/加以\"+动词宾语赘余吗？→是：删\"进行\"","前置知识":["宾语","动词","搭配不当"],"类比":"像手拉错了手：端正要拉态度的手，提高要拉水平的手，端正学习、发扬球技都是拉错了手。动词和宾语配对了，动作才牵得起来。"}],"name":"常见病句类型（20种）"},{"id":"gaoji","name":"高级句式（10种）","items":[{"name":"把字句","类比":"把字句就像\"抓娃娃机\"：先\"把\"娃娃抓住（提起宾语），再决定怎么处置它。","讲解":"把宾语提前到动词前，强调对宾语的处置。公式：主语＋把＋宾语＋动词＋补语/了。","深讲":"公式：主语＋把＋宾语＋动词＋补语/了；动词不能光秃秃，后面要有补语或了表结果；心理动词（喜欢、觉得）不能用把字句。","分类":[{"类":"动词＋了式","说明":"动词后加了，表结果完成。","代表":"把＋宾语＋动词＋了","例子":["我把作业写完了。"]},{"类":"动词＋补语式","说明":"动词后加补语，表处置结果。","代表":"把＋宾语＋动词＋补语","例子":["妈妈把房间收拾干净了。"]}],"怎么认":["句子里有没有把？有。","把后面是不是宾语，动词在宾语后面？是的。","动词后面有没有补语或了？有，才是规范的把字句。"],"辨析":"把字句和被字句的区别：把字句强调处置（我把作业写完了：我处置了作业）；被字句强调承受（杯子被打碎了：杯子承受了打碎）。看主语是处置者还是承受者。","例句解析":[{"句":"我把作业写完了。","析":"把提前了宾语作业，动词写后有了了，是把字句。"},{"句":"他把杯子打碎了。","析":"把提前了宾语杯子，动词打后有了碎了，是把字句。"}],"练习":[{"q":"下面哪个把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或了表结果。","类":"动词＋了式"},{"q":"“妈妈把房间收拾干净了”属于？","options":["动词＋了式","动词＋补语式","被字句","存现句"],"answer":1,"解析":"动词收拾后有补语干净。","类":"动词＋补语式"},{"q":"“他喜欢音乐”能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"喜欢是心理动词，无处置义，不能用把。","类":"动词＋了式"}],"口诀":"把字提起宾，动词要有根（补语）","例子":["我把作业写完了","他把杯子打碎了","妈妈把房间收拾干净了","小明把垃圾扔进了垃圾桶。","老师把试卷发下来了。","我把这本书看完了。","爸爸把车修好了。","她把花插进了花瓶。","我们把教室打扫得干干净净。","奶奶把毛衣织好了。","把盐递给我。","我把他介绍给我老板了。","你们把那个问题解决了吗？","你把我手机放在哪儿了？","你能不能把你房间打扫干净？","他已经把钱还给我了。","我可能把手机忘在朋友家了。","他把最后三块蛋糕吃完了。","你把这几句话读一下。","把课文读一遍。","他把手机摔坏过两三次。","请把客人带进去。","把我的眼镜拿过来。","我把作业做完了。","老师把我的名字读错了。","阿姨没有把房间打扫干净。","我没把钱借给他。","你们不要把这件事告诉她。","我们把礼物送给客人了。","他把房子卖给谁了？"],"易错":"✗ 我把书看（动词光秃秃） ✓ 我把书看完了；心理动词（喜欢/觉得）不能用把字句；“把”后面的宾语通常是特指的、说话人和听话人都知道是哪个：我把这本书看完了（自然）／我把一本书看完了（单说不太自然）；“把＋一＋量＋名”的无定把字句是受限格式、不是病句，放进语境能说，如“这个寒假我总算把一本书看完了”；否定词（不要/别/没有）只能放在“把”前面，不能放在“把”后面：✓我没有把书看完；双宾语把字句：主语＋把＋宾语1＋动词＋给＋宾语2，如“我们把礼物送给客人了”；副词放“把”前还是动词后，意思会变：“我们都把作业做完了”（“都”修饰“我们”）vs“他把咖啡都喝完了”（“都”修饰“咖啡”）；数量短语的位置：名词量词短语跟在“把”后（我把那两件脏衣服洗干净了），动词量词放在句末（她把这个字写了十遍）；知觉动词（看、听、闻、像）不能用把字句，心理动词（爱、喜欢、想、了解、害怕、恨）也一样；可能补语不能进把字句：✗我把衣服洗不干净（可能补语讲的是“还没发生”，把字句必须讲实际发生的事）；为什么非用“把”不可：不说“放书在桌子上”（这句不合语法——动词后不能直接跟宾语、后面再跟别的成分），必须把宾语提前：“把书放在桌子上”；“把”还兼作量词：一词多义别混淆，如“请你把那把伞拿给我”（第一个“把”是介词，第二个“把”是量词）；把字句的疑问句有三种问法：加\"吗\"（你们把那个问题解决了吗？）、用疑问词（你把我手机放在哪儿了？/他把钱借给谁了？）、正反问（你能不能把你房间打扫干净？）；提问也要守住两点：宾语通常是说话双方都知道的那一个、必须讲清楚对宾语做了什么；把字句不跟时间挂钩：过去的事、现在的要求都能用；把字句爱讲\"把宾语怎么样了\"，动词后面最好有\"料\"：结果补语最搭（我把作业做完了、老师把我的名字读错了），趋向补语也搭（请把客人带进去、把我的眼镜拿过来）；双宾语把字句常用动词：送、拿、递、卖、借、还、介绍，如\"把盐递给我\"\"我把他介绍给我老板了\"；否定词只能放\"把\"前面的道理：否定词放\"把\"里面，等于说\"发生的事是什么都没发生\"，听着别扭，所以只能放外面：阿姨没有把房间打扫干净、我没把钱借给他、你们不要把这件事告诉她；副词新例：\"已经\"修饰整句（他已经把钱还给我了）；\"可能\"表推测（我可能把手机忘在朋友家了）；数量短语新例：他把最后三块蛋糕吃完了；你把这几句话读一下；把课文读一遍；他把手机摔坏过两三次；把字句是SOV语序：主语＋把＋宾语＋动词，\"宾语\"被提前到动词前面，语序从SVO变成了SOV","小测":[{"q":"哪句把字句正确？","options":["我把饭吃","我把饭吃完了","我把饭吃着"],"answer":1,"解析":"动词后要有补语或\"了\"表结果。"},{"q":"\"他喜欢音乐\"能改把字句吗？","options":["他把音乐喜欢了","不能改","他把音乐喜欢着"],"answer":1,"解析":"\"喜欢\"无处置义，不能用把。"}],"变式表":{"不变":"主+把+宾+动+补语/了，强调对宾语的处置","可变":{"主语":["我/他/妈妈"],"宾语":["具体（饭/书）","抽象（问题/心）"],"动补":["动+了（吃了）","动+结果补语（写完/洗干净）"]},"边界":"动词后须有'根'（✗我把饭吃）；心理动词不用把（✗我把他喜欢）；不及物动词不用把（✗我把跑步了）","覆盖已确认":["主语","宾语","动补"],"覆盖缺失":[]},"前置知识":["宾语","补语","动词","主语","副词","量词","介词"]},{"name":"被字句","类比":"被字句就像\"领奖台\"：动作的承受者站上主语位，强调它\"遭了什么\"。","讲解":"主语是动作的承受者。公式：受事＋被/叫/让＋施事＋动词＋补语。","深讲":"被后多为不如意事；被后可以没有施事，直接跟动词。","分类":[{"类":"被＋施事式","说明":"被后有施事，说明谁做的。","代表":"受事＋被＋施事＋动词","例子":["小明被小狗咬了。"]},{"类":"被无施事式","说明":"被后没有施事，只说承受了什么。","代表":"受事＋被＋动词","例子":["杯子被打碎了。"]},{"类":"叫让式","说明":"用叫、让代替被，意思一样。","代表":"受事＋叫/让＋施事＋动词","例子":["他叫雨淋湿了。"]}],"怎么认":["主语是不是承受者？是的。","句子里有没有被、叫、让？有。","被后是施事还是直接动词？施事就是被＋施事式，直接动词就是被无施事式。"],"辨析":"被字句和把字句的区别：被字句主语是承受者（杯子被打碎了）；把字句主语是处置者（我把杯子打碎了）。同一件事，角度不同，句式就不同。","例句解析":[{"句":"小明被小狗咬了。","析":"小明是承受者，被后有施事小狗，是被＋施事式。"},{"句":"我的气球被风吹走了。","析":"气球是承受者，被后有施事风，是被＋施事式。"}],"练习":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。","类":"被＋施事式"},{"q":"“杯子被打碎了”属于？","options":["被＋施事式","被无施事式","叫让式","把字句"],"answer":1,"解析":"被后没有施事，直接跟动词打碎。","类":"被无施事式"},{"q":"“他被吃了饭”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"被后多为不如意事，吃了饭不是遭遇，不能这样说。","类":"被＋施事式"}],"口诀":"被字一出，受害现身","例子":["小明被小狗咬了","杯子被打碎了","我的气球被风吹走了","作业被我写完了。","杯子被他打碎了。","房间被妈妈收拾干净了。","窗户被风吹开了。","我的书包被雨淋湿了。","庄稼被洪水淹没了。","他被老师表扬了。","球被小明踢进了球门。","衣服被太阳晒干了。"],"易错":"✗ 他被吃了饭 ✓ 他被批评了；\"被\"后多为不如意事","小测":[{"q":"被字句强调？","options":["谁做的","主语遭受了什么","动作多快"],"answer":1,"解析":"主语是受事，强调遭遇。"}],"变式表":{"不变":"主（承受者）+被+施事+动+补语，强调承受","可变":{"施事":["出现（杯子被他打碎了）","省略（杯子被打碎了）"],"动补":["动+了（打碎了）","动+补语（修好了）"]},"边界":"主语是承受者（与把字句主语是处置者相对）；'被'可换'叫/让'（口语）；不及物动词不用被；'被'字句多表不幸（'被表扬了'较少）","覆盖已确认":["施事","动补"],"覆盖缺失":[]},"前置知识":["主语","宾语","补语","动词"]},{"name":"存现句","类比":"存现句就像\"监控画面\"：某地（出现了/消失了）某物，讲的是\"有无\"，不是\"谁干了什么\"。","讲解":"表示某处存在、出现、消失某人/物。公式：处所＋动词＋人/物。如\"门口站着一个人\"。","深讲":"存现句表示某处存在、出现、消失某人或物。公式：处所＋动词＋人/物；主语是处所不是人；动词多为有、站、坐、来、去、走出、掉下。","分类":[{"类":"存在式","说明":"某处存在某人或物。","代表":"处所＋站/坐/写着＋人/物","例子":["门口站着一个人。"]},{"类":"出现式","说明":"某处出现某人或物。","代表":"处所＋走出/掉下＋人/物","例子":["屋里走出一位老人。"]},{"类":"消失式","说明":"某处消失某人或物。","代表":"处所＋少/不见＋人/物","例子":["屋里少了一个人。"]}],"怎么认":["主语是不是处所（门口、屋里、天上）？是的。","动词后面是不是人或物？是的。","整句是不是在说哪里有啥、哪里来了啥、哪里少了啥？是的。"],"辨析":"存现句和一般主谓句的区别：存现句主语是处所（门口站着一个人）；一般主谓句主语是人或物（一个人站在门口）。看主语是处所还是人。","例句解析":[{"句":"门口站着一个人。","析":"主语门口是处所，站着表存在，是存现句。"},{"句":"黑板上写着几个大字。","析":"主语黑板上是处所，写着表存在，是存现句。"}],"练习":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所门口，表存在。","类":"存在式"},{"q":"“屋里走出一位老人”属于？","options":["存在式","出现式","消失式","被字句"],"answer":1,"解析":"走出表出现。","类":"出现式"},{"q":"存现句的主语是？","options":["人","物","处所","动词"],"answer":2,"解析":"存现句的主语是处所不是人。","类":"存在式"}],"口诀":"哪里有啥，存现回答","例子":["天上掉下个馅饼","屋里走出一位老人","黑板上写着几个大字","天上有一轮明月。","桌子上放着一本书。","门口站着一位老师。","山上开满了野花。","水里游着一群小鱼。","墙上挂着一幅画。","教室里坐着许多学生。","天空中飞过一群大雁。","院子里种着几棵果树。","远处跑来一只小狗。"],"易错":"存现句的动词多为\"有/站/坐/来/去\"，主语是处所不是人","小测":[{"q":"哪句是存现句？","options":["我看见一个人","门口站着一个人","一个人站在门口"],"answer":1,"解析":"主语是处所\"门口\"，表存在。"}],"变式表":{"不变":"处所+动词+人/物，表示某处存在/出现/消失","可变":{"动词":["存在（有/是）","出现（来/走进）","消失（死/跑了）"],"处所":["句首（天上掉下个馅饼）","具体/抽象"]},"边界":"主语是处所不是施事；动词后名词是存在物（'天上掉馅饼'：馅饼是存在物）；'有'字句（'我有书'）不是存现句（主语是'我'）","覆盖已确认":["动词","处所"],"覆盖缺失":[]},"前置知识":["主语","谓语"]},{"name":"是…的句","类比":"是…的就像\"聚光灯\"：把\"是\"和\"的\"框住的部分照亮，强调\"就是它\"。","讲解":"强调已发生情况的时间/方式/处所。框住被强调成分。","深讲":"是……的句强调已发生情况的时间、方式、处所：是和的框住被强调的成分；只用于已发生的事，没发生的事不能用。","分类":[{"类":"强调时间式","说明":"是和的框住时间。","代表":"是＋昨天＋来的","例子":["我是昨天来的。"]},{"类":"强调方式式","说明":"是和的框住方式。","代表":"是＋坐火车＋走的","例子":["他是坐火车走的。"]},{"类":"强调处所式","说明":"是和的框住处所。","代表":"是＋在北京＋出生的","例子":["他是在北京出生的。"]}],"怎么认":["句子里有没有是……的框住一个成分？有。","这件事是不是已经发生了？是的。","框住的是时间、方式还是处所？对应就是哪种强调。"],"辨析":"是……的句和判断句的区别：是……的句强调已发生情况的状语（我是昨天来的：强调时间）；判断句是说谁是什么（我是学生）。看是后是不是时间、方式、处所。","例句解析":[{"句":"我是昨天来的。","析":"是和的框住昨天，强调时间。"},{"句":"他是坐火车走的。","析":"是和的框住坐火车，强调方式。"}],"练习":[{"q":"“我是昨天来的”强调？","options":["方式","时间","处所","原因"],"answer":1,"解析":"是和的框住昨天，强调时间。","类":"强调时间式"},{"q":"“他是坐火车走的”强调？","options":["时间","方式","处所","原因"],"answer":1,"解析":"是和的框住坐火车，强调方式。","类":"强调方式式"},{"q":"是……的句只用于？","options":["没发生的事","已发生的事","将来的事","假设的事"],"answer":1,"解析":"只用于已发生的事。","类":"强调时间式"}],"口诀":"是的框住，强调突出","例子":["我是昨天来的","他是坐火车走的","这本书是我昨天买的","他是昨天来的。","我是在图书馆看的这本书。","这件事是他告诉我的。","我们是坐火车去的北京。","这幅画是我画的。","她是去年毕业的。","这个消息是妈妈告诉我的。","我是用毛笔写的字。","他们是步行上山的。","这件毛衣是奶奶织的。","我是昨天来的。（'是'可省：我昨天来的）","我是坐车来的。（'的'不可省：✗我是坐车来）"],"易错":"只用于已发生的事；\"是…的\"中间是被强调的状语","变式表":{"不变":"是+…+的，强调已然情况的时间/方式/处所等","可变":{"强调":["时间（我是昨天来的）","方式（我是走来的）","处所（我在北京买的）","对象（我是给你买的）"],"省略":["'是'可省（我昨天来的）","'的'不可省"]},"边界":"表已然（✗我是明天来的）；'是'后是强调成分不是谓语；与判断句区别：判断句'是'后是名词（他是老师），是…的句'是'后可接动词短语","覆盖已确认":["强调"],"覆盖缺失":["省略"]},"前置知识":["主语","谓语","助词"]},{"name":"比较句","类比":"比较句就像\"天平\"：左边放一个，右边放一个，看哪边重。","讲解":"A 比 B ＋形容词：A 超过 B。否定用\"没有\"（我没有他高＝我不如他高，他高一些）。","深讲":"比较句常见三种说法：A 比 B ＋形容词（A 超过 B，可加「更」「还」表示程度更深）；A 没有 B ＋形容词（A 不如 B，B 高一些；不说差多少）；A 跟 B 一样＋形容词（两者相同）。","分类":[{"类":"比字句","说明":"用比表示超过。","代表":"A 比 B ＋形容词","例子":["我比他高。"]},{"类":"没有字句","说明":"用没有表示否定比较。","代表":"A 没有 B ＋形容词","例子":["今天没有昨天冷。"]},{"类":"一样句","说明":"用「跟（和）……一样」表示两者相同。","代表":"A 跟 B 一样＋形容词","例子":["我跟他一样高。"]}],"怎么认":["句子里有没有「比」「没有」「跟……一样」？有。","这些词后面是不是比较的对象？是的。","句末是不是说比较的结果（高、冷、跑得快）？是的。"],"辨析":"没有字句和比字句的区别：没有只否定“比”（我没有他高：我不如他高，他高一些，也就是我比他矮一些）；“差不多高”要说“不比”（他不比我高）。比是肯定超过（我比他高）。","例句解析":[{"句":"我比他高。","析":"比后是参照他，句末形容词高，是比字句。"},{"句":"今天没有昨天冷。","析":"没有表示否定比较，是没有字句。"}],"练习":[{"q":"“我没有他高”意思是？","options":["我和他一样高","我不如他高","他比我矮"],"answer":1,"解析":"没有＝不如他高，他高一些；“一样高”是“不比”的意思。","类":"没有字句"},{"q":"“弟弟比我高半头”属于？","options":["比字句","没有字句","一样句","把字句"],"answer":0,"解析":"比后是参照我，句末高半头。","类":"比字句"},{"q":"“他比我更高”属于？","options":["比字句","没有字句","一样句","把字句"],"answer":0,"解析":"用「比」引出比较对象「我」，是比字句；「更」表示程度更深。","类":"比字句"}],"口诀":"比后参照，形容收尾","例子":["我比他高","今天没有昨天冷","弟弟比我高半头","他比我高。","这本书比那本书有趣。","今天比昨天冷。","小明跑得比小红快。","西瓜比苹果甜。","他的成绩比我好得多。","这座山比那座山高。","夏天比冬天热。","我更喜欢红色。","弟弟不如哥哥高。"],"易错":"\"没有\"是否定比较：我没有他高＝我不如他高，他高一些；\"不比\"才多表示差不多高；\"更\"表递进（更好）","小测":[{"q":"\"我没有他高\"意思是？","options":["我和他一样高","我不如他高","他比我矮"],"answer":1,"解析":"\"没有\"＝不如他高，他高一些；\"一样高\"是\"不比\"的意思。"}],"变式表":{"不变":"比较两者的异同、高低","可变":{"类型":["比字句（他比我高）","没有（他没有我高）","更/最（更高/最高）","像…一样（像他一样高）"],"比较点":["性质（高）","动作（跑得快）","数量（多）"]},"边界":"'比'后是比较对象（'他比我高'：比我）；'更'须有比较对象（✗他更高了，无对象时表程度加深）；自比（'比以前好'）也成立","覆盖已确认":["类型","比较点"],"覆盖缺失":[]},"前置知识":["形容词","主语"]},{"name":"双重否定","类比":"双重否定就像\"负负得正\"：两个\"不\"撞在一起，变成强烈的肯定。","讲解":"不得不＝必须；不能不＝一定要。语气比单用\"必须\"更强烈、更无奈。","深讲":"双重否定是两个否定词连用，意思变成肯定：不得不＝必须，不能不＝一定要；语气比单用必须更强烈、更无奈。","分类":[{"类":"不得不式","说明":"不得不等于必须。","代表":"不得不＋动词","例子":["我不得不去。"]},{"类":"不能不式","说明":"不能不等于一定要。","代表":"不能不＋动词","例子":["他不能不承认。"]},{"类":"不会不式","说明":"不会不等于一定会。","代表":"不会不＋动词","例子":["他不会不来。"]}],"怎么认":["句子里有没有两个否定词（不、没、无、非）？有。","两个否定算一算，是不是变成肯定？是的。","语气是不是比单说必须更强烈？是的。"],"辨析":"双重否定和单否定不要搞混：不得不去＝必须去（肯定），不是不去；不能不承认＝一定要承认。算清否定，意思就对了。","例句解析":[{"句":"我不得不去。","析":"不得不等于必须，是双重否定。"},{"句":"我不得不承认他是对的。","析":"不得不等于必须承认，是双重否定。"}],"练习":[{"q":"“我不得不去”意思是？","options":["我不去","我必须去","我不想去","我没去"],"answer":1,"解析":"不得不等于必须。","类":"不得不式"},{"q":"“他不能不承认”意思是？","options":["他不承认","他一定要承认","他不想承认","他没承认"],"answer":1,"解析":"不能不等于一定要。","类":"不能不式"},{"q":"“他不会不来”意思是？","options":["他不来","他一定来","他可能不来","他不想来"],"answer":1,"解析":"不会不等于一定会。","类":"不会不式"}],"口诀":"双否变肯，语气加倍","例子":["我不得不去","他不能不承认","我不得不承认他是对的","他不得不承认错误。（=他必须承认错误）","这件事非他莫属。（=这件事一定是他）","没有人不喜欢和平。（=人都喜欢和平）","我不会不去的。（=我一定去）","这不是不重要。（=这很重要）","他无时无刻不在想念家乡。（=他一直想念家乡）","没有谁不渴望成功。（=都渴望成功）","这个道理不讲不明。（=讲了就明）","我不能不帮他。（=我一定要帮他）","没有付出就没有收获。（双重否定表强调）","他不能不说。（弱：语气较轻）","这件事非办不可。（强：语气强烈）"],"易错":"\"不会不\"（他不会不来＝他一定来）别和\"不\"搞混","变式表":{"不变":"两个否定表肯定，语气比单肯定强","可变":{"形式":["不得不（不得不去=必须去）","不会不（不会不知道=肯定知道）","没有…不…（没有人不…=都…）"],"强度":["弱（不能不说）","强（非去不可）"]},"边界":"双否=肯定（'不得不去'=去）；三重否定表否定（'我不是不知道'=知道，实际是双否）；口语'不…不…'（'不吃不喝'）是并列不是双否","覆盖已确认":["形式"],"覆盖缺失":["强度"]},"前置知识":["副词"]},{"name":"歧义句","类比":"歧义句就像\"魔术贴\"：一句话能贴出两种意思，病句题最爱考。","讲解":"一句话有两种理解。消歧方法：换切分、加标点、改语序。","深讲":"病句表意不明多为歧义，改法是明确主语或加标点。","分类":[{"类":"切分歧义","说明":"停顿（结构）不同，意思不同。","代表":"咬死了猎人的狗","例子":["咬死了猎人的狗。"]},{"类":"语义歧义","说明":"一个词、一个说法有两种意思。","代表":"走了一个小时","例子":["鸡不吃了。","他走了一个小时。"]},{"类":"指代歧义","说明":"代词不知道指谁。","代表":"他说他不去了","例子":["他说他不去了。"]}],"怎么认":["一句话能不能有两种理解？能，就是歧义。","换个切分，意思变不变？变，就是切分歧义。","代词指谁说不清？就是指代歧义。"],"辨析":"歧义句和病句表意不明的关系：歧义句是现象（一句话两种理解），表意不明是毛病（要改掉）；消歧的方法是换切分、加标点、改语序、明确主语。","例句解析":[{"句":"鸡不吃了。","析":"可以是鸡不吃食，也可以是人不吃鸡——停顿怎么切都一样，是谁吃谁说不清，属于语义（施受）歧义。"},{"句":"他走了一个小时。","析":"走可以是离开，也可以是步行，是语义歧义。"}],"练习":[{"q":"“咬死了猎人的狗”有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。","类":"切分歧义"},{"q":"“他走了一个小时”属于？","options":["切分歧义","语义歧义","指代歧义","把字句"],"answer":1,"解析":"走有离开和步行两种意思。","类":"语义歧义"},{"q":"“他说他不去了”属于？","options":["切分歧义","语义歧义","指代歧义","存现句"],"answer":2,"解析":"不知道是谁不去，是指代歧义。","类":"指代歧义"}],"口诀":"两切两意，歧义现形","例子":["鸡不吃了（鸡不吃/人不吃鸡）","他走了一个小时（离开/步行）","他说他不去了（到底谁不去？）","咬死了猎人的狗。（谁咬死谁？有歧义）","他背着总经理去开会。（他背？还是总经理背？）","数理化学习经验。（数理化学/习经验？）","我想起来了。（想起/起来？）","开刀的是他父亲。（他动手术？他是医生？）","这辆车没有锁。（没锁车/车没锁？）","他说不好。（说得不好/说不行？）","校长请老师吃饭。（谁请谁？）","雨天没有晴天多。（比较对象不明）","咬死了猎人的狗。（结构歧义：谁咬谁？）","他方便的时候你来。（词汇歧义：'方便'多义）","期中考试。（多音字成因：期中/期终？）","他一个人走了。（指代不明成因：独自去/他先走？）"],"易错":"病句\"表意不明\"多为歧义；改法：明确主语或加标点","小测":[{"q":"\"咬死了猎人的狗\"有几种理解？","options":["1种","2种","3种"],"answer":1,"解析":"两种切分，两种意思。"}],"变式表":{"不变":"一句话有两种以上理解","可变":{"类型":["语音歧义（'期中考试'断句）","词汇歧义（'方便'多义）","结构歧义（'咬死了猎人的狗'：谁咬谁）","语义指向歧义（'他一个人走了'）"],"成因":["多音字","多义词","结构","指代不明"]},"边界":"歧义是客观存在（不是病句）；消除靠加语境/标点/改词；病句是错，歧义是'可对可错'——考试常考辨析","覆盖已确认":[],"覆盖缺失":["类型","成因"]},"前置知识":["主语","谓语","宾语","定语"]},{"name":"兼语句","讲解":"一句话里，有个人或物“一身兼两职”：既是前一个动词的宾语，又是后一个动词的主语。","深讲":"兼语句的公式：主语 + 动词1 + 兼语 + 动词2。比如“我请他吃饭”：“他”既是“请”的宾语（我请他），又是“吃”的主语（他吃饭）。动词1多是“让/叫/请/使/派”这类带“使唤”意思的词。否定词放动词1前面：“老师没让我去”。","类比":"兼语句像接力赛：第一棒（请）把接力棒（他）交出去，“他”接到棒立刻跑第二棒（吃）——一个人跑了两棒。","口诀":"一人兼两职，前宾后主是他","例子":["我请他吃饭。","妈妈让我学钢琴。","老师请他进来。","公司派我出国。","这件事使我很感动。","这部电影让大家都哭了。","老师没让我交作业。","他的话使妹妹决定去工作。"],"易错":"“使”偏书面，“让”偏口语；“请”是请求，“让”还可以是允许或致使，别乱换。","分类":[{"类":"使令兼语","说明":"动词1是要求、派遣：请/派/要求/叫。","代表":"请他进来、派我出国","例子":["老师请他进来。","公司派我出国。"]},{"类":"致使兼语","说明":"动词1是导致某种结果或心情：让/使。","代表":"让我感动、使我高兴","例子":["这件事使我很感动。","这部电影让大家都哭了。"]},{"类":"否定式","说明":"不/没放在动词1前面。","代表":"没让我去","例子":["老师没让我交作业。","妈妈没让我看电视。"]}],"怎么认":["找“让/叫/请/使/派”这类词。","看它后面的人后面还有没有动词：有→可能是兼语。","那个人是不是“前是宾、后是主”：我请他（宾）+他吃饭（主）✓。"],"辨析":"兼语句和连动句的区别：连动句是同一个人做两件事（“我去北京看朋友”——去和看都是我）；兼语句是中间换了人（“我请他吃饭”——吃的是他不是我）。看第二件事是谁做的。","例句解析":[{"句":"我请他吃饭。","析":"“他”兼两职：是“请”的宾语（我请他），又是“吃”的主语（他吃饭）。"},{"句":"这件事使我很感动。","析":"“我”兼两职：是“使”的宾语，又是“感动”的主体（我很感动）。主语“这件事”是事情的起因。"}],"练习":[{"q":"“妈妈让我学钢琴”中，兼语是？","options":["妈妈","让","我","钢琴"],"answer":2,"解析":"“我”既是“让”的宾语，又是“学”的主语。","类":"结构"},{"q":"哪句是兼语句？","options":["我去北京看朋友","我请他吃饭","他喜欢唱歌","我们一起回家"],"answer":1,"解析":"“我请他吃饭”中“他”兼两职；“我去北京看朋友”是连动句。","类":"辨析"},{"q":"“老师没让我交作业”的否定词放哪？","options":["让后面","让我中间","让前面","句末"],"answer":2,"解析":"否定词放在动词1“让”的前面。","类":"否定"},{"q":"“使”和“让”有什么不同？","options":["没区别","使偏书面，让偏口语","使只能口语","让只能书面"],"answer":1,"解析":"“使”多用于书面正式场合，“让”口语常用。","类":"辨析"}],"前置知识":["主语","谓语","宾语","动词"]},{"name":"话题句","讲解":"把要强调的部分提前到句首当“话题”，后面再对它发表“评论”，话题和评论之间常有停顿。","深讲":"话题句的结构：话题 + 评论。比如“那部电影，看过的人都喜欢”：“那部电影”是话题（要强调的），“看过的人都喜欢”是评论。话题常常是宾语提前（“水果，我最爱吃草莓”）。主谓谓语句是话题句的一种：大主语带着小主谓（“他身体很好”：“他”是大话题，“身体很好”是小主谓）。","类比":"话题句像演出报幕：先报节目名（话题：下面请听《那部电影》），再正式演出（评论：看过的人都喜欢）。","口诀":"强调谁提前谁，话题评论逗号隔","例子":["那部电影，看过的人都喜欢。","水果，我最爱吃草莓。","这个问题，你一个人没办法解决。","你借我的钱，还没还吧？","他身体很好。","北京的话，秋天去最好。","那道菜，我已经吃了。","找对象，他特别挑剔。"],"易错":"话题和评论意思要相关；书面写话题句，话题后别忘了逗号（停顿）。","分类":[{"类":"宾语话题","说明":"把宾语提前当话题，后面评论。","代表":"水果，我爱吃","例子":["水果，我最爱吃草莓。","那道菜，我已经吃了。"]},{"类":"主谓谓语句","说明":"大主语 + 小主谓，小主谓说明大主语。","代表":"他身体很好","例子":["他身体很好。","她的话很多。"]},{"类":"时间处所话题","说明":"时间或地点提前，强调背景。","代表":"北京的话","例子":["北京的话，秋天去最好。","明天，我去你家。"]}],"怎么认":["句首的名词后是不是直接跟了个完整句子？是→可能是话题句。","把句首词放回动词后面，句子还通不通？通→是话题提前。","话题后有没有停顿（逗号）？有→更像话题句。"],"辨析":"话题句和一般主谓句的区别：一般主谓句的主语是动作的发出者；话题句的话题不一定是施事（“这件事你决定”——真正做决定的是“你”，“这件事”只是话题）。看句首词是不是动作的发出者。","例句解析":[{"句":"那部电影，看过的人都喜欢。","析":"“那部电影”是话题（被提前的宾语），“看过的人都喜欢”是评论。正常语序是“看过那部电影的人都喜欢”。"},{"句":"他身体很好。","析":"这是主谓谓语句：“他”是大话题，“身体很好”是个小主谓句，说明“他”的情况。"}],"练习":[{"q":"“水果，我最爱吃草莓”中，话题是？","options":["我","最爱","水果","草莓"],"answer":2,"解析":"“水果”被提前到句首当话题，后面是评论。","类":"结构"},{"q":"哪句是话题句？","options":["我吃苹果","那本书，我看了三遍","他跑得快","今天下雨"],"answer":1,"解析":"“那本书”提前当话题，后面“ 我看了三遍”是评论。","类":"辨析"},{"q":"“他身体很好”是什么句式？","options":["主谓句","主谓谓语句","把字句","被字句"],"answer":1,"解析":"大主语“他”+小主谓“身体很好”，是主谓谓语句。","类":"结构"},{"q":"话题句书面写的时候，话题后常加什么？","options":["句号","逗号","问号","顿号"],"answer":1,"解析":"话题后有停顿，书面用逗号隔开。","类":"书写"}],"前置知识":["主语","宾语"]},{"name":"给字被动","讲解":"口语里的被动句不用“被”，用“给”：事情给解决了吗？= 事情被解决了吗？","深讲":"结构：承受者 + 给 + 动词，比如“事情给解决了吗”（不说发出者）；要说出发出者，可以说“钱包给小偷偷走了”，口语也常说“叫/让 + 发出者 + 给 + 动词”（他叫老师给批评了一顿）。“给”字被动多用于口语，常带“倒霉、意外”的味道（“车给撞了”“钱包给偷了”）。正式书面语还是用“被”。","类比":"“给”字被动像“被”字的口语替身演员：正式场合“被”上场，胡同里聊天“给”上场，演的是同一出戏。","口诀":"口语被动不用被，给字顶上也对味","例子":["事情给解决了吗？","钱给花光了。","车给撞了。","我的钱包给偷了。","他叫老师给批评了一顿。","这事儿给忘了。","手机给摔坏了。"],"易错":"书面正式场合用“被”，口语才用“给”；“给”在这里是被动标记，不是“送给”的动词，别按“给东西”理解。","分类":[{"类":"省略发出者","说明":"不说谁干的，只说结果。","代表":"钱给花光了","例子":["钱给花光了。","车给撞了。"]},{"类":"带发出者","说明":"承受者+给+发出者+动词；或 承受者+叫/让+发出者+给+动词。","代表":"他叫老师给批评了","例子":["他叫老师给批评了一顿。"]}],"怎么认":["主语是不是受事（被…的那个）？是→可能是被动。","动词前有没有“给”？有→可能是给字被动。","换成“被”字意思变不变？不变→就是被动句。"],"辨析":"给字被动 vs 被字句：意思一样，语体不同（给=口语，被=通用/书面）。给字被动 vs 把字句：把字句强调“处置”（我把作业写完了），给字被动强调“承受”（作业给写完了）。看主语是处置者还是承受者。","例句解析":[{"句":"事情给解决了吗？","析":"“事情”是承受者，“给”是被动标记，发出者省略了。= 事情被解决了吗？"},{"句":"他叫老师给批评了一顿。","析":"完整结构：他（承受者）+叫+老师（发出者）+给+批评。“叫”引出发出者，“给”放在动词前。"}],"练习":[{"q":"“钱给花光了”换成“被”字句是？","options":["钱把花光了","钱被花光了","钱给花光被","钱花光了给"],"answer":1,"解析":"“给”换成“被”，意思不变：钱被花光了。","类":"辨析"},{"q":"哪句是给字被动？","options":["我给他钱","车给撞了","把书给他","他给了我一本书"],"answer":1,"解析":"“车给撞了”：车是承受者，“给”是被动标记。其余的“给”是动词（送给）。","类":"辨析"},{"q":"给字被动多用于？","options":["书面正式","口语","古文","法律文书"],"answer":1,"解析":"“给”字被动是口语说法，正式书面语用“被”。","类":"语体"},{"q":"“他叫老师给批评了一顿”里，谁是动作的发出者？","options":["他","老师","给","批评"],"answer":1,"解析":"“叫”后面的“老师”是发出者，“他”是承受者。","类":"结构"}],"前置知识":["被字句","主语","宾语"]}]},{"id":"xuci","name":"虚词精讲（16组）","items":[{"name":"了/着/过","类比":"\"了\"像拍照\"咔嚓\"（事成了/情况变了），\"着\"像视频\"录制中\"（持续），\"过\"像相册\"曾经\"（有过经历）。","讲解":"了₁表完成（动词后），了₂表变化（句末）；着表持续；过表经历。","深讲":"了有两种：了₁在动词后表完成，了₂在句末表变化；着表持续；过表经历。注意：“我吃饭了”的“了”在句末，是了₂，表示出现新情况；了₁和了₂也可以同时出现，如“我吃了饭了”。","分类":[{"类":"了₁完成式","说明":"动词后的了，表动作完成。","代表":"动词＋了","例子":["我吃了饭。"]},{"类":"了₂变化式","说明":"句末的了，表出现新情况。","代表":"句末＋了","例子":["太好了。"]},{"类":"着持续式","说明":"动词后的着，表动作持续。","代表":"动词＋着","例子":["他看着书。"]},{"类":"过经历式","说明":"动词后的过，表曾经的经历。","代表":"动词＋过","例子":["我去过长城。"]}],"怎么认":["了在动词后还是句末？动词后是了₁，句末是了₂。","动作是不是在持续？持续用着。","是不是在说曾经？曾经用过。"],"辨析":"了₁和了₂的区别：了₁在动词后表完成（我吃了饭）；了₂在句末表变化（太好了）。我吃饭了的了是了₂，表新情况，不是了₁。","例句解析":[{"句":"我吃了饭。","析":"吃了后的了在动词后，表完成，是了₁。"},{"句":"妹妹正哭着找妈妈。","析":"哭着的着表动作持续，是着持续式。"}],"练习":[{"q":"“我吃饭了”的了是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况，是了₂。","类":"了₂变化式"},{"q":"表“曾经”用？","options":["了","着","过"],"answer":2,"解析":"去过＝有过去的经历。","类":"过经历式"},{"q":"“他看着书”的着表？","options":["完成","持续","经历"],"answer":1,"解析":"看着表动作持续。","类":"着持续式"}],"口诀":"了表完成着表持续，过表曾经经历","例子":["我吃了饭","太好了","他看着书","我去过长城","我昨天去过动物园","妹妹正哭着找妈妈","我吃了饭。（了：完成）","他正看着书。（着：进行）","我去过北京。（过：经历）","天黑了。（了：变化）","门开着。（着：状态持续）","他读过这本书。（过：曾经）","下雨了，快回家吧。（了）","他笑着说话。（着）"],"易错":"句末的“了”是了₂，别当成了₁（我吃饭了＝了₂）","小测":[{"q":"\"我吃饭了\" 的\"了\"是？","options":["了₁完成","了₂变化","都是"],"answer":1,"解析":"句末表新情况（开始吃饭/吃完），是了₂。"},{"q":"表\"曾经\"用？","options":["了","着","过"],"answer":2,"解析":"\"去过\"＝有过去的经历。"}],"对照表":{"维度":["含义","用法","例句","误用"],"对比":[["了₁","含义：在动词后，表动作完成；用法：动词+了₁；例句：我吃了饭；误用：“我吃饭了”的了是了₂不是了₁，不要混"],["了₂","含义：在句末，表变化/新情况；用法：句末+了₂；例句：太好了；误用：“我吃饭了”的了是了₂，表新情况"],["着","含义：表进行/状态持续；用法：动词+着；例句：他看着书；门开着；误用：“正”字句一般不用“着”收尾"],["过","含义：表经历（曾经）；用法：动词+过；例句：我去过长城；误用：表一次完成不用“过”，用“了₁”"]]},"前置知识":["助词","动词"]},{"name":"的/地/得","类比":"的像\"标签\"（贴名词），地像\"滤镜\"（修饰动作），得像\"成绩单\"（动作后打分）。","讲解":"的＋名词（定语），地＋动词（状语），得＋补语。口诀：的地得，不一样；名前的（白勺）的，动前的（土也）地，动后的得。","深讲":"口诀：白勺的贴名，土也地跟动，得后补结果。","分类":[{"类":"的定语式","说明":"的后面是名词，修饰名词。","代表":"的＋名词","例子":["美丽的花。"]},{"类":"地状语式","说明":"地后面是动词，修饰动词。","代表":"地＋动词","例子":["认真地听。"]},{"类":"得补语式","说明":"得后面是补语，补充动词结果。","代表":"动词＋得＋补语","例子":["跑得快。"]}],"怎么认":["后面是不是名词？名词前的用白勺的。","后面是不是动词？动词前的用土也地。","是不是在动词后补结果？补结果的用得。"],"辨析":"的地得不要混：的贴名（美丽的花），地跟动（认真地听），得后补结果（跑得快）。看后面的词是名词、动词还是补语。","例句解析":[{"句":"美丽的花。","析":"的后面是名词花，是定语，用白勺的。"},{"句":"他高兴地笑了。","析":"地后面是动词笑，是状语，用土也地。"}],"练习":[{"q":"“认真_听讲”填？","options":["的","地","得"],"answer":1,"解析":"修饰动词听，用地。","类":"地状语式"},{"q":"“跑_很快”填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用得。","类":"得补语式"},{"q":"“美丽_花”填？","options":["的","地","得"],"answer":0,"解析":"后面是名词花，用白勺的。","类":"的定语式"}],"口诀":"白勺的贴名，土也地跟动，得后补结果","例子":["美丽的花","认真地听","跑得快","他高兴地笑了","这道题做得真好","美丽的花。（的+名词）","认真地听讲。（地+动词）","跑得快。（得+补语）","可爱的孩子。（的）","高兴地说。（地）","写得好。（得）","红红的苹果。（的）"],"易错":"的地得是小学高频错；记住\"的地得\"顺口溜","小测":[{"q":"\"认真_听讲\"填？","options":["的","地","得"],"answer":1,"解析":"修饰动词\"听\"，用\"地\"。"},{"q":"\"跑_很快\"填？","options":["的","地","得"],"answer":2,"解析":"动词后补结果，用\"得\"。"}],"对照表":{"维度":["含义","用法","例句","误用"],"对比":[["的","含义：贴名词（定语的标志）；用法：的+名词；例句：美丽的花；误用：❌“认真的话”（修饰动词“说”该用“地”）"],["地","含义：跟动词（状语的标志）；用法：地+动词；例句：认真地听；误用：❌“高兴的话”（修饰动词“说”）→ ✅“高兴地说”"],["得","含义：后接补语（结果/状态）；用法：动词/形容词+得+补语；例句：跑得快；误用：❌“跑的快”→ ✅“跑得快”"]]},"前置知识":["定语","状语","补语","助词"]},{"name":"在/再","讲解":"“在”表处所、存在，“再”表重复、又一次。读音一样（zài），看意思选字。","深讲":"在和再读音一样（zài），意思不同：在表处所、存在，再表重复、又一次。看意思选字，不能只听读音。","分类":[{"类":"在处所式","说明":"在表处所、存在。","代表":"在＋处所","例子":["我在教室里读书。"]},{"类":"再重复式","说明":"再表又一次、重复。","代表":"再＋动词","例子":["妈妈说明天再去公园。"]}],"怎么认":["是不是在说哪里？哪里用在。","是不是在说又一次？又一次用再。","换成处所或又一次，意思通吗？通的就是对的。"],"辨析":"在和再的区别：在是处所（我在教室里），再是重复（再说一遍）。请在说一遍是错的，应为请再说一遍。","例句解析":[{"句":"我在教室里读书。","析":"在表处所教室里，是在处所式。"},{"句":"妈妈说明天再去公园。","析":"再表又一次去，是再重复式。"}],"练习":[{"q":"“请_说一遍”填？","options":["在","再"],"answer":1,"解析":"又一次说，用再。","类":"再重复式"},{"q":"“我_教室里读书”填？","options":["在","再"],"answer":0,"解析":"表处所，用在。","类":"在处所式"},{"q":"“我_吃一次”填？","options":["在","再"],"answer":1,"解析":"又一次吃，用再。","类":"再重复式"}],"例子":["我在教室里读书（处所）","妈妈说明天再去公园（又一次）","✗ 我在吃一次 → ✓ 我再吃一次","我在学校上课。（在：处所）","我们再见面吧。（再：又一次）","他在家里看书。（在）","请再说一遍。（再）","小鸟在天上飞。（在）","明天再来吧。（再）","他在操场上跑步。（在）","吃完饭再出去玩。（再）","鱼在水里游。（在）"],"口诀":"处所在，再又来","易错":"✗ 请在说一遍 → ✓ 请再说一遍","类比":"“在”像图钉📌，钉住地点；“再”像回放键🔁，事情重来一遍。","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["在","含义：表处所；用法：在+处所；例句：我在教室里读书；误用：❌“请在说一遍”→ ✅“请再说一遍”"],["再","含义：表重复（又一次）；用法：再+动词；例句：明天再去公园；误用：❌“我在吃一次”→ ✅“我再吃一次”"]]},"前置知识":["副词","介词"]},{"name":"做/作","讲解":"“做”多指具体动手干，“作”多指抽象创作。口语多用“做”，书面语“作”更多。","深讲":"做多指具体动手干，作多指抽象创作。口语多用做，书面语作更多。口诀：动手做，动笔作。","分类":[{"类":"做动手式","说明":"做表具体动手干。","代表":"做作业、做饭、做游戏","例子":["做作业。"]},{"类":"作抽象式","说明":"作表抽象创作、书面。","代表":"作文、作品、作为","例子":["作文。"]}],"怎么认":["是不是动手干的活？动手用做。","是不是写文章、创作？创作、书面用做。","「作」有两个读音：大多数词读 zuò（作息、作文、工作），只有「作坊」「作揖」等少数词读 zuō。"],"辨析":"做和作的区别：做是动手（做饭、做游戏），作是动笔、抽象（作文、作品）。做文是错的，应为作文。","例句解析":[{"句":"做作业、做饭、做游戏。","析":"都是动手干的活，用做。"},{"句":"作文、作品、作为。","析":"都是抽象创作、书面词，用作。"}],"练习":[{"q":"“_文”填？","options":["做","作"],"answer":1,"解析":"作文是抽象创作，用作。","类":"作抽象式"},{"q":"“_饭”填？","options":["做","作"],"answer":0,"解析":"做饭是动手干，用做。","类":"做动手式"},{"q":"“作息”读？","options":["zuò xī","zuō xī","zhuō xī"],"answer":0,"解析":"作息的「作」读 zuò（《现代汉语词典》：作息 zuòxī）。读 zuō 的是「作坊」等少数词。","类":"作抽象式"}],"例子":["做作业、做饭、做游戏（动手）","作文、作品、作为（书面/抽象）","✗ 做文 → ✓ 作文","做作业。（做：从事）","作报告。（作：写作/担任）","做饭。（做）","作文。（作：写文章）","做人要诚实。（做）","作为班长，他很负责。（作）","做梦。（做）","作曲。（作）","做生意。（做）"],"口诀":"动手做，动笔作","易错":"“作息”读 zuò xī，不读 zuō；读 zuō 的是“作坊”“作揖”等少数词","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["做","含义：动手、从事（口语常用）；用法：做+具体事；例句：做饭、做游戏；误用：❌“做文”→ ✅“作文”"],["作","含义：动笔、抽象、书面；用法：作+抽象/书面语；例句：作文、作品；误用：❌“做文是错的，应为作文”"]]},"前置知识":["动词"],"类比":"像两兄弟分工：<b>做</b>是动手干活的哥哥，做饭、做作业；<b>作</b>是动笔创作的弟弟，作文、作品。动手找哥哥，动笔找弟弟，口诀就是动手做、动笔作。"},{"name":"和/与","讲解":"“和”可做连词也可做介词，“与”是书面说法。做连词时前后能互换，做介词时不能。","深讲":"和可做连词也可做介词，与是书面说法。做连词时前后能互换，做介词时不能互换，否则意思变了。","分类":[{"类":"和连词式","说明":"和做连词，前后能互换。","代表":"我和妈妈","例子":["我和妈妈去公园。"]},{"类":"和介词式","说明":"和做介词，前后不能互换。","代表":"和老师谈话","例子":["他和老师谈话。"]},{"类":"与书面式","说明":"与是和的书面说法。","代表":"我与妈妈","例子":["我与妈妈去公园。"]}],"怎么认":["前后换个位置，意思变不变？不变，就是连词。","换了位置意思变了，就是介词。","是不是书面语？书面语多用与。"],"辨析":"和连词和和介词的区别：连词能互换（我和妈妈＝妈妈和我）；介词不能互换（他和老师谈话≠老师和他谈话，意思变了）。","例句解析":[{"句":"我和妈妈去公园。","析":"前后能互换：妈妈和我去公园，是连词。"},{"句":"他和老师谈话。","析":"前后不能互换，是介词。"}],"练习":[{"q":"“我和妈妈去公园”中的和是？","options":["连词","介词","动词"],"answer":0,"解析":"前后能互换，是连词。","类":"和连词式"},{"q":"“他和老师谈话”中的和是？","options":["连词","介词","动词"],"answer":1,"解析":"前后不能互换，是介词。","类":"和介词式"},{"q":"“我与妈妈”中的与是？","options":["口语","书面说法","错别字"],"answer":1,"解析":"与是和的书面说法。","类":"与书面式"}],"例子":["我和妈妈去公园（连词，可换：妈妈和我）","我与妈妈（书面）","他和老师谈话（介词，不可换）","我和他是好朋友。（和：连词）","他与我同岁。（与：连词）","我把书和笔放在桌上。（和）","老师与同学一起劳动。（与）","苹果和香蕉都很甜。（和）","他与大家分享快乐。（与）","爸爸和妈妈去上班了。（和）","我们与时间赛跑。（与）","小猫和小狗在玩耍。（和）"],"口诀":"能互换是连词","易错":"作介词时前后不能换，否则意思变了","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["和（连词）","含义：连接并列成分；用法：前后能互换；例句：我和妈妈＝妈妈和我；误用：互换后意思变了就不是连词"],["和（介词）","含义：引出对象；用法：前后不能互换；例句：他和老师谈话（≠老师和他谈话）；误用：❌把介词“和”当连词互换"],["与","含义：书面语的“和”；用法：多用于书面；例句：我与妈妈同岁；误用：口语少用“与”"]]},"前置知识":["连词","介词"],"类比":"像两兄弟一个口语一个书面：<b>和</b>能当连词也能当介词，<b>与</b>是书面的说法。连词的兄弟能换位，我和妈妈等于妈妈和我；介词的不能换，和老师谈话换了意思就变了。"},{"name":"把/被","讲解":"“把”字句强调处置（对宾语做了什么），“被”字句强调遭遇（主语受了什么）。","深讲":"把字句强调处置（对宾语做了什么），被字句强调遭遇（主语受了什么）。口诀：把字处置，被字受害；被后多为不如意事。","分类":[{"类":"把处置式","说明":"把字句，主语处置宾语。","代表":"把＋宾语＋动词","例子":["我把教室打扫干净了。"]},{"类":"被遭遇式","说明":"被字句，主语受到动作。","代表":"受事＋被＋动词","例子":["小明被老师表扬了。"]}],"怎么认":["主语是不是在处置宾语？是的，用把。","主语是不是受到了什么？是的，用被。","被后多为不如意事，说好事用被要小心。"],"辨析":"把和被的区别：把是处置（我把教室打扫干净了：我处置了教室）；被是遭遇（小明被老师表扬了：小明受到表扬）。看主语是处置者还是承受者。","例句解析":[{"句":"我把教室打扫干净了。","析":"我处置了教室，是把处置式。"},{"句":"小明被老师表扬了。","析":"小明受到表扬，是被遭遇式。"}],"练习":[{"q":"“我把教室打扫干净了”强调？","options":["处置","遭遇","处所","时间"],"answer":0,"解析":"把字句强调处置。","类":"把处置式"},{"q":"“小明被老师表扬了”强调？","options":["处置","遭遇","处所","时间"],"answer":1,"解析":"被字句强调遭遇。","类":"被遭遇式"},{"q":"“我喜欢音乐”能改把字句吗？","options":["我把音乐喜欢了","不能改","我把音乐喜欢着"],"answer":1,"解析":"喜欢无处置义，不能用把。","类":"把处置式"}],"例子":["我把教室打扫干净了（我处置了教室）","小明被老师表扬了（小明受到表扬）","我喜欢音乐 → 不能改成“把”字句","我把作业写完了。（把：处置）","杯子被打碎了。（被：被动）","妈妈把衣服洗干净了。（把）","他被老师表扬了。（被）","他把门关上了。（把）","我把这本书看完了。（把）","庄稼被水淹了。（被）","她把花插进花瓶。（把）"],"口诀":"把字处置，被字受害","易错":"“被”后多为不如意事，说好事用“被”很别扭","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["把","含义：表处置；用法：主语是处置者；例句：我把教室打扫干净了；误用：❌“我喜欢音乐”不能改成“把”字句（“喜欢”不是处置）"],["被","含义：表遭遇（被动）；用法：主语是承受者；例句：小明被老师表扬了；误用：看主语是处置者还是承受者"]]},"前置知识":["把字句","被字句"],"类比":"像两兄弟一个动手一个挨着：<b>把</b>是处置的哥哥，我把教室打扫干净了；<b>被</b>是承受的弟弟，小明被老师表扬了。看主语是处置者还是承受者，就知道叫哪个兄弟。"},{"name":"吗/呢/吧","讲解":"“吗”问是非，“呢”问补充或反问，“吧”表商量、祈使。","深讲":"吗问是非，呢问补充或反问，吧表商量、祈使。口诀：吗问是非，呢问补充，吧来商量；陈述句末不能加吗。","分类":[{"类":"吗是非问式","说明":"吗问是不是。","代表":"……吗？","例子":["你去吗？"]},{"类":"呢补充问式","说明":"呢问补充，也可反问。","代表":"……呢？","例子":["你呢？"]},{"类":"吧商量式","说明":"吧表商量、祈使、催促。","代表":"……吧！","例子":["我们走吧！"]}],"怎么认":["是不是在问是非？是非问用吗。","是不是在追问补充？你呢用呢。","是不是在商量、催促？商量、催促用吧。"],"辨析":"吗、呢、吧的区别：吗问是非（你去吗？），呢问补充（你呢？），吧表商量（我们走吧！）。陈述句末不能加吗：我去吗学校是错的。","例句解析":[{"句":"你去吗？","析":"问是非，用吗。"},{"句":"我们走吧！","析":"表商量，用吧。"}],"练习":[{"q":"“你去_？”填？","options":["吗","呢","吧"],"answer":0,"解析":"问是非，用吗。","类":"吗是非问式"},{"q":"“你_？”（追问补充）填？","options":["吗","呢","吧"],"answer":1,"解析":"追问补充，用呢。","类":"呢补充问式"},{"q":"“我们走_！”（商量）填？","options":["吗","呢","吧"],"answer":2,"解析":"表商量，用吧。","类":"吧商量式"}],"例子":["你去吗？（是非问）","你呢？（补充问）","我们走吧！（商量）","快点吧！（催促）","你去过北京吗？（吗：疑问）","他去哪儿了呢？（呢：疑问）","我们一起去吧。（吧：建议）","你吃饭了吗？（吗）","这本书好看呢。（呢：强调）","快点吧，要迟到了。（吧：催促）","你是谁呀？（呢/呀语气）","让我想想吧。（吧：商量）"],"口诀":"吗问是非，呢问补充，吧来商量","易错":"陈述句末不能加“吗”：✗ 我去吗学校","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["吗","含义：问是非；用法：句末，答“是/不是”；例句：你去吗？；误用：❌“我去吗学校”（陈述句末不能加“吗”）"],["呢","含义：问补充/表强调；用法：句末；例句：你呢？；这本书好看呢；误用：“呢”不问是非"],["吧","含义：表商量/催促/建议；用法：句末；例句：我们走吧！；快点吧！；误用：“吧”不是疑问语气"]]},"前置知识":["语气词"],"类比":"像三姐妹各管一种口气：<b>吗</b>管是非问，你去吗；<b>呢</b>管追问补充，你呢；<b>吧</b>管商量催促，我们走吧。陈述句末不能加吗，就像不能请问句的姐姐来管陈述。"},{"name":"才/就","讲解":"“才”表晚、少、难（比想的晚/少），“就”表早、多、易（比想的早/多）。","深讲":"才表晚、少、难（比想的晚、少、难），就表早、多、易（比想的早、多、易）。口诀：才嫌晚少难，就嫌早多易；时间＋才/就，意思正好相反，别用反。","分类":[{"类":"才晚少难式","说明":"才表比想的晚、少、难。","代表":"九点才起床","例子":["他九点才起床。"]},{"类":"就早多易式","说明":"就表比想的早、多、易。","代表":"六点就起床","例子":["他六点就起床了。"]}],"怎么认":["是不是比想的晚、少、难？是的，用才。","是不是比想的早、多、易？是的，用就。","换成另一个，意思是不是正好相反？是的，说明才和就不能用反。"],"辨析":"才和就的区别：才是晚、少、难（九点才起床：晚），就是早、多、易（六点就起床了：早）。这么难的题，他才用了五分钟：才是少。","例句解析":[{"句":"他九点才起床。","析":"九点比想的晚，用才。"},{"句":"他六点就起床了。","析":"六点比想的早，用就。"}],"练习":[{"q":"“他九点_起床”（比想的晚）填？","options":["才","就"],"answer":0,"解析":"晚用才。","类":"才晚少难式"},{"q":"“他六点_起床了”（比想的早）填？","options":["才","就"],"answer":1,"解析":"早用就。","类":"就早多易式"},{"q":"“这么难的题，他_用了五分钟”填？","options":["才","就"],"answer":0,"解析":"五分钟是少，用才。","类":"才晚少难式"}],"例子":["他九点才起床（比想的晚）","他六点就起床了（比想的早）","这么难的题，他才用了五分钟（少）","他才十岁，就会背诗了。（才：小/就：顺承）","我等了半天，他才来。（才：晚）","他一看就会了。（就：快）","这么难的题，他才不怕呢。（才：强调）","一下课，同学们就跑出去了。（就）","他才走了三分钟。（才：少）","有志者事竟成，他就是例子。（就：确定）","妈妈才回来，就开始做饭。（才…就…）","这本书才五块钱。（才：便宜）"],"口诀":"才嫌晚少难，就嫌早多易","易错":"时间+才/就，意思正好相反，别用反","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["才","含义：表晚、少、难；用法：数量/时间超出预期地“多耗”；例句：他九点才起床（晚）；这么难的题，他才用了五分钟（少）；误用：❌“他九点就起床”想表达“晚”时不能用“就”"],["就","含义：表早、多、易；用法：数量/时间比预期“省”；例句：他六点就起床了（早）；误用：❌“他六点才起床”想表达“早”时不能用“才”"]]},"前置知识":["副词"],"类比":"像跷跷板的两头：<b>才</b>压着晚、少、难那头，九点才起床；<b>就</b>压着早、多、易那头，六点就起床。同一句话换一个词，跷跷板就翻到相反一边，千万别用反。"},{"name":"都/也","讲解":"“都”表全部、总括，“也”表同样、类推。","深讲":"都表全部、总括，也表同样、类推。口诀：都管全部，也管同样；都和全部意思重复，不能叠用。","分类":[{"类":"都全部式","说明":"都表全部。","代表":"同学们都来了","例子":["同学们都来了。"]},{"类":"也同样式","说明":"也表同样。","代表":"我也想去","例子":["我也想去。"]}],"怎么认":["是不是在说全部？全部用都。","是不是在说同样？同样用也。","都和全部叠用了吗？叠用了就是重复。"],"辨析":"都和也的区别：都是全部（同学们都来了），也是同样（我也想去）。全班都全部来了是错的，都和全部重复了。","例句解析":[{"句":"同学们都来了。","析":"都表全部，是都全部式。"},{"句":"他跑得快，我也跑得快。","析":"也表同样，是也同样式。"}],"练习":[{"q":"“同学们_来了”（全部）填？","options":["都","也"],"answer":0,"解析":"全部用都。","类":"都全部式"},{"q":"“我_想去”（同样）填？","options":["都","也"],"answer":1,"解析":"同样用也。","类":"也同样式"},{"q":"“全班都全部来了”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"都和全部重复了。","类":"都全部式"}],"例子":["同学们都来了（全部）","我也想去（同样）","他跑得快，我也跑得快","我们都爱祖国。（都：全部）","他也会唱歌。（也：同样）","同学们都到齐了。（都）","我也想去。（也）","大家都笑了。（都）","她也不知道。（也）","花草树木都绿了。（都）","你也来啦。（也）","这些题我都会。（都）"],"口诀":"都管全部，也管同样","易错":"✗ 全班都全部来了（“都”和“全部”重复）","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["都","含义：表全部；用法：都+范围；例句：同学们都来了；误用：❌“全班都全部来了”（“都”和“全部”重复）"],["也","含义：表同样；用法：也+相同情况；例句：我也想去；误用：“也”不表全部"]]},"前置知识":["副词"],"类比":"像两兄弟一个管全部一个管同样：<b>都</b>把同学们都来了全包进来，<b>也</b>把我也想去贴在别人后面。都和全部意思重复，不能叠用，全班都全部来了就是穿了两件一样的衣服。"},{"name":"以/已","讲解":"“以”表凭借、按照（yǐ），“已”表已经（yǐ）。同音不同义，看意思选。","深讲":"以和已同音（yǐ），意思不同：以表凭借、按照，已表已经。看意思选字，看偏旁区分。","分类":[{"类":"以凭借式","说明":"以表凭借、按照。","代表":"以第一名的成绩","例子":["他以第一名的成绩获奖。"]},{"类":"已已经式","说明":"已表已经。","代表":"已经写完","例子":["我已经写完作业了。"]}],"怎么认":["是不是在说凭借、按照？凭借用以。","是不是在说已经？已经用已。","以经吃饭是错的，应为已经吃饭。"],"辨析":"以和已的区别：以是凭借（以第一名的成绩），已是已经（已经写完作业）。同音不同义，看意思选。","例句解析":[{"句":"他以第一名的成绩获奖。","析":"以表凭借，是以凭借式。"},{"句":"我已经写完作业了。","析":"已表已经，是已已经式。"}],"练习":[{"q":"“他_第一名的成绩获奖”填？","options":["以","已"],"answer":0,"解析":"凭借用以。","类":"以凭借式"},{"q":"“我_经写完作业了”填？","options":["以","已"],"answer":1,"解析":"已经用已。","类":"已已经式"},{"q":"“以经吃饭”对吗？","options":["对","不对","有时对","看情况"],"answer":1,"解析":"应为已经吃饭。","类":"已已经式"}],"例子":["他以第一名的成绩获奖（凭借）","我已经写完作业了（已经）","✗ 以经吃饭 → ✓ 已经吃饭","他已经走了。（已：已经）","我们要以诚待人。（以：用）","会议已结束。（已）","他以优异的成绩毕业。（以）","我早已听说过他。（已）","以理服人。（以）","天色已晚。（已）","他以跑步为乐。（以）","事情已经办妥。（已）"],"口诀":"以表凭借，已表已经","易错":"同音字，看偏旁区分","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["以","含义：表凭借、用；用法：以+凭借物；例句：他以第一名的成绩获奖；误用：❌“以经吃饭”→ ✅“已经吃饭”"],["已","含义：就是“已经”；用法：已+完成；例句：我已经写完作业了；误用：同音不同义，看意思选"]]},"前置知识":["介词","副词"],"类比":"像同音的两兄弟，声音一样、分工不同：<b>以</b>管凭借、按照，以第一名的成绩；<b>已</b>管已经，已经写完作业。听声音分不出，看意思、看偏旁才能认对人。"},{"name":"像/象","讲解":"“像”表相似、好像，“象”指大象或形状、现象。","深讲":"像表相似、好像，象指大象或形状、现象。口诀：相似用单人像，大象气象用象；好像不能写成好象。","分类":[{"类":"像相似式","说明":"像表相似、好像。","代表":"像爸爸一样高","例子":["他像爸爸一样高。"]},{"类":"象动物式","说明":"象指大象。","代表":"大象","例子":["大象的鼻子很长。"]},{"类":"象现象式","说明":"象指形状、现象。","代表":"气象","例子":["气象。"]}],"怎么认":["是不是在说相似、好像？相似用单人像。","是不是在说大象？大象用象。","是不是在说气象、现象？现象用象。"],"辨析":"像和象的区别：像是相似（像爸爸一样高），象是大象或现象（大象、气象）。气像是错的，应为气象。","例句解析":[{"句":"他像爸爸一样高。","析":"表相似，用单人像。"},{"句":"大象的鼻子很长。","析":"指大象，用象。"}],"练习":[{"q":"“他_爸爸一样高”填？","options":["像","象"],"answer":0,"解析":"相似用单人像。","类":"像相似式"},{"q":"“大_的鼻子很长”填？","options":["像","象"],"answer":1,"解析":"大象用象。","类":"象动物式"},{"q":"“气_”填？","options":["像","象"],"answer":1,"解析":"气象是现象，用象。","类":"象现象式"}],"例子":["他像爸爸一样高（相似）","大象的鼻子很长","✗ 气像 → ✓ 气象","他像爸爸一样高。（像：好像）","大象的鼻子很长。（象：动物）","天上的云像棉花。（像）","这只小象很可爱。（象）","她的笑容像春风。（像）","画像挂在墙上。（象：形状/画像）","他长得像妈妈。（像）","气象万千。（象：景象）","好像要下雨了。（像）"],"口诀":"相似用单人像，大象气象用象","易错":"“好像”不能写成“好象”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["像","含义：表相似（好像）；用法：像+比较对象；例句：他像爸爸一样高；误用：❌“气像”→ ✅“气象”"],["象","含义：大象或现象/景象；用法：象+动物/景象；例句：大象的鼻子很长；气象万千；误用：表相似时不用“象”"]]},"前置知识":["动词"],"类比":"像两兄弟一个管相似一个管本物：单人旁的<b>像</b>管相似、好像，像爸爸一样高；<b>象</b>管大象和气象、现象。好像不能写成好象，认准单人旁就是相似的像。"},{"name":"必须/必需","讲解":"“必须”是副词，表一定要（后跟动词）；“必需”是动词，表一定需要（后跟名词）。","深讲":"必须和必需意思不同：必须是副词，表一定要，后跟动词；必需是动词，表一定需要，后跟名词。口诀：必须跟动作，必需跟东西。","分类":[{"类":"必须动作式","说明":"必须后跟动词，表一定要。","代表":"必须按时到校","例子":["我们必须按时到校。"]},{"类":"必需东西式","说明":"必需后跟名词，表一定需要。","代表":"必需品、日用品","例子":["水是生命必需的。"]}],"怎么认":["后面是不是动词？动词前用必须。","后面是不是名词、东西？东西前用必需。","必需品、日用品用必需，重点记。"],"辨析":"必须和必需的区别：必须跟动作（必须按时到校），必需跟东西（必需品）。必须品是错的，应为必需品。","例句解析":[{"句":"我们必须按时到校。","析":"必须后跟动词到校，是必须动作式。"},{"句":"水是生命必需的。","析":"必需后跟名词，是必需东西式。"}],"练习":[{"q":"“我们_按时到校”填？","options":["必须","必需"],"answer":0,"解析":"后跟动词，用必须。","类":"必须动作式"},{"q":"“_品、日用品”填？","options":["必须","必需"],"answer":1,"解析":"必需品用必需。","类":"必需东西式"},{"q":"“水是生命_的”填？","options":["必须","必需"],"answer":1,"解析":"后跟名词，用必需。","类":"必需东西式"}],"例子":["我们必须按时到校（后跟动词）","水是生命必需的（后跟名词）","✗ 必须品 → ✓ 必需品","我们必须遵守纪律。（必须：一定要）","水是生命必需的。（必需：需要）","你必须按时到校。（必须）","这是生活必需品。（必需）","做人必须诚实。（必须）","阳光是植物生长必需的。（必需）","他必须完成任务。（必须）","粮食是必需品。（必需）","我们必须努力学习。（必须）"],"口诀":"必须跟动作，必需跟东西","易错":"“必需品、日用品”用“必需”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["必须","含义：一定要（后跟动作）；用法：必须+动词；例句：我们必须按时到校；误用：❌“必须品”→ ✅“必需品”"],["必需","含义：需要（后跟东西）；用法：必需+名词；例句：水是生命必需的；误用：❌“必需按时到校”"]]},"前置知识":["副词","动词"],"类比":"像两兄弟一个跟动作一个跟东西：<b>必须</b>跟在动词前，必须按时到校；<b>必需</b>跟在名词、东西前，水是生命必需的、必需品。看后面跟的是动作还是东西，就不会叫错人。"},{"name":"哪/那","讲解":"“哪”表疑问（哪里、哪个），“那”表指示（那里、那个）。","深讲":"哪表疑问（哪里、哪个），那表指示（那里、那个）。口诀：哪是问，那是指；问句用哪，回答用那。","分类":[{"类":"哪疑问式","说明":"哪表疑问。","代表":"哪里、哪个","例子":["你去哪里？"]},{"类":"那指示式","说明":"那表指示。","代表":"那里、那个","例子":["我在那里等你。"]}],"怎么认":["是不是在问？问用哪。","是不是在指？指用那。","问句用哪，回答用那，对号入座。"],"辨析":"哪和那的区别：哪是问（你去哪里？），那是指（我在那里等你）。问地点要用“哪里”：你住在哪里？写成“你住在那里？”就成了指示。","例句解析":[{"句":"你去哪里？","析":"问地点，用哪。"},{"句":"我在那里等你。","析":"指地点，用那。"}],"练习":[{"q":"“你去_里？”填？","options":["哪","那"],"answer":0,"解析":"问地点，用哪。","类":"哪疑问式"},{"q":"“我在_里等你”填？","options":["哪","那"],"answer":1,"解析":"指地点，用那。","类":"那指示式"},{"q":"“_里有几个人？”（问句）填？","options":["哪","那"],"answer":0,"解析":"问句用哪。","类":"哪疑问式"}],"例子":["你去哪里？（疑问）","我在那里等你（指示）","✗ 你住在那里？（问地点）→ ✓ 你住在哪里？","你去哪儿？（哪：疑问）","那是我的书包。（那：指示）","哪个是你的？（哪）","那座山很高。（那）","你喜欢哪一个？（哪）","那边有很多人。（那）","哪里有困难，哪里就有我们。（哪）","那天我们很开心。（那）","你要去哪里？（哪）"],"口诀":"哪是问，那是指","易错":"问句用“哪”，回答用“那”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["哪","含义：表疑问；用法：哪+疑问；例句：你去哪里？；误用：❌“你住在那里？”（问地点）→ ✅“你住在哪里？”"],["那","含义：表指示；用法：那+指示；例句：我在那里等你；误用：❌“哪里风景好”（指代时）→ ✅“那里风景好”"]]},"前置知识":["代词"],"类比":"像两兄弟一个问路一个指路：<b>哪</b>是问的，哪里、哪个；<b>那</b>是指的，那里、那个。问句请问路的哪，回答请指路的那，对号入座就不会走错。"},{"name":"不/没","讲解":"“不”表主观不愿、经常性否定；“没”表客观没有、过去没发生。","深讲":"不表主观不愿、经常性否定，没表客观没有、过去没发生。口诀：不表意愿，没表有无；没常和过搭配表过去。","分类":[{"类":"不意愿式","说明":"不表主观不愿意，或经常性的否定。","代表":"不去、不喜欢","例子":["我不去。"]},{"类":"没客观式","说明":"没表客观没有、没去成。","代表":"没去","例子":["我没去。"]},{"类":"没过去式","说明":"没＋过表过去没发生。","代表":"没来过","例子":["他没来过北京。"]}],"怎么认":["是不是不想去？不想用不。","是不是没去成？没去成用没。","是不是在说过去？过去用没＋过。"],"辨析":"不和没的区别：不去是不想去（主观），没去是没去成（客观）；不喜欢是经常， 没来过是过去。看是意愿还是有无、过去。","例句解析":[{"句":"我不去。","析":"不想去，是不意愿式。"},{"句":"我没去。","析":"没去成，是没客观式。"}],"练习":[{"q":"“我_去”（不想去）填？","options":["不","没"],"answer":0,"解析":"不想去用不。","类":"不意愿式"},{"q":"“我_去”（没去成）填？","options":["不","没"],"answer":1,"解析":"没去成用没。","类":"没客观式"},{"q":"“他_来过北京”（过去）填？","options":["不","没"],"answer":1,"解析":"过去用没＋过。","类":"没过去式"}],"例子":["我不去（不想去）","我没去（没去成）","他没来过北京（过去）","我不喜欢吃辣（经常）","我不喜欢吃辣。（不：意愿/性质否定）","我没吃过。（没：未曾）","他不去。（不）","我没带伞。（没）","今天不冷。（不）","他没来上课。（没）","我不怕困难。（不）","作业还没写完。（没）"],"口诀":"不表意愿，没表有无","易错":"“没”常和“过”搭配表过去：我没看过","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["不","含义：主观否定（意愿/性质）；用法：不+意愿/经常；例句：我不去（不想去）；我不喜欢吃辣（经常）；误用：表“过去未曾”不用“不”"],["没","含义：客观否定（有无/过去）；用法：没+有无/过去；例句：我没去（没去成）；他没来过北京（过去）；误用：表意愿不用“没”：❌“我没去（想表达不想去）”"]]},"前置知识":["副词"],"类比":"像两兄弟一个管意愿一个管有无：不想去用<b>不</b>，是主观不愿；没去成用<b>没</b>，是客观没有；说过去还要没加过，没来过北京。意愿找不，有无和过去找没。"},{"name":"还是/或者","讲解":"“还是”用于选择问句，“或者”用于陈述句表选择。","深讲":"还是用于选择问句，或者用于陈述句表选择。口诀：问句还是，陈述或者；问句里用还是，陈述句里用或者，别用反。","分类":[{"类":"还是问句式","说明":"还是用于选择问句。","代表":"还是喝牛奶？","例子":["你喝水还是喝牛奶？"]},{"类":"或者陈述式","说明":"或者用于陈述句。","代表":"或者去公园，或者去图书馆","例子":["周末或者去公园，或者去图书馆。"]}],"怎么认":["是不是在问？问用还是。","是不是在陈述选择？陈述用或者。","你去或者不去是错的，应为你去还是不去。"],"辨析":"还是和或者的区别：还是问（你喝水还是喝牛奶？），或者陈述（周末或者去公园，或者去图书馆）。看是不是问句。","例句解析":[{"句":"你喝水还是喝牛奶？","析":"选择问句，用还是。"},{"句":"周末或者去公园，或者去图书馆。","析":"陈述句表选择，用或者。"}],"练习":[{"q":"“你喝水_喝牛奶？”填？","options":["还是","或者"],"answer":0,"解析":"问句用还是。","类":"还是问句式"},{"q":"“周末_去公园，_去图书馆”（陈述）填？","options":["还是，还是","或者，或者","还是，或者"],"answer":1,"解析":"陈述句用或者。","类":"或者陈述式"},{"q":"“你去_不去？”填？","options":["还是","或者"],"answer":0,"解析":"问句用还是。","类":"还是问句式"}],"例子":["你喝水还是喝牛奶？（问句）","周末或者去公园，或者去图书馆（陈述）","✗ 你去或者不去？→ ✓ 你去还是不去？","你喝茶还是喝咖啡？（还是：选择问）","他或者去北京，或者去上海。（或者：陈述选择）","你喜欢红色还是蓝色？（还是）","周末或者去爬山，或者去看电影。（或者）","是你去，还是我去？（还是）","他或者跑步，或者游泳。（或者）","你要苹果还是香蕉？（还是）","我们或者今天走，或者明天走。（或者）","你是学生还是老师？（还是）"],"口诀":"问句还是，陈述或者","易错":"问句里用“还是”，陈述句里用“或者”","对照表":{"维度":["含义","用法","例句","误用"],"对比":[["还是","含义：表选择问；用法：用在问句；例句：你喝水还是喝牛奶？；误用：❌“你去或者不去？”→ ✅“你去还是不去？”"],["或者","含义：表陈述中的选择；用法：用在陈述句；例句：周末或者去公园，或者去图书馆；误用：问句中不用“或者”"]]},"前置知识":["连词","选择复句"],"类比":"像两兄弟一个管问一个管说：问句里选，喝水还是喝牛奶，请<b>还是</b>；陈述句里选，周末或者去公园或者去图书馆，请<b>或者</b>。问句里用或者就像请错了人。"},{"name":"又/再辨析","讲解":"“又”和“再”都表示“再一次”，但时间分工不同：又管过去（已经又发生了），再管将来（还没发生等下次）。","深讲":"又 + 过去：动作已经重复发生，常带“了”（他又迟到了）。再 + 将来：动作还没发生，等下一次（明天再来吧）。再还有两个本事：表“再一个”（再来一碗）、表“然后”（先看再说）。又还能表“并列更”（又大又圆）。记住：过去用又，将来用再，换错了中国人听着别扭。","类比":"“又”是回放键：播的是已经发生过的事；“再”是预约键：约的是还没发生的事。","口诀":"又是过去再将来，时间错了就露馅","例子":["他又迟到了。","明天再来吧！","今天他又来了，明天再来。","再见！（=再相见）","再来一碗。","又大又圆。","明天又是星期一。","先看再说。"],"易错":"✗“明天又来”（→明天再来）；✗“昨天再迟到”（→昨天又迟到）。看时间选词。","分类":[{"类":"过去又","说明":"动作在过去重复发生，常带“了”。","代表":"他又迟到了","例子":["他又迟到了。","今天他又来了。"]},{"类":"将来再","说明":"动作还没发生，等下一次。","代表":"明天再来","例子":["明天再来吧！","我们下次再来。"]},{"类":"再的其他义","说明":"表“再一个”或“然后”。","代表":"再来一碗、先看再说","例子":["再来一碗。","先看再说。"]}],"怎么认":["看时间：过去的事→又，将来的事→再。","看搭配：带“了”→又；带“吧/要/下次”→再。","看意思：是不是“再一次”？是→在又/再里二选一。"],"辨析":"又/再和“还”的区别：“还”表“仍旧、继续”（他还在睡觉＝没停）；又/再表“重复一次”（他又睡了＝醒了再睡）。一个讲状态延续，一个讲动作重复。","例句解析":[{"句":"今天他又来了，明天再来。","析":"“今天…又”：今天的事已发生，用又；“明天…再”：明天的事还没发生，用再。一句里两个时间，两个词。"},{"句":"再见！","析":"“再”表将来再一次：这次见完，下次再见。是最常用的“再”字句。"}],"练习":[{"q":"“明天____来吧”填哪个？","options":["又","再","还","也"],"answer":1,"解析":"明天的事还没发生，用“再”。","类":"时间"},{"q":"“他昨天____迟到了”填哪个？","options":["再","又","还","就"],"answer":1,"解析":"昨天的事已发生，用“又”。","类":"时间"},{"q":"“____大____圆”填哪个词？","options":["再","又","还","更"],"answer":1,"解析":"“又…又…”表并列：又大又圆。","类":"并列"},{"q":"哪句是错的？","options":["他又迟到了","明天再来","昨天再下雨","再来一碗"],"answer":2,"解析":"“昨天”已过去，该用“又”：昨天又下雨。","类":"易错"}],"前置知识":["副词"]}]},{"id":"juxing","name":"句型句式（7种）","items":[{"name":"双宾语句","讲解":"一个动词后面接连带两个宾语：先说人（近宾语，给谁），再说事物（远宾语，给什么）。","类比":"有的动词像传东西：谁给，给谁，给什么，三样都要有。奶奶给我一个苹果。“给”伸出三只手：抓住奶奶、我、一个苹果。","例子":["奶奶给我一个苹果。","老师教我们一首歌。","小明送妹妹一张卡片。","错：奶奶给一个苹果我。（应改为：奶奶给我一个苹果。）","我还你一本书。","他赢了我两盘棋。","我问老师一个问题。","错：爷爷讲我们一个故事。（应改为：爷爷给我们讲了一个故事。）","我送妹妹一张卡片。","我送给妹妹一张卡片。","我把这张卡片送给了妹妹。","我借了他一本书。","我借给他一本书。","我向他借了一本书。"],"深讲":"双宾语句的架子：谁 + 动词 + 人 + 东西。离动词近的是人，叫近宾语；远一点的是东西，叫远宾语。普通话里人在前、物在后，不能倒过来。不是每个动词都能带两个宾语。能带的主要有三类：给出去（给、送、还、递），拿进来（收、抢、赢），告诉人（告诉、问、教）。“讲”不行：不能说“爷爷讲我们一个故事”，要用“给”把人请到前面。双宾语句可以换说法：我送妹妹一张卡片，也能说成：我送给妹妹一张卡片。东西是确定的那一件时，还能用“把”：我把这张卡片送给了妹妹。想一想：“我借了他一本书”，书是从我这儿到他那儿，还是从他那儿到我这儿？两种都可以！双宾语句里，东西可以“给出去”，也可以“拿进来”。“借、租”两个方向都能用，所以这句话有两种意思。说清楚要加字：借给他，或者，向他借。语法书把“给、借”这类必须抓住三样东西的动词叫三价动词。（出处：朱德熙《语法讲义》，商务印书馆 1982，「双宾语」一章（给予/取得两类；章次待核））","怎么认":["“给”要抓住几样东西？","“爷爷讲我们一个故事”能说吗？","书往哪边走？"],"易错":"把远宾语（东西）放在近宾语（人）前面：✗奶奶给一个苹果我。；给“讲、写、买”等不带双宾语的动词硬加两个宾语：✗爷爷讲我们一个故事。；“借、租”双向，句子可能有两种意思，要用“借给/向…借”说清。","练习":[{"q":"把“爷爷讲我们一个故事”改成正确的句子","options":["爷爷给我们讲了一个故事。","爷爷讲一个故事我们。"],"answer":0,"解析":"“讲”只能带一个宾语，听的人用“给”放到动词前面。","类":"回练"}],"例句解析":[{"句":"奶奶给一个苹果我。","析":"普通话双宾语句先说人，后说东西。（应改为：奶奶给我一个苹果。）"},{"句":"爷爷讲我们一个故事。","析":"“讲”只能带一个宾语，听的人要用“给”引出来。（应改为：爷爷给我们讲了一个故事。）"}],"前置知识":["宾语","把字句"]},{"name":"连动句","讲解":"同一个主语后面接连用两个或更多动词（短语），按先后、目的或方式排好，中间不停顿、不用关联词。","类比":"弟弟跑过去开门。谁跑过去？弟弟。谁开门？还是弟弟。一个人，接连做了两件事。","例子":["弟弟跑过去开门。","他吃完饭去散步。（先后）","我去图书馆借书。（目的）","她坐地铁上学。（方式）","我去食堂吃饭。（连动句）","我请他吃饭。（兼语句，不是连动句）","他又唱又跳。→ 他又跳又唱。（并列，能换）","他坐公交车到学校。（连动）","他到学校坐公交车。（也是连动句，但意思变了）","他坐公交车到学校。","他到学校坐公交车。"],"深讲":"连动句里，两个动作的关系有三种常见的。先后：他吃完饭去散步。目的：我去图书馆借书——去，是为了借书。方式：她坐地铁上学——坐地铁，是怎么去上学。“我去食堂吃饭”和“我请他吃饭”，看着很像。问：后一个动作是谁做的？我去食堂吃饭——吃饭的是“我”，连动句。我请他吃饭——吃饭的是“他”，兼语句。连动句的两个动作不能随便调换，换了意思就变，或者不成话。并列的两个动作能换：他又唱又跳，也能说又跳又唱。他坐公交车到学校，换成他到学校坐公交车，意思完全变了。想一想：为什么连动句不能随便换？汉语常常按事情发生的先后来排词：先发生的说在前，后发生的说在后。他坐公交车到学校：先坐车，后到校。他到学校坐公交车：先到校，后坐车。语言学家把这叫“时间顺序原则”。语法书里，连动句也叫“连谓句”。（出处：Tai, James H-Y.（戴浩一）1985. Temporal Sequence and Chinese Word Order. In J. Haiman (ed.), Iconicity in Syntax, John Benjamins；朱德熙《语法讲义》，商务印书馆 1982，「连谓结构」）","怎么认":["开门的是谁？","吃饭的是谁？","哪件事先发生？"],"易错":"把兼语句当连动句：要问后一个动作是谁做的。；把并列（又唱又跳）当连动：并列能调换，连动不能随便换。；两个动作中间加了逗号或关联词，就成了复句，不再是连动句。","练习":[{"q":"判断“我去书店买书”是连动句还是兼语句","options":["兼语句。","连动句：“去书店”和“买书”都是“我”做的。"],"answer":1,"解析":"后一个动作还是主语自己做的，是连动句；换成别人做的，才是兼语句。","类":"回练"}],"例句解析":[{"句":"他吃完饭去散步。","析":"先后"},{"句":"我去图书馆借书。","析":"目的"},{"句":"她坐地铁上学。","析":"方式"},{"句":"我去食堂吃饭。","析":"连动句"},{"句":"我请他吃饭。","析":"不是连动句。兼语句，不是连动句"},{"句":"他又唱又跳。→ 他又跳又唱。","析":"不是连动句。并列，能换"},{"句":"他坐公交车到学校。","析":"连动"},{"句":"他到学校坐公交车。","析":"也是连动句，但意思变了"}],"前置知识":["兼语句","谓语"]},{"name":"主谓谓语句","讲解":"谓语本身是一个主谓短语：大主语 ‖ 小主语 + 小谓语，如“他 ‖ 身体很好”。","类比":"他身体很好。先装“身体很好”：身体，怎么样？很好。再把整个“身体很好”拿来说“他”。一个“谁怎么样”，装进了另一个“谁怎么样”里。","例子":["他身体很好。","大象鼻子长。（整体—部分）","这道题我会做。（大主语是受事）","他的身体很好。","这本书我看完了。","我这本书看完了。"],"深讲":"第一种：大主语和小主语是“整体和部分”：大象鼻子长。鼻子是大象的。第二种：大主语是被处置的东西：这道题我会做。说的是这道题，做题的是我。他身体很好，和，他的身体很好，意思差不多，结构却不同。他的身体很好：主语是“他的身体”，谓语是“很好”，普通主谓句。他身体很好：主语是“他”，谓语是“身体很好”，主谓谓语句。想一想：“这本书我看完了”和“我这本书看完了”，都能说吗？都能说。区别在于从哪儿说起：前一句先说这本书，后一句先说我。很多语法学家认为，汉语句首的大主语就是“话题”：先摆出说的是什么，后面再评论它。（出处：赵元任《汉语口语语法》（吕叔湘译），商务印书馆 1979（主语即话题的观点）；黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（主谓谓语句））","怎么认":["先装哪两块？","两句都能说吗？"],"易错":"只看到小主语，把大主语漏掉。；以为加上“的”意思一样，结构也一样：加“的”后成了普通主谓句。；大主语后面常可以停顿，书面可加逗号，但不是必须。","练习":[{"q":"找出“弟弟胆子很小”的主语","options":["大主语是“弟弟”；“胆子很小”整个作谓语，“胆子”只是谓语里的小主语。","胆子"],"answer":0,"解析":"主谓谓语句先找大主语，再看谓语里面的小“谁怎么样”。","类":"回练"}],"例句解析":[{"句":"大象鼻子长。","析":"整体—部分"},{"句":"这道题我会做。","析":"大主语是受事"},{"句":"他的身体很好。","析":"不是主谓谓语句。"}],"前置知识":["话题句","主谓式","主语"]},{"name":"四种句类","讲解":"按用途（语气）把句子分成陈述句、疑问句、祈使句、感叹句；要看用途和语调，不能只看句末标点。","类比":"下雨了。——告诉别人一件事。下雨了吗？——问别人。快收衣服！——叫别人做事。雨下得真大啊！——说出自己的感受。","例子":["下雨了。（陈述句）","下雨了吗？（疑问句）","快收衣服！（祈使句）","雨下得真大啊！（感叹句）","你去吗？（是非问）","谁去？（特指问）","你去还是他去？（选择问）","你去不去？（正反问）","请把门关上。","别在走廊里跑！","（你）坐下！","请把门关上。（句号结尾的祈使句）","难道你不认识我吗？（反问：无疑而问）","火！","火？"],"深讲":"疑问句又有四种问法。是非问：你去吗？特指问：谁去？选择问：你去还是他去？正反问：你去不去？祈使句是要别人做或者别做什么：请坐。别跑！祈使句的主语常常是“你、你们”，也常常不说出来。语气可以很客气，也可以很强硬：请坐下。——坐下！句类看用途，不只看标点。请把门关上。——用句号，也是祈使句，只是语气缓和。难道你不认识我吗？——用问号，可它不是真的在问：意思是“你应该认识我”。这是反问，仍归疑问句一类。想一想：“火！”这一个字，算哪一类句子？要看怎么说：大喊“火！”，是提醒大家——感叹或祈使；指着问“火？”，是疑问。按语气分出来的叫句类；按结构分出来的叫句型，比如主谓句、非主谓句。“火！”是非主谓句，句类却要靠语调来定。（参考：黄伯荣、廖序东主编《现代汉语》）","怎么认":["这句话是告诉对方一件事、在问对方、要对方做事，还是在表达感受？先看用途。","去掉句末标点，语气还在吗？不在，说明语气主要靠标点和语调；在，则语气来自词语本身。","“火”是哪一类句子？大喊“火！”是感叹或祈使，指着问“火？”是疑问，要看语境。"],"易错":"只按句末标点判断句类：句号也能结束祈使句，叹号也能结束反问句。反问句形式是问，意思是确定的。“是非问”用“吗”，“正反问”不再加“吗”：✗你去不去吗？","练习":[{"q":"给“你明天来不来”加标点并说出句类","options":["你明天来不来？——正反问，疑问句。","你明天来不来！——祈使句"],"answer":0,"解析":"“来不来”是正反问的格式，问的是对方的选择，用问号。","类":"回练"}],"例句解析":[{"句":"下雨了。","析":"陈述句"},{"句":"下雨了吗？","析":"疑问句"},{"句":"快收衣服！","析":"祈使句"},{"句":"雨下得真大啊！","析":"感叹句"},{"句":"你去吗？","析":"是非问"},{"句":"谁去？","析":"特指问"},{"句":"你去还是他去？","析":"选择问"},{"句":"你去不去？","析":"正反问"},{"句":"请把门关上。","析":"句号结尾的祈使句"},{"句":"难道你不认识我吗？","析":"反问：无疑而问"}],"前置知识":["吗/呢/吧","语气词","反问"]},{"name":"引语转述","讲解":"直接引语照录原话、加引号；转述（间接引语）去掉引号，人称、指示和时间词要按转述人的立场改过来。","类比":"妈妈说：“我明天去学校。”——这是妈妈的原话，用引号框住。妈妈说她明天去学校。——这是我把妈妈的话转告别人，引号没了，“我”变成了“她”。","例子":["妈妈说：“我明天去学校。”","妈妈说她明天去学校。","小红对我说：“我借你的书看完了。”","小红对我说，她借我的书看完了。","老师问我们作业写完了没有。","妈妈让我快去睡觉。","错：弟弟对我说，我把你的球弄丢了。（应改为：弟弟对我说，他把我的球弄丢了。）","小明说：“我在这儿等你。”","小明说他在那儿等我。"],"深讲":"第一步：冒号、引号去掉，常改成逗号或不用标点。第二步：看谁对谁说，换人称：说话人自己的“我”变“他/她”，对听话人说的“你”，如果听话人就是转述的人，变成“我”。第三步：语气词、称呼去掉，句子要通顺。问话转述：老师问：“你们作业写完了吗？”——老师问我们作业写完了没有。请求转述：妈妈对我说：“你快去睡觉。”——妈妈让我快去睡觉。问号、叹号都换成句号。最常见的错：人称没换。弟弟对我说，我把你的球弄丢了。——到底是谁弄丢了谁的球？改成：弟弟对我说，他把我的球弄丢了。想一想：小明昨天在公园对我说：“我在这儿等你。”今天我在家里转述，“这儿”还能说吗？不能。“这儿”是小明当时站的地方，我现在不在那儿，要改成“那儿”。我、你、这儿、那儿、今天、明天……这些词的意思要看是谁、在哪儿、什么时候说的。语言学把它们叫“指示语”。（出处：Stephen C. Levinson, Pragmatics, Cambridge University Press 1983, Chapter 2 “Deixis”（指示语））","怎么认":["“我”为什么变成了“她”？","“这儿”还能说吗？"],"易错":"只改了“我”，忘了改“你”。；转述时留着引号或冒号。；指示词、时间词跟着当时的情境走：这儿/那儿、今天/昨天要看转述的时间地点。","练习":[{"q":"把“爸爸对我说：‘你的自行车我修好了。’”改成转述句","options":["爸爸对我说，你的自行车他修好了。","爸爸对我说，我的自行车他修好了。"],"answer":1,"解析":"爸爸对“我”说的“你”，转述时要变成“我”。","类":"回练"}],"例句解析":[{"句":"弟弟对我说，我把你的球弄丢了。","析":"转述时，弟弟的“我”要变成“他”，对我说的“你”要变成“我”。（应改为：弟弟对我说，他把我的球弄丢了。）"}],"前置知识":["代词"]},{"name":"多重复句","讲解":"复句里有两层或更多层关系；先找第一层（把全句分成两大块的那道缝），再往里一层层分。","类比":"虽然天很冷，但是大家都来了，而且来得很早。先问：这句话最大的一道缝在哪儿？在“天很冷”后面：前面说天冷，后面一转，说大家来了。后面那一块里还有一道小缝：都来了，而且来得早。","例子":["①虽然天很冷，｜②但是大家都来了，‖③而且来得很早。","①如果明天不下雨，｜②我们就去爬山，‖③而且要爬到山顶。","错：①如果明天不下雨，②我们就去爬山，｜③而且要爬到山顶。（应改为：①如果明天不下雨，｜②我们就去爬山，‖③而且要爬到山顶。）","虽然下雨了，｜但是比赛照常进行，‖因为场馆有屋顶。","因为下雨了，‖比赛推迟了，｜但是观众都没走。"],"深讲":"第一步：数一数有几个分句。第二步：圈出关联词。第三步：找第一层——哪个关联词“管”得最远，第一层就在哪儿。第四步：在每一块里再分。习惯上第一层画一条竖线“｜”，第二层画两条“‖”。有同学把这句分成：①②一块，③一块。可是“如果”假设的是“明天不下雨”，在这个条件下，去爬山和爬到山顶两件事都要发生。“如果…就”管到了句末。所以第一层在①后面。想一想：下面两句都是三个分句，为什么分法不一样？虽然下雨了，｜但是比赛照常进行，‖因为场馆有屋顶。——“虽然…但是”先把全句一分为二。因为下雨了，‖比赛推迟了，｜但是观众都没走。——前两句是一块因果，再和后面转折。关联词“管”多远，决定了一层层怎么装。（出处：黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（多重复句）；邢福义《汉语复句研究》，商务印书馆 2001）","怎么认":["最大的缝在哪儿？","两句的第一层各在哪儿？"],"易错":"只按关联词出现的先后切，不看它管多远。；层次符号要统一：本稿第一层“｜”、第二层“‖”（与成分层的主谓分界‖不同屏使用）。；分号常用来标出多重复句的第一层。","练习":[{"q":"划分“因为他生病了，所以没来上学，但是作业按时交了”的层次","options":["因为他生病了，‖所以没来上学，｜但是作业按时交了。","因为他生病了，｜所以没来上学，‖但是作业按时交了。"],"answer":0,"解析":"前两句是一组因果，合起来再和“但是”一句转折：第一层在“没来上学”后面。","类":"回练"}],"例句解析":[{"句":"①如果明天不下雨，②我们就去爬山，｜③而且要爬到山顶。","析":"“如果…就”的假设管到句末，第一层在①后面。（应改为：①如果明天不下雨，｜②我们就去爬山，‖③而且要爬到山顶。）"}],"前置知识":["转折复句","递进复句","假设复句","因果复句"]},{"name":"紧缩复句","讲解":"把复句压紧成一句话的样子，中间不停顿，常用“一…就”“越…越”“不…不”“再…也”“非…不”等格式，意思仍有两层。","类比":"如果你去，我就去。把逗号和“如果”拿掉，压一压：你去我就去。看起来像一句话，其实还是两件事、一层关系。","例子":["如果你去，我就去。","你去我就去。","他一下课就跑出去。","雨越下越大。","我们不见不散。","再忙也要吃早饭。","这本书我非看不可。","不见不散。→ 如果不见面，就不散去。","再忙也要吃早饭。→ 即使再忙，也要吃早饭。","他一进门就喊妈妈。","他进门喊妈妈。","他一到家就睡了。","我一紧张就结巴。"],"深讲":"一…就：一下课就跑出去。越…越：越跑越快。不…不：不见不散。再…也：再忙也要吃早饭。非…不：这本书我非看不可。读懂紧缩句，就把它“松开”。不见不散：如果不见面，就不散去。再忙也要吃早饭：即使再忙，也要吃早饭。他一进门就喊妈妈。——“一…就”连着两件事，前一件刚发生，后一件马上跟着，是紧缩复句。他进门喊妈妈。——没有关联格式，是连动句，单句。想一想：“他一到家就睡了”和“我一紧张就结巴”，两个“一…就”一样吗？第一句说的是已经发生的一次：到家，紧接着睡了。第二句说的是常常这样：只要紧张，就会结巴，更像条件。紧缩句不写关联词的全部，关系要靠意思还原。语法书把它叫“紧缩复句”。（出处：黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（紧缩复句）；吕叔湘主编《现代汉语八百词》（增订本），商务印书馆 1999，「一」条）","怎么认":["压紧以后，意思变了吗？","两个“一…就”一样吗？"],"易错":"中间加了逗号，就还是普通复句。；“非…不”是双重否定，意思是“一定要”。；同一格式可能表示不同关系，要还原成复句再判断。","练习":[{"q":"把“如果你不来，我就不走”压成紧缩句","options":["你不来，我就不走。","你不来我就不走。"],"answer":1,"解析":"紧缩句中间不停顿，逗号要去掉。","类":"回练"}],"例句解析":[{"句":"他进门喊妈妈。","析":"不是紧缩复句。"}],"前置知识":["一…就…","条件复句","假设复句"]}]},{"id":"buyu_xifen","name":"补语细分（5种）","items":[{"name":"结果补语","讲解":"动词后面紧跟一个动词或形容词，说明动作带来的结果：洗干净、看懂、打碎；中间不加“得”，已然的否定用“没”。","类比":"杯子好好的。弟弟一碰——杯子打碎了。“打”是动作，“碎”是结果。动作后面紧跟着结果，就是结果补语。","例子":["弟弟把杯子打碎了。","我听见有人敲门。","这道题我看懂了。","他把名字写错了。","衣服洗干净了。","错：我昨天不写完作业。（应改为：我昨天没写完作业。）","不写完不许看电视。（条件句可以用“不”）","错：我看书完了。（应改为：我看完书了。）","我写累了。","我写错了。"],"深讲":"常做结果补语的有：完、好、懂、见、到、住、走、掉、错，还有干净、清楚。看——看见；听——听懂；写——写错。加上结果，动作就有了着落。说已经发生的事没有结果，用“没”，不用“不”。我昨天不写完作业——不对。我昨天没写完作业——对。注意：说条件时可以用“不”：不写完不许看电视。结果补语和动词贴得很紧，宾语要放在结果后面。看书完——不对。看完书——对。想一想：“我写累了”和“我写错了”，“累”和“错”说的是同一个东西吗？写累了：累的是“我”。写错了：错的是写的字，是动作做得不对。再看：衣服洗干净了——干净的是衣服。结果补语在意思上可以挂在主语、宾语或动作本身上，语法学叫“语义指向”。（出处：陆俭明《现代汉语语法研究教程》（第五版），北京大学出版社 2019，「语义指向分析」章）","怎么认":["“打”了以后，杯子怎么样了？","“累”和“错”说的是谁？"],"易错":"结果补语前加“得”就变成可能补语：洗干净 / 洗得干净。；已然否定用“没”：✗我不吃饱 → 我没吃饱。；宾语放在结果补语后面：看完书。","练习":[{"q":"想说“衣服已经洗干净了”，改正“衣服我洗得干净了”","options":["衣服我洗干净得了。","衣服我洗干净了。"],"answer":1,"解析":"说已经得到的结果，用结果补语，动词和结果紧贴，中间不加“得”；加了“得”就成了“能不能洗干净”。","类":"回练"}],"例句解析":[{"句":"我昨天不写完作业。","析":"已经发生的事，否定结果用“没”。（应改为：我昨天没写完作业。）"},{"句":"不写完不许看电视。","析":"条件句可以用“不”"},{"句":"我看书完了。","析":"动词和结果补语中间不能插宾语。（应改为：我看完书了。）"}],"前置知识":["补语","把字句"]},{"name":"可能补语","讲解":"在动词和结果补语或趋向补语中间插“得/不”，表示能不能实现：看得见/看不见、搬得动/搬不动；还有“V得了/V不了”。","类比":"黑板上的字很小。坐在前面的同学说：我看得清。坐在后面的同学说：我看不清。在“看”和“清”中间放一个“得”，就是能；放一个“不”，就是不能。","例子":["我看得清。","我看不清。","作业太多，今天做不完。","山太陡，我们上不去。","这么多菜，我吃不了。","这个字太难，我写不好。（可能补语的否定）","他这个字写得不好。（状态补语的否定）","错：我把这个箱子搬不动。（应改为：这个箱子我搬不动。）","这门课我学不会。","你学得会吗？——学得会。","我能学会。"],"深讲":"结果补语：做完。插“得”：做得完。插“不”：做不完。趋向补语：上去。插“得”：上得去。插“不”：上不去。还有一种：V得了、V不了，“了”读 liǎo：这么多菜，我吃不了。“他写得好”可以有两种意思：一是能写好，二是写得很好。分辨：能加“很”的，是在描写样子：写得很好。否定说“写得不好”。表示能不能的，否定说“写不好”。把字句说的是已经做了、产生了结果的事，可能补语说的是能不能，两个合不到一起。我把这个箱子搬不动——不对。这个箱子我搬不动——对。想一想：“这门课我学不会”和“这门课我学得会”，哪一句平时更常听到？否定的“学不会”常常单独用；肯定的“学得会”多半出现在回答问题或者反问里：你学得会吗？——学得会。语法书指出：可能补语的否定式比肯定式常用得多。肯定的意思，平时多用“能”来说：我能学会。（出处：刘月华、潘文娱、故韡《实用现代汉语语法》（增订本），商务印书馆 2001，「可能补语」）","怎么认":["中间放什么，意思是“能”？","哪一句更常听到？"],"易错":"否定式是“V不C”，不是“V得不C”：✗写得不完。；可能补语不进把字句。；“V得好”可能是可能补语，也可能是状态补语，看能不能加“很”、怎样否定。","练习":[{"q":"改正“这么多作业，我写得不完”","options":["这么多作业，我写不完。","这么多作业，我写得没完。"],"answer":0,"解析":"可能补语的否定：“不”直接插在动词和补语中间，不带“得”。","类":"回练"}],"例句解析":[{"句":"这个字太难，我写不好。","析":"可能补语的否定"},{"句":"他这个字写得不好。","析":"状态补语的否定"},{"句":"我把这个箱子搬不动。","析":"可能补语不能进把字句。（应改为：这个箱子我搬不动。）"}],"前置知识":["补语","趋向补语引申义","把字句"]},{"name":"程度补语","讲解":"形容词或心理动词后面加“极了、得很、得多、死了、坏了、透了、得不得了、得要命”等，只说程度高，不描写具体的样子。","类比":"我很高兴。——高兴。我高兴极了！——高兴到了顶。我高兴得不得了！——也是高兴到了顶。“极了”“得不得了”跟在后面，说的是程度。","例子":["我高兴极了。","我高兴得不得了。","今天热得要命。","这件衣服贵得多。","他累坏了。","这个主意好极了。","今天热得很。≈ 今天很热。","他跑得很快。（状态补语）","错：他高兴得极了。（应改为：他高兴极了。）","他高兴得很。","小狗累坏了。","杯子摔坏了。"],"深讲":"程度补语分两种。不带“得”的：好极了、累坏了、气死了、坏透了。带“得”的：好得很、热得要命、冷得不得了、贵得多。他跑得很快。——“很快”描写跑的样子，可以问：跑得怎么样？这叫状态补语。今天热得很。——“很”只说热的程度，换成“很热”意思差不多。这是程度补语。程度补语前面多是形容词或心理动词，如热、高兴、喜欢。“极了”直接贴在形容词后面，中间不加“得”。他高兴得极了——不对。他高兴极了——对。“得很”才要带“得”。想一想：“小狗累坏了”和“杯子摔坏了”，两个“坏了”意思一样吗？杯子摔坏了：杯子真的坏了，“坏”是结果，叫结果补语。小狗累坏了：小狗没有坏，只是累到了极点，“坏了”说的是程度，叫程度补语。同一个词，在不同的动词后面，可以做不同的补语。（出处：刘月华、潘文娱、故韡《实用现代汉语语法》（增订本），商务印书馆 2001，「程度补语」「结果补语」）","怎么认":["“极了”“得很”“死了”前面是形容词或心理动词吗？是的，多半是程度补语。","能不能换成“很”或“非常”？能，说明它表示的是程度。","后面有没有说明具体样子？有，像“跑得很快”，就是状态补语，不是程度补语。"],"易错":"“极了”前不加“得”：✗高兴得极了。程度说一次就够：✗很多得很。“跑得很快”这类在不同教材中叫法不一，本页归为状态补语。","练习":[{"q":"改正“今天的作业多得很多”","options":["今天的作业多得很。（或：今天的作业多极了。）","今天的作业很多得很。"],"answer":0,"解析":"程度说一次就够：“得很”已经表示程度高，前后不能再加“很”。","类":"回练"}],"例句解析":[{"句":"他跑得很快。","析":"不是程度补语。状态补语"},{"句":"他高兴得极了。","析":"“极了”前不加“得”。（应改为：他高兴极了。）"}],"前置知识":["补语","形容词","副词"]},{"name":"时量补语","讲解":"动词后面用表示一段时间的词语（一会儿、三天、两个小时）补充说明动作持续了多久，或者动作完成后过了多久。","类比":"他游了半个小时。从下水到上岸，时间轴上画出一段——这一段有多长？半个小时。说时间长短的词跟在动词后面，就是时量补语。","例子":["他游了半个小时。","他学汉语学了三年。","他学了三年汉语。","我等了他半天。","灯开了三个小时。（持续）","他来了三天了。（完成后过了多久）","错：我等了半天他。（应改为：我等了他半天。）","他学了三年汉语了。"],"深讲":"动词带宾语时，有两种常见说法。重复动词：他学汉语学了三年。宾语放后面：他学了三年汉语。宾语是“他、我”这样的代词，放在时间前面：我等了他半天。灯开了三个小时。——灯一直亮着，亮了三个小时。他来了三天了。——“来”一下子就完成了，三天是来了以后到现在过去的时间。像来、到、毕业、离开这类一下子完成的动词，后面的时间说的是“过了多久”。我等了半天他——不顺。宾语是代词时，要放在动词后、时间前。改成：我等了他半天。想一想：“他学了三年汉语”和“他学了三年汉语了”，差在哪儿？第一句只说学了三年，现在可能已经不学了。第二句句末多了一个“了”，意思是到现在已经三年，而且还在学。动词后的“了”表示完成，句末的“了”表示到现在为止的新情况。（出处：吕叔湘主编《现代汉语八百词》（增订本），商务印书馆 1999，「了」条；刘月华、潘文娱、故韡《实用现代汉语语法》（增订本），商务印书馆 2001，「时量补语」）","怎么认":["游了多久？","他现在还在学吗？"],"易错":"名词宾语一般放在时量补语后：看了两个小时电视。；代词宾语放在时量补语前：等了他半天。；时间放在动词前是状语，意思不同：三天看完了（用了三天）。","练习":[{"q":"改正“我看了电视两个小时”","options":["我两个小时看了电视。","我看了两个小时电视。（或：我看电视看了两个小时。）"],"answer":1,"解析":"名词宾语放在时量补语后面，或者重复动词。时间放到动词前面，意思就变成别的了。","类":"回练"}],"例句解析":[{"句":"灯开了三个小时。","析":"持续"},{"句":"他来了三天了。","析":"完成后过了多久"},{"句":"我等了半天他。","析":"人称代词作宾语，放在时量补语前面。（应改为：我等了他半天。）"}],"前置知识":["补语","了/着/过"]},{"name":"动量补语","讲解":"动词后面用“数词＋动量词”（一次、三遍、两趟、一下）补充说明动作的次数。","类比":"咚、咚、咚——他敲了三下门。“三下”说的是敲了几次。动词后面说次数的，就是动量补语。","例子":["他敲了三下门。","我去过两次北京。","这首诗我读了三遍。","他去了一趟超市。","小狗咬了一口骨头。","这本书我看了一次。","这本书我看了一遍。","错：我找了两次他。（应改为：我找了他两次。）","我去过北京两次。","他嘴里含着一口苹果。","他咬了一口苹果。"],"深讲":"次、回：几次。遍：从头到尾一次。趟：走一个来回。下：很短的一下。顿：吃饭、批评。场：一场雨、一场球。还能借身体和工具来数：踢一脚、看一眼、咬一口。这本书我看了一次。——看过一回，不一定看完。这本书我看了一遍。——从第一页看到最后一页。宾语是“他、你”这类代词时，放在次数前面。我找了两次他——不顺。我找了他两次——对。地名可以前也可以后：我去过北京两次，我去过两次北京。想一想：“一口苹果”和“咬一口苹果”，两个“一口”量的是同一样东西吗？一口苹果：量的是苹果有多少，是名量。咬一口：量的是咬了几次，是动量。“口、脚、眼、拳”本来是名词，借来数动作，语法书叫借用动量词。（出处：黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（量词：动量词、借用量词）；刘月华、潘文娱、故韡《实用现代汉语语法》（增订本），商务印书馆 2001，「动量补语」）","怎么认":["敲了几下？","两个“一口”一样吗？"],"易错":"代词宾语放在动量补语前：找了他两次。；“次”和“遍”不同：遍强调从头到尾。；名量词和动量词别混：一口苹果（名量）/ 咬一口（动量）。","练习":[{"q":"改正“我叫了好几次他”","options":["我好几次叫了他。","我叫了他好几次。"],"answer":1,"解析":"次数作动量补语时跟在动词后面，代词宾语放在次数前；“好几次”放前面就成了状语，不是动量补语。","类":"回练"}],"例句解析":[{"句":"我找了两次他。","析":"代词宾语放在动量补语前。（应改为：我找了他两次。）"}],"前置知识":["补语","量词"]}]},{"id":"ciyu_duanyu","name":"词与短语（7种）","items":[{"name":"重叠","讲解":"词语按 AA、AABB、ABAB 等方式重叠会带来新意思：动词重叠表示时间短、试一试、轻松；形容词重叠多表示描写和程度；量词、部分名词重叠表示“每一”。","类比":"看——看看：看一下，试试。红——红红的：红得好看。个——个个：每一个。同一个字说两遍，意思就多了一点。","例子":["你看看这幅画。","她的脸红红的。","同学们个个都很开心。","我们讨论讨论吧。","错：我们讨讨论论吧。（应改为：我们讨论讨论吧。）","错：他正在看看书。（应改为：他正在看书。）","教室打扫得干干净净的。","错：教室很干干净净。（应改为：教室干干净净的。）","他天天跑步。","人人都要遵守规则。","她有一双大大的眼睛。","他的成绩大大地提高了。"],"深讲":"单音节动词：看看、看一看、看了看。双音节动词按 ABAB 叠：打扫打扫、休息休息，不说“打打扫扫”式的 AABB。动词重叠表示动作时间短、量少、试一试，所以不和“正在”“着”一起用。单音节形容词：AA 的，高高的、慢慢地。双音节：AABB，干干净净、高高兴兴。形容词重叠以后，自己就带着程度，前面不能再加“很”。很干干净净——不对。干干净净的，或者，很干净——对。量词重叠：个个、条条、张张，意思是“每一”。一些名词也能这样叠：人人、天天、家家户户。条条大路——每一条大路。想一想：“一双大大的眼睛”和“成绩大大地提高了”，两个“大大”程度一样吗？放在名词前面作定语时，“大大的”带着一点喜爱，程度并不强。放在动词前面作状语时，“大大地”是程度很深：提高得很多。放在名词前面作定语，“大大的”带着一点喜爱，程度并不强；放在动词前面作状语，“大大地”表示很多，如“成绩大大地提高了”。","怎么认":["是动词重叠、形容词重叠，还是量词重叠？先看词性，再对应规则。","能不能和“正在”“着”一起用？动词重叠不能，它表示短时或尝试。","前面能不能再加“很”？形容词重叠后不能，它自己已经带着程度。"],"易错":"双音节动词按 ABAB，不按 AABB：✗讨讨论论。；形容词重叠后不再加“很”。；动词重叠不和“正在”“着”同用。","练习":[{"q":"改正“她把房间收拾得很整整齐齐”","options":["她把房间收拾得很整齐齐。","她把房间收拾得整整齐齐的。（或：她把房间收拾得很整齐。）"],"answer":1,"解析":"形容词要么用“很+原形”，要么用重叠式，二者不同时用；重叠要完整按 AABB。","类":"回练"}],"例句解析":[{"句":"我们讨讨论论吧。","析":"双音节动词按 ABAB 重叠。（应改为：我们讨论讨论吧。）"},{"句":"他正在看看书。","析":"动词重叠表示短时、尝试，不和“正在”同用。（应改为：他正在看书。）"},{"句":"教室很干干净净。","析":"重叠式本身表程度，不再受“很”修饰。（应改为：教室干干净净的。）"}],"前置知识":["动词","形容词","量词"]},{"name":"能愿动词","讲解":"用在动词前，表示能力、可能、意愿、许可或必要（能、会、可以、要、想、愿意、应该、得 děi）；能单独回答问题，后面不带“了、着、过”，不能重叠。","类比":"我会游泳。——学会的本领。我想游泳。——心里愿意。我可以游泳吗？——问允许不允许。我应该先热身。——该这样做。这些词站在动词前面，说的是能不能、想不想、该不该。","例子":["我会游泳。","我想游泳。","我可以游泳吗？","我应该先热身。","我能游一千米。","我今天感冒了，不能游泳。","明天会下雨。","你会游泳吗？——会。","错：我能了游泳。（应改为：我能游泳了。）","错：明天要考试吗？——不要考。（应改为：明天要考试吗？——不用考。）","他应该到家了。","你应该早点到家。"],"深讲":"我会游泳。——学会了，有这个本领。我能游一千米。——本领达到了什么程度。我今天感冒了，不能游泳。——条件不允许。“会”还能表示可能：明天会下雨。能愿动词能单独回答：你会游泳吗？——会。能用“会不会、能不能”提问。后面不能带“了”：我能了游泳——不对；要说：我能游泳了。也不能重叠：不说“能能”。“要”有几种意思，否定说法也不一样。我要去。——想去，否定说：我不想去。明天要考试吗？——必须吗？否定说：不用考。说“不要考”，就成了劝人别考。想一想：“他应该到家了”和“你应该早点到家”，两个“应该”一样吗？第一句是猜：按时间算，他大概已经到家了。第二句是要求：你该早点回来。能愿动词常常有两种用法：一种表示说话人的推测，一种表示义务和要求。语法学把这叫“情态”。（参考：吕叔湘主编《现代汉语八百词》）","怎么认":["后面能不能直接接“了、着、过”？不能，这是能愿动词的特点。","能不能用“会不会、能不能”来提问？能，说明它是能愿动词。","这个词是说能力、意愿、许可，还是推测、要求？两个“应该”的意思不一样，要看语境。"],"易错":"能愿动词后不带“了、着、过”。；“要”表必要时否定用“不用”，“不要”是劝阻。；“会”既表本领，又表可能（明天会下雨）。","练习":[{"q":"改正“我昨天会了骑自行车”","options":["我昨天会骑了自行车。","我昨天学会了骑自行车。（或：我会骑自行车了。）"],"answer":1,"解析":"能愿动词“会”后面不带“了”；要说学会的过程，用“学会了”。","类":"回练"}],"例句解析":[{"句":"我能了游泳。","析":"能愿动词后面不带“了”，“了”放到句末。（应改为：我能游泳了。）"},{"句":"明天要考试吗？——不要考。","析":"“要”表示必要时，否定用“不用”；“不要”是劝阻。（应改为：明天要考试吗？——不用考。）"}],"前置知识":["动词","副词"]},{"name":"方位词","讲解":"表示方向和位置的名词，有单纯方位词（上、下、里、外、前、后、左、右、东、西、南、北、中、内、旁）和合成方位词（上面、里边、之间、以前）；常贴在名词后面组成方位短语。","类比":"球在箱子里。球在箱子上。球在箱子旁边。一个“里”、一个“上”，球的位置就完全不同。这些说位置的词叫方位词。","例子":["球在箱子里。","球在箱子上。","球在箱子旁边。","书在桌子上。","饭前要洗手。","同学之间要互相帮助。","错：我在桌子找到了笔。（应改为：我在桌子上找到了笔。）","错：他住在北京里。（应改为：他住在北京。）","我在学校（里）等你。","在老师的帮助下，我学会了游泳。","在这个问题上，大家意见一致。","在桌子上","在北京"],"深讲":"名词 + 方位词 = 方位短语：桌子上、教室里、大树下。方位词也能说时间：饭前、十年后、三天以前。还能说范围：会议期间、同学之间。普通的东西当地点，后面要加方位词：在桌子找到了笔——不对，要说在桌子上。地名本身就是地点，不加：在北京，不说“在北京里”。学校、图书馆这类，加不加都行：在学校、在学校里。方位词还能说抽象的“位置”：在老师的帮助下，在这个问题上。这时候没有真的上下，说的是条件、方面。想一想：为什么“在桌子上”要两个词，“在北京”一个就够？“在”只说“在某处”，“上”说明是哪个位置。普通名词本身不是地方，要靠方位词把它变成地方。有的语言学家认为，“在……上”像一个前后两半合起来的“框”，叫框式介词。（出处：刘丹青《汉语中的框式介词》，《当代语言学》2002 年第 4 期）","怎么认":["球在哪儿？","为什么一个要两个词，一个只要一个？"],"易错":"普通名词当处所时漏掉方位词：✗在桌子找到。；地名后多加方位词：✗在北京里。；方位词常被误认为副词或介词：它是名词的一个小类。","练习":[{"q":"改正“我在盒子找到了一块糖”","options":["我在盒子里面里找到了一块糖。","我在盒子里找到了一块糖。（或：我在盒子里面找到了一块糖。）"],"answer":1,"解析":"方位词加一个就够：“里”或“里面”，不能叠在一起。","类":"回练"}],"例句解析":[{"句":"我在桌子找到了笔。","析":"普通名词当处所要加方位词。（应改为：我在桌子上找到了笔。）"},{"句":"他住在北京里。","析":"地名本身表示处所，不加方位词。（应改为：他住在北京。）"}],"前置知识":["名词","介词"]},{"name":"同位短语","讲解":"前后两部分指同一个人或事物，从不同角度说，合起来充当一个成分：首都北京、我们俩、他自己、诗人李白。","类比":"首都北京。“首都”是北京，“北京”就是首都。两张卡，指着同一个地方。他自己：“他”就是“自己”。","例子":["我们去首都北京参观。","这件事他自己会处理。","首都北京 → 首都就是北京","首都的公园 → 首都就是公园（偏正短语）","我们班长小李来了。","班长和小李来了。（并列短语）","诗人李白","我们学生","他们两个","小明自己","我们学生要爱护课桌。","我们学校有一个大操场。"],"深讲":"判断同位短语，在中间加“就是”试试：首都就是北京——能说。首都的公园——加“就是”：首都就是公园？不对。这是偏正短语，“首都”修饰“公园”。我们班长小李来了。——班长就是小李，一个人。班长和小李来了。——加了“和”，变成两个人，是并列短语。名词 + 名词：诗人李白。代词 + 名词：我们学生。代词 + 数量：他们两个。名词或代词 + 自己：小明自己。想一想：“我们学生”和“我们学校”，结构一样吗？我们就是学生——能说，同位短语。我们就是学校——不能说。“我们学校”是“我们的学校”，偏正短语。也有语法书把同位短语看作一种特殊的偏正结构，因为前一部分也在限定后一部分。（出处：黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（短语的结构类型：同位短语）；朱德熙《语法讲义》，商务印书馆 1982（同位性偏正结构的说法，章节待核））","怎么认":["“首都”和“北京”是两个地方吗？","两个“我们”一样吗？"],"易错":"把同位短语当并列短语：并列是两个东西，同位是一个。；把“我们学校”这类偏正短语当同位短语。；同位短语整体只作一个成分。","练习":[{"q":"判断“诗人李白”的短语类型","options":["并列短语","同位短语：诗人就是李白，指同一个人。"],"answer":1,"解析":"两部分指同一个人或事物，中间能加“就是”，是同位短语；指两个不同的东西，才是并列短语。","类":"回练"}],"例句解析":[{"句":"首都的公园 → 首都就是公园","析":"不是同位短语。偏正短语"},{"句":"班长和小李来了。","析":"不是同位短语。并列短语"}],"前置知识":["偏正式","并列式","代词"]},{"name":"介宾短语","讲解":"介词加上名词、代词或短语组成介宾短语，交代时间、地点、对象、方式、原因等；常作状语，也作补语、定语，但不单独作谓语，一般也不作主语（“从这儿到学校要走十分钟”这类起止格式是少见的例外）。","类比":"小狗在操场上跑。“在”像一个领路的人，领着“操场上”，告诉我们小狗在哪儿跑。“在操场上”就是一个介宾短语。","例子":["小狗在操场上跑。","我们从早上开始练习。","我给妈妈打电话。","请用铅笔写名字。","为了大家，他留了下来。","他在图书馆看书。（状语）","他住在学校旁边。（补语）","我借了一本关于恐龙的书。（定语）","他在家。（“在”是动词）","错：在老师的帮助下，使我进步了。（应改为：在老师的帮助下，我进步了。）","我给他一本书。","我给他写信。"],"深讲":"时间：从早上开始。处所：往前走。对象：对他说、给妈妈打电话。方式、依据：用铅笔写、按要求做。原因、目的：因为下雨、为了大家。作状语：他在图书馆看书。作补语：他住在学校旁边。作定语：一本关于恐龙的书——作定语要带“的”。注意：他在家。这里的“在”后面没有别的动词，“在”自己作谓语，是动词，不是介词。介宾短语一般不能作主语。在老师的帮助下，使我进步了——谁进步了？“在老师的帮助下”是状语，“使”又把“我”变成了宾语，句子没了主语。去掉“使”：在老师的帮助下，我进步了。想一想：“我给他一本书”和“我给他写信”，两个“给”一样吗？第一句，“给”后面没有别的动词，它自己就是动作：动词。第二句，真正的动作是“写信”，“给他”只是交代对象：介词。汉语的介词大多是从动词变来的，所以“在、给、到、跟、比”都有动词和介词两种身份。（出处：黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（介词）；吕叔湘主编《现代汉语八百词》（增订本），商务印书馆 1999，「给」条）","怎么认":["小狗在哪儿跑？","两个“给”一样吗？"],"易错":"句首介宾短语后又用“使”，造成主语残缺。；把作谓语的动词“在、给”当成介词。；介宾短语作定语要带“的”：关于恐龙的书。","练习":[{"q":"找出“他住在学校旁边”的介宾短语并说出成分","options":["“在学校旁边”，作状语。","“在学校旁边”，放在动词“住”后面，作补语。"],"answer":1,"解析":"介宾短语在动词前作状语，在动词后作补语。","类":"回练"}],"例句解析":[{"句":"他在图书馆看书。","析":"状语"},{"句":"他住在学校旁边。","析":"补语"},{"句":"我借了一本关于恐龙的书。","析":"定语"},{"句":"他在家。","析":"“在”是动词"},{"句":"在老师的帮助下，使我进步了。","析":"介宾短语作状语，不能当主语；删去“使”，让“我”作主语。（应改为：在老师的帮助下，我进步了。）"}],"前置知识":["介词","状语","主语残缺"]},{"name":"“的”字短语","讲解":"实词或短语后面加“的”，整体相当于一个名词，指人或事物：红的、我的、开车的、昨天买的。","类比":"你要哪个苹果？——我要红的。“红的”就是“红的苹果”，大家都知道说的是苹果，“苹果”就省掉了。","例子":["我要红的。","我要红的苹果。","这支笔是新的。","这本书是图书馆的。","开车的是我爸爸。","墙上那幅画是我画的。","红的苹果（偏正短语）","红的","这本书是送你的。","送你的在门口等着呢。"],"深讲":"形容词 + 的：新的。名词、代词 + 的：妈妈的、我的。动词短语 + 的：卖菜的、开车的。主谓短语 + 的：我画的、你送的。红的苹果：后面有名词，是偏正短语。红的：后面的名词省了，“红的”自己当名词用，是“的”字短语。检查方法：能不能补出被省掉的那个名词。“的”字短语相当于名词，所以能作主语、宾语。开车的是我爸爸——主语。这本书是图书馆的——宾语。想一想：“送你的”指的是什么？可以是送给你的东西：这是送你的。也可以是送你回家的人：送你的在门口等着。“的”字短语会把意思“转”到人或东西身上，转到哪一个，要看上下文。语法学把这叫“转指”。（出处：朱德熙《自指和转指——汉语名词化标记“的、者、所、之”的功能和语义作用》，《方言》1983 年第 1 期）","怎么认":["“红的”是什么？","“送你的”是人还是东西？"],"易错":"省名词时把“的”也省掉：✗这件是姐姐。；“的”字短语可能指人，也可能指东西，要看上下文。；和偏正短语区分：后面还有名词的是偏正短语。","练习":[{"q":"把“这件衣服是姐姐的衣服”改得简洁","options":["这件衣服是姐姐的。","这件是姐姐。"],"answer":0,"解析":"省掉的是重复的名词“衣服”，“的”要留下，“姐姐的”才能指东西。","类":"回练"}],"例句解析":[{"句":"红的苹果","析":"不是“的”字短语。偏正短语"}],"前置知识":["偏正式","助词","的/地/得"]},{"name":"“所”字结构","讲解":"“所”用在及物动词前，组成“所＋动词”，指动作涉及的对象（所见＝看见的东西）；现代多说“所＋动词＋的”“为…所…”，带书面色彩。","类比":"我所知道的，都告诉你了。“我所知道的”就是“我知道的事情”。“所”放在动词前面，指的是这个动作涉及的东西。","例子":["我所知道的，都告诉你了。","这次旅行的所见所闻，让我难忘。","这是大家所关心的问题。","这个秘密很少为人所知。","我所知道的 → 我知道的","大家所关心的问题 → 大家关心的问题","错：这是大家所关心。（应改为：这是大家所关心的问题。）","写的和读的都来了。（“写的”指人）","这是我所写的。（“所写的”只指东西）"],"深讲":"所 + 动词：所见、所闻、所想。名词 + 所 + 动词 + 的：大家所关心的问题。为 + 名词 + 所 + 动词：表示被动，为人所知，就是被人知道。“所＋动词＋的”里的“所”，去掉以后意思基本不变：我所知道的——我知道的。“所”让说法更书面、更郑重。“所”后面要是能带宾语的动词：所关心、所写、所说。这是大家所关心——话没说完：关心的是什么？要补上“的”，或者补上名词：这是大家所关心的，这是大家所关心的问题。想一想：“写的”可以指写的人吗？可以：写的和读的都来了。那“所写的”呢？只能指写出来的东西，不能指写的人。“的”转指的对象很灵活；“所”只转指动作涉及的对象，从不指做动作的人。语法学家朱德熙把这一点讲得很清楚。（出处：朱德熙《自指和转指——汉语名词化标记“的、者、所、之”的功能和语义作用》，《方言》1983 年第 1 期）","怎么认":["“所知道的”指什么？","“所写的”能指写的人吗？"],"易错":"“所＋动词”后漏掉“的”或名词。；“所”只指动作涉及的对象，不指动作的发出者。；“为…所…”表示被动，书面色彩浓。","练习":[{"q":"改正“这些都是同学们所喜欢”","options":["这些都是同学们所喜欢的。","这些都是同学们所喜欢所。"],"answer":0,"解析":"“所＋动词”后面补“的”（或补名词），不是再加一个“所”。","类":"回练"}],"例句解析":[{"句":"这是大家所关心。","析":"“所＋动词”在现代汉语里一般要带“的”或后面的名词。（应改为：这是大家所关心的问题。）"},{"句":"写的和读的都来了。","析":"“写的”指人"},{"句":"这是我所写的。","析":"“所写的”只指东西"}],"前置知识":["的/地/得","被字句"]}]},{"id":"shenceng","name":"深层语法（6种）","items":[{"name":"配价","讲解":"一个动词必须带上几个名词性成分句子才完整，它就是几价动词：下雨（零价）、游泳（一价）、喜欢（二价）、送（三价）；必需的那只手空着，句子就残缺。","类比":"下雨了。——“下雨”不用抓谁。弟弟游泳。——“游泳”一只手，抓住弟弟。我喜欢画画。——“喜欢”两只手：谁喜欢，喜欢什么。奶奶给我一个苹果。——“给”三只手。","例子":["下雨了。","弟弟游泳。","我喜欢画画。","奶奶给我一个苹果。","错：奶奶给我。（应改为：奶奶给我一个苹果。）","错：这次比赛使我。（应改为：这次比赛使我明白了坚持的意义。）","错：他游泳那条河。（应改为：他在那条河里游泳。）","我吃了苹果。","苹果我吃了。","门口站着一位老师。","一位老师站在门口。"],"深讲":"奶奶给我——给什么？一只手空着，话没说完。这次比赛使我——使你怎么样？也没说完。检查病句时，数一数动词的手，空着的就补上。一价动词只有一只手，不能硬带宾语。他游泳那条河——不对。“游泳”只抓“他”，地方要用“在”引出来：他在那条河里游泳。苹果我吃了。“苹果”跑到前面去了，“吃”还是两只手吗？还是。“吃”一只手抓“我”，一只手伸到前面抓“苹果”。手抓的东西可以换位置，手的数目不变。想一想：“门口站着一位老师”，“站”抓住的是“门口”还是“老师”？抓住的是“老师”——站的是老师。“门口”只是地点，排在句首，却不是“站”的手。语法学把动词必须带的名词叫“论元”，把这种数手的办法叫“配价分析”。不同的书数法略有不同：有的把“在…”引出的地点也算一只手。（出处：陆俭明《现代汉语语法研究教程》（第五版），北京大学出版社 2019，「配价分析」章；沈阳、郑定欧主编《现代汉语配价语法研究》，北京大学出版社 1995）","怎么认":["每个动词要几只手？","“站”抓的是谁？"],"易错":"数手时把地点、时间也算进去：多数情况它们不是必需的手。；一价动词硬带宾语：✗游泳那条河。；三价动词少带一样：✗这个故事告诉我们。","练习":[{"q":"补全“这个故事告诉”","options":["这个故事告诉我们要诚实。","这个故事告诉我们。"],"answer":0,"解析":"“告诉”是三价动词：谁告诉、告诉谁、告诉什么，三只手都要抓住。","类":"回练"}],"例句解析":[{"句":"奶奶给我。","析":"“给”要三只手，缺了“给什么”。（应改为：奶奶给我一个苹果。）"},{"句":"这次比赛使我。","析":"“使”后面要说出让人怎么样。（应改为：这次比赛使我明白了坚持的意义。）"},{"句":"他游泳那条河。","析":"“游泳”是一价动词，处所用介词“在”引出。（应改为：他在那条河里游泳。）"}],"前置知识":["动词","宾语","成分残缺或赘余","宾语残缺"]},{"name":"语义指向","讲解":"一个修饰或补充成分，在意思上跟句子里的哪个词挂钩，就是它的语义指向；挨得近的，不一定是它说的那个。","类比":"他高高兴兴地吃了一碗面。“高高兴兴”挨着“吃”，可是高兴的是谁？是“他”。姐姐浓浓地泡了一杯茶。浓的是什么？是茶。","例子":["他高高兴兴地吃了一碗面。","姐姐浓浓地泡了一杯茶。","我们都喜欢猫。","这些书我都看过。","你都买了什么？","我吃饱了。","衣服洗干净了。","我把作业写完了。","我只吃了一个苹果。","只有我吃了苹果。","他在车上看书。","他在本子上画画。","他把画画在本子上。","错：他把书看在车上。（应改为：他在车上看书。）"],"深讲":"我们都喜欢猫。——“都”指“我们”：每个人都喜欢。这些书我都看过。——“都”指“这些书”：每本都看过。你都买了什么？——“都”指后面的“什么”：要你把买的东西全说出来。我吃饱了。——饱的是“我”。衣服洗干净了。——干净的是“衣服”。我把作业写完了。——“完”说的是“写”这个动作做完了。我只吃了一个苹果。——“只”指“一个”：吃得少。只有我吃了苹果。——“只”指“我”：别人都没吃。位置一换，指向就换，意思也跟着变。想一想：“他在车上看书”和“他在本子上画画”，两个“在……上”一样吗？他在车上看书：车上的是“他”。他在本子上画画：本子上的是画出来的画，人并不在本子上。看着一样的结构，指向不一样，所以能变的说法也不一样：能说“把画画在本子上”，不能说“把书看在车上”。（出处：陆俭明《现代汉语语法研究教程》（第五版），北京大学出版社 2019，「语义指向分析」章；朱德熙《“在黑板上写字”及相关句式》，《语言教学与研究》1981 年第 1 期）","怎么认":["高兴的是谁？浓的是什么？","在车上的是谁？在本子上的是什么？"],"易错":"以为修饰语只说紧挨着的词。；“都”多指前面的复数成分，问句里可指后面的疑问词。；指向不同，句子能做的变换也不同。","练习":[{"q":"说出“他们都是我的同学”中“都”的语义指向","options":["指“他们”：他们每一个都是我的同学。","指“同学”"],"answer":0,"解析":"“都”总括的是它前面那些人或东西的每一个。","类":"回练"}],"例句解析":[{"句":"他把书看在车上。","析":"“在车上”指人所在的地方，不能移到动词后面。（应改为：他在车上看书。）"}],"前置知识":["状语","补语","都/也","副词"]},{"name":"层次分析","讲解":"短语和句子是一层一层组合起来的；分析时每次一分为二，从大到小切，切到词为止，每一刀切出的两块都要能成立、能搭配。","类比":"妈妈买的新书包。先装：妈妈买。再装：妈妈买的。“新”和“书包”也装一盒：新书包。最后两大盒装在一起：妈妈买的 + 新书包。","例子":["妈妈买的新书包","小明认真地写作业。","错：新书｜包（应改为：新｜书包）","（三个）（班的同学）（三个同学）","（三个班）的同学（三个班的所有同学）","我们公司打算进口零件。（动宾）","这批进口零件质量很好。（偏正）"],"深讲":"句子也一样：小明认真地写作业。第一刀：小明｜认真地写作业——主谓。第二刀：认真地｜写作业——偏正。第三刀：写｜作业——动宾。从左到右，一层一层往下切，一分为二，到词为止。新书包：切成“新｜书包”——新的书包。切成“新书｜包”——新书的包？意思不对了。每一刀切出来的两块，要合起来正好是原来的意思。三个班的同学。可以装成：三个｜班的同学——三个同学。也可以装成：三个班｜的同学——来自三个班的同学，人可能很多。装法不同，意思就不同，这就是歧义。想一想：“进口零件”只能切一刀：进口｜零件。为什么还会有两种意思？一种是动宾：进口零件——把零件买进来。一种是偏正：进口的零件。层次相同，结构关系不同，也会产生歧义。所以分析时既要看“怎么切”，也要看“切开以后是什么关系”。（出处：朱德熙《语法讲义》，商务印书馆 1982（层次构造）；陆俭明《现代汉语语法研究教程》（第五版），北京大学出版社 2019，「层次分析法」章）","怎么认":["先装哪两个？","只有一刀，为什么有两种意思？"],"易错":"切出不成立的一块：✗新书｜包（指新的书包时）。；一刀切成三块：层次分析每次只一分为二。；同样的切法可能有不同的结构关系。","练习":[{"q":"给“我的好朋友”切第一刀","options":["我的好｜朋友","我的｜好朋友"],"answer":1,"解析":"第一刀切出的两块要各自成立：“我的”修饰“好朋友”；“我的好”不成一块。","类":"回练"}],"例句解析":[{"句":"新书｜包","析":"这里说的是新的书包，不是装新书的包。（应改为：新｜书包）"},{"句":"（三个）（班的同学）","析":"三个同学"},{"句":"（三个班）的同学","析":"三个班的所有同学"},{"句":"我们公司打算进口零件。","析":"动宾"},{"句":"这批进口零件质量很好。","析":"偏正"}],"前置知识":["偏正式","主谓式","动宾式","歧义句","定语"]},{"name":"省略与 ∅","讲解":"话里有的成分不说出来，听的人能根据上下文补出唯一的那个词，这个空位记作 ∅，叫省略；补不出来，就是成分残缺。","类比":"你吃饭了吗？——吃了。“吃了”前面少了谁？少了“我”。听的人一下就能补出来，所以可以不说。空着的位置，我们画一个空框。","例子":["你吃饭了吗？——（我）吃了。","小明进了门，∅放下书包。","∅一进门，他就喊饿。","小明拿起书，∅走了出去。","错：经过大家的努力，使班级卫生有了很大改善。（应改为：经过大家的努力，班级卫生有了很大改善。）","错：小红和小丽是好朋友，常常去她家玩。（应改为：小红和小丽是好朋友，小红常常去小丽家玩。）","下雨了。（无主句）","（我）吃了。（省略）"],"深讲":"承前省：前面说过，后面省掉。小明进了门，∅放下书包。蒙后省：后面才出现，前面先省掉。∅一进门，他就喊饿。∅ 读作“空”，表示这里本来有一个词。小明拿起书，∅走了出去。——补得出“小明”，是省略。经过大家的努力，使班级卫生有了很大改善。——谁努力的结果？主语的位置补不出唯一的词，是残缺。能补出唯一的词，才叫省略。小红和小丽是好朋友，∅常常去她家玩。谁去谁家？∅ 可能是小红，也可能是小丽，“她”也说不清。∅ 有两个可能的落点时，就要把人说出来。想一想：“下雨了”前面是不是也省了什么？没有。“下雨了”本来就不需要主语，也补不出一个非有不可的词。这种句子叫无主句，不是省略。“吃了”前面的空位能补出“我”，是省略。语言学把后面再次提到时用空位代替的现象叫“零形回指”。汉语比英语更常用空位。（出处：陈平《汉语零形回指的话语分析》，《中国语文》1987 年第 5 期；黄伯荣、廖序东主编《现代汉语》增订六版下册「语法」章（省略句与非主谓句））","怎么认":["谁吃了？","“下雨了”省掉了什么吗？"],"易错":"把成分残缺当作省略。；空位有两个可能的落点时会造成指代不明。；无主句本来不需要主语，不算省略。","练习":[{"q":"判断“通过这次实验，使我们懂得了很多道理”是省略还是残缺","options":["省略了主语，可以不改。","主语残缺：补不出唯一的主语。改成“通过这次实验，我们懂得了很多道理”。"],"answer":1,"解析":"补得出唯一的词是省略；补不出来是残缺，要改。","类":"回练"}],"例句解析":[{"句":"经过大家的努力，使班级卫生有了很大改善。","析":"主语位置补不出确定的词，是残缺；删去“使”即可。（应改为：经过大家的努力，班级卫生有了很大改善。）"},{"句":"小红和小丽是好朋友，常常去她家玩。","析":"空位和“她”都有两个可能的人，要说清。（应改为：小红和小丽是好朋友，小红常常去小丽家玩。）"},{"句":"下雨了。","析":"无主句"},{"句":"（我）吃了。","析":"省略"}],"前置知识":["主语残缺","成分残缺或赘余","指代不明"]},{"name":"话题与焦点","讲解":"话题是句子从哪儿说起（常在句首、是已知的）；焦点是句子最想让你知道的新信息（常在句末，也可以用“是”“连”和重音标出来）。","类比":"谁打碎了杯子？——是弟弟打碎的。问的是“谁”，答句里最要紧的就是“弟弟”。句子最想告诉你的那一块，叫焦点。","例子":["谁打碎了杯子？——是弟弟打碎的。","我昨天买了一本书。","他是昨天来的。","连爷爷都会用手机了。","只有她答对了。","这本书，我看过。","错：一本书，我看过。（应改为：有一本书我看过。）","你什么时候来的？——我是昨天来的。","错：你什么时候来的？——是我昨天来的。（应改为：你什么时候来的？——我是昨天来的。）"],"深讲":"不加任何标记时，新信息一般放在句子后面：我昨天买了一本书。检验办法：看它回答什么问题。“你昨天买了什么？”——一本书。句首的“我”大家都知道，是话题；句末的“一本书”是新信息。用“是……的”：他是昨天来的——焦点是“昨天”。用“连……都/也”：连爷爷都会用手机了——焦点是“爷爷”，意思是“最不可能的都会了”。用“只、就”：只有她答对了。这本书，我看过。——“这本书”大家知道是哪本，可以当话题。一本书，我看过。——一本什么书？没头没脑，不能这样开头。要说：有一本书我看过，或者，这本书我看过。想一想：有人问“你什么时候来的？”，下面哪个回答合适？我是昨天来的。——焦点是“昨天”，正好回答“什么时候”。是我昨天来的。——焦点变成了“我”，好像别人问的是“谁来的”。同样几个词，焦点放错，就答非所问。语法学把用“是”标出的焦点叫对比焦点。（出处：方梅《汉语对比焦点的句法表现手段》，《中国语文》1995 年第 4 期；徐烈炯、刘丹青《话题的结构与功能》，上海教育出版社 1998）","怎么认":["答句里最要紧的是哪个词？","哪个回答合适？"],"易错":"把焦点放在问题没问的地方，答非所问。；话题一般是已知、确定的。；话题和主语常重合，但不总是同一个：这本书我看过（话题是“这本书”，主语是“我”）。","练习":[{"q":"用“是……的”回答“谁把窗户打开了？”","options":["我是昨天打开的窗户。","是我打开的。"],"answer":1,"解析":"问“谁”，焦点在人身上，“是”要放在人的前面。","类":"回练"}],"例句解析":[{"句":"一本书，我看过。","析":"话题一般是已知的、确定的，不能是随便的“一本书”。（应改为：有一本书我看过。）"},{"句":"你什么时候来的？——是我昨天来的。","析":"问时间，焦点要落在时间上，“是”放在“昨天”前。（应改为：你什么时候来的？——我是昨天来的。）"}],"前置知识":["话题句","是…的句"]},{"name":"语序与重音","讲解":"汉语主要靠语序和虚词表达语法意义：词换了位置，意思可能完全不同；同一句话重读不同的词，强调的重点也跟着变。","类比":"狗咬猫。——狗是咬的，猫是被咬的。把“狗”和“猫”换个位置：猫咬狗。字一样，事情完全反过来了。","例子":["狗咬猫。","猫咬狗。","这道菜不很好吃。","这道菜很不好吃。","我们一会儿再说。","我们再说一会儿。","我明天去北京。","错：我们要及时解决并发现问题。（应改为：我们要及时发现并解决问题。）","信来了。","来信了。"],"深讲":"不很好：不太好，还行。很不好：非常差。再说一会儿：继续说一阵。一会儿再说：过一阵再说。同样的字，顺序一换，意思就变了。我明天去北京。重读“我”：是我去，不是别人。重读“明天”：是明天，不是今天。重读“北京”：去北京，不是别的地方。重音落在哪儿，就在回答哪个问题。我们要及时解决并发现问题——先解决，再发现？顺序反了。事情有先后，词语就按先后排：及时发现并解决问题。想一想：“信来了”和“来信了”，说的信一样吗？信来了：说的是大家在等的那封信，是确定的。来信了：来了一封信，事先不知道是谁的。汉语里，放在动词前的名词常常是已知、确定的，放在动词后的常常是新出现的。语序在帮我们分“旧”和“新”。（出处：赵元任《汉语口语语法》（吕叔湘译），商务印书馆 1979（主语有定、宾语无定的倾向）；朱德熙《语法讲义》，商务印书馆 1982（章节待核））","怎么认":["换位置以后，谁咬谁？","两封信一样吗？"],"易错":"改语序不当时删掉内容，改变了原意。；“不很”和“很不”意思相差很大。；重音不同，强调的焦点不同。","练习":[{"q":"改正“会上，大家讨论并听取了校长的报告”","options":["会上，大家听取并讨论了校长的报告。","会上，大家讨论了校长的报告。"],"answer":0,"解析":"语序不当要调换顺序，不能删掉内容：先听取，再讨论。","类":"回练"}],"例句解析":[{"句":"我们要及时解决并发现问题。","析":"先发现，才能解决，按事情先后排列。（应改为：我们要及时发现并解决问题。）"}],"前置知识":["语序不当","歧义句","话题句"]}]},{"id":"xiuci_buqi","name":"修辞补齐（6种）","items":[{"name":"借代","讲解":"不直接说本来的人或事物，借和它密切相关的东西（特征、标志、部分、所在地、作品等）来代称；借体和本体靠“相关”联系，不靠“相像”。","类比":"一群红领巾跑进了操场。红领巾会跑吗？不会。说的是戴红领巾的少先队员。借一样和他们紧紧相关的东西来叫他们，这就是借代。","例子":["一群红领巾跑进了操场。","大胡子刚才来找你。（特征代人）","白大褂们连夜救治病人。（标志代人）","港口里停着上百张帆。（部分代整体）","他一口气读完了三本鲁迅。（作者代作品）","天上的棉花糖慢慢飘走了。（借喻（比喻））","白大褂们连夜救治病人。","全场都为她鼓掌。→ 全场观众都为她鼓掌。","长发姐姐唱得真好。","长发唱得真好。"],"深讲":"借特征：大胡子刚才来找你。借标志：白大褂们连夜救治病人。借部分代整体：港口里停着上百张帆——帆代船。借作者代作品：他一口气读完了三本鲁迅。天上的棉花糖慢慢飘走了。——能说“云像棉花糖”，靠的是相像，这是比喻里的借喻。白大褂们在救人。——不能说“医生像白大褂”，靠的是相关，这是借代。检验：能补成“A 像 B”的是借喻；补不成的是借代。读到借代，把借体换回本体，意思应该不变：全场都为她鼓掌——全场的观众都为她鼓掌。借体要让人一下就懂。借得太偏，别人就读不懂了。想一想：“长发姐姐唱得真好”和“长发唱得真好”，哪一句用了借代？第一句，“长发”只是修饰“姐姐”，本体“姐姐”还在，不是借代。第二句，本体不见了，只用特征“长发”来代人，是借代。修辞学里，比喻靠“相似”，借代靠“相关”。语言学把后一种叫“转喻”。（出处：陈望道《修辞学发凡》（借代格），1932 年大江书铺初版，后有多种重印本；格名以原书为准；沈家煊《转指和转喻》，《当代语言学》1999 年第 1 期）","怎么认":["跑进操场的是什么？","哪一句用了借代？"],"易错":"把借喻当借代：能补成“A 像 B”的是比喻。；本体也出现了的，不是借代。；借体要让读者能懂。","练习":[{"q":"判断“满天的星星像眨着的眼睛”的修辞","options":["借代","比喻：本体星星、喻体眼睛都出现，靠的是相像。"],"answer":1,"解析":"有“像”、靠相似的是比喻；只出现相关事物、不出现本体的才是借代。","类":"回练"}],"例句解析":[{"句":"大胡子刚才来找你。","析":"特征代人"},{"句":"白大褂们连夜救治病人。","析":"标志代人"},{"句":"港口里停着上百张帆。","析":"部分代整体"},{"句":"他一口气读完了三本鲁迅。","析":"作者代作品"},{"句":"天上的棉花糖慢慢飘走了。","析":"不是借代。借喻（比喻）"},{"句":"长发姐姐唱得真好。","析":"不是借代。"}],"前置知识":["比喻"]},{"name":"对比","讲解":"把两种相反或相对的事物，或同一事物相反的两个方面放在一起比照，让好坏、冷热、美丑更鲜明。","类比":"屋外寒风刺骨，屋里却暖洋洋的。冷和暖放在一起，屋里的暖就显得更暖了。","例子":["屋外寒风刺骨，屋里却暖洋洋的。","哥哥爱静，弟弟好动。（两物对比）","他嘴上说不怕，腿却在发抖。（一物两面）","说起来容易，做起来难。（对比，不是对偶）","春风吹绿柳，细雨润青苗。（对偶，不是对比）","这片树林，夏天热闹，冬天冷清。","哥哥爱静，弟弟好动。（对比：两边平等）","别的花都谢了，只有梅花还开着。（衬托：有主有次）"],"深讲":"两样东西对比：哥哥爱静，弟弟好动。同一个东西的两面对比：他嘴上说不怕，腿却在发抖。对比看意思：是不是相反、相对。对偶看形式：字数相等，结构相同。说起来容易，做起来难。——意思相反，是对比；字数不等，不是对偶。春风吹绿柳，细雨润青苗。——字数结构都对上，是对偶；意思不相反，不是对比。找对比，先找成对的词：静和动，冷和暖，容易和难。这片树林，夏天热闹，冬天冷清。——对比点：夏天和冬天，热闹和冷清。想一想：“别的花都谢了，只有梅花还开着”是对比吗？这里两边不是平起平坐：写别的花，是为了让梅花更突出。这叫衬托，有主有次。对比的两边地位相当，各说各的。陈望道把这两种合称为“映衬”。（出处：陈望道《修辞学发凡》（映衬格），1932 年大江书铺初版，后有多种重印本；格名以原书为准）","怎么认":["放在一起比，哪个显得更突出？","两边一样重要吗？"],"易错":"把对偶当对比：对偶看形式，对比看意思。；把衬托当对比：衬托有主次。；对比和对偶可以同时出现。","练习":[{"q":"判断“他的房间乱糟糟，姐姐的房间干干净净”的修辞","options":["对比：乱和干净相反；两半句字数不等，不是对偶。","对偶"],"answer":0,"解析":"意思相反是对比；字数相等、结构相同才是对偶。","类":"回练"}],"例句解析":[{"句":"哥哥爱静，弟弟好动。","析":"两物对比"},{"句":"他嘴上说不怕，腿却在发抖。","析":"一物两面"},{"句":"说起来容易，做起来难。","析":"对比，不是对偶"},{"句":"春风吹绿柳，细雨润青苗。","析":"不是对比。对偶，不是对比"},{"句":"哥哥爱静，弟弟好动。","析":"对比：两边平等"},{"句":"别的花都谢了，只有梅花还开着。","析":"不是对比。衬托：有主有次"}],"前置知识":["对偶","转折复句"]},{"name":"反语","讲解":"故意说和本意相反的话：正话反说或反话正说，常带讽刺、幽默或亲昵；要靠语境才听得出来，书面上常加引号。","类比":"上课铃响了一个小时，他才慢悠悠走进教室。老师说：你来得可真早啊！真的早吗？一点也不早。老师说的是反话，意思是：你来得太晚了。","例子":["你来得可真早啊！","把作业藏起来不交，真是个“聪明”的办法。（讽刺）","妈妈笑着说：“你这个小坏蛋！”（亲昵）","难道你不知道要迟到了吗？（反问）","你来得真早啊！","（他第一个到教室）你来得真早啊！（真心夸奖）","这个办法可真“好”。","（窗外大雨）今天天气真不错啊！"],"深讲":"正话反说，常常是讽刺：把作业藏起来不交，真是个“聪明”的办法。反话正说，常常是亲昵：妈妈笑着说：你这个小坏蛋！其实是喜欢。反问用问句的样子说确定的意思：难道你不知道要迟到了吗？——你应该知道。反语是把意思说反：你来得真早啊！——你来得太晚了。反问看形式是不是问句；反语看字面和本意是不是相反。同一句“你来得真早啊”，如果他真的第一个到，那就是真心夸奖，不是反语。反语靠语境。书面上，常给反话加上引号提醒读者：这个办法可真“好”。想一想：为什么大家都能听出反话？因为字面意思和眼前的事实明显不合：明明迟到，却说“早”。听的人发现不合，就去找说话人真正的意思。反语在陈望道的书里叫“倒反”。研究说话含义的学问叫语用学。（出处：陈望道《修辞学发凡》（倒反格），1932 年大江书铺初版，后有多种重印本；格名以原书为准）","怎么认":["老师的意思是早还是晚？","听的人是怎么听出来的？"],"易错":"离开语境判断反语。；把反问当反语：反问看形式，反语看意思是否相反。；反语有讽刺也有亲昵，不一定是坏意思。","练习":[{"q":"判断“你的字写得真‘漂亮’”（字歪歪扭扭）是不是夸奖","options":["不是，是反语：字写得很乱，“漂亮”加了引号，是说反话。","是夸奖"],"answer":0,"解析":"字面意思和事实相反，又加了引号，多半是反语。","类":"回练"}],"例句解析":[{"句":"把作业藏起来不交，真是个“聪明”的办法。","析":"讽刺"},{"句":"妈妈笑着说：“你这个小坏蛋！”","析":"亲昵"},{"句":"难道你不知道要迟到了吗？","析":"不是反语。反问"},{"句":"（他第一个到教室）你来得真早啊！","析":"不是反语。真心夸奖"}],"前置知识":["反问","夸张"]},{"name":"顶真","讲解":"用前一句末尾的词语作后一句的开头，首尾相连，像接龙一样（也写作“顶针”）。","类比":"门前有条河，河上有座桥，桥上走着小花猫。前一句最后是“河”，后一句就从“河”开始；前一句最后是“桥”，后一句就从“桥”开始。一环扣一环，这叫顶真。","例子":["门前有条河，河上有座桥，桥上走着小花猫。","学习要有计划，计划要能坚持，坚持才有收获。","盼着，盼着，春天终于来了。（反复）","门前有条河，河上有座桥。","我们走进树林，树林里鸟儿在唱歌。","我们走进树林，鸟儿在树林里唱歌。","我帮你，你帮我。"],"深讲":"顶真让句子环环相扣、条理清楚，读起来顺口。学习要有计划，计划要能坚持，坚持才有收获。——一步推出下一步。反复是为了强调，把同一个词或句子重复说：盼着，盼着，春天终于来了。顶真是首尾相接，后一句从前一句的结尾接下去。检验：重复的词是不是正好在“前句尾、后句头”。我们走进树林，树林里鸟儿在唱歌。——前句末尾“树林”，后句开头“树林”，是顶真。我们走进树林，鸟儿在树林里唱歌。——“树林”在后一句中间，没有接上，不是顶真。想一想：“我帮你，你帮我”是顶真吗？前句尾“你”，后句头“你”——接上了，是顶真；而且“我—你、你—我”转了一圈回来，也是回环。顶真只要求首尾相接；回环要求前后词序颠倒、意思循环。一句话可以同时用两种辞格。（出处：陈望道《修辞学发凡》（顶真格、回文格），1932 年大江书铺初版，后有多种重印本；格名以原书为准）","怎么认":["每一句是从哪个字开始的？","它是顶真吗？"],"易错":"重复的词不在“前句尾、后句头”，不是顶真。；和反复、回环分清。；“顶真”也写作“顶针”。","练习":[{"q":"用顶真续写“天上有朵云”","options":["天上有朵云，云里藏着雨。","天上有朵云，雨从云里落下来。"],"answer":0,"解析":"顶真要用前一句末尾的词作后一句的开头。","类":"回练"}],"例句解析":[{"句":"盼着，盼着，春天终于来了。","析":"不是顶真。反复"},{"句":"我们走进树林，鸟儿在树林里唱歌。","析":"不是顶真。"}],"前置知识":["反复","排比"]},{"name":"互文","讲解":"前后两个部分的词语互相呼应、互相补充，读的时候要把它们合在一起理解，不能拆开各管各（古人叫“互文见义”）。","类比":"为了找回丢失的小狗，他东奔西走。是往东边奔、往西边走吗？不是。“东西”合起来是到处，“奔走”合起来是忙着跑。意思是：他到处奔走。","例子":["为了找回丢失的小狗，他东奔西走。","车站里南来北往的旅客很多。","我们千呼万唤，他才出来。","他站在门口左顾右盼。","唐时风雨宋时桥。（仿古自编）","春风吹绿柳，细雨润青苗。（对偶）","唐时风雨宋时桥。","唐宋时的风雨，唐宋时的桥。"],"深讲":"不少四字成语就是这样的：南来北往——来来往往的人从各处来、往各处去。千呼万唤——呼和唤合起来，叫了很多很多次。左顾右盼——左右合起来，到处看。唐时风雨宋时桥。是唐朝的风雨、宋朝的桥吗？要合起来读：唐宋时的风雨，唐宋时的桥——这座桥经历了很久很久。互文常常借用对偶的样子，但对偶不一定是互文。春风吹绿柳，细雨润青苗。——拆开读意思就对，是对偶，不是互文。检验：拆开读是不是片面、不合情理？是，就要合起来读。想一想：直接说“唐宋时的风雨和桥”不行吗？也行，但不整齐、不好读。互文把一个完整的意思分到两半里说，字数省了，句子也整齐了。古人注书时常说“互文见义”“参互见义”，意思就是两边要互相补足来理解。（出处：待核（拟查：杨树达《汉文文言修辞学》中「参互」一章；黄伯荣、廖序东主编《现代汉语》增订六版下册「修辞」章是否收「互文」））","怎么认":["他只往东、往西跑吗？","为什么不直接说？"],"易错":"把互文拆开逐字翻译。；把一般的对偶当互文。；互文要靠上下文和常理判断。","练习":[{"q":"解释“南来北往”","options":["从各处来，往各处去，形容来来往往的人很多。","从南边来，往北边去。"],"answer":0,"解析":"互文要合起来理解，不能拆开各管各。","类":"回练"}],"例句解析":[{"句":"春风吹绿柳，细雨润青苗。","析":"不是互文。对偶"}],"前置知识":["对偶"]},{"name":"通感","讲解":"用一种感官的感觉去写另一种感官的感受：把声音写得有颜色、有味道，把香气写得像声音……也叫“移觉”。","类比":"她的歌声甜甜的。歌声是用耳朵听的，“甜”是用舌头尝的。把听到的写成尝到的，这就是通感。","例子":["她的歌声甜甜的。","门外传来一串清亮的笑声。（听→视）","桂花的香气，像一支轻轻的歌。（嗅→听）","这幅画用的是暖暖的颜色。（视→触）","她的眼睛像星星。（比喻）","她的笑声像阳光一样明亮。（通感兼比喻）","全场响起热烈的掌声。"],"深讲":"听觉写成视觉：一串清亮的笑声。亮，本来是看的。嗅觉写成听觉：桂花的香气，像一支轻轻的歌。视觉写成触觉：这幅画用的是暖暖的颜色。她的眼睛像星星。——眼睛和星星都是看的，没有换感官，只是比喻。她的笑声像阳光一样明亮。——笑声是听的，明亮是看的，换了感官：通感，同时也用了比喻。检验：有没有从一种感官跳到另一种感官。很多通感已经变成了常用词：热烈的掌声、尖叫、甜美的声音、冷色、响亮。掌声没有温度，“热烈”却说的是热。用久了，大家就不觉得是修辞了。想一想：为什么“甜甜的歌声”我们一听就懂？因为不同的感觉给人的心情相通：甜的东西让人舒服，好听的歌也让人舒服。作者借这种相通，把一种感觉“搬”到另一种感觉上。钱钟书专门写过一篇文章《通感》，讨论古今诗文里的这种写法。（出处：钱钟书《通感》，原载《文学评论》1962 年第 1 期，收入《七缀集》，上海古籍出版社 1985）","怎么认":["歌声能尝出甜味吗？","为什么一听就懂？"],"易错":"把普通比喻当通感：要看是否换了感官。；通感常和比喻同时出现。；已成常用词的通感（热烈的掌声）也属于通感。","练习":[{"q":"判断“花儿红得像火”是否用了通感","options":["用了通感","没有，这是比喻：花的红和火的红都是看到的，没有换感官。"],"answer":1,"解析":"通感要从一种感官跳到另一种感官；同一种感官里的打比方是比喻。","类":"回练"}],"例句解析":[{"句":"门外传来一串清亮的笑声。","析":"听→视"},{"句":"桂花的香气，像一支轻轻的歌。","析":"嗅→听"},{"句":"这幅画用的是暖暖的颜色。","析":"视→触"},{"句":"她的眼睛像星星。","析":"不是通感。比喻"},{"句":"她的笑声像阳光一样明亮。","析":"通感兼比喻"}],"前置知识":["比喻"]}]},{"id":"biaodian","name":"标点符号（5种）","items":[{"name":"引号","讲解":"引号标示直接引用的内容，或需要着重论述、有特殊含义的词语；横排时外层用双引号，里层用单引号。","类比":"妈妈说：“回家吃饭吧。”引号像一个框，框住的是妈妈的原话，一个字也不改。","例子":["妈妈说：“回家吃饭吧。”","老师说：“明天带尺子。”","“的”是一个助词。","他把作业藏起来，真是“聪明”。","错：他说：“我喜欢秋天”。（应改为：他说：“我喜欢秋天。”）","他常说“慢慢来”。","小明问：“老师，‘燕子’这个词怎么写？”","他说：“快走，要下雨了。”","“快走，”他说，“要下雨了。”"],"深讲":"引用原话：老师说：“明天带尺子。”要特别讲的词：“的”是一个助词。有特殊意思的词，比如反话：他把作业藏起来，真是“聪明”。引用的话完整、独立，句末的点号放在引号里面：他说：“我喜欢秋天。”引用的话只是句子的一部分，引号里不加句号，句号放在外面：他常说“慢慢来”。引号里面还要用引号时，外面一层用双引号，里面一层用单引号。小明问：“老师，‘燕子’这个词怎么写？”想一想：“说”放在不同位置，后面的标点一样吗？“说”在引语前面，用冒号：他说：“快走。”“说”插在引语中间，只能用逗号：“快走，”他说，“要下雨了。”这些规定都写在国家标准《标点符号用法》里。（出处：GB/T 15834—2011《标点符号用法》4.8 引号；附录 B.1.5（“说”“道”之后用冒号或逗号）、B.2.1（引号内外的标点））","怎么认":["引号里是谁说的话？","“说”后面用冒号还是逗号？"],"易错":"完整独立的引语，句末点号放引号外：✗他说：“我喜欢秋天”。；引语作句子成分时，引号里却加了句号。；插在引语中间的“说”后面用冒号：应用逗号。","练习":[{"q":"改正 爸爸说：‘我们去公园吧’。 的标点","options":["爸爸说，“我们去公园吧”。","爸爸说：“我们去公园吧。”"],"answer":1,"解析":"单层引语用双引号；“说”在前用冒号；完整的引语，句号放在引号里面。","类":"回练"}],"例句解析":[{"句":"他说：“我喜欢秋天”。","析":"完整独立的引语，句末点号保留在引号内。（应改为：他说：“我喜欢秋天。”）"}],"前置知识":["反问"]},{"name":"冒号","讲解":"冒号用在总说性或提示性的词语后面，提示下文；也可总结上文、引出注释说明、放在称呼语后。它管到句末，一句话里一般不套用两个冒号。","类比":"书包里有三样东西：书、本子、铅笔。冒号像在说：“注意，下面就是！”后面的话是前面的展开。","例子":["书包里有三样东西：书、本子、铅笔。","她说：“我们开始吧。”","时间：明天上午九点。","亲爱的同学们：","错：他说：我的意见是：先吃饭。（应改为：他说：“我的意见是先吃饭。”）","错：他买了三样水果：苹果、香蕉和梨，然后回家了。（应改为：他买了三样水果：苹果、香蕉和梨。然后他回家了。）","据天气预报说，明天有雨。","光说“不知道”可不行。"],"深讲":"说、问之后引出原话：她说：“我们开始吧。”总说之后分说：明天的安排是：上午参观，下午画画。注释说明：时间：明天上午九点。书信称呼之后：亲爱的同学们：他说：我的意见是：先吃饭。——一句话里两个冒号，层次乱了。改成：他说：“我的意见是先吃饭。”冒号管多远，就要在那里用句号收住。他买了三样水果：苹果、香蕉和梨，然后回家了。——“然后回家了”不是水果，却被冒号管进去了。改成：他买了三样水果：苹果、香蕉和梨。然后他回家了。想一想：“据天气预报说”后面要用冒号吗？不用。“据……说”只是交代消息来源，不是提示下文，用逗号：据天气预报说，明天有雨。有停顿、真在提示下文的地方才用冒号；没有停顿的地方不用：光说“不知道”可不行。（出处：GB/T 15834—2011《标点符号用法》4.7 冒号（4.7.3.5 一个句子内部一般不应套用冒号）；附录 A.6.1–A.6.3）","怎么认":["冒号后面的话和前面是什么关系？","要用冒号吗？"],"易错":"一句里套用两个冒号。；冒号管辖范围过宽，把不相干的话也管了进去。；不是提示性话语（据……说）后用冒号。","练习":[{"q":"改正“我的爱好有：画画、游泳、下棋，我每周都练。”","options":["我的爱好有画画、游泳、下棋。我每周都练。","我的爱好有：画画、游泳、下棋：我每周都练。"],"answer":0,"解析":"冒号要管到句末，又不能套用；“有”后面直接列举、没有停顿时也可以不用冒号。","类":"回练"}],"例句解析":[{"句":"他说：我的意见是：先吃饭。","析":"一个句子内部一般不套用冒号。（应改为：他说：“我的意见是先吃饭。”）"},{"句":"他买了三样水果：苹果、香蕉和梨，然后回家了。","析":"冒号的提示范围要到句末，范围外的话用句号隔开。（应改为：他买了三样水果：苹果、香蕉和梨。然后他回家了。）"}]},{"name":"顿号与分号","讲解":"顿号用在并列词语之间，停顿最短；分号用在复句内部并列分句之间（分句里常已有逗号），也用于分项列举和非并列多重复句的第一层，停顿比逗号长、比句号短。","类比":"我喜欢红色、黄色和蓝色。并排的词之间用顿号，停得最短。最后两个之间用了“和”，就不再加顿号。","例子":["我喜欢红色、黄色和蓝色。","错：来了三、四个人。（应改为：来了三四个人。）","《草房子》《城南旧事》都是好书。","春天，桃花开了；夏天，荷花开了；秋天，菊花开了。","错：因为下雨了；所以比赛取消了。（应改为：因为下雨了，所以比赛取消了。）","如果明天晴天，我们就去爬山；如果明天下雨，我们就在家看书。"],"深讲":"挨着的两个数字表示大概的数目，不用顿号：三四个人。并列的词已经有“和、或”连着，不再用顿号。带书名号或引号的并列词之间，通常不用顿号：《草房子》《城南旧事》都是好书。春天，桃花开了；夏天，荷花开了；秋天，菊花开了。每个分句里面已经有了逗号，分句之间再用逗号就分不清层次，所以用分号。因为下雨了；所以比赛取消了。——只有两个短分句的因果复句，用逗号就够了。分号主要用在并列分句之间，或者长复句的第一层。想一想：下面这句为什么在中间用分号？如果明天晴天，我们就去爬山；如果明天下雨，我们就在家看书。两个假设复句并列在一起，每个里面已经有逗号。分号标出了全句的第一层：两大块并列。国家标准还规定：非并列的多重复句，第一层（如转折、选择）也可以用分号。（出处：GB/T 15834—2011《标点符号用法》4.5 顿号（4.5.3.4、4.5.3.5）、4.6 分号（4.6.3.1–4.6.3.3）；附录 B.1.4（顿号、逗号、分号的层次））","怎么认":["为什么“黄色”和“蓝色”中间没有顿号？","为什么中间用分号？"],"易错":"概数中间加顿号：✗三、四个。；“和”前面又加顿号：✗红色、黄色、和蓝色。；简单复句用分号：分号用于并列分句或多重复句第一层。","练习":[{"q":"改正“我买了三、四本书。”","options":["我买了三，四本书。","我买了三四本书。"],"answer":1,"解析":"相邻两个数字表示大概的数目，中间不加任何标点。","类":"回练"}],"例句解析":[{"句":"来了三、四个人。","析":"相邻两数字连用表示概数，通常不用顿号。（应改为：来了三四个人。）"},{"句":"因为下雨了；所以比赛取消了。","析":"简单的因果复句，分句间用逗号。（应改为：因为下雨了，所以比赛取消了。）"}],"前置知识":["并列复句","并列式"]},{"name":"破折号","讲解":"破折号标示注释或补充说明（是正文的一部分），也表示插入语、话题转换、声音延长、话语中断、总结上文等；占两个字的位置，中间不能断开。","类比":"他就是我们班的“小百科”——王明。破折号后面的话，解释前面说的“小百科”是谁。","例子":["他就是我们班的“小百科”——王明。","我的家乡——江南水乡，春天特别美。","今天天气真好。——对了，你的作业交了吗？","“呜——”火车开过来了。","“我想说的是——”他突然停住了。","我的家乡（浙江省的一个小镇）春天特别美。","错：我的家乡—江南水乡，春天特别美。（应改为：我的家乡——江南水乡，春天特别美。）","“叮咚——”门铃响了。"],"深讲":"解释说明：我的家乡——江南水乡，春天特别美。话题转换：今天天气真好。——对了，你的作业交了吗？声音延长：“呜——”火车开过来了。话语中断：“我想说的是——”他突然停住了。破折号引出的解释是正文的一部分，可以连着读出来。括号里的是注释，不是正文，朗读时可以不读。我的家乡——江南水乡，春天特别美。我的家乡（浙江省的一个小镇）春天特别美。破折号占两个字的位置，写成“——”，不能写成一短横“—”或者“-”。破折号不能拆开，一半在上一行、一半在下一行。想一想：“叮咚——”和“我的家乡——江南”，两个破折号意思一样吗？第一个是声音拉长，第二个是引出解释。破折号的意思要看上下文。国家标准列了它的十种用法：注释说明、插入语、总结或提示、话题转换、声音延长、话语中断、引出对话、事项列举、副标题前、标示作者出处。（出处：GB/T 15834—2011《标点符号用法》4.10 破折号（4.10.3.1–4.10.3.10）；5.1.4（占两个字位置、不能断开）；附录 B.1.7（破折号与括号的区别））","怎么认":["破折号后面的话在做什么？","两个破折号一样吗？"],"易错":"把破折号写成一短横或连接号。；破折号分处两行。；破折号的解释是正文的一部分；括号里的注释可不读。","练习":[{"q":"改正“他就是我的同桌-小林。”","options":["他就是我的同桌：小林。","他就是我的同桌——小林。"],"answer":1,"解析":"引出对前面词语的解释，用破折号，占两个字位置。","类":"回练"}],"例句解析":[{"句":"我的家乡—江南水乡，春天特别美。","析":"破折号占两个字位置，是“——”。（应改为：我的家乡——江南水乡，春天特别美。）"}]},{"name":"省略号","讲解":"省略号标示引文、列举的省略，或语意未尽、说话断断续续、沉默不语；形式是六个点，占两个字的位置；不和“等”“等等”同时用。","类比":"公园里开着桃花、杏花、梨花……六个小点像在说：还有很多，不一一说了。","例子":["公园里开着桃花、杏花、梨花……","“我……我不是故意的。”","“作业写完了吗？”“……”","错：我买了笔、本子、橡皮……等文具。（应改为：我买了笔、本子、橡皮等文具。）","……（六个点，占两格）","我喜欢吃苹果、香蕉……","“我……我不知道。”"],"深讲":"列举省略：桃花、杏花、梨花……说话断断续续：我……我不是故意的。沉默不语：“作业写完了吗？”“……”我买了笔、本子、橡皮……等文具。——省略号和“等”说的是同一件事，重复了。二选一：我买了笔、本子、橡皮等文具。要读出来的地方，用“等”。省略号是六个点，占两个字的位置，不能拆到两行。省略整段诗文时，可以连用两个省略号，也就是十二个点，单独占一行；不能再多。想一想：“苹果、香蕉……”和“我……我不知道”，六个点意思一样吗？第一个省掉的是没列完的东西；第二个省掉的是说话时的停顿，表示紧张、犹豫。国家标准列出省略号的七种用法；另有一条补充规则：省略号和“等”“等等”“什么的”不能同时使用。（出处：GB/T 15834—2011《标点符号用法》4.11 省略号（4.11.3.1–4.11.3.7）；5.1.5（占两个字位置）；附录 A.9.1、A.9.2）","怎么认":["六个点代表什么？","两个省略号意思一样吗？"],"易错":"省略号和“等”同时用。；写成三个点或九个点：省略号是六个点。；省略号不能拆到两行。","练习":[{"q":"改正“我们班有足球队、合唱队、美术组……等兴趣小组。”","options":["我们班有足球队、合唱队、美术组等兴趣小组。","我们班有足球队、合唱队、美术组……等等兴趣小组。"],"answer":0,"解析":"省略号和“等”“等等”不能同时用，留一个。","类":"回练"}],"例句解析":[{"句":"我买了笔、本子、橡皮……等文具。","析":"省略号和“等”“等等”不能同时使用。（应改为：我买了笔、本子、橡皮等文具。）"}]}]}],"module":"语法知识库","标准":"《义务教育语文课程标准》附录三·语法修辞知识要点","说明":"覆盖词类、短语、单句成分、复句、修辞、病句六大块，为中考语文基础知识与作文语言服务"},"logic":{"categories":[{"id":"gainian","name":"形式逻辑基础","items":[{"name":"概念：定义与划分","lv":1,"讨论卡":{"问题":"给家里一件东西下个定义，再按一个标准把它分一分，你会怎么分？","提示":"定义回答“这是什么”，要抓住这个东西跟同类不一样的地方（种差），再说出它属于哪个大类（属）。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">白马不是马</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">白马≠马，混淆层次</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">定义不能循环</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">好定义</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"人是能制造工具的动物\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">坏定义</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"人是两条腿的动物\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">好划分</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"学生\\\"按年级分为一年级/二年级/三年级</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">坏划分</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"水果\\\"按颜色分红的、按大小分大的</text></g></svg>","目标":"今天学会给概念下定义、给大类做划分。","类比":"概念就像抽屉标签：定义是写清标签上是什么，划分是把大抽屉分成小格。","讲解":"定义揭示内涵（是什么），划分揭示外延（有哪些）。定义=种差+属概念。","口诀":"定义讲内涵，划分列外延","例子":["白马不是马：白马（种）≠马（属），混淆层次","定义不能循环","好定义：\"人是能制造工具的动物\"（种差\"能制造工具\"+属\"动物\"）","坏定义：\"人是两条腿的动物\"（鸡也是，种差不唯一）","好划分：\"学生\"按年级分为一年级/二年级/三年级（标准统一）","坏划分：\"水果\"按颜色分红的、按大小分大的（标准不一）","比喻不是定义：\"老师是辛勤的园丁\"很美，但不是定义","好定义：\"椅子是供人坐的家具\"（属\"家具\"＋种差\"供人坐\"，一听就知道是什么）","坏定义：\"西瓜是夏天吃的东西\"（只讲了季节，没讲出西瓜本身的样子和特点）","坏划分：\"把同学分成男生和戴眼镜的\"（标准交叉：戴眼镜的男生两边都算，子项不互斥）","坏划分：我爱读外国文学，尤其爱读俄罗斯的、拉美的、古典的（“俄罗斯的、拉美的”按地区分，“古典的”按年代分，标准混用；出处：统编高中语文选择性必修上册第四单元任务2）","错：农场决心提高粮食、棉花和经济作物的产量（棉花属于经济作物，大类和小类不能并列；出处：百度百科「病句」）","好划分：三角形按角分为锐角三角形、直角三角形、钝角三角形（一个标准，不重不漏）","定义太宽：“正方形是四条边的图形”（梯形也是四条边；出处：思方网《定义理论》）","定义太窄：“家人就是爸爸妈妈”（爷爷奶奶、兄弟姐妹也是家人，界定得太窄）","郑县人得车轭：捡到一个，人说“此车轭也”；又捡到一个，人还说“车轭”，他大怒“此女欺我也”（不懂一个名称能指一整类东西；出处：《韩非子·外储说左上》）"],"深讲":"新同学问你：“什么是文具？”你说“就是铅笔”，他会以为橡皮不算；你说“就是学习用的东西”，他又问书包、台灯算不算。把一个词说清楚，原来不容易——这正是“定义”和“划分”要解决的事。\n\n定义回答“它是什么”：先找它属于哪个大家庭（属概念，也就是大类），再说出它和家里其他成员不一样的地方（种差，也就是独特之处）。“三角形是由三条线段围成的图形”：大类是“图形”，独特之处是“三条线段围成”。划分回答“它有哪些”：拿同一把尺子（一个标准）把大类一次切开，切出的小格子不重叠、不遗漏。三角形按角分成锐角、直角、钝角三角形，就一个不多、一个不少。\n\n常见的坑有几种。定义太宽：“正方形是四条边的图形”，长方形、梯形也能挤进来；定义太窄：“家人就是爸爸妈妈”，爷爷奶奶被漏掉了；循环定义：“学生就是学生”，等于没说；拿比喻当定义：“老师是辛勤的园丁”很美，却不是定义。划分的坑是标准混用（“红的、大的”）和大类小类并排（“粮食、棉花和经济作物”，棉花本来就属于经济作物）。《韩非子》里还有个郑县人，捡到一个车轭，别人告诉他叫“车轭”；又捡到一个，别人还说“车轭”，他气得说人家骗他——他不懂一个词可以指一整类东西。\n\n写作文时，先给题目里的关键词下个定义，比如“什么是勇敢”，范围清楚了就不容易跑题；列举时先想好按什么标准分，再检查有没有重叠。和人争论前先问一句“你说的××是什么意思”，很多争吵当场就停了。","怎么认":["先找属：这个东西属于哪个大类？","再找种差：它跟同类比，特别在哪里？","检查划分：是不是一个标准分到底？小类有没有重叠或漏掉？"],"辨析":"定义和划分别混：定义是给一个概念“画像”（内涵），划分是给一个大类“分家”（外延）。“人是能制造工具的动物”是定义；“动物分为哺乳动物、鸟类、鱼类……”是划分。","例句解析":[{"句":"白马不是马：白马（种）≠马（属），混淆层次","析":"“白马”是“马”下面的一个小类，把小类和大类画等号，就像说“苹果不是水果”一样，层次搞混了。"},{"句":"好划分：\"学生\"按年级分为一年级/二年级/三年级（标准统一）","析":"一个标准（年级）一次分完，每个学生只属于一个年级，不重叠、不遗漏，这就是合格的划分。"},{"句":"坏划分：我爱读外国文学，尤其爱读俄罗斯的、拉美的、古典的","析":"“俄罗斯的”“拉美的”是按地区分，“古典的”是按年代分，两把尺子混着用。一本俄罗斯古典小说两边都算，小类就重叠了。改成“尤其爱读俄罗斯和拉美的作品”，只用一把尺子。"},{"句":"定义太宽：“正方形是四条边的图形”","析":"大类“图形”找对了，可独特之处“四条边”太宽，长方形、梯形都能挤进来。补上“四条边相等、四个角都是直角”，就只剩正方形了。检查定义的好办法：想一个反例，能挤进来就说明太宽。"},{"句":"郑县人得车轭：“曩者曰车轭，今又曰车轭，是何众也？此女欺我也！”","析":"“车轭”是能指一整类东西的词（普遍概念），就像每支铅笔都叫“铅笔”。郑县人以为一个名字只能配一个东西，所以第二次听到同样的名字就以为被骗，闹了笑话。"}],"易错":"划分标准要统一，不能一会儿按颜色一会儿按大小","练习":[{"q":"给“钢笔”下定义，哪个最好？","options":["钢笔是笔","钢笔是用来写字的笔","钢笔是学生用的东西"],"answer":1,"解析":"属（笔）＋种差（用来写字）。A只有属没种差，C种差不唯一（学生用的东西太多了）。"},{"q":"“把水果按颜色分为红的、大的”错在哪里？","options":["标准不统一","颜色分错了","水果不能分"],"answer":0,"解析":"一会儿按颜色一会儿按大小，两个标准混在一起，小类会重叠。"},{"q":"下面哪个是划分？","options":["椅子是供人坐的家具","动物分为哺乳动物和鸟类","西瓜是夏天吃的东西"],"answer":1,"解析":"“分为……”是把大类分小类；另外两个都是在给单个概念下定义（一个好一个坏）。"},{"q":"“家具分为桌子、椅子和木头家具”这个划分错在哪？","options":["桌子不是家具","标准不统一：前两个按用途分，“木头家具”按材料分","分得太少了"],"answer":1,"解析":"桌子、椅子是按用途分，“木头家具”是按材料分，木头桌子两边都算，小类重叠了。"},{"q":"下面哪个定义“太宽”了？","options":["三角形是由三条线段围成的图形","鸟是有羽毛的动物","鱼是生活在水里的动物"],"answer":2,"解析":"鲸、海豚、乌龟也生活在水里，却不是鱼，“生活在水里”这个独特之处框得太大了。"},{"q":"郑县人捡到第二个车轭，别人仍说是“车轭”，他却以为被骗。这个故事说明概念的什么特点？","options":["一个概念可以指一整类东西","一个名称只能配一个东西","名称可以随便起"],"answer":0,"解析":"“车轭”指的是一整类东西，每一个车轭都叫车轭；郑县人的误会恰恰是以为一个名称只能配一个东西。"}],"动画":{"steps":[{"tokens":["属概念","＋","种差","＝","定义"],"note":"定义公式：先找大类（属），再说出区别（种差）"},{"tokens":["人","是","会制造工具的","动物"],"note":"动物（属）＋会制造工具（种差）＝人"},{"tokens":["✗","人","是","人类的一员"],"note":"错：循环定义，用\"人类\"解释\"人\"等于没说"}]},"小测":[{"q":"给\"学生\"下定义，哪个对？","options":["学生是上学的人","学生是在学校学习的人","学生是学生"],"answer":1,"解析":"属（人）＋种差（在学校学习）。A太宽，C循环。"}],"前置知识":[],"来源":["统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83","香港大学 思方网 H06《定义理论》（类差定义、过宽过狭）https://philosophy.hku.hk/think/chi/def.php","统编选必上《逻辑的力量》第1课时教学设计（概念关系、四大规律、六种常见逻辑错误）http://www.yinruiwen.net/news/194567.htm","百度百科「病句」·不合逻辑类（自相矛盾、概念并列不当、强加因果、主客颠倒）https://baike.baidu.com/item/%E7%97%85%E5%8F%A5/689579","《韩非子·外储说左上》原文（郑县人得车轭、郑人买履）https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E5%A4%96%E5%84%B2%E8%AA%AA%E5%B7%A6%E4%B8%8A"]},{"name":"三段论","lv":3,"讨论卡":{"问题":"家里人说“所有鸟都会飞”，你怎么用企鹅这个例子跟他聊一聊？","提示":"关键是中间那个词（中项）要在两句话里真正搭上桥，而且前提本身要是真的。"},"目标":"今天学会用三段论推出结论：大前提加小前提，得出结论。","类比":"三段论就像接力赛：大前提交棒给小前提，推出结论。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">大前提：凡人皆有死</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大范围的真理</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">小前提：苏格拉底是人</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">具体归属</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">结论：苏格拉底有死</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">必然推出</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">三段论=接力赛：大前提交棒给小前提<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","讲解":"大前提（一般）+小前提（个别）→结论。","口诀":"大套小，推出结论跑不了","例子":["凡人皆有死，苏格拉底是人，所以苏格拉底有死","大前提：所有金属都导电；小前提：铜是金属；结论：铜导电","大前提：鲸是哺乳动物；小前提：哺乳动物用肺呼吸；结论：鲸用肺呼吸","错例：鸟会飞，企鹅是鸟，所以企鹅会飞（大前提\"鸟会飞\"不真）","错例：人是动物，狗是动物，所以人是狗（中项\"动物\"不周延）","有效式：下雨地就湿；下雨了→所以地湿了（肯定前件）","大前提：鸟类都用肺呼吸；小前提：鸽子是鸟类；结论：鸽子用肺呼吸","大前提：植物都需要阳光；小前提：阳台上的绿萝是植物；结论：绿萝需要阳光","错例：下雨地就湿；地湿了→所以下雨了（错：洒水车洒水也会湿，肯定后件推不出前件）","大前提：所有偶数都能被2整除；小前提：14是偶数；结论：14能被2整除","晏子使楚：大前提“从狗门进的，是出使狗国的人”；小前提（省略）“我出使的楚国不是狗国”；结论“我不该从狗门进”（出处：《晏子春秋》，统编教材《晏子使楚》）","错例：十五贯案——“杀死尤葫芦的罪犯有十五贯钱，熊友兰有十五贯钱，所以熊友兰是罪犯”（中项“有十五贯钱的人”两次都没说到全体，不周延；出处：昆剧《十五贯》，统编高中选择性必修上册第四单元）","错例：鲁迅的作品不是一天能读完的，《孔乙己》是鲁迅的作品，所以《孔乙己》不是一天能读完的（“鲁迅的作品”前指全部、后指一篇，出现了四个概念；出处：同上任务1）","错例：所有金属都能被磁铁吸住，铝是金属，所以铝能被磁铁吸住（形式对，但大前提不真：铝、铜不能被磁铁吸住）","否定式：所有鱼都用鳃呼吸，鲸不用鳃呼吸，所以鲸不是鱼（一个前提否定，结论也否定，推理有效）"],"深讲":"晏子出使楚国，楚人嫌他个子矮，在大门旁开了个小门让他钻。晏子说：“出使狗国的人，才从狗门进。今天我出使楚国，不该从这个门进。”楚人只好请他走大门。晏子用的就是三段论，还故意省掉一句“楚国不是狗国”，让楚人自己去补——补上了，就不能再让他钻狗门。\n\n三段论由三句话组成：大前提讲一类东西的共同规律（所有金属都导电），小前提说某个东西属于这一类（铜是金属），结论把规律交到它身上（铜导电）。三句话里只出现三个词：结论的主角“铜”（小项），结论说它怎样“导电”（大项），还有只在前提里出现、负责搭桥的“金属”（中项）。分清大小前提有个诀窍：含有结论后半截那个词（大项）的，是大前提。只要前提都真、桥搭牢了，结论就一定真。\n\n常见的坑有三种。一是前提不真：“所有金属都能被磁铁吸住”，铝和铜就不能，结论自然错。二是桥没搭上：古戏《十五贯》里，县官过于执推理“凶手有十五贯钱，熊友兰有十五贯钱，所以熊友兰是凶手”。有十五贯钱的人多着呢，“有十五贯钱的人”这个中项两次都没说到全体（叫“不周延”），两人可能根本不在同一个小圈里，于是错判了冤案。三是偷换中项：“鲁迅的作品不是一天能读完的，《孔乙己》是鲁迅的作品”，前一个“作品”指全部作品，后一个只指一篇，三个词悄悄变成了四个。\n\n写议论文时，你的论证常常是省掉大前提的三段论：“他每天坚持练字，所以字越写越好”，背后藏着“坚持练习能让本领进步”。写完问问自己：藏起来的那句大前提，读者会认同吗？听别人推理时，也试着把三句话补全，看哪一句站不住。","怎么认":["先找结论：它要证明什么？","再找大前提（一般道理）和小前提（个别情况）。","检查两点：前提是不是真的？中间词有没有真正搭上桥？"],"辨析":"三段论和“因为……所以……”不完全一样：日常的因为所以常常只说一个理由；三段论必须有两个前提，一个讲一般、一个讲个别，结论是被“推”出来的，不是直接喊出来的。","例句解析":[{"句":"大前提：所有金属都导电；小前提：铜是金属；结论：铜导电","析":"“金属”是中项，在大前提里讲所有金属，在小前提里把铜放进金属，桥搭上了，结论站得住。"},{"句":"错例：人是动物，狗是动物，所以人是狗（中项\"动物\"不周延）","析":"“动物”这个词两头都没说全——人只是动物中的一小部分，狗也是另一小部分，两小部分不能因为同属动物就画等号。"},{"句":"错例：十五贯案——“罪犯有十五贯钱，熊友兰有十五贯钱，所以熊友兰是罪犯”","析":"画两个圈来看：罪犯在“有十五贯钱的人”这个大圈里，熊友兰也在这个大圈里，可大圈里的人很多，两人可能各站一角，根本不重合。中项两次都只说到一部分人，桥只搭了一半，结论就推不出来。要破案，得找只有罪犯才有的特征。"},{"句":"晏子使楚：“使狗国者，从狗门入。今臣使楚，不当从此门入。”","析":"补全后是：从狗门进的，都是出使狗国的人（大前提）；我出使的楚国不是狗国（小前提）；所以我不该从狗门进（结论）。楚人如果坚持让他钻小门，就等于承认楚国是狗国——晏子把难题原样还给了对方。"},{"句":"错例：鲁迅的作品不是一天能读完的，《孔乙己》是鲁迅的作品……","析":"前一句的“鲁迅的作品”是全部作品合在一起，后一句的“鲁迅的作品”是其中一篇。同一个词说了两个意思，三段论里就多出了第四个概念，桥断了，结论也就错了（《孔乙己》很短，一天当然读得完）。"}],"易错":"两个坑最常见：一是前提本身不真（“鸟都会飞”），结论就不可靠；二是中项两头都不周延（“人是动物，狗是动物”），两个小类不能硬凑成一对。","练习":[{"q":"“所有鸟都会飞，企鹅是鸟，所以企鹅会飞”问题出在哪？","options":["小前提错了","大前提不全真","结论推错了"],"answer":1,"解析":"企鹅、鸵鸟都不会飞，“所有鸟都会飞”这个大前提本身不真，结论就靠不住。"},{"q":"补全三段论：大前提：植物都需要水；小前提：仙人掌是植物；结论是？","options":["仙人掌不需要水","仙人掌需要水","所有植物都是仙人掌"],"answer":1,"解析":"把小前提套进大前提：仙人掌属于植物，所以也需要水。"},{"q":"“下雨地就湿；地湿了，所以下雨了”错在哪里？","options":["前提错了","肯定了后件，推不出前件","结论太长"],"answer":1,"解析":"地湿的原因很多（洒水、拖地），从“地湿”不能倒推出“下雨”，这是肯定后件的毛病。"},{"q":"“所有金属都能被磁铁吸住，铝是金属，所以铝能被磁铁吸住。”结论错了，原因是？","options":["小前提错了，铝不是金属","大前提不真，并非所有金属都能被磁铁吸住","推理形式错了"],"answer":1,"解析":"铝确实是金属，形式也没错；毛病出在大前提——只有铁、钴、镍等少数金属能被磁铁吸住。"},{"q":"“所有植物都需要水，绿萝是植物，所以绿萝需要水。”哪个词是中项？","options":["绿萝","需要水","植物"],"answer":2,"解析":"“植物”只出现在两个前提里，负责把“绿萝”和“需要水”连起来，它就是中项。"},{"q":"《十五贯》里过于执推理“罪犯有十五贯钱，熊友兰有十五贯钱，所以熊友兰是罪犯”，错在哪？","options":["中项“有十五贯钱的人”两次都没说到全体，桥没搭上","大前提不真","熊友兰其实没有十五贯钱"],"answer":0,"解析":"教材说过于执掌握的线索都是准确的，错在推理形式：有十五贯钱的人很多，两句话说的未必是同一群人。"}],"动画":{"steps":[{"tokens":["所有","人","都会","死"],"note":"大前提：一般道理"},{"tokens":["苏格拉底","是","人"],"note":"小前提：个别情况"},{"tokens":["所以","苏格拉底","会","死"],"note":"结论：水到渠成"}]},"小测":[{"q":"三段论哪项错了？大前提：鸟会飞。小前提：企鹅是鸟。结论：企鹅会飞","options":["大前提错了","小前提错了","推理错了"],"answer":0,"解析":"大前提\"鸟会飞\"不全真（鸵鸟企鹅不会），前提错结论就不可靠。"}],"前置知识":["概念：定义与划分"],"来源":["统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83","统编选必上《逻辑的力量》第4课时教学设计（晏子使楚、十五贯、邹忌）http://www.yinruiwen.net/news/194572.htm","香港大学 思方网 H29《三段论与范氏图》https://philosophy.hku.hk/think/chi/venn2.php","统编选必上《逻辑的力量》第2课时教学设计（教材任务1逐条分析）http://www.yinruiwen.net/news/194568.htm"]},{"name":"四大逻辑规律","lv":3,"讨论卡":{"问题":"和家人聊一聊：你们说的“勇敢”，前后是不是同一个意思？","提示":"同一律（概念确定）、矛盾律（不自相矛盾）、排中律（非此即彼）、充足理由律（言之有据）。"},"目标":"今天认识四大逻辑规律：同一律、矛盾律、排中律、充足理由律。","类比":"四律就像思维交通规则：违反就撞车（自相矛盾）。","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">同一律</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前后说的一个意思</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">矛盾律</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">不能自相矛盾</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">排中律</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">非此即彼，必有一真</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">充足理由律</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">断言要有证据</text></g><text x=\"320\" y=\"280\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">四律=思维交通规则：违反就撞车<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"3.3s\" fill=\"freeze\"/></text></svg>","讲解":"同一律（概念确定）、矛盾律（不自相矛盾）、排中律（非此即彼）、充足理由律（言之有据）。","口诀":"同一矛盾排中足，思维守法不糊涂","动画":{"steps":[{"tokens":["这杯","咖啡","不能","一会儿变茶"],"note":"同一律：概念要确定，前后一致"},{"tokens":["今天","下雨了","＋","没下雨","＝","✗"],"note":"矛盾律：不能自相矛盾"},{"tokens":["灯","开","或","关"],"note":"排中律：非此即彼，不许骑墙"},{"tokens":["猫聪明","因为","会开门"],"note":"充足理由律：说观点要给理由"}]},"例子":["同一律：讨论\"成功\"时，前后必须指同一个意思，不能一会儿说成绩一会儿说快乐","矛盾律：不能同时说\"这本书我看过\"又说\"这本书我没看过\"（同一意义上）","排中律：\"小明及格了\"和\"小明没及格\"，必有一真（非此即彼）","充足理由律：说\"他作弊了\"要有证据，不能空口断言","违反排中律：\"这次考试要么第一要么倒数第一\"（还有中间名次）","违反同一律：辩论时把\"自由\"一会儿讲成\"为所欲为\"，一会儿讲成\"自律\"","同一律：写作文说\"我的妈妈\"，全文都要指同一个人，不能写着写着变成奶奶","充足理由律：说\"我们班最干净\"，要拿出证据：地面没纸屑、桌椅排整齐","违反充足理由律：\"他肯定偷懒了\"——没有证据，只是\"我觉得\"，这就是缺理由","排中律：\"今天是星期一\"和\"今天不是星期一\"，必有一真","违反排中律（两不可）：有人说《红楼梦》值得读，有人说不值得，两种意见我都不赞成（出处：统编高中语文选择性必修上册第四单元任务1）","排中律用错地方：不薄之谓厚，不白之谓黑（薄厚、黑白之间还有中间状态；出处：同上任务1）","违反同一律：刻舟求剑——“是吾剑之所从坠”，可“舟已行矣，而剑不行”，记号处早已不是落剑处（出处：《吕氏春秋·察今》）","违反同一律（转移话题）：老师问“你为什么没交作业”，回答“昨天的晚霞特别好看”","不违反矛盾律：有的人活着，他已经死了；有的人死了，他还活着（一个说肉体，一个说精神，不是同一方面；出处：臧克家《有的人》，教材单元导语引用）","违反充足理由律（推不出）：我一口气读完了这本书，所以你也一定能一口气读完（出处：统编选必上《逻辑的力量》教学设计练习）"],"深讲":"有人说《红楼梦》值得读，有人说不值得读。小林说：“两种意见我都不赞成：读吧，太花时间；不读吧，又有点可惜。”听上去很稳妥，其实他什么也没说——这是统编教材里的一个例子，毛病叫“两不可”。\n\n四大逻辑规律就像思维的四条交通规则。同一律：在同一段讨论里，一个词从头到尾保持一个意思，讨论的对象也不能偷偷换掉。矛盾律（也叫不矛盾律）：对同一件事、在同一个方面，不能既说“是”又说“不是”，两句互相否定的话不能都真。排中律：这两句话也不能都假，总得认一个，不能两头都不要。充足理由律：下一个判断要有理由，理由要真，理由和结论还要接得上。\n\n用这四条要小心几个误区。第一，排中律只管真正“非此即彼”的两句话。“不薄就是厚，不白就是黑”就用错了地方：薄和厚中间还有不厚不薄，白和黑中间还有灰。第二，矛盾律管的是“同一时间、同一方面”。“有的人活着，他已经死了”不算违反，诗人一个说肉体、一个说精神；“我以前怕黑，现在不怕了”也不矛盾，时间不同。第三，同一律不是不许一词多义，而是不许在同一段推理里偷换。刻舟求剑的楚人认定船上的记号就是“剑落下的地方”，可船已经走了，那个“地方”早就不是原来的地方。第四，“我觉得”“大家都这么说”不是充足的理由。\n\n写作文时，先给关键词下定义并全文守住（同一律）；写完检查前后观点有没有打架（矛盾律）；遇到正反两方，敢于表态（排中律）；每个观点后面问一句“凭什么”，补上事实或道理（充足理由律）。辩论时抓住对方偷换概念、自相矛盾、两不可，往往最有力。","怎么认":["先问：同一个词前后意思变了吗？（同一律）","再问：有没有自己打自己？（矛盾律）","是“非此即彼”吗？中间还有没有第三种？（排中律）","最后问：理由拿出来了吗？（充足理由律）"],"辨析":"矛盾律和排中律最容易混：矛盾律是“不能两个都真”（不能又下雨又没下雨）；排中律是“不能两个都假”（“及格”和“没及格”必有一真）。一个管“不能都真”，一个管“不能都假”。","例句解析":[{"句":"违反排中律：\"这次考试要么第一要么倒数第一\"（还有中间名次）","析":"第一和倒数第一不是“非此即彼”，中间还有第二名、第三名……硬说“要么这个要么那个”，就是排中律用错了地方。"},{"句":"充足理由律：说\"他作弊了\"要有证据，不能空口断言","析":"“作弊”是严重的判断，没有证据就说出口，等于没理由下结论——充足理由律要求每个判断都有根据。"},{"句":"违反排中律（两不可）：《红楼梦》值得读和不值得读，两种意见我都不赞成","析":"“值得读”和“不值得读”是一对互相否定的说法，必有一个是真的。两个都否定，等于没表态。可以说“值得读，但要挑时间读”，先选一边，再补条件。"},{"句":"排中律用错地方：不薄之谓厚，不白之谓黑","析":"“厚”和“薄”、“黑”和“白”之间还有中间状态，它们不是“非此即彼”的一对，可以两个都不是（不厚不薄、灰色）。把有中间地带的两样东西硬说成二选一，是排中律用错了地方。"},{"句":"不违反矛盾律：有的人活着，他已经死了","析":"矛盾律只管“同一方面”。“活着”说的是身体还在，“死了”说的是精神上已经没有价值，换了角度，两句可以同时成立。这是文学里故意“表面违背逻辑”的写法。"}],"易错":"排中律只管“非此即彼”的两种情况：中间还有别的情况时不能硬套（“第一还是倒数第一”中间还有很多名次）；矛盾律管的是同一个意义上的自相矛盾，换了意思就不算（“我喜欢吃苹果”和“我不喜欢吃青苹果”不矛盾）。","练习":[{"q":"“讨论'勇敢'时，一会儿说敢举手，一会儿说敢打架”违反了哪条规律？","options":["矛盾律","同一律","排中律"],"answer":1,"解析":"同一个词“勇敢”前后意思偷偷换了，违反同一律。"},{"q":"“这盏灯既开着又没开着”违反了哪条规律？","options":["充足理由律","矛盾律","排中律"],"answer":1,"解析":"同一个意义上又肯定又否定，自己打自己，违反矛盾律。"},{"q":"“我觉得他跑得最快”作为判断缺什么？","options":["缺同一律","缺充足理由","缺排中律"],"answer":1,"解析":"“我觉得”不是理由，要拿出计时成绩或比赛名次，才算有充足理由。"},{"q":"“或者采纳他的意见，或者不采纳他的意见，我都不赞成。”违反了哪条规律？","options":["同一律","矛盾律","排中律"],"answer":2,"解析":"“采纳”和“不采纳”必有一个要选，两个都否定，就是两不可，违反排中律。"},{"q":"“为演好课本剧我可以赴汤蹈火，要不是雨下得太大我就赶去排练了。”违反了哪条规律？","options":["矛盾律","排中律","同一律"],"answer":0,"解析":"连“赴汤蹈火”都不怕，却被一场雨拦住了，前后说法不能同时成立，是自相矛盾，违反矛盾律（教材原例）。"},{"q":"下面哪一组话不能用排中律的“必有一真”？","options":["“小明及格了”和“小明没及格”","“这杯水是热的”和“这杯水是冷的”","“今天是星期一”和“今天不是星期一”"],"answer":1,"解析":"热和冷之间还有温的，两句话可以都假；另外两组是一句肯定一句否定，必有一真。"}],"前置知识":["概念：定义与划分"],"来源":["统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83","统编选必上《逻辑的力量》第1课时教学设计（概念关系、四大规律、六种常见逻辑错误）http://www.yinruiwen.net/news/194567.htm","统编选必上《逻辑的力量》第2课时教学设计（教材任务1逐条分析）http://www.yinruiwen.net/news/194568.htm","《吕氏春秋·察今》原文（刻舟求剑、引婴投江、尝一脟肉）https://www.guwendao.net/shiwenv_440a90e138ee.aspx"]},{"name":"推理三兄弟：演绎/归纳/类比","lv":1,"讨论卡":{"问题":"尝了十个苹果都甜，这箱苹果是不是一定甜？和家人说说你的理由。","提示":"十个苹果只是这箱的一部分，结论只能说“大概”，不能说“一定”——归纳的结论永远留有余地。"},"目标":"今天学会分清三种推理：演绎、归纳、类比。","类比":"演绎像\"漏斗\"（从大到小），归纳像\"堆塔\"（从小堆到大），类比如\"照镜子\"（看A像B）。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">演绎</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">漏斗：从大到小，人会死→苏格拉底会死</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">归纳</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">堆塔：从小到大，看一万只乌鸦都黑</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">类比</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">照镜子：地球有水→火星可能有</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">演绎必然，归纳或然，类比要看本质<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","讲解":"演绎：一般→个别（三段论）；归纳：个别→一般（看多了总结）；类比：A像B，B有某性→A也有。","口诀":"演绎漏斗归纳塔，类比照镜子","例子":["演绎：人会死→苏格拉底会死","归纳：乌鸦都是黑的（看了一万只）","类比：地球有水有生命→火星有水→可能有生命","演绎：三角形内角和180°→这个三角形内角和也是180°（数学证明）","归纳：尝了十个苹果都甜→这箱苹果大概是甜的（或然，非必然）","类比错例：蝙蝠会飞，鸟会飞→蝙蝠是鸟（表面像，本质不同）","演绎：直角三角形的两条直角边是3和4，斜边就是5（勾股定理套用）","归纳：班里十个同学都喜欢踢足球，大概全班很多同学喜欢踢足球（只是大概，不是必然）","类比：水管堵了水流不畅，血管堵了血液不畅→血管也要“疏通”（医生打比方）","归纳错例：昨天吃冰淇淋拉肚子，就说所有冰淇淋都不好（一次个例推全体，样本太小）","归纳：尝一脟肉，而知一镬之味（尝一块肉就知道一锅的味道；出处：《吕氏春秋·察今》）","归纳错例：守株待兔——见一只兔撞树桩而死，便“释其耒而守株，冀复得兔”（一次偶然当规律；出处：《韩非子·五蠹》）","类比错例：“此其父善游”，就要把婴儿扔进江里（父亲会游泳推不出孩子会游泳；出处：《吕氏春秋·察今》）","类比：新药先在老鼠、猴子身上试，有效才推想对人也可能有效（生理结构相似，是和结论相干的相似点；出处：思方网《类比论证》）","类比：邹忌由“妻私我、妾畏我、客有求于我，都说我比徐公美”，推出大王身边的人也会蒙蔽大王（出处：《邹忌讽齐王纳谏》，统编选必上第四单元任务）","演绎：袁滋断案——如果是县官调包，送到县衙的应是约六百斤真金，两人用竹扁担抬不动；事实上只有两人抬来，所以不是县官调包（出处：冯梦龙《智囊全集》，统编选必上第四单元）"],"深讲":"妈妈煮了一大锅汤，舀一小勺尝尝就说“咸了”。她没喝完整锅，凭什么知道？两千多年前的《吕氏春秋》就写过：“尝一脟肉，而知一镬之味。”尝一块肉，就知道一锅的味道。这里面藏着推理。\n\n推理三兄弟走的方向不同。老大演绎：从一般到个别，“所有金属都导电，铜是金属，所以铜导电”，只要前提真、形式对，结论一定真，像漏斗一样稳。老二归纳：从个别到一般，“尝了几勺都咸，这锅汤咸”，例子越多、越有代表性，结论越可信，可它永远只是“很可能”，新的发现随时能推翻它。老三类比：从这个到那个，新药先在老鼠、猴子身上试，有效了才推想对人可能也有效，因为它们的身体结构在相关方面相似，结论同样只是“可能”。\n\n三兄弟各有各的坑。归纳怕样本太少：守株待兔的农夫只见过一只兔子撞死在树桩上，就扔下农具天天守着，把一次偶然当成了规律。类比怕“像的地方不相干”：《吕氏春秋》里有人要把婴儿扔进江里，理由是“他父亲很会游泳”——父子长得像，可游泳是练出来的本领，和像不像父亲没关系。演绎也会出错：前提不真（“所有鸟都会飞”）或形式不对，“一定”就落空了。\n\n写议论文时，举一个例子只是归纳的开始，最好从不同方面举两三个，再用“由此可见”收住，少说“所有”“一定”。打比方讲道理时，要选本质上相像的：用“磨刀不误砍柴工”说预习，像在“先准备，后面更省力”，就站得住。最后用演绎把道理落到眼前：“坚持能带来进步，所以我也要坚持练琴。”","怎么认":["看方向：一般→个别是演绎，个别→一般是归纳。","看关系：A像B所以A可能像B那样，是类比。","看把握：说“一定”的是演绎，说“大概、可能”的是归纳或类比。"],"辨析":"归纳和类比都只能得“可能”，但路子不同：归纳是“见得多了，总结规律”（看了一万只乌鸦）；类比是“这个像那个，借来推一推”（地球像火星）。演绎最保险，但前提必须真。","例句解析":[{"句":"归纳：尝了十个苹果都甜→这箱苹果大概是甜的（或然，非必然）","析":"十个苹果只是这箱的一部分，结论只能说“大概”，不能说“一定”——归纳的结论永远留有余地。"},{"句":"类比错例：蝙蝠会飞，鸟会飞→蝙蝠是鸟（表面像，本质不同）","析":"会飞只是表面相似，蝙蝠是胎生哺乳动物，鸟是卵生——类比只看表面就会推错。"},{"句":"归纳错例：守株待兔——“因释其耒而守株，冀复得兔”","析":"农夫只看到一次兔子撞树，就归纳出“兔子会常来撞这棵树”。样本只有一个，又是碰巧发生的，结论当然靠不住。归纳要看得多、看得广，还要想想这件事是不是偶然。"},{"句":"类比错例：“此其父善游”，就要把婴儿扔进江里","析":"父子在长相等方面相似，可“会游泳”是靠练习得来的本领，和长得像不像没有关系。类比时要问：拿来比的相似点，真的和结论有关吗？（原文就反问：“其父虽善游，其子岂遽善游哉？”）"},{"句":"类比：邹忌由妻、妾、客都夸他美，推出大王也被身边人蒙蔽","析":"两边真正相似的地方是“身边的人有私心、有畏惧、有所求，就不说真话”，这和“受蒙蔽”直接相关，所以齐王听了信服。好的类比，像的正是和结论有关的那一点。"}],"易错":"归纳的\"枚举\"不完全会翻车（黑天鹅）；类比要本质像，不能表面像","练习":[{"q":"“所有矩形的对角线相等，这个图形是矩形，所以它的对角线相等”是什么推理？","options":["归纳","类比","演绎"],"answer":2,"解析":"从一般定理套到个别图形，是演绎（前提真结论必然真）。"},{"q":"“连续三天都下雨，明天大概也会下雨”是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从几天的个别情况推明天的一般情况，是归纳，结论只是“大概”。"},{"q":"“自行车胎破了跑不快，人的血管堵了也跑不快”这是在？","options":["演绎","归纳","类比"],"answer":2,"解析":"拿自行车和人作比较、借来推一推，是类比；要小心只看表面相似。"},{"q":"老师随机抽查了全班不同座位的十位同学，作业都写完了，于是推测全班大概都写完了。这是？","options":["演绎","归纳","类比"],"answer":1,"解析":"从十个个别同学推测全班，是归纳；抽查分散、随机，结论比较可信，但仍然只是“大概”。"},{"q":"守株待兔的农夫错在哪？","options":["演绎的形式写反了","只凭一次偶然就归纳出规律","类比找错了对象"],"answer":1,"解析":"兔子撞树只发生了一次，还是碰巧，农夫却当成会反复发生的规律。"},{"q":"“父亲会游泳，所以孩子也会游泳。”这个类比为什么不成立？","options":["父子长得不像","会游泳靠练习，和父子相像没有关系","游泳太难学了"],"answer":1,"解析":"类比要求相似点和结论有关；游泳本领不是靠“像父亲”得来的。"}],"小测":[{"q":"\"看到10只白天鹅，得出天鹅都是白的\"是什么推理？","options":["演绎","归纳","类比"],"answer":1,"解析":"从个别到一般，是归纳（不完全归纳，有风险）。"}],"前置知识":["概念：定义与划分"],"来源":["香港大学 思方网 H14《归纳推论》https://philosophy.hku.hk/think/chi/induction.php","香港大学 思方网 H16《类比论证》https://philosophy.hku.hk/think/chi/analogy.php","《吕氏春秋·察今》原文（刻舟求剑、引婴投江、尝一脟肉）https://www.guwendao.net/shiwenv_440a90e138ee.aspx","《韩非子·五蠹》原文（守株待兔）https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E4%BA%94%E8%A0%B9","统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83","统编选必上《逻辑的力量》第4课时教学设计（晏子使楚、十五贯、邹忌）http://www.yinruiwen.net/news/194572.htm"]},{"name":"命题与真假","lv":2,"目标":"今天学会分辨哪些话是命题（能说出是真还是假的话），哪些话不是。","类比":"命题像一道判断题：老师能在后面打✓或打✗。问句、命令句、半截话放进判断题里，老师就没法打勾打叉。","讲解":"能判断真假的陈述句叫命题（也叫判断）；问句、命令句、半截话没有真假，不是命题。","口诀":"能打勾叉是命题，问句命令不算数","例子":["“地球绕着太阳转。”——命题，真","“一个星期有八天。”——命题，假（假话也是命题，只是假命题）","“3＋5＝8。”——命题，真","“你吃早饭了吗？”——问句，没有真假，不是命题","“请把窗户关上！”——命令句，没有真假，不是命题","“教室后面的那张桌子”——半截话，没说出什么事，不是命题","“大洋最深处住着一种还没被人发现的鱼。”——命题：今天没人知道真假，但它本身要么真要么假","错例：“‘一个星期有八天’说错了，所以它不是命题。”（错：说错了是假命题，仍然是命题）","错例：“凡是带问号的都不是命题。”（错：反问句“这难道不是你的书吗？”其实在说“这是你的书”，能分真假）","错例：“我不知道真假的话就不是命题。”（错：有没有真假，和我们现在知不知道是两回事）"],"深讲":"逻辑学最先要问的就是“真还是假”。一句话如果在说世界是什么样子，就能拿去和事实对一对：对得上为真，对不上为假，这样的话叫命题。“鲸是哺乳动物”是真命题，“鲸是鱼”是假命题——假命题仍然是命题，就像判断题做错了，它也还是一道判断题。问句“你几岁？”、命令“快去写作业！”只是在问、在要求，没有描述什么，所以没有真假。还要注意：有真假，不等于我们已经知道真假。“大洋最深处有一种还没被发现的鱼”，今天没人能确定，但它本身要么真要么假，所以也是命题。以后学推理，我们搬来搬去的每一块“积木”都是命题。","怎么认":["先看它是不是一句完整的话，半截话直接排除。","再问：这句话在描述“事情是怎样的”吗？一般的问句、命令、请求不算；反问句要先还原成陈述句。","想象拿它去和事实对照：能说出“对”或“错”（哪怕现在还不知道答案），就是命题。"],"辨析":"命题和“推理”不一样：命题是一句话，只问它真还是假；推理是从几个命题推出一个新命题的过程，问的是推得对不对（有效还是无效）。命题和“句子”也不完全一样：“小明比小红高”和“小红比小明矮”是两个句子，说的却是同一个命题。","例句解析":[{"句":"“一个星期有八天。”","析":"它在描述一件事，拿去和日历一对就知道是错的。错了，所以是假命题——但它依然是命题。不是命题的，是那些根本没法对照的话。"},{"句":"“这难道不是你的书吗？”","析":"这是反问句，说话的人不是真在提问，而是在说“这是你的书”。还原成陈述句后能分真假，所以它表达了一个命题。普通的问句“这是你的书吗？”才没有真假。"},{"句":"“大洋最深处住着一种还没被人发现的鱼。”","析":"今天谁也没法确定，可世界上要么真有这种鱼，要么没有，这句话总有一个真假，只是我们暂时不知道。所以它是命题。"}],"易错":"三个坑：一是以为假话不是命题（假命题也是命题）；二是以为现在不知道真假的话不是命题；三是见到问号就排除，忘了反问句其实在陈述。","练习":[{"q":"下面哪一句是命题？","options":["你喜欢画画吗？","熊猫爱吃竹子。","快把作业交上来！"],"answer":1,"解析":"“熊猫爱吃竹子”在描述事实，能判断真假（是真的）。另外两句一句是问句、一句是命令，没有真假。"},{"q":"“企鹅会飞。”是不是命题？","options":["是，是真命题","是，是假命题","不是命题，因为它是错的"],"answer":1,"解析":"企鹅不会飞，所以这句话是假的；但能判断真假，它就是命题——是假命题。"},{"q":"“难道月亮自己会发光吗？”这句话……","options":["是普通问句，没有真假","是反问句，意思是“月亮自己不会发光”，可以判断真假","是命令句"],"answer":1,"解析":"反问句用问的样子表达肯定的意思。还原后是“月亮自己不会发光”，这是真命题。"}],"讨论卡":{"问题":"“这句话是假的。”——它到底是真还是假？和家人一起想一想，为什么越想越绕？","提示":"假设它是真的，那它说的“自己是假的”就成立，它就成了假的；假设它是假的，那它说对了，又成了真的。这叫“说谎者悖论”，哲学家争论了两千多年。它绕晕人，是因为这句话在说它自己。我们平时学的命题都在说别的事情。"},"前置知识":["概念：定义与划分"],"来源":["https://philosophy.hku.hk/think/chi/basic-logic.php","https://philosophy.hku.hk/think/chi/sl2.php","https://gmat.kmf.com/learn/cr/1/0/3366.html"]},{"name":"所有·有的·没有：全称与特称","lv":2,"目标":"今天学会分清“所有”“有的”“没有”这几种说法，尤其分清“不都是”和“都不是”。","类比":"像清点一盒彩笔：“都是新的”一支旧的也不能有；“有的是新的”找到一支新的就够；“都不是新的”一支新的也不能有；“不都是新的”只要找到一支旧的就够。","讲解":"全称命题（说到一类里的每一个）：所有S都是P、所有S都不是P；特称命题（说到至少一个）：有的S是P、有的S不是P。“不都是”＝“有的不是”；“都不是”＝“一个也不是”。","口诀":"“不都”是有的不，“都不”是全都不","例子":["全称肯定：所有三角形都有三条边。（真）","全称否定：所有正方形都不是圆形，也就是没有一个正方形是圆形。（真）","特称肯定：有的鸟会游泳，比如鸭子、企鹅。（真）","特称否定：有的鸟不会飞，比如鸵鸟。（真）","“我们组的同学不都戴眼镜”＝至少有一位同学不戴眼镜（也可能有人戴）。","“我们组的同学都不戴眼镜”＝一个戴眼镜的也没有。","要推翻“所有天鹅都是白的”，不用数遍天下的天鹅，找到一只黑天鹅就够了。","错例：听到“有的同学交了作业”，就认定“有的同学没交作业”。（错：逻辑里的“有的”是“至少有一个”，也可能全交了）","错例：把“水果不都是甜的”理解成“水果都不甜”。（错：柠檬是酸的，但西瓜是甜的）","错例：“并非所有同学都去了春游，所以所有同学都没去春游。”（错：只能推出“有的同学没去”）"],"深讲":"我们常给一大群东西下结论，这时“所有”“有的”“没有”这些小词（逻辑上叫量词）就决定了这句话说得有多宽。说“所有”的叫全称命题，一个例外就能推翻它：要推翻“所有天鹅都是白的”，找到一只黑天鹅就够。说“有的”的叫特称命题，逻辑里的“有的”只表示“至少有一个”，并不暗示“其余的不是”。最绕的是“不都是”和“都不是”：“不”在“都”前面，否定的是“都”，意思是“不全是”；“不”在“都”后面，就是每一个都被否定。再记住两对“死对头”（矛盾关系，必定一真一假）：“所有都是”对“有的不是”，“所有都不是”对“有的是”。","怎么认":["找量词：所有、凡是、每个、都（全称）；有的、有些、存在（特称）。","看是肯定（是）还是否定（不是）；遇到“不都”“都不”，看“不”在“都”的前面还是后面。","要否定一句话时，找它的“死对头”：所有都是↔有的不是；所有都不是↔有的是。"],"辨析":"和「以偏概全」比：以偏概全是拿“有的”的证据得出“所有”的结论（三个同学近视→全班近视），这是推理犯错；本专题先学把每句话本身说了多宽看清楚。和「三段论」比：三段论的大前提常是全称命题，量词一看错，整个三段论就会塌。","例句解析":[{"句":"我们组的同学不都戴眼镜。","析":"“不”在“都”前，否定的是“都”：不是全部都戴。至少有一位不戴，也可能有人戴。等于“有的同学不戴眼镜”。"},{"句":"我们组的同学都不戴眼镜。","析":"“不”在“都”后，每个人都被否定：一个戴眼镜的也没有。等于“没有一位同学戴眼镜”。比上一句的范围大得多。"},{"句":"错例：听到“有的同学交了作业”，就认定“有的同学没交作业”。","析":"逻辑里的“有的”只保证“至少一个交了”，没说别人怎样。也许全班都交了，所以推不出“有人没交”。"}],"易错":"两个坑：一是把“不都是”当成“都不是”，把“有一部分不”说成“全部不”；二是以为“有的是”就暗含“有的不是”。","练习":[{"q":"“这筐苹果不都是红的”意思是？","options":["这筐苹果一个红的也没有","这筐苹果至少有一个不是红的","这筐苹果全是红的"],"answer":1,"解析":"“不都”否定的是“都”：不全是红的，至少有一个不红，也可能有红的。"},{"q":"要证明“所有的鸟都会飞”是假的，最省事的办法是？","options":["数遍所有会飞的鸟","找到一只不会飞的鸟，比如鸵鸟","找到很多会飞的鸟"],"answer":1,"解析":"全称命题怕反例：一只不会飞的鸟就能推翻它。会飞的鸟找得再多也证明不了“所有”。"},{"q":"已知“有的同学参加了合唱团”是真的，能确定的是？","options":["有的同学没参加合唱团","所有同学都参加了合唱团","“所有同学都没参加合唱团”是假的"],"answer":2,"解析":"“有的是”和“所有都不是”是死对头，一真一假。前两项都可能真也可能假，没法确定。"}],"讨论卡":{"问题":"爸爸说“你的作业不都对”，妈妈说“你的作业都不对”。这两句话哪句更严重？各自至少要几道错题才说得通？","提示":"“不都对”只要有一道错就成立；“都不对”要每一道都错。一个字的位置一换，意思差了一大截。"},"前置知识":["概念：定义与划分","命题与真假"],"来源":["https://gmat.kmf.com/learn/cr/1/0/3366.html","https://gmat.kmf.com/learn/cr/1/0/3367.html","https://philosophy.hku.hk/think/chi/venn1.php"]},{"name":"且·或·非：联言、选言与负命题","lv":2,"目标":"今天学会看懂用“并且”“或者”“要么……要么……”“并非”连起来的话，知道它们什么时候真、什么时候假。","类比":"像几种电路：“且”是串联，两个开关都合上灯才亮；“或”是并联，合上一个就亮，都合上也亮；“要么……要么……”像跷跷板，只能一头在上；“并非”像把开关拨到反面。","讲解":"联言命题（p并且q）：两个都真才真；相容选言命题（p或者q）：至少一个真就真，可以都真；不相容选言命题（要么p要么q）：恰好一个真；负命题（并非p）：和p的真假正好相反。","口诀":"且要全真，或要一真，要么只一，并非翻身","例子":["联言：小明既会游泳，又会滑冰。（两样都会，这句话才真）","联言也会藏在“虽然……但是……”“不但……而且……”里：这本书虽然厚，但是很好看。","相容选言：这次没考好，或者因为粗心，或者因为没复习。（两个原因可能同时都有）","不相容选言：一个整数要么是奇数，要么是偶数。（只能是其中一种）","负命题：并非“小红今天迟到了”＝小红今天没迟到。","并非“小明既会游泳又会滑冰”＝小明不会游泳，或者不会滑冰（至少有一样不会）。","并非“周六去公园或者去图书馆”＝周六既不去公园，也不去图书馆。","错例：“他没考好，或者因为粗心，或者因为没复习；他确实粗心了，所以他一定复习了。”（错：相容的“或”，两个可以同时成立）","错例：把“并非他既高又胖”理解成“他既不高也不胖”。（错：只能说至少有一样不是）","错例：“你要么支持我，要么反对我。”（错：还可以保持中立，选项没列全，却硬说成只能二选一）"],"深讲":"很多句子是用小命题拼起来的，拼接用的小词决定整句话的真假。“并且”像串联电路，两盏灯都亮才算亮；“或者”像并联，亮一盏就行。麻烦在于中文的“或”有两种：一种是“至少一个，可以都有”（相容的），比如“没考好，或者因为粗心，或者因为没复习”，两个原因完全可能同时存在；另一种是“只能选一个”（不相容的），常说成“要么……要么……”。分辨方法就是问一句：这两件事能同时成立吗？对相容的“或”，排除一个可以肯定另一个，肯定一个却不能排除另一个。“并非”是把整句话翻个面：翻“且”变“或”，翻“或”变“且”。","怎么认":["找连接词：并且、既……又……、虽然……但是……（联言）；或者（相容选言）；要么……要么……（不相容选言）；并非、不是说……（负命题）。","遇到“或”，问一句：“这两件事能同时成立吗？”能，就是相容的；不能，就是不相容的。","遇到“并非”管着整句话时，整句翻面：且变或、或变且，每一小句都加上“不”。"],"辨析":"和「充分条件与必要条件」比：且·或·非只管几件事“同时有没有”，不分谁是谁的条件；“如果……就……”讲的是条件关系，有方向。和常见谬误里的「非黑即白」比：不相容选言只有在选项真的列全、而且只能选一个时才成立；把还有第三条路的事硬说成二选一，就是非黑即白。","例句解析":[{"句":"这次没考好，或者因为粗心，或者因为没复习。","析":"两个原因能同时存在，是相容选言。知道“不是因为粗心”，才能推出“是因为没复习”；知道“确实粗心了”，却推不出“一定复习了”。（前提是原因真的只有这两个）"},{"句":"并非“小明既会游泳又会滑冰”。","析":"否定“既……又……”，只说明两样没有都会：可能不会游泳，可能不会滑冰，也可能两样都不会。等于“小明不会游泳，或者不会滑冰”。"},{"句":"或者闭关，或者送去，或者等别人“送来”，或者自己去拿；不能闭关，不能送去，不能等别人“送来”，所以只有自己去拿。","析":"鲁迅《拿来主义》的思路（高中课本里会学到）：先列出所有可能，再一个个否定，剩下的就是结论。这叫排除法，用的就是选言推理。关键是选项要列全。"}],"易错":"两个坑：一是把相容的“或者”当成只能选一个，于是“肯定一个就排除另一个”；二是否定“既……又……”时否定过头，说成“两样都不”。","练习":[{"q":"“小红既会弹琴又会画画”什么时候是真的？","options":["只要会一样就行","两样都会","两样都不会"],"answer":1,"解析":"联言命题要每一部分都真才真：会弹琴和会画画缺一不可。"},{"q":"“周末我去图书馆或者去公园”为真（两个都去也算）。已知我没去图书馆，能推出？","options":["我去了公园","我没去公园","推不出"],"answer":0,"解析":"相容选言至少有一个为真。排除了图书馆，剩下的公园就一定去了。"},{"q":"“并非‘今天既刮风又下雨’”等于？","options":["今天既不刮风也不下雨","今天不刮风，或者不下雨","今天刮风但不下雨"],"answer":1,"解析":"否定“且”要变成“或”：至少有一样没发生。A否定过头了，C只是其中一种可能。"}],"讨论卡":{"问题":"服务员问：“您要米饭还是面条？”你说：“都要！”——服务员的“还是”是相容的还是不相容的？生活里还有哪些“或”，其实只能选一个？","提示":"问一句“两个能同时成立吗？”服务员这么问，通常默认只选一样（不相容）；“周末去公园或者图书馆”，两个都去往往也算数（相容）。把“可以都选”还是“只能选一”说清楚，能少很多误会。"},"前置知识":["命题与真假"],"来源":["https://philosophy.hku.hk/think/chi/sl2.php","https://gmat.kmf.com/learn/cr/1/0/3367.html","https://www.ixuehai.cn/html/1776.html"]},{"name":"充分条件与必要条件","lv":3,"目标":"今天学会分清“如果……就……”（充分条件）和“只有……才……”（必要条件），会用“有它一定行吗、没它一定不行吗”来检验。","类比":"充分条件像班规“考满分就发奖状”：考满分一定拿奖状，但拿奖状不一定靠满分（还有进步奖）。必要条件像台灯的电：没电一定不亮，有电却不一定亮（灯泡可能坏了）。","讲解":"如果p就q：p是q的充分条件——有p一定有q，没p不一定没q。只有p才q：p是q的必要条件——没p一定没q，有p不一定有q。","口诀":"如果就：有它准成；只有才：没它不成","例子":["充分：如果下雨，地面就会湿。（下雨足够让地湿；但地湿也可能是洒水车洒的）","充分：班规——如果考满分，就能得奖状。（得奖状也可能是因为进步大）","充分：如果一个数是4的倍数，那么它是2的倍数。","必要：只有通电，台灯才会亮。（没电一定不亮；有电也可能因为灯泡坏了不亮）","必要：只有有氧气，蜡烛才能燃烧。","换说法：“只要……就……”“一旦……就……”表示充分条件；“没有……就没有……”“除非……否则不……”表示必要条件。","同一件事两种说法：“如果是4的倍数，就是2的倍数”＝“只有是2的倍数，才是4的倍数”。","错例：“只有报了名，才能参加比赛。小东报了名，所以小东一定能参加比赛。”（错：把必要条件当成了充分条件）","错例：把“如果下雨，地就湿”理解成“只有下雨，地才湿”。（错：洒水、拖地也能让地湿）","充分必要（充要）：一个三角形三条边都相等，当且仅当它三个角都相等。"],"深讲":"生活里很多话在讲条件。“如果……就……”说的是充分条件：前一件事一出现，后一件事一定跟着来，好比“如果下雨，地就会湿”。但它没说“地湿只能因为下雨”，洒水车也能让地湿。“只有……才……”说的是必要条件：缺了前一件事，后一件事一定不会发生，好比“只有通电，台灯才会亮”。但它没说“通了电就一定亮”，灯泡坏了照样黑着。检验条件就问两句：“有了它，一定行吗？”是，它就充分；“没有它，一定不行吗？”是，它就必要。两句都答“是”，就是充分必要条件（简称充要条件）。最后记一个换装术：“如果p就q”等于“只有q才p”。","怎么认":["找关联词：如果／只要／一旦……就……（充分）；只有……才……、没有……就没有……、除非……否则不……（必要）。","问：“有了它，一定行吗？”一定行→它是充分条件。","问：“没有它，一定不行吗？”一定不行→它是必要条件；两个问题都答“是”→充要条件。"],"辨析":"和「假言推理四式」比：本专题学“认条件”——谁是谁的什么条件；四式学“用条件推理”——已知一句条件话和一个事实，能推出什么。和「强加因果」比：条件关系要求“一定”，强加因果是把没有必然联系的两件事硬说成有联系。","例句解析":[{"句":"只有通电，台灯才会亮。","析":"“通电”是“灯亮”的必要条件：没电一定不亮。可有电不一定亮，灯泡坏了、开关没开都不行。所以不能说“通电了，灯一定亮”。"},{"句":"如果一个数是4的倍数，那么它是2的倍数。","析":"“是4的倍数”是充分条件：只要是，就一定是2的倍数。反过来不行：6是2的倍数，却不是4的倍数。所以“是2的倍数”只是“是4的倍数”的必要条件。"},{"句":"错例：“只有报了名，才能参加比赛。小东报了名，所以小东一定能参加比赛。”","析":"报名只是必要条件：没报名一定不能参加；报了名，还可能因为生病、名额满了等原因参加不了。从“有必要条件”推不出“一定成功”。"}],"易错":"最常见的是把“只有……才……”当成“如果……就……”用，以为有了必要条件就一定成功；另一个是反过来，把充分条件当成唯一原因（“地湿了，一定下过雨”）。","练习":[{"q":"“只有认真审题，才能把应用题做对。”这句话说的是？","options":["认真审题了就一定做对","没认真审题一定做不对","做错了一定是因为没审题"],"answer":1,"解析":"“只有……才……”说的是必要条件：没有它一定不行。有了它不保证做对，做错也可能是算错了。"},{"q":"“如果一个图形是正方形，那么它的四条边相等。”下面哪句也一定对？","options":["四条边相等的图形一定是正方形","四条边不相等的图形一定不是正方形","不是正方形的图形，四条边一定不相等"],"answer":1,"解析":"没有后者（四边相等）就一定没有前者（正方形）。A、C都错：菱形四条边相等，却不是正方形。"},{"q":"“有氧气”对于“蜡烛燃烧”是什么条件？","options":["充分条件：有氧气蜡烛就一定燃烧","必要条件：没有氧气蜡烛一定不能燃烧","没有关系"],"answer":1,"解析":"没氧气一定烧不起来，所以是必要条件；但有氧气还得点火，所以不是充分条件。"}],"讨论卡":{"问题":"妈妈说：“只有写完作业，才能看动画片。”你写完了作业，妈妈就一定得让你看吗？先从字面上分析，再想想妈妈平时说这句话真正的意思。","提示":"从字面看，写完作业只是必要条件，不保证一定能看（比如已经到睡觉时间了）。不过生活里很多人说“只有……才……”时，心里也包含“写完了就可以”。遇到这种情况，最好的办法是把话问清楚——把话说准，正是逻辑的用处。"},"前置知识":["命题与真假","且·或·非：联言、选言与负命题"],"来源":["https://philosophy.hku.hk/think/chi/nsc.php","https://gmat.kmf.com/learn/cr/1/0/3367.html","https://www.ixuehai.cn/html/1776.html"]},{"name":"假言推理四式","lv":3,"目标":"今天学会用“如果p就q”做推理：肯定前件、否定后件是对的；否定前件、肯定后件是错的；还要记住“逆否命题”和原句等价。","类比":"“如果p就q”像一支单向箭头p→q。顺着箭头走（有p就有q），或者从箭头尖往回查（没有q，就没有p），都安全；逆着箭头从q推p，或者从“没有p”推“没有q”，都会掉坑。","讲解":"充分条件假言推理（如果p就q）：肯定前件→肯定后件✓；否定后件→否定前件✓；否定前件、肯定后件都推不出必然结论✗。“如果p就q”等价于它的逆否命题“如果非q就非p”。","口诀":"肯前否后都能推，否前肯后要吃亏","例子":["肯定前件✓：如果下雨，地就湿；下雨了，所以地湿了。","否定后件✓：如果下雨，地就湿；地没湿，所以没下雨。","错例（否定前件）：如果下雨，地就湿；没下雨，所以地不湿。（洒水车也能让地湿）","错例（肯定后件）：如果下雨，地就湿；地湿了，所以下雨了。（可能是洒水车洒的）","肯定前件✓：班规——如果考满分，就得奖状；小丽考了满分，所以小丽得奖状。","否定后件✓：小刚没得奖状，所以小刚没考满分。","错例（肯定后件）：小芳得了奖状，所以小芳考了满分。（可能是进步奖）","逆否等价：“如果下雨，地就湿”＝“如果地不湿，那么没下雨”。","不等价：“如果地湿，就下了雨”（逆命题）和“如果不下雨，地就不湿”（否命题）都不能代替原句。","侦探用法：如果是小猫打翻了牛奶，地上就会有小猫爪印；地上没有爪印，所以不是小猫打翻的。"],"深讲":"学会认条件，就能拿它推理了。“如果p就q”像一支朝一个方向射的箭。已知p成立，顺着箭头得到q，这叫肯定前件式；已知q不成立，p也不可能成立——要是p成立了，q早该出现了——这叫否定后件式，侦探最爱用。另外两条路走不通：已知q成立，不能倒推出p，因为q可能另有来源（肯定后件）；已知p不成立，也推不出q不成立，因为别的原因照样能带来q（否定前件）。数学课会讲到：原命题和它的逆否命题“如果非q就非p”同真同假，逆命题、否命题却不一定。注意：碰到“只有p才q”，先改写成“如果q就p”，再套这四式。","怎么认":["把条件句写成“如果p，就q”，圈出前件p、后件q（“只有p才q”先改写成“如果q，就p”）。","看另一个已知条件：是肯定了p、否定了q，还是否定了p、肯定了q？","肯定p得q、否定q得非p，放心推；否定p、肯定q，结论只是“可能”，不能说“一定”。"],"辨析":"和「充分条件与必要条件」比：那个专题学认条件，本专题学用条件推理。和「三段论」比：三段论的大前提是“所有M都是P”这类性质命题，假言推理的大前提是“如果p就q”这类条件句；“鸟都用肺呼吸”是三段论的材料，“如果下雨地就湿”是假言推理的材料。","例句解析":[{"句":"如果是小猫打翻了牛奶，地上就会有小猫爪印；地上没有爪印，所以不是小猫打翻的。","析":"否定后件式，有效：要是小猫打翻的，爪印一定在；现在爪印不在，小猫就被排除了。（前提是那句“如果……就……”本身是真的）"},{"句":"错例：小芳得了奖状，所以小芳考了满分。","析":"班规只说“考满分→得奖状”，没说“得奖状只能靠满分”。从后件“得奖状”倒推前件“考满分”，犯了肯定后件的错误，小芳可能拿的是进步奖。"},{"句":"袁滋断案（高中课本里的故事）：如果县官把金子换成了土，那么送到他那里的就该是真金，二百五十多块真金两个人用竹扁担抬不动；可事实上是两个人用竹扁担抬来的。","析":"这是否定后件式：后件“两个人抬不动”被事实否定了，所以前件“县官调包”也被否定，县官被冤枉了。"}],"易错":"最常见的是“倒着推”（肯定后件）：看到结果就认定是某个原因。还有把逆命题当成等价：“如果下雨地就湿”不等于“如果地湿就下过雨”。另外，形式有效只保证“前提真则结论真”，前提本身错了，结论照样靠不住。","练习":[{"q":"“如果是小猫打翻的，地上就有爪印。地上有爪印。”能推出？","options":["一定是小猫打翻的","可能是小猫打翻的，但不一定","一定不是小猫打翻的"],"answer":1,"解析":"这是肯定后件，推不出“一定”。爪印可能是小猫平时路过留下的。"},{"q":"下面哪个推理是有效的？","options":["如果下雨地就湿；地湿了，所以下雨了","如果下雨地就湿；没下雨，所以地不湿","如果下雨地就湿；地没湿，所以没下雨"],"answer":2,"解析":"C是否定后件式，有效。A是肯定后件，B是否定前件，都无效。"},{"q":"“如果考满分，就得奖状”的逆否命题是？","options":["如果得奖状，就考了满分","如果没考满分，就得不到奖状","如果没得奖状，就没考满分"],"answer":2,"解析":"逆否命题：把前后件对调，再都加上“不”。A是逆命题，B是否命题，都不和原句等价。"}],"讨论卡":{"问题":"“如果偷吃蛋糕的是小狗，沙发上就会有狗毛。”沙发上发现了狗毛，能断定是小狗偷吃的吗？要是没发现狗毛呢？","提示":"有狗毛是肯定后件——小狗平时也可能在沙发上躺过，推不出；没有狗毛是否定后件——可以推出不是小狗（前提是那句“如果……就……”真的靠得住）。"},"决策树":"①把条件句写成“如果p，就q”（“只有p才q”先改写成“如果q，就p”）→②看另一个已知条件说的是哪一边→肯定了p：可以推出q（肯定前件式，有效）→否定了q：可以推出非p（否定后件式，有效）→肯定了q：推不出p（肯定后件，无效）→否定了p：推不出非q（否定前件，无效）→③最后再查一查：那句“如果……就……”本身是真的吗？","前置知识":["充分条件与必要条件","三段论"],"来源":["https://philosophy.hku.hk/think/chi/valid.php","https://gmat.kmf.com/learn/cr/1/0/3367.html","https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83"]},{"name":"好定义的规则","lv":2,"目标":"今天学会检查一个定义好不好：不太宽也不太窄、不绕圈子、一般不用否定、不用比喻。","类比":"定义像给一个词做身份证：照片要和本人一模一样（不太宽不太窄），不能写“我就是我”（绕圈子），不能只写“我不是你”（否定），也不能写“我是一朵花”（比喻）。","讲解":"好定义四条规则：①相称：定义说的范围和被定义的词一样大，不太宽、不太窄；②不循环：不能用被定义的词解释它自己；③一般用肯定的说法：只说“不是什么”说明不了“是什么”；④清楚确切：不用比喻和含糊的词。","口诀":"不宽不窄刚合适，不绕圈子不说“不是”，比喻再美不算数","例子":["好定义：正方形是四条边都相等、四个角都是直角的四边形。","好定义：偶数是能被2整除的整数。","错例：正方形是有四条边的图形。（太宽：长方形、梯形也有四条边）","太窄：家人就是爸爸和妈妈。（爷爷奶奶、兄弟姐妹也是家人，被关在了门外）","错例：近视就是眼睛近视。（同语反复：用“近视”解释“近视”，等于没说）","循环定义：老师就是教学生的人，学生就是跟老师学习的人。（两个词互相解释，绕回原地）","否定定义：白天就是不是夜晚的时候。（只说了不是什么，没说是什么）","错例：书是人类进步的阶梯。（是夸书的好句子，但这是比喻，不是定义）","比喻不能当定义：“眼睛是心灵的窗户”很美，却没说清眼睛是什么器官。","可以用否定的情况：“无脊椎动物是没有脊椎的动物”——这个词本身就是“没有……”的意思，用否定说才准确。"],"深讲":"下定义，就是用一句话把一个词的意思说准，让别人拿着这句话就能把它和别的东西分开。好定义像一件合身的衣服：太宽了（“正方形是有四条边的图形”），梯形也钻了进来；太窄了（“家人就是爸爸和妈妈”），爷爷奶奶被挡在门外。检查办法是两头找反例：有没有符合定义却不是它的？有没有是它却不符合定义的？其次不能绕圈子，“近视就是眼睛近视”等于没说。再次，一般不能只说“不是什么”，不过“无脊椎动物”这种本身带“无”的词，用否定说才准确。最后，比喻再生动也不是定义：“书是人类进步的阶梯”是夸书的好句子，却说不清书是什么。","怎么认":["两头找反例：有没有符合这句话、却不是它的？（有→太宽）有没有是它、却不符合这句话的？（有→太窄）","看解释里有没有又出现被解释的词，或者两个词互相解释。（有→同语反复或循环定义）","看是不是只说了“不是什么”，或者用了比喻、含糊的词。（是→否定定义或比喻代定义）"],"辨析":"和「概念：定义与划分」比：那个专题教怎么下定义（大类＋特点，也就是“属＋种差”）；本专题教怎么给定义挑毛病。和常见谬误里的「循环论证」比：循环定义是解释一个词时绕圈子；循环论证是证明一个观点时，拿这个观点自己当理由。","例句解析":[{"句":"正方形是有四条边的图形。","析":"找反例：长方形、梯形都有四条边，却不是正方形——定义太宽。要加上“四条边都相等、四个角都是直角”，把别的图形挡在外面。"},{"句":"老师就是教学生的人，学生就是跟老师学习的人。","析":"想懂“老师”，先要懂“学生”；想懂“学生”，又要先懂“老师”——转了一圈回到原地，这是循环定义。"},{"句":"书是人类进步的阶梯。","析":"这是比喻，说的是书的作用很大，并没有说清书到底是什么东西。写作文时用它很好，当定义就不行。"}],"易错":"两个坑：一是只查一头，查了太宽忘了太窄——一个定义可能又宽又窄，比如“鸟是会飞的动物”，蝙蝠混了进来（太宽），企鹅被关在外面（太窄）；二是以为所有否定说法都不行，其实本身带“无”“非”意思的词可以用否定来定义。","练习":[{"q":"“三角形是由线段组成的图形。”这个定义的问题是？","options":["太宽","太窄","用了比喻"],"answer":0,"解析":"四边形、五边形也由线段组成，符合这句话却不是三角形——定义太宽。"},{"q":"“交通工具就是在马路上跑的汽车。”这个定义的问题是？","options":["太宽","太窄","循环定义"],"answer":1,"解析":"船、飞机、火车都是交通工具，却不符合这句话——定义太窄。"},{"q":"下面哪个是好定义？","options":["近视就是眼睛近视","等边三角形是三条边都相等的三角形","老师是辛勤的园丁"],"answer":1,"解析":"B说出了大类（三角形）和特点（三条边相等），不宽不窄。里面的“三角形”是大类，被定义的是“等边三角形”，不算绕圈子。A是同语反复，C是比喻。"}],"讨论卡":{"问题":"和家人比赛给“椅子”下定义：一个人先说，另一个人找反例（有没有符合这句话却不是椅子的？有没有是椅子却不符合的？），看谁的定义最“合身”。","提示":"“有四条腿的东西”太宽（桌子、小狗都有四条腿），也太窄（转椅没有四条腿）。可以慢慢加条件，比如“有靠背、供人坐的家具”，再接着找反例——一步步修改，正是想清楚问题的办法。"},"决策树":"①找反例：有没有符合定义却不是它的？→有：定义过宽→②有没有是它却不符合定义的？→有：定义过窄→③定义里又出现被定义的词，或两个词互相解释？→是：同语反复或循环定义→④只说了“不是什么”？→是：否定定义（被定义的词本身带“无”“非”的除外）→⑤用了比喻或含糊的词？→是：比喻代定义或定义含混→都没有：这是个好定义","前置知识":["概念：定义与划分"],"来源":["https://philosophy.hku.hk/think/chi/def.php","https://docs.hanyu123.cn/B81-%E9%80%BB%E8%BE%91%E5%AD%A6/%E4%B8%8B%E5%AE%9A%E4%B9%89"]}]},{"id":"luojibing","name":"病句里的逻辑错误","items":[{"name":"自相矛盾","lv":1,"讨论卡":{"问题":"“他是众多死难者中幸免的一个”哪里打架了？和家人一起把前后两句拆开说说。","提示":"找它的方法是把前后分句拆开，问一句“这两句能同时成立吗”——不能，就是自相矛盾。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他是众多死难者中幸免的一个</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他是这次事故中幸免于难的一个</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">将近三十多人</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">对</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">将近三十人</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">会场上一片寂静，同学们都在大声讨论</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">会场上一片寂静，同学们都在认真听讲</text></g></svg>","目标":"今天学会认出自相矛盾：前后说法打架的句子。","讲解":"前后说法打架：他是众多死难者中幸免的一个（都死了还幸免？）。","口诀":"前后打架自己吵，改掉一个就好了","例子":["错：他是众多死难者中幸免的一个","对：他是这次事故中幸免于难的一个","错：将近三十多人（“将近”是不到三十，“多”是超过三十，自相矛盾）","对：将近三十人／三十多人","错：会场上一片寂静，同学们都在大声讨论","对：会场上一片寂静，同学们都在认真听讲","错：这道题我不会做，但我已经做出来了","对：这道题我一开始不会做，后来做出来了","错：操场上一个人也没有，只有小明在跑步","对：操场上只有小明在跑步","错：楚人鬻盾与矛，“吾楯之坚，物莫能陷也”“吾矛之利，于物无不陷也”（出处：《韩非子·难一》，成语“自相矛盾”的来历）","错：为演好课本剧我可以赴汤蹈火，要不是雨下得太大我就赶去排练了（出处：统编高中语文选择性必修上册第四单元任务2）","错：“这是拿破仑小时候的头骨”（一个人只有一个头骨，成年后去世的人不会留下“小时候的头骨”；出处：同上任务1）","错：我答应昨天来修门铃，可来了三次，每次按门铃都没人来开门（要修的正是坏门铃，按了不会响；出处：同上任务1）","错：凡是在科学研究上有成就的人，不少是在艰苦条件下成功的（“凡是”是全部，“不少”是一部分；出处：百度百科「病句」）","不算病句：有的人活着，他已经死了；有的人死了，他还活着（身体和精神两个角度；出处：臧克家《有的人》）"],"深讲":"楚国有个卖矛又卖盾的人，先夸盾：“我的盾坚固得什么都刺不穿。”又夸矛：“我的矛锋利得什么都能刺穿。”旁边有人问：“用你的矛刺你的盾，会怎么样？”他答不上来。韩非子评论说：“不可陷之楯与无不陷之矛，不可同世而立。”这就是成语“自相矛盾”的来历。\n\n自相矛盾，就是同一个人，在同一件事、同一个意思上，说了两句不能同时成立的话，违反的是矛盾律。病句里最常见的几种：意思打架，“他是众多死难者中幸免的一个”，死了又没死；数量打架，“将近三十多人”，不到三十又超过三十；范围打架，“凡是有成就的人，不少是靠勤奋成功的”，“凡是”是全部，“不少”只是一部分；状态打架，“会场一片寂静，大家都在大声讨论”。找它只要一招：把前后拆开，问“能同时为真吗”。\n\n也有几个误区。第一，看着矛盾的不一定是病句。臧克家写“有的人活着，他已经死了”，一个说身体、一个说精神；鲁迅写“大约孔乙己的确死了”，“大约”是没亲眼看见，“的确”是心里认定，都是有意的写法。第二，时间不同不算矛盾：“我以前不会游泳，现在会了”。第三，改病句别换汤不换药。把“死难者”换成“遇难者”，很多老师仍判为矛盾，因为词典里“遇难”就是“遭遇危难而死”；最稳妥的改法是“他是这次事故中幸免于难的一个”。\n\n写作文最容易在夸张时打架，比如“我从来不哭，那天却哭得稀里哗啦”。想写反差，就加上限制：“平时很少哭”。写完一段，圈出“全部、都、从来、只有、唯一、一个也没有”这些绝对的词，再看后文有没有例外来拆台。说话时被人指出矛盾，大方承认、改口说清楚，比硬撑更像讲道理的人。","怎么认":["把句子拆成前后两半。","每半各是什么意思？写下来比一比。","两半能不能同时是真的？不能，就是自相矛盾。"],"辨析":"自相矛盾和“前后不一致”不一样：前后不一致可能是话题跑偏了；自相矛盾是同一个点上自己否定自己，比如“都死了”又“幸免”，同一个“死”字两边打架。","例句解析":[{"句":"错：他是众多死难者中幸免的一个","析":"“死难者”就是已经死了的人，“幸免”是没死——同一个人既死了又没死，自己打自己。（“遇难者”也是在灾祸中死去的人，换成它照样矛盾。）改成“他是这次事故中幸免于难的一个”就通了。"},{"句":"错：将近三十多人（“将近”是不到三十，“多”是超过三十，自相矛盾）","析":"“将近三十”是还不到三十，“三十多”是已经超过三十——一个说不到，一个说超过，两个意思撞车，留一个就行：“将近三十人”或“三十多人”。注意：“大约三十多人”可以说，“三十多”本身就是一个大概的数。"},{"句":"错：“吾楯之坚，物莫能陷也”“吾矛之利，于物无不陷也”","析":"如果盾真的什么都刺不穿，那矛就不是什么都能刺穿；如果矛真的什么都能刺穿，那盾就不是什么都刺不穿。两句话至少有一句是假的，所以卖矛盾的人答不上来。"},{"句":"错：“这是拿破仑小时候的头骨”","析":"拿破仑是成年后去世的，他留下的头骨只能是成年人的。“拿破仑的头骨”和“小时候的头骨”不能同时成立，耍戏法的人越解释越露馅。"},{"句":"错：凡是在科学研究上有成就的人，不少是在艰苦条件下成功的","析":"“凡是”说的是全部，“不少”说的是一部分，范围前后打架。保留原意的改法是删掉“凡是”：“在科学研究上有成就的人，不少是在艰苦条件下成功的。”"}],"易错":"检查前后分句能否同时为真","练习":[{"q":"“将近五十多个同学参加了比赛”错在哪里？","options":["数字不对","“将近”和“多”自相矛盾","同学写错了"],"answer":1,"解析":"“将近五十”是不到五十，“五十多”是超过五十，两个意思打架，留一个：“将近五十个同学”或“五十多个同学”。"},{"q":"下面哪句自相矛盾？","options":["他是这次事故中幸免于难的一个","他是死难者中幸免的一个","他是幸存者中的一个"],"answer":1,"解析":"“死难者”已经死了，不可能“幸免”；另外两句都没有自己打自己。"},{"q":"“会场上一片寂静，同学们都在大声讨论”为什么错？","options":["会场写错了","“一片寂静”和“大声讨论”意思打架","同学们写错了"],"answer":1,"解析":"“一片寂静”是一点声音也没有，“大声讨论”却很吵——前后不能同时成立。"},{"q":"卖矛和盾的楚人为什么答不上来？","options":["他的矛其实不够锋利","“什么都刺不穿的盾”和“什么都能刺穿的矛”不能同时存在","围观的人太多了"],"answer":1,"解析":"两句夸口互相否定，不可能都真，一碰面就露馅（“不可同世而立”）。"},{"q":"下面哪句不是自相矛盾的病句？","options":["我从来不吃辣，昨天吃了一大碗辣面","我以前不会游泳，这个暑假学会了","操场上一个人也没有，只有小明在跑步"],"answer":1,"解析":"“以前不会”和“现在学会了”说的是不同时间，可以同时成立；另外两句前后打架。"},{"q":"“凡是参加比赛的同学，不少都获了奖。”怎样改最好？","options":["凡是参加比赛的同学，都获了奖","参加比赛的同学中，不少获了奖","凡是参加比赛的同学，不少也许获了奖"],"answer":1,"解析":"原意是“一部分人获奖”，删掉“凡是”即可；A改变了原意，C仍然“凡是”“不少”打架。"}],"动画":{"steps":[{"tokens":["众多","死难者","中"],"note":"死难者＝已经死了"},{"tokens":["幸免","的","一个"],"note":"幸免＝没死"},{"tokens":["✗","死了","＋","没死"],"note":"撞车！改成“他是这次事故中幸免于难的一个”"}]},"决策树":"①把句子拆成前后两半→②每半各是什么意思？写下来比一比→③两半能同时是真吗？→能：不是自相矛盾，转查其他逻辑错误→不能：自相矛盾，删掉或改掉其中一半","前置知识":["四大逻辑规律"],"类比":"像自己跟自己下棋还悔棋：都死了又幸免，将近又多，寂静又大声讨论。把前后两半拆开问一句，能同时是真的吗？不能，就是自己打自己。","来源":["台湾教育部《成语典》“自相矛盾”（含《韩非子·难一》原文）https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=89","统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83","百度百科「病句」·不合逻辑类（自相矛盾、概念并列不当、强加因果、主客颠倒）https://baike.baidu.com/item/%E7%97%85%E5%8F%A5/689579","汉文学网 汉语词典“遇难：遭遇危难而死”https://cd.hwxnet.com/view/lilaajiplbfnhpmo.html","统编选必上《逻辑的力量》第1课时教学设计（概念关系、四大规律、六种常见逻辑错误）http://www.yinruiwen.net/news/194567.htm"]},{"name":"主客倒置","lv":1,"讨论卡":{"问题":"“这首诗对我们很熟悉”错在哪里？和家人说说应该怎么对调。","提示":"有些感受词（熟悉、陌生、清楚、感动、了解）的主人只能是人：是“人对东西熟悉”，不是“东西对人熟悉”。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">爱迪生这个名字对我们不陌生</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我们对爱迪生这个名字不陌生</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这部电影对观众很感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">对</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">观众对这部电影很感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他的事迹对我们很感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">对</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我们对他的事迹很感动</text></g></svg>","目标":"今天学会认出主客倒置：谁对谁说反了。","讲解":"谁对谁说反了：京剧对她很熟悉→她对京剧很熟悉。","口诀":"谁感受谁在前，东西不能当主角","例子":["错：爱迪生这个名字对我们不陌生","对：我们对爱迪生这个名字不陌生","错：这部电影对观众很感动","对：观众对这部电影很感动","错：他的事迹对我们很感动","对：我们对他的事迹很感动","错：这个问题对他很清楚","对：他对这个问题很清楚","错：这首古诗对我们很熟悉","对：我们对这首古诗很熟悉","错：那场比赛对我印象很深　对：我对那场比赛印象很深（或：那场比赛给我留下了很深的印象）","错：这些问题对他来说并不了解　对：他对这些问题并不了解","错：这部电影对观众很感动　对：这部电影深深感动了观众／观众被这部电影深深感动","不是倒置：这本书对我很有启发（启发是书带给人的，东西作主语没有错）","错：爱迪生这个名字，对我们青年学生是不陌生的（应是“我们青年学生对爱迪生这个名字是不陌生的”；出处：百度百科「病句」主客颠倒）","错：去年的学习情绪和今年比较起来大不相同（比较时一般以后来的为主体，可改为“我今年的学习情绪和去年比起来大不相同”；出处：百度百科「病句」主客颠倒）"],"深讲":"小雨在日记里写：“这首儿歌对我很熟悉。”妈妈笑着问：“儿歌认识你吗？”小雨一愣：熟悉这首儿歌的明明是自己，不是儿歌。这种把“谁对谁”说反了的毛病，叫主客倒置，也叫主客颠倒。\n\n一句话里常有两方：一方是“主”，是去认识、去感受的人；一方是“客”，是被认识、被感受的东西。熟悉、陌生、了解、清楚、印象深、后悔、感兴趣，说的都是人心里的状态，主语应该是人：“我们对爱迪生这个名字不陌生”。把东西放到主语的位置，说成“爱迪生这个名字对我们不陌生”，就把被认识的一方说成了去认识的一方。改法很简单：把人放回前面，“对”后面放东西；也可以换个句式，比如“那场比赛给我留下了很深的印象”。\n\n也有容易误判的地方。第一，不是带“对”字的句子都错。“这本书对我很有启发”“跑步对身体有好处”“这件事对他很重要”都是对的，因为启发、好处、重要本来就是东西带给人的。判断时问一句：这个词说的是人心里的状态，还是东西的作用？第二，东西可以“感动”人。“这部电影感动了观众”完全通顺，这里的“感动”是动词；有毛病的是“这部电影对观众很感动”，“很感动”是观众心里的感受。可以改成“观众被这部电影深深感动”或“这部电影让观众很感动”。\n\n写读后感、观后感时最容易犯这个毛病。写完后找出“对……很熟悉、很陌生、很感动、印象很深”这样的句子，问一句“这是谁的感受”，再把人放回前面。说话也一样，“我对那部动画片印象很深”，一听就知道是谁记着它。","怎么认":["找感受词：熟悉、陌生、清楚、感动、了解。","问：谁在感受？感受的一方应该是人。","如果主语是东西（电影、名字、事迹），就是倒置，对调人和东西的位置。"],"辨析":"主客倒置和“被动句”不一样：“我被老师表扬了”主语是我，动作是我接受的，没错；主客倒置是感受的主人错了——“电影对观众很感动”里，真正感动的是观众，不是电影。","例句解析":[{"句":"错：爱迪生这个名字对我们不陌生","析":"“不陌生”的感受主人是我们——是我们对名字不陌生。名字不会“对我们陌生”，把“我们”和“名字”对调就对了。"},{"句":"错：这部电影对观众很感动","析":"感动的是观众，电影是让人感动的东西。主语应该是“观众”，电影不能“感动”观众作主语——对调：“观众对这部电影很感动”。"},{"句":"错：那场比赛对我印象很深","析":"“印象很深”是我心里的感受，主人是“我”。比赛不会对谁“有印象”。改成“我对那场比赛印象很深”，或者让比赛作“给”的主语：“那场比赛给我留下了很深的印象”。"},{"句":"不是倒置：这本书对我很有启发","析":"“启发”是书带给人的作用，就像“跑步对身体有好处”，东西作主语正合适。只有“熟悉、陌生、了解、感动”这类人心里的状态，才必须让人当主语。"},{"句":"对：这部电影深深感动了观众","析":"这里的“感动”是动词，意思是“使人感动”，电影当然可以作主语。病句“这部电影对观众很感动”的问题，是把观众心里的“很感动”安到了电影身上。"}],"易错":"不是所有“对……”的句子都倒置：“老师对我们很亲切”没错（亲切的是老师，老师是人）；只有感受词（熟悉、陌生、清楚、感动、了解）的主人必须是人，东西作主语才算倒置。","练习":[{"q":"“这首诗对我们很熟悉”错在哪里？","options":["诗不能作主语","熟悉的主人应该是我们，不是诗","我们写错了"],"answer":1,"解析":"“熟悉”是人的感受，应该是“我们对这首诗很熟悉”，诗不会熟悉我们。"},{"q":"下面哪句是对的？","options":["故宫对游客不陌生","游客对故宫不陌生","故宫很熟悉游客"],"answer":1,"解析":"熟悉的主人是游客：游客对故宫不陌生。A和C都把故宫当成了感受的主人。"},{"q":"“老师对我们很亲切”有没有主客倒置？","options":["有","没有","说不清"],"answer":1,"解析":"亲切的是老师，老师是人，主语没错——不是所有“对”字句都是倒置，只有感受词的主人错了才算。"},{"q":"下面哪句有主客倒置？","options":["跑步对身体有好处","那段经历对我印象很深","这本书对我很有启发"],"answer":1,"解析":"“印象很深”是人心里的状态，应改为“我对那段经历印象很深”；“好处”“启发”是东西带给人的，原句没错。"},{"q":"“这部动画片对小朋友很感动”最好改为？","options":["小朋友对这部动画片很感动","这部动画片深深感动了小朋友","这部动画片对小朋友很感人"],"answer":1,"解析":"用动词“感动”，让动画片作主语最通顺；A的“对……很感动”搭配别扭，C的“对小朋友很感人”也不通。"},{"q":"“这些成语对他早就熟悉了”应改为？","options":["他对这些成语早就熟悉了","这些成语早就熟悉他了","这些成语对他早就很熟了"],"answer":0,"解析":"熟悉的是“他”，把人放回主语位置，“对”后面放成语。"}],"决策树":"①找感受词：熟悉、陌生、清楚、感动、了解→②谁在感受？→是人：检查主谓搭配对吗→是东西（电影、名字、事迹）：主客倒置→③对调人和东西的位置→通顺了吗？→通顺：改对→还别扭：转查搭配不当","前置知识":["主语","宾语"],"类比":"像把帽子戴反了：熟悉、感动这些感受只能人戴，东西戴不上。电影对观众很感动是戴反了，对调过来，观众对电影很感动，帽子才戴正。","来源":["百度百科「病句」·不合逻辑类（自相矛盾、概念并列不当、强加因果、主客颠倒）https://baike.baidu.com/item/%E7%97%85%E5%8F%A5/689579","统编选必上《逻辑的力量》第1课时教学设计（概念关系、四大规律、六种常见逻辑错误）http://www.yinruiwen.net/news/194567.htm","统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83"]},{"name":"强加因果","lv":1,"讨论卡":{"问题":"“他早上吃了鸡蛋，所以考试考好了”——鸡蛋真能推出考好吗？和家人聊聊检验办法。","提示":"检验办法就一句：前者真能推出后者吗？"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">因为他是北方人，所以思想守旧</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">错</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">早上没吃鸡蛋，所以没考好</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他穿了红衣服，所以比赛赢了</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">对</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">昨晚熬夜刷题，今天上课精神不振</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">检验法</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">问一句\\\"前者真能推出后者吗\\\"，推不出就是强加因果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">错</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">因为他个子高，所以数学一定好</text></g></svg>","目标":"今天学会认出强加因果：没有因果硬说因果。","讲解":"无因果硬说因果：因为他来自北方，思想还是旧的一套。","口诀":"没有因果别硬凑，先问一句推得出","易错":"问一句：前者真能推出后者吗","例子":["错：因为他是北方人，所以思想守旧（地域推不出思想）","错：早上没吃鸡蛋，所以没考好（毫无关联）","错：他穿了红衣服，所以比赛赢了（迷信式因果）","对：昨晚熬夜刷题，今天上课精神不振（真实因果）","检验法：问一句\"前者真能推出后者吗\"，推不出就是强加因果","错：因为他个子高，所以数学一定好（身高推不出数学）","错：因为今天是星期三，所以要下雨（星期推不出天气）","错：因为教室里坐满了人，所以这节课一定讲得好（人数推不出质量）","对：多喝水、早睡觉，感冒好得快（身体恢复需要休息和水分）","对：每天练字半小时，字越写越好看（练习带来进步）","错：《祝福》中鲁四老爷说祥林嫂“不早不迟，偏偏要在这时候——这就可见是一个谬种！”（死的时间推不出人的好坏；出处：鲁迅《祝福》，统编高中选择性必修上册第四单元任务1）","错：他出生时天昏地暗、飞沙走石，注定此生不凡（出处：同上任务2）","错：因为他对学科有所偏重，所以对数理化不感兴趣（“不感兴趣”是偏重的具体表现，不是结果；出处：百度百科「病句」）","错：因为今天是周末，老师们还是来到了学校（周末不是来学校的原因；应改为“虽然……还是……”）","错：公鸡一叫太阳就升起，所以太阳是公鸡叫出来的（先后发生≠因果）","存疑：不吃早饭的孩子成绩常常差一些（可能有共同原因，如作息、家庭照顾，不能直接说早饭决定成绩；出处：思方网《因果关系1》）"],"深讲":"每天早上公鸡一叫，太阳就升起来了。如果公鸡得意地说“太阳是我叫出来的”，你一定会笑。可我们自己也常这么想：“我穿了红袜子，所以考了满分。”两件事挨着发生，就被硬说成“因为……所以……”，这就是强加因果。\n\n真正的因果要过三关。第一关，原因得发生在结果前面；不过这只是最起码的条件，“在前面”不等于“是原因”，公鸡就是被这一关骗了。第二关，要能讲出一条说得通的链子，比如熬夜→睡眠不足→第二天上课犯困，每一环都接得上。第三关，换一换还成立吗？只改变这个原因，结果会跟着变吗？换一双袜子再考，满分照样可能，也照样可能考不到。过不了这三关，就是没有因果硬说因果，违反了充足理由律（理由和结论接不上）。\n\n这些情况要特别留心。《祝福》里，鲁四老爷说祥林嫂“不早不迟，偏偏要在这时候——这就可见是一个谬种”，祥林嫂死在年关前后，和她是不是“谬种”毫无关系，只是时间凑在了一起。“他出生时天昏地暗、飞沙走石，注定此生不凡”，天气推不出一个人的命运。还要小心“共同原因”：调查发现不吃早饭的孩子成绩常常差一些，可能不是早饭本身起作用，而是背后有作息乱、没人照顾这类共同原因。反过来，也别把真因果一律说成假的：饿着肚子确实可能没精神，只是不能说它是唯一原因。\n\n写作文用“因为……所以……”之前，先在心里补出中间那条链子；补不出来，就把“所以”换成“后来”“同时”，或改成转折句：“虽然今天是周末，老师们还是来到了学校。”写议论文分析原因时，多用“之一”“往往”，少用“一定”“全靠”。听到别人说“自从……就……”，问一句：还有别的原因吗？","怎么认":["找出“因为”后面的原因和“所以”后面的结果。","问：原因真能推出结果吗？换个情况还成立吗？","推不出，或者只是碰巧一起出现，就是强加因果。"],"辨析":"强加因果和“真实因果”的区别在“必然”：熬夜→上课没精神，是身体规律，换谁都一样；穿红衣服→比赛赢，换件衣服也可能赢——经不起“换一换”检验的，就是强加。","例句解析":[{"句":"错：因为他是北方人，所以思想守旧（地域推不出思想）","析":"“北方人”是出生地，“思想守旧”是个人想法，出生地推不出想法——两件事没有因果链，硬凑就是强加。"},{"句":"对：昨晚熬夜刷题，今天上课精神不振（真实因果）","析":"熬夜少睡→白天没精神，是身体的真实规律，换谁熬夜都一样，这才叫因果。"},{"句":"错：鲁四老爷说祥林嫂“不早不迟，偏偏要在这时候——这就可见是一个谬种！”","析":"祥林嫂的死和年关的“祝福”只是时间挨得近，并没有谁导致谁；而“死在这时候”更推不出“她是谬种”。鲁迅借这句话写出鲁四老爷的冷酷和迷信，这正是强加因果。"},{"句":"错：因为今天是周末，老师们还是来到了学校","析":"“还是”说明这是一件“本来不该、却仍然发生”的事，前后是转折，不是因果。改成“虽然今天是周末，老师们还是来到了学校”就通了。"},{"句":"错：公鸡一叫太阳就升起，所以太阳是公鸡叫出来的","析":"公鸡叫在前、太阳升在后，只过了“先后”这一关。换一换就知道：公鸡不叫，太阳照样升起。说不定恰恰相反，是天快亮的光线让公鸡叫起来的。"}],"练习":[{"q":"“他早上吃了鸡蛋，所以考试考好了”错在哪里？","options":["鸡蛋不能吃","吃鸡蛋和考好没有因果","考试写错了"],"answer":1,"解析":"吃鸡蛋不会让人变聪明，两件事只是碰巧同一天发生，硬说因果就是强加。"},{"q":"下面哪个是真实因果？","options":["穿新鞋所以跑得快","下雨所以地面湿了","戴眼镜所以成绩好"],"answer":1,"解析":"雨水落到地上，地面自然会湿，这是真实规律；新鞋、眼镜和跑得快、成绩好没有因果。"},{"q":"检验因果最好的办法是？","options":["看两件事是不是同一天发生","问一句“前者真能推出后者吗”","看句子有没有“因为”"],"answer":1,"解析":"同一天发生不等于有因果；有没有“因为”也不作数——关键看前者能不能推出后者。"},{"q":"“因为今天是星期天，妈妈还是很早起床做早饭。”怎么改最合适？","options":["因为今天是星期天，所以妈妈很早起床","虽然今天是星期天，妈妈还是很早起床做早饭","今天是星期天，妈妈因此很早起床"],"answer":1,"解析":"“还是”表示转折：星期天本可以睡懒觉，妈妈却仍然早起，应该用“虽然……还是……”。"},{"q":"公鸡说“太阳是我叫出来的”，它把什么当成了因果？","options":["只是先后发生的两件事","经过实验证明的规律","一条讲得通的因果链"],"answer":0,"解析":"公鸡叫和日出只是一先一后；换一换（公鸡不叫）太阳照样升起。"},{"q":"调查发现常不吃早饭的同学成绩偏低。下面哪种说法最稳妥？","options":["不吃早饭一定会让成绩变差","两件事有关联，但可能有共同原因，还要进一步弄清楚","两件事毫无关系"],"answer":1,"解析":"有关联不等于有因果，也可能是作息、家庭照顾等共同原因；说“一定”或“毫无关系”都太绝对。"}],"决策树":"①找出\"因为\"后面的原因和\"所以\"后面的结果→②原因真能推出结果吗？→能：不是强加因果→不能/存疑：换个情况还成立吗？→成立：因果成立→不成立：强加因果，删掉因果关联词或改写","前置知识":["因果复句","概念：定义与划分"],"类比":"像把碰巧站在一起的两个人说成亲戚：北方人推不出思想守旧，红衣服推不出比赛赢。问一句前者真能推出后者吗，换一换还成立吗，推不出就是硬攀亲戚。","来源":["香港大学 思方网 H18《因果关系1》（先后≠因果、共同原因、早餐与成绩例）https://philosophy.hku.hk/think/chi/causation-1.php","统编高中语文选择性必修上册 第四单元《逻辑的力量》学习活动原文（转录）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83","统编选必上《逻辑的力量》第2课时教学设计（教材任务1逐条分析）http://www.yinruiwen.net/news/194568.htm","百度百科「病句」·不合逻辑类（自相矛盾、概念并列不当、强加因果、主客颠倒）https://baike.baidu.com/item/%E7%97%85%E5%8F%A5/689579"]},{"name":"以偏概全","lv":1,"讨论卡":{"问题":"班里三个同学近视，能不能说全班都近视？和家人聊聊要下“全部”的结论还缺什么。","提示":"想下“全部”的结论，要么调查全体，要么有足够大的抽样和数据；只凭几个例子就下大结论，一定翻车。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">错</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我班三个同学近视，所以全班都近视</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">错</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他北方人，北方人都豪爽</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">错</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">我去过一次北京很堵，所以北京天天堵</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">错</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">两个学霸都熬夜，所以熬夜才能当学霸</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">对</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">调查显示我班80%同学近视，需注意用眼</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">写作提醒</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">举例后必须\\\"扣题分析\\\"，摆个例子就下大结论必翻车</text></g></svg>","目标":"今天学会认出以偏概全：拿部分当全部。","类比":"以偏概全就像\"盲人摸象\"：摸到腿说象是柱子，摸到鼻子说象是管子。","讲解":"拿部分当全部。看到几个就下结论全体，犯了\"简单枚举\"的错。","口诀":"部分推全体，十有八九错","例子":["错：我班三个同学近视，所以全班都近视","错：他北方人，北方人都豪爽","错：我去过一次北京很堵，所以北京天天堵","错：两个学霸都熬夜，所以熬夜才能当学霸","对：调查显示我班80%同学近视，需注意用眼（有数据支撑≠以偏概全）","写作提醒：举例后必须\"扣题分析\"，摆个例子就下大结论必翻车","错：我家猫怕水，所以所有猫都怕水","错：他一次考试没考好，就说他不是学习的料","错：只看到操场上有几个纸团，就说我们学校卫生最差","对：问了全班同学才说“我们班大多数同学喜欢踢球”（调查全体再下结论）","课文里：《小马过河》老牛说水浅、松鼠说水深——都只拿自己的身子量了一次，就给整条河下结论（统编二年级下册）","成语：坐井观天——井底的青蛙只看到井口那么大一块天，就说天只有这么大（韩愈《原道》：“坐井而观天，曰天小者，非天小也。”）","成语：管中窥豹，时见一斑——从竹管里看豹子，只看到一块斑纹（《世说新语·方正》）","错：欧洲人见过的天鹅全是白的，就说“天鹅都是白的”——后来在澳大利亚发现了黑天鹅","错：我买的两个西瓜都不甜，所以这家店的西瓜全都不甜（样本只有两个）","对：每个班都抽10名同学来问，大约七成每天睡够9小时——所以“年级里大多数同学睡眠够”（抽得广、结论留余地）","改法：把“北方人都豪爽”改成“我认识的几个北方同学都很豪爽”——只说看到的，就不犯错"],"深讲":"统编二年级下册有个故事叫《小马过河》：小马问老牛，老牛说“水很浅，刚没小腿”；松鼠却拦住它说“深得很哩”。两个都没撒谎，可都只拿自己的身子量了一次，就替整条河下了结论。最后小马自己蹚过去才发现：河水既不像老牛说的那样浅，也不像松鼠说的那样深。\n\n以偏概全，就是拿一小部分（样本：被拿来看的那一小部分）去说全部。从几个例子推出一个大结论，叫归纳推理（从个别推到一般）。归纳本身没有错，科学家天天在用，可它推出的结论只是“很可能对”。样本越少、越不像全体，结论就越靠不住。欧洲人很长时间里见到的天鹅全是白的，就说“天鹅都是白的”，后来在澳大利亚见到了黑天鹅，这个“都”一下子就倒了。所以要问两句：看了多少个？看的这些像不像全体？\n\n最常见的误区有三个。第一，以为有例子就能说“都”“天天”“所有”。第二，分不清“所有”“大多数”“有些”：一个反例能推翻“所有”，却推不翻“大多数”。第三，凭几个人给一群人贴标签（刻板印象：给一群人贴同一张标签），再把标签硬贴到眼前这个人身上，比如“他是南方人，肯定会做生意”。这句话里藏着一个没说出口的“都”，它就是以偏概全。\n\n写作文时，例子后面的结论要和例子一样大：用“往往”“很多”“可见……很重要”给结论留点余地，再补上不同方面的例子（古今、中外、身边）。和人聊天时，听到“所有人都……”，可以笑着问一句：“你看了几个？”","怎么认":["找结论里的大词：都、天天、所有、肯定。","问：结论是凭几个例子下的？还是调查了全体/有数据？","只凭几个例子就下大结论，就是以偏概全。"],"辨析":"以偏概全和“举例论证”不一样：举例论证是拿例子当证据，结论留有余地（“可见……很重要”）；以偏概全是拿例子当全部，结论说死（“所以全班都……”）。例子后面有没有“扣题分析”、结论有没有留余地，是分水岭。","例句解析":[{"句":"错：我班三个同学近视，所以全班都近视","析":"三个同学只是全班的一小部分，从三个人推到全班，样本太小——要下“全班”的结论，得调查全班。"},{"句":"对：调查显示我班80%同学近视，需注意用眼（有数据支撑≠以偏概全）","析":"这个结论有调查数据支撑，“80%”也不是“全部”——有数据、留余地，就不是以偏概全。"},{"句":"错：欧洲人见过的天鹅全是白的，就说“天鹅都是白的”","析":"见过再多白天鹅，也只是“见过的那些”。只要出现一只黑天鹅，“都是白的”就倒了。归纳出来的“都”，永远要留个心眼。"},{"句":"课文里：《小马过河》老牛说水浅、松鼠说水深","析":"老牛个子高，松鼠个子小，各自只量了自己那一次，就替所有动物下结论。样本（被拿来看的那部分）不像全体，结论就歪了。小马自己一试，才知道河水不深也不浅。"},{"句":"对：每个班都抽10名同学来问，大约七成每天睡够9小时","析":"每个班都抽到了，人数也不算太少，结论还用“大多数”留了余地。这就是合格的归纳，不是以偏概全。"}],"易错":"议论文举例后一定要\"扣题分析\"，不能例子一摆就下大结论","练习":[{"q":"“我去过一次北京很堵，所以北京天天堵”错在哪里？","options":["北京不堵","一次经历推不出天天","去字写错了"],"answer":1,"解析":"一次堵车只是某一天的情况，推不到“天天”——以偏概全。"},{"q":"下面哪个不是以偏概全？","options":["两个学霸熬夜，所以熬夜才能当学霸","调查了全班才说大多数同学喜欢踢球","我家猫怕水，所以所有猫都怕水"],"answer":1,"解析":"调查了全班再下结论，有全体数据支撑；另外两个都是拿个别推全体。"},{"q":"写议论文时，举例后最应该做什么？","options":["再举一个例子","扣题分析，把例子和观点连起来","直接下大结论"],"answer":1,"解析":"摆个例子就下大结论是以偏概全；要分析例子为什么能证明观点，结论才站得住。"},{"q":"下面哪个结论最靠得住？","options":["问了同桌，同桌喜欢踢球，所以全班都爱踢球","问了全班40人，31人喜欢踢球，所以班里大多数人爱踢球","看到操场上很多人踢球，所以全校都爱踢球"],"answer":1,"解析":"调查了全班、结论用“大多数”留了余地，最靠得住。另外两个都是看了一点点就说“全”。"},{"q":"“他是南方人，所以他一定很会做生意。”和以偏概全有什么关系？","options":["没有关系，这句话没毛病","它藏着“南方人都会做生意”这个以偏概全的前提，再把标签硬贴到他身上","它是自相矛盾"],"answer":1,"解析":"先凭少数人给一群人贴标签（以偏概全），再把标签套到一个人身上。揪出那个藏起来的“都”，错误就露出来了。"},{"q":"成语“坐井观天”说的道理最接近？","options":["只看到一小部分，就对全部下结论","井里的青蛙过得很开心","天空其实很小"],"answer":0,"解析":"青蛙只看到井口那么大的天，就说天只有那么大，正是以偏概全。"}],"决策树":"①找结论里的大词：都、天天、所有、肯定→②结论凭几个例子下的？→调查了全体/有数据：不是以偏概全→只凭几个例子：以偏概全→③改法：缩小结论范围（\"有些\"\"部分\"）或补充依据","前置知识":["概念：定义与划分"],"来源":["Joe Lau《批判性思考网》Critical Thinking Web · F04 Insufficiency（Limited sampling：样本有限的谬误）：https://philosophy.hku.hk/think/fallacy/is.php","统编高中语文选择性必修上册第四单元《采用合理的论证方法》第1课时课堂实录（举例论证＝归纳推理；道理论证＝演绎推理；对比论证＝相反或相异的比较）：https://81952.com/yuwen/1473.html","统编二年级下册课文《小马过河》全文（央广网课文示范朗读页）：https://edu.cnr.cn/eduzt/ywkwsfsd/jdld/erx/20231226/t20231226_526534581.html","教育部《成语典》“坐井观天”（典源：韩愈《原道》）：https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=73 ；“管中窥豹”（典源：《世说新语·方正》）：http://dict.idioms.moe.edu.tw/idiomView.jsp?ID=190&la=0&webMd=2"]}]},{"id":"lunzheng","name":"议论文论证逻辑","items":[{"name":"举例论证","lv":1,"讨论卡":{"问题":"讲完一个例子不分析，家人能知道你想证明什么吗？聊聊分析要说什么。","提示":"故事只是证据，真正说服人的是后面的分析——这个例子为什么能证明我的观点。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">樊锦诗守敦煌</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">事例+坚守的分析+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">论\\\"勤奋\\\"</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">匡衡凿壁偷光+分析\\\"条件再差也不放弃\\\"+回扣\\\"勤奋成就人生\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">论\\\"诚信\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">曾子杀猪+分析\\\"对孩子也守信\\\"+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">论\\\"创新\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">鲁班观草叶造锯+分析\\\"观察+思考\\\"+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">反例</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">只摆事例不分析=\\\"例子堆砌\\\"，分析才是得分点</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">公式</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分论点→事例简述→扣题分析→小结回扣</text></g></svg>","目标":"今天学会举例论证：用事例证明分论点，分析才是灵魂。","类比":"举例就像证人出庭：光有观点不行，得叫证人作证。","讲解":"公式：分论点+事例简述+扣题分析+小结回扣。事例是载体，分析才是灵魂。","口诀":"观点事例加分析，回扣分论才扎实","例子":["樊锦诗守敦煌：事例+坚守的分析+回扣","论\"勤奋\"：匡衡凿壁偷光+分析\"条件再差也不放弃\"+回扣\"勤奋成就人生\"","论\"诚信\"：曾子杀猪+分析\"对孩子也守信\"+回扣","论\"创新\"：鲁班观草叶造锯+分析\"观察+思考\"+回扣","反例：只摆事例不分析=\"例子堆砌\"，分析才是得分点","公式：分论点→事例简述（100字内）→扣题分析→小结回扣","论\"坚持\"：同桌每天练字一页，一学期后字大变样+分析\"每天一小步\"+回扣","论\"诚信\"：小明答应还书按时还+分析\"小事守信才靠得住\"+回扣","论\"勤奋\"：班长每天早读半小时，英语越读越顺+分析\"天天练才有语感\"+回扣","论\"分享\"：小红把新书借给同学，全班都爱上了阅读+分析\"分享让快乐翻倍\"+回扣","课文里：《生于忧患，死于安乐》连举舜、傅说、胶鬲、管夷吾、孙叔敖、百里奚六人，都从艰难处起家，再推出“生于忧患”","论“后天学习”：方仲永五岁能作诗，父亲却“不使学”，后来“泯然众人矣”（王安石《伤仲永》）","论“勤学”：宋濂家贫借书抄写，“天大寒，砚冰坚，手指不可屈伸，弗之怠”（《送东阳马生序》）","论“好问”：孔子“入太庙，每事问”（《论语·八佾》）","错例：论“坚持”却讲某人买彩票中了大奖——事例和观点对不上（两张皮）","错例：“爱迪生、居里夫人都很勤奋，所以所有勤奋的人都能成为科学家”——结论比例子大，推过头了","补法：一个古人例子＋一个今人或身边例子，互相撑腰（点面结合）"],"深讲":"班会上你说“坚持很重要”，同学们没什么反应；你接着讲：同桌每天练一页字，一个学期后字大变样，连老师都在作业本上画了五角星。大家这才点头。观点是抽象的，事例能让道理“看得见、摸得着”，这就是举例论证的力量。\n\n按统编高中教材的说法，举例论证从逻辑上看是归纳推理（从个别推到一般）。归纳得出的结论只是“很可能真”，所以事例要做到三点：真实，不编造；典型（最能代表这一类）；扣题，和观点对得上。一个例子嫌单薄，就补不同方面的例子。《生于忧患，死于安乐》一口气举了舜、傅说、胶鬲、管夷吾、孙叔敖、百里奚六个人，身份各不相同，却都是从艰难里走出来的，“生于忧患”的结论就稳多了。\n\n常见误区：一是光摆事例不分析，变成“例子堆砌”；二是事例写得太长，挤掉了分析；三是事例和观点“两张皮”，论“坚持”却讲一个运气好的故事；四是结论比例子大，摆了两个名人，就说“所有人都能……”，滑进了以偏概全；五是编造名人事例，或者把传说当史实。\n\n写作时记住四步：分论点→事例简述（100字以内，只留和观点有关的细节）→扣题分析（“正是因为……才……”“这说明……”）→小结回扣。和人讲道理时也一样：先说观点，再讲一个身边的例子，最后补一句“所以我觉得……”。","怎么认":["先找分论点：这段要证明什么？","再看事例：故事讲的是不是这回事？","最后看分析：有没有讲清“这个例子为什么能证明观点”？没有，就是例子堆砌。"],"辨析":"举例论证和“讲故事”的区别在“扣题”：讲故事讲完就完了；举例论证讲完必须回扣——“这说明……”“可见……”。没有回扣的例子，读者不知道你想证明什么。","例句解析":[{"句":"论\"勤奋\"：匡衡凿壁偷光+分析\"条件再差也不放弃\"+回扣\"勤奋成就人生\"","析":"事例只讲了“凿壁偷光”的意思，重点在分析“条件再差也不放弃”——分析把事例和“勤奋”连起来，回扣点明观点，结构才完整。"},{"句":"反例：只摆事例不分析=\"例子堆砌\"，分析才是得分点","析":"光摆事例，读者只能看到故事，看不到观点。分析是桥梁：没有桥，事例到不了观点那边。"},{"句":"课文里：《生于忧患，死于安乐》连举舜、傅说、胶鬲、管夷吾、孙叔敖、百里奚六人","析":"六个人有种田的、筑墙的、卖鱼盐的、从狱官手里放出来的、隐居海边的、从市井里被赎出来的，身份各不相同，却都从困境中成才。例子多、覆盖面广，归纳出的结论才比单个例子稳。"},{"句":"论“后天学习”：方仲永五岁能作诗，父亲却“不使学”，后来“泯然众人矣”","析":"事例只留下三个细节：五岁能诗、父亲不让学、长大泯然众人，别的枝节全删掉。分析时点明转折就在“不使学”，正好扣住“后天学习”。"},{"句":"错例：“爱迪生、居里夫人都很勤奋，所以所有勤奋的人都能成为科学家”","析":"这两个例子能说明“勤奋对科学家很重要”，推不出“所有勤奋的人都能成科学家”。结论只能和例子一样大，不能比例子还大。"}],"易错":"两个坑：一是事例写太长（超过100字），挤占分析空间；二是事例讲完不分析不回扣，变成例子堆砌。记住：分析才是得分点。","练习":[{"q":"举例论证最关键的一步是？","options":["事例讲得长","扣题分析","事例讲得感人"],"answer":1,"解析":"事例只是证据，分析把事例和观点连起来——没有分析就是例子堆砌。"},{"q":"“论勤奋：匡衡凿壁偷光。”这样写缺什么？","options":["缺事例","缺分析和回扣","缺分论点"],"answer":1,"解析":"只有事例没有分析，读者不知道这个故事怎么证明勤奋——要补“条件再差也不放弃”的分析和回扣。"},{"q":"事例简述应该多长？","options":["越长越好","100字内，越短越好","不用写事例"],"answer":1,"解析":"事例是载体不是主角，100字内讲清即可，篇幅要留给分析和回扣。"},{"q":"论“后天学习很重要”，哪个事例最扣题？","options":["方仲永天资过人，因父亲不让他学习，最后泯然众人","李白斗酒诗百篇","司马光砸缸救人"],"answer":0,"解析":"方仲永的事正好说明：天赋再好，不学习也会变平常，扣住了“后天学习”。"},{"q":"从逻辑上看，举例论证属于哪种推理？","options":["演绎推理：从一般推到个别","归纳推理：从个别推到一般","类比推理：从这个推到那个"],"answer":1,"解析":"举例论证是从一个个事例归纳出一般结论，是归纳推理。"},{"q":"“爱迪生、居里夫人都很勤奋，所以所有勤奋的人都能成为科学家。”问题在哪？","options":["例子不真实","结论比例子说得大，推过头了","没有用名人做例子"],"answer":1,"解析":"两个例子撑不起“所有勤奋的人都能成科学家”，结论要收小，比如“勤奋是科学家成功的重要条件”。"}],"前置知识":["概念：定义与划分"],"来源":["统编高中语文选择性必修上册第四单元《采用合理的论证方法》第1课时课堂实录（举例论证＝归纳推理；道理论证＝演绎推理；对比论证＝相反或相异的比较）：https://81952.com/yuwen/1473.html","王安石《伤仲永》原文（维基文库）：https://zh.wikisource.org/wiki/%E5%82%B7%E4%BB%B2%E6%B0%B8","教育部《成语典》“不耻下问”条（说明孔子是在称赞孔文子）：https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=167&la=0&q=1&webMd=2"]},{"name":"道理论证","lv":1,"讨论卡":{"问题":"一句名言摆出来不解释，算不算论证？和家人聊聊阐释要说什么。","提示":"名言自己不会说话——必须阐释：这句名言为什么能证明我的观点？"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">论\\\"坚持\\\"</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">荀子\\\"锲而不舍，金石可镂\\\"+解释+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">论\\\"学习方法\\\"</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">朱熹\\\"读书有三到，心到眼到口到\\\"+阐释+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">论\\\"谦虚\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"满招损，谦受益\\\"+阐释为什么适用+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">论\\\"团结\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"人心齐，泰山移\\\"+阐释+回扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">名言堆三四句却不阐释=白费，阐释才是得分点</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">公式</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分论点→名言/定理→阐释→回扣</text></g></svg>","目标":"今天学会道理论证：用名言定理证明观点，并讲清为什么。","类比":"道理论证就像\"请权威背书\"：名人名言、定理公理往那一摆，分量立马不同。","讲解":"公式：分论点+名言/定理+阐释（为什么这句能证明观点）+回扣。","口诀":"名言开道，阐释跟上","例子":["论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣","论\"学习方法\"：朱熹\"读书有三到，心到眼到口到\"+阐释+回扣","论\"谦虚\"：\"满招损，谦受益\"+阐释为什么适用+回扣","论\"团结\"：\"人心齐，泰山移\"+阐释+回扣","忌：名言堆三四句却不阐释=白费，阐释才是得分点","公式：分论点→名言/定理→阐释（为什么能证明）→回扣","论\"学习态度\"：《论语》\"学而不思则罔，思而不学则殆\"+阐释+回扣","论\"诚信\"：《论语》\"人而无信，不知其可也\"+阐释+回扣","论\"谦虚\"：《论语》\"三人行，必有我师焉\"+阐释+回扣","提醒：名言要和分论点贴得紧，贴不上的名言再有名也是白摆","论“积累”：荀子《劝学》“不积跬步，无以至千里；不积小流，无以成江海”+阐释+回扣","论“团结”：《孟子》“天时不如地利，地利不如人和”（统编八上《得道多助，失道寡助》）+阐释+回扣","论“学要善疑”：张载“在可疑而不疑者，不曾学；学则须疑”（统编九上顾颉刚《怀疑与学问》开头所引）+阐释+回扣","论“防微杜渐”：俗语“千里之堤，溃于蚁穴”（化用《韩非子·喻老》“千丈之堤，以蝼蚁之穴溃”）+阐释+回扣","论“节约用水”：引用常识“地球上能直接利用的淡水很少”并解释——科学事实和常识也能当道理论据","错例（张冠李戴）：写“孔子说自己不耻下问”——其实是孔子称赞孔文子“敏而好学，不耻下问”（《论语·公冶长》）","错例（断章取义）：用“言必信，行必果”当最高夸奖——原文后面紧跟“硁硁然小人哉”，孔子把这种人排在第三等（《论语·子路》）","错例（诉诸权威）：“这是名人说的，所以一定对，不用解释”——道理论证要讲“为什么对”，不能只亮名片"],"深讲":"你劝同桌别骄傲，说了一句“满招损，谦受益”。同桌眨眨眼：“凭什么？”这下你发现了：名言只是一个开头，接下来你得讲清它为什么对，还得说明它和眼前这件事有什么关系。\n\n道理论证，就是拿大家公认的道理当证据，比如经典名言、科学定理、常识和俗语。统编高中教材说，它的逻辑形式是演绎推理：先摆出大道理（大前提），再把眼前的事放进去（小前提），结论就跟着出来了。荀子说“锲而不舍，金石可镂”，意思是一刀一刀不停地刻，连金属石头都能刻穿，这是大前提；学习就像刻金石，难，要一点点来，这是小前提；所以学习贵在坚持，这是结论。演绎要靠得住，得满足两条：大道理本身是真的，而且它和眼前的事真正搭得上桥。“阐释”就是专门搭这座桥的。\n\n常见误区有三个。第一，把名人当保险箱，以为“名人说的，所以一定对”，这是诉诸权威，不是道理论证。名言有分量，是因为它讲的道理经得起检验，不是因为说话的人有名。第二，张冠李戴：“不耻下问”不是孔子说自己，而是孔子称赞卫国大夫孔文子的话（《论语·公冶长》）。第三，断章取义：“言必信，行必果”后面紧跟着“硁硁然小人哉”，孔子只把这种人排在“士”的第三等，拿它当最高夸奖就曲解了原意。\n\n写作时可以用四步：引（短而准，标明出处）→释（翻译成大白话）→联（说清它和论点的关系）→扣（回到分论点）。引用前先查一查原文和上下文。说话时也别只亮名人的名字，要讲出“为什么”。","怎么认":["找名言：引的是谁的话、哪条定理？","找阐释：有没有讲这句为什么能证明观点？","找回扣：最后有没有回到分论点？"],"辨析":"道理论证和举例论证的区别：举例是拿“事”证明（匡衡的故事），道理论证是拿“理”证明（荀子的话、定理）。一个讲事实，一个讲道理；写议论文时两者常常配合用。","例句解析":[{"句":"论\"坚持\"：荀子\"锲而不舍，金石可镂\"+解释+回扣","析":"荀子的话讲“不停地刻，连金石都能刻穿”——阐释要把“刻”对应到“坚持”，再回扣“坚持才能成事”，名言才算用上了。"},{"句":"忌：名言堆三四句却不阐释=白费，阐释才是得分点","析":"三四句名言排队站岗，看起来有气势，其实都没和观点连上线——阐释才是把名言变成论证的那一步。"},{"句":"论“积累”：荀子《劝学》“不积跬步，无以至千里；不积小流，无以成江海”","析":"阐释分三步：译（半步半步攒，才能走到千里）→联（学习也是一天天攒出来的）→扣（所以学习贵在积累）。少了中间的“联”，名言就和论点脱了节。"},{"句":"错例（断章取义）：用“言必信，行必果”当最高夸奖","析":"子贡问怎样才算“士”，孔子讲了三等，第三等才是“言必信，行必果”，还说这种人“硁硁然”（固执）。只截前半句来夸人，就曲解了原意。引用前一定要查原文上下文。"},{"句":"错例（诉诸权威）：“这是名人说的，所以一定对，不用解释”","析":"道理论证靠的是道理本身经得起检验，只拿名气压人就成了诉诸权威。分辨它们看一点：有没有讲出“为什么对”。"}],"易错":"名言不能堆砌，阐释（为什么适用）才是得分点","练习":[{"q":"道理论证里最不能少的是？","options":["名言的数量","阐释（为什么能证明观点）","名言的作者名气"],"answer":1,"解析":"名言再有名，不阐释就和观点连不上线——阐释才是得分点。"},{"q":"论“谦虚”引用“满招损，谦受益”，接下来最应该写什么？","options":["再引一句名言","阐释为什么骄傲招损、谦虚受益","直接结尾"],"answer":1,"解析":"要讲清这句为什么能证明谦虚——骄傲让人看不见缺点，谦虚让人不断进步。"},{"q":"下面哪种是道理论证？","options":["讲匡衡凿壁偷光的故事","引用荀子“锲而不舍，金石可镂”并阐释","正反两个例子对照"],"answer":1,"解析":"引用名言讲道理是道理论证；讲故事是举例论证；正反对照是对比论证。"},{"q":"道理论证从逻辑上看，最像哪种推理？","options":["归纳：从许多例子推出结论","演绎：用公认的大道理推出眼前的结论","类比：两件事像，所以结论也像"],"answer":1,"解析":"道理论证先摆公认的道理（大前提），再套到眼前的事上，是演绎推理。"},{"q":"下面哪句引用出了错？","options":["荀子《劝学》：“锲而不舍，金石可镂。”","《论语》里孔子称赞孔文子“敏而好学，不耻下问”","孔子说自己“不耻下问”"],"answer":2,"解析":"“不耻下问”是孔子称赞孔文子的话，不是孔子说自己。"},{"q":"“这句话是大科学家说的，所以一定对，不用解释。”这样写属于？","options":["完整的道理论证","诉诸权威：只亮名气，不讲道理","对比论证"],"answer":1,"解析":"道理论证必须讲清“为什么对”，只靠名气是诉诸权威。"}],"前置知识":["概念：定义与划分"],"来源":["统编高中语文选择性必修上册第四单元《采用合理的论证方法》第1课时课堂实录（举例论证＝归纳推理；道理论证＝演绎推理；对比论证＝相反或相异的比较）：https://81952.com/yuwen/1473.html","教育部《成语典》“不耻下问”条，典源《论语·公冶长》：子贡问孔文子何以谓之“文”，子曰“敏而好学，不耻下问”：https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=167&la=0&q=1&webMd=2","《论语·子路》13.20 原文（维基文库）：“言必信，行必果，硁硁然，小人哉，抑亦可以为次矣”：https://zh.wikisource.org/zh-hans/%E8%AB%96%E8%AA%9E/%E5%AD%90%E8%B7%AF%E7%AC%AC%E5%8D%81%E4%B8%89","统编九年级上册《怀疑与学问》（顾颉刚）课文与教学设计，开头引程颐“学者先要会疑”、张载“在可疑而不疑者，不曾学；学则须疑”：http://www.yinruiwen.net/news/189316.htm"]},{"name":"对比论证","lv":1,"讨论卡":{"问题":"方仲永荒废、匡衡凿壁，两个例子摆出来不分析，家人看得出你想说什么吗？聊聊比完要分析什么。","提示":"比完要分析：为什么一个成、一个败？分析出原因，结论才有说服力。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">论\\\"勤奋\\\"</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">方仲永荒废 vs 匡衡凿壁</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">论\\\"诚信\\\"</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">曾子杀猪守信 vs 周幽王烽火戏诸侯失信</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">论\\\"节俭\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">朱元璋节俭 vs 石崇斗富奢靡</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">论\\\"谦虚\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">孔子不耻下问 vs 项羽刚愎自用</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">结构</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">正面事例+反面事例+对比分析→结论</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">提醒</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">对比点要扣住分论点，不能为对比而对比</text></g></svg>","目标":"今天学会对比论证：正反例子一对比，结论就清楚了。","类比":"对比就像\"照妖镜\"：正反一放，好坏立现。","讲解":"正面例子+反面例子+对比分析，得出结论。是非分明，说服力强。","口诀":"正反对照，是非自现","例子":["论\"勤奋\"：方仲永荒废 vs 匡衡凿壁","论\"诚信\"：曾子杀猪守信 vs 周幽王烽火戏诸侯失信","论\"节俭\"：朱元璋节俭 vs 石崇斗富奢靡","论\"谦虚\"：孔子不耻下问 vs 项羽刚愎自用","结构：正面事例+反面事例+对比分析→结论","提醒：对比点要扣住分论点，不能为对比而对比","论\"认真\"：小明检查三遍全对 vs 小刚交卷就跑错一半","论\"坚持\"：每天练跑步的同学越跑越轻松 vs 三天打鱼两天晒网的同学一直喘","论\"合作\"：小组分工的同学做得又快又好 vs 单打独斗的同学手忙脚乱","论\"阅读\"：爱读书的同学写作文有话说 vs 从不读书的同学对着作文纸发呆","课文里：《出师表》“亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也”（一句话里正反对比）","课文里：《孙权劝学》吕蒙读书前后判若两人，鲁肃惊叹“非复吴下阿蒙”（同一个人前后对比）","课文里：《送东阳马生序》宋濂拿自己当年借书抄书、冒雪求师的苦，和太学生衣食无忧相比，劝人勤学","课文里：《得道多助，失道寡助》“寡助之至，亲戚畔之；多助之至，天下顺之”","实验里：两盆一样的绿豆苗、一样浇水，一盆放阳台、一盆放柜子里——对比实验要“只改一个条件”","错例：论“勤奋”拿神童和普通孩子比成绩——两人起点差太多，比不出勤奋的作用","错例：“爱读书的同学都是好孩子，不读书的全是坏孩子”——把对比写成了非黑即白"],"深讲":"诸葛亮在《出师表》里劝刘禅：“亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也。”同一个汉朝，两种用人的做法，两个完全相反的结局。这么一摆，不用多说，该亲近谁一目了然。这就是对比论证。\n\n对比论证，是把相反或不同的两种情况放在一起比，让观点在差别里显出来。统编教材把它归在“比较法”里：类比找相同，对比找不同。对比要比得出原因，有个和科学课一样的秘密：除了要比的那一点，其他条件最好都差不多。这就是“控制变量”（一次只改一个条件）。同一个班、同样的老师，一个同学天天读书，一个从不读书，作文的差别才能算到“读书”头上。对比的形式不止“一正一反”：可以是同一个人的前后对比，比如《孙权劝学》里吕蒙读书后，鲁肃惊叹“非复吴下阿蒙”；也可以是古今对比、中外对比。\n\n常见误区：一是对比点跑偏，论勤奋却比身高；二是两个对象条件差太远，拿神童和普通孩子比勤奋，比不出原因；三是只把两个例子并排放，不分析；四是为了对比把反面写得夸张失真，甚至写成“不是好人就是坏人”，滑进了非黑即白。\n\n写作时可以这样安排：分论点→正例（简）→反例（简）→“同样是……，为什么一个……一个……？关键在于……”→回扣。平时说话也能用：“如果……就会……；如果不……就会……”。","怎么认":["找正面和反面两个例子。","看对比点：是不是扣住分论点？（论勤奋就比勤奋不勤奋，别比别的）","看对比分析：比完有没有讲清原因、得出结论？"],"辨析":"对比论证和“举两个例子”不一样：举两个正面例子是举例论证；一正一反、比出高下才是对比论证。没有反面，就没有对比。","例句解析":[{"句":"论\"勤奋\"：方仲永荒废 vs 匡衡凿壁","析":"一个天赋好却荒废，一个条件差却勤奋——天赋和条件都不是决定因素，对比点正好扣住“勤奋”，结论“勤奋成就人生”就立住了。"},{"句":"提醒：对比点要扣住分论点，不能为对比而对比","析":"论勤奋却对比“谁长得高”，比得再热闹也没用——对比点跑偏，论证就跑偏。"},{"句":"课文里：《出师表》“亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也”","析":"同一个汉朝，两种用人做法，一个兴隆、一个倾颓。条件相同，只差“亲谁远谁”，所以“要亲贤臣”的结论很有力。"},{"句":"课文里：《孙权劝学》吕蒙读书前后判若两人","析":"对比不一定要找两个人。同一个人读书前后的变化，就把“读书能改变人”摆在眼前了。这叫前后对比（纵比）。"},{"句":"错例：论“勤奋”拿神童和普通孩子比成绩","析":"对比要“只差一个条件”。神童和普通孩子差的是天赋，不是勤奋，比出来的结果说明不了勤奋的作用。应该找条件相近、只在勤不勤奋上不同的两个人来比。"}],"易错":"两个坑：一是对比点跑偏（论勤奋比长相）；二是比完不分析，只把两个例子并排放，读者看不出你想说什么。比完一定要分析原因、得出结论。","练习":[{"q":"对比论证必须有什么？","options":["两个正面例子","一正一反两个例子","三个例子"],"answer":1,"解析":"一正一反、比出高下才是对比；两个正面例子只是举例论证。"},{"q":"论“坚持”，下面哪组对比最合适？","options":["小明高 vs 小刚矮","每天练跑步越跑越轻松 vs 三天打鱼一直喘","小红爱笑 vs 小军爱哭"],"answer":1,"解析":"对比点必须扣住“坚持”：天天练和三天打鱼，正好是坚持和不坚持。"},{"q":"对比完两个例子，最应该做什么？","options":["再比一组","分析原因、得出结论","直接换话题"],"answer":1,"解析":"比完要分析为什么一个成一个败，结论才有说服力；只并排放例子等于没论证。"},{"q":"《孙权劝学》里吕蒙读书前后判若两人，这属于哪种对比？","options":["同一对象前后对比","两个不同的人正反对比","不是对比"],"answer":0,"解析":"同一个人，读书前后差别巨大，是前后对比（纵比）。"},{"q":"想证明“阳光影响绿豆苗生长”，下面哪个对比最合理？","options":["一盆放阳台天天浇水、一盆放柜子从不浇水","两盆一样的苗、一样浇水，只有一盆见光","一盆绿豆苗和一盆仙人掌比"],"answer":1,"解析":"只让“见不见光”不同，其余都一样，差别才能算到阳光头上。"},{"q":"“亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也。”这句话最突出的论证方法是？","options":["举例论证","道理论证","对比论证"],"answer":2,"解析":"两种做法、两个结局正反对照，是典型的对比论证。"}],"前置知识":["概念：定义与划分"],"来源":["统编高中语文选择性必修上册第四单元《采用合理的论证方法》第1课时课堂实录（举例论证＝归纳推理；道理论证＝演绎推理；对比论证＝相反或相异的比较）：https://81952.com/yuwen/1473.html","王安石《伤仲永》原文（维基文库）：https://zh.wikisource.org/wiki/%E5%82%B7%E4%BB%B2%E6%B0%B8","教育部《成语典》“不耻下问”条，典源《论语·公冶长》：子贡问孔文子何以谓之“文”，子曰“敏而好学，不耻下问”：https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=167&la=0&q=1&webMd=2"]},{"name":"常见谬误","lv":1,"讨论卡":{"问题":"“他普通话不标准，他讲的道理肯定不对”——这是驳观点还是驳人？和家人聊聊。","提示":"认谬误时别乱扣帽子：先确认对方原话到底是什么（防稻草人误判），再确认每步因果是不是必然（防滑坡误判）。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">滑坡</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">今天不上补习班，明天就考不上大学</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">人身攻击</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">他学习不好，他的话不可信</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">偷换概念</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">辩论\\\"作业该不该多\\\"时把\\\"作业\\\"偷换成\\\"学习\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">稻草人</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">你说\\\"该减少作业\\\"，他反驳\\\"你就是不想学习\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">滑坡</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这次考砸→考不上高中→找不到工作→人生完蛋</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">诉诸权威</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"专家都说对，所以一定对\\\"</text></g></svg>","目标":"今天学会认出四种谬误：偷换概念、滑坡、人身攻击、稻草人。","类比":"谬误就像逻辑陷阱：看起来有道理，一脚踩空。","讲解":"偷换概念（白马非马式）、滑坡谬误（可能性变必然性）、人身攻击（不驳观点驳人）、稻草人（曲解对方再打）。","口诀":"偷滑人稻，谬误四套","例子":["打架区·偷换概念：“鲁迅的作品一天读不完，《孔乙己》是鲁迅的作品，所以《孔乙己》一天读不完”→去看《偷换概念》","打架区·自相矛盾：楚人夸盾“物莫能陷也”，又夸矛“于物无不陷也”（《韩非子》，统编五下《自相矛盾》）→去看《自相矛盾》","跑题区·诉诸人身：“你自己数学都不及格，凭什么说这道题解错了？”→去看《诉诸人身》","跑题区·稻草人谬误：你说“课间可以多休息”，他说“你就是想整天玩、不学习”→去看《稻草人谬误》","跑题区·转移话题：被问“作业写完了吗”，答“你看今天晚霞多好看”→去看《转移话题》","跑题区·从众：“全班都买了这款文具，所以它一定最好用”→去看《诉诸众人：大家都这样》","跑题区·诉诸权威：“一位著名歌星说这种学习法有效，所以一定有效”（歌星不是教育专家）→去看《诉诸权威：名人说的就对？》","缺证区·以偏概全：“我班三个同学近视，所以全班都近视”→去看《以偏概全》","缺证区·幸存者偏差：“老房子都特别结实，现在的房子不行”——不结实的老房子早拆了，留下来的才被看见→去看《幸存者偏差》","缺证区·相关≠因果：“冰淇淋卖得多的日子，空调也卖得多，所以吃冰淇淋让人买空调”——其实两者都因为天热→去看《相关不等于因果》","缺证区·强加因果：“我穿了红袜子，所以比赛赢了”→去看《强加因果》","缺证区·滑坡：“今天少背一个单词，期末就会不及格，以后就考不上好学校”→去看《滑坡谬误》","缺证区·赌徒谬误：“硬币连着5次正面，下一次肯定是反面”→去看《赌徒谬误》","埋雷区·非黑即白：“你不参加足球队，就是不热爱集体”→去看《非黑即白》","埋雷区·循环论证：“这本书好看，因为它就是一本好看的书”→去看《循环论证》","不算谬误：“听牙医的建议早晚刷牙”——专家讲本行的事、有根据，不是诉诸权威","不算谬误：“不复习，考试可能会丢分”——说的是“可能”、有道理，不是滑坡"],"深讲":"去动物园，先看导览图：一共有几个馆，每个馆住着哪些动物，找起来就不会晕。谬误也一样。它们的名字有几十个，一个个背会背糊涂；先学会分“区”，再听到一句怪话，就知道该去哪个区找它的名字。\n\n谬误，就是听起来有道理、其实推不出结论的说法。香港大学“批判性思考网”把常见谬误分成四大类，我们给它们起个好记的名字。①打架区（前后不一致）：同一个词前后换了意思（偷换概念），或者两句话互相打架（自相矛盾）。②跑题区（理由不相干）：不讲道理，改去攻击人（诉诸人身）；歪曲对方的话（稻草人谬误）；把话题扯开（转移话题）；拿“大家都这样”（从众）或“名人说的”（诉诸权威）当理由。③缺证区（证据不够）：几个例子就推全体（以偏概全）；只看到成功的人（幸存者偏差）；一起出现就当成因果（相关≠因果、强加因果）；把“可能”说成“必然”（滑坡）；以为运气会自己“补回来”（赌徒谬误）。④埋雷区（偷藏前提）：偷偷假定只有两种选择（非黑即白），或者先把要证明的结论当成理由（循环论证）。\n\n认谬误不是贴标签比赛。有三点要记住：第一，像谬误的不一定是谬误。听真正懂行的专家讲他本行的事，不算诉诸权威；“不复习可能考不好”说的是可能，不算滑坡。第二，一句话可能同时犯两种错，先抓最主要的那一个。第三，对方的论证有谬误，只说明这个理由不行，他的结论还可能碰巧是对的，要另外检验。\n\n听到一句可疑的话，按顺序问四个问题：前后一致吗？理由相干吗？证据够吗？有没有偷藏前提？写完作文，也拿这四问给自己查一遍。每个区里的具体招数，再到对应的专题里细学。","怎么认":["问：词的意思中途换了吗？（偷换概念）","问：每一步因果都必然吗？（滑坡）","问：反驳的是观点还是人？（人身攻击）","问：打的是对方原话，还是曲解后的靶子？（稻草人）"],"辨析":"滑坡谬误和“合理推测”不一样：“不好好复习可能考不好”是合理推测（说“可能”）；“这次考砸→找不到工作→人生完蛋”是滑坡（把可能说成必然，还一环套一环）。","例句解析":[{"句":"滑坡：这次考砸→考不上高中→找不到工作→人生完蛋（可能变必然）","析":"每一步都只是“可能”，连起来却说成了“必然”——考砸不一定考不上高中，考不上高中也不一定找不到工作，链条每环都要打问号。"},{"句":"稻草人：你说\"该减少作业\"，他反驳\"你就是不想学习\"（曲解后再打）","析":"对方原话是“减少作业”，被曲解成“不想学习”再打倒——打的是自己立的稻草靶子，不是对方真正的观点。"},{"句":"缺证区·幸存者偏差：“老房子都特别结实，现在的房子不行”","析":"先问“理由相干吗”：相干。再问“证据够吗”：只看到了留下来的老房子，倒掉、拆掉的都看不见了，证据是偏的。所以它住在缺证区。"},{"句":"跑题区·转移话题：被问“作业写完了吗”，答“你看今天晚霞多好看”","析":"前后没有打架；但晚霞和作业毫无关系，理由不相干，落在跑题区。它也违反了“说话要相关”的规矩，所以还藏着“没写完”的言外之意。"},{"句":"不算谬误：“听牙医的建议早晚刷牙”","析":"诉诸权威的毛病是“权威不懂行”或“只看名气不看证据”。牙医讲刷牙是他的本行，又有大量研究支持，这是合理引用，不进地图。"}],"易错":"认谬误时别乱扣帽子：先确认对方原话到底是什么（防稻草人误判），再确认每步因果是不是必然（防滑坡误判）。扣错帽子，自己就成了诡辩的一方。","练习":[{"q":"“他普通话不标准，他讲的道理肯定不对”犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"普通话标不标准和道理对不对没关系，攻击人而不反驳观点，是人身攻击。"},{"q":"“这本书好，因为它就是好书”犯了什么谬误？","options":["循环论证","滑坡谬误","稻草人"],"answer":0,"解析":"用结论“就是好书”来证明结论“这本书好”，原地打转，是循环论证。"},{"q":"“不喜欢数学，就是讨厌学习”犯了什么谬误？","options":["诉诸权威","非黑即白","人身攻击"],"answer":1,"解析":"不喜欢数学和讨厌学习之间还有很多情况（喜欢语文、喜欢画画），硬说成只有两种，是非黑即白。"},{"q":"“你不参加足球队，就是不热爱集体。”在谬误地图的哪个区？","options":["缺证区","埋雷区：偷偷假定只有两种选择","打架区"],"answer":1,"解析":"它偷藏了“不参加足球队＝不热爱集体”这个前提，好像只有两种可能，是非黑即白。"},{"q":"“老房子都特别结实，现在的房子不行”——问题出在哪？","options":["跑题区：攻击了人","缺证区：只看到留下来的老房子，倒掉的看不见","打架区：词义变了"],"answer":1,"解析":"不结实的老房子早就拆了，留下来的才被看见，这是幸存者偏差，住在缺证区。"},{"q":"下面哪一句不算谬误？","options":["“歌星说这种学习法有效，所以一定有效”","“听牙医的建议，早晚刷牙”","“大家都这么做，所以一定对”"],"answer":1,"解析":"牙医讲本行的事，有根据，是合理引用；另外两句分别是诉诸权威和从众。"}],"动画":{"steps":[{"tokens":["滑坡：","不上补习班","→","考不上大学"],"note":"可能性被说成必然性：每环因果经得起问吗？"},{"tokens":["人身攻击：","他成绩差","→","话不可信"],"note":"不驳观点驳人：成绩差≠观点错"},{"tokens":["稻草人：","曲解对方","→","打倒假想敌"],"note":"先歪曲再反驳：打的是自己立的靶子"}]},"小测":[{"q":"\"你这么胖，还好意思谈健康饮食？\"犯了什么谬误？","options":["滑坡谬误","人身攻击","偷换概念"],"answer":1,"解析":"攻击人而不反驳观点，是人身攻击。"}],"前置知识":["举例论证","道理论证"],"地图":{"打架区（前后不一致）":{"先问":"同一个词、同一件事，前后说法一致吗？","专题":["偷换概念","自相矛盾"],"备注":"都和《四大逻辑规律》有关：偷换概念违反同一律，自相矛盾违反矛盾律。"},"跑题区（理由不相干）":{"先问":"给出的理由，真的和结论有关吗？","专题":["诉诸人身","稻草人谬误","转移话题","诉诸众人：大家都这样","诉诸权威：名人说的就对？"],"备注":"诉诸情感（拿眼泪、同情代替证据）也住在这里。统编教材把“转移论题”归为违反同一律，所以它和打架区是邻居。"},"缺证区（证据不够）":{"先问":"证据够不够撑起这么大的结论？","专题":["以偏概全","幸存者偏差","相关不等于因果","强加因果","滑坡谬误","赌徒谬误"],"备注":"多数是“坏掉的归纳”或“坏掉的因果”，可以先学《推理三兄弟：演绎/归纳/类比》《归纳的强与弱》《证据够不够》和《因果链：多米诺》。"},"埋雷区（偷藏前提）":{"先问":"有没有偷偷塞进一个没说出口、又站不住的前提？","专题":["非黑即白","循环论证","复杂问语"],"备注":"“你还在偷懒吗？”这类复杂问语也住这里：怎么回答都等于承认自己偷过懒。想练“揪出藏起来的前提”，可以先学《隐含前提》。"}},"来源":["Joe Lau《批判性思考网》F06 List of fallacies：https://philosophy.hku.hk/think/fallacy/list.php","Joe Lau《批判性思考网》F03 Irrelevance（不相干：诉诸同情、大众、传统、权威，攻击提出者）：https://philosophy.hku.hk/think/fallacy/ir.php","Joe Lau《批判性思考网》F04 Insufficiency（证据不足：样本有限等）：https://philosophy.hku.hk/think/fallacy/is.php","Joe Lau《批判性思考网》F05 Inappropriate presumption（不当预设：复杂问句、偷藏前提、循环）：https://philosophy.hku.hk/think/fallacy/ip.php"]}]},{"id":"tuili","name":"日常语言推理","items":[{"name":"言外之意","lv":1,"讨论卡":{"问题":"问蛋糕好吃吗，答“盘子很漂亮”——真意思是什么？和家人聊聊你是怎么听出来的。","提示":"找言外之意，就是找“哪里违反了规矩”。"},"图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">蛋糕好吃吗？答：盘子很漂亮。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">妈妈</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"你房间真'整洁'啊！\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">问</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">这道题难吗？答：全班最高分60。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"你先走吧，我还有点事\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">\\\"改天请你吃饭\\\"</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">识别</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">违反\\\"相关</text></g></svg>","目标":"今天学会听出言外之意：话里没明说的意思。","类比":"言外之意就像冰山：说出口的只是水面上的尖，意思藏在水下。","讲解":"合作原则：说话默认 truthful、相关、清楚。违反处即有言外之意。","口诀":"话里有话藏水下，违反常规是信号","例子":["问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）","妈妈：\"你房间真'整洁'啊！\"（=乱得不行，反话）","问：这道题难吗？答：全班最高分60。（=很难）","\"你先走吧，我还有点事\"（=不想跟你一起走）","\"改天请你吃饭\"（=客套话，不必当真）","识别：违反\"相关","清楚\"的地方，就有言外之意","问：电影好看吗？答：还行。（=一般，没直说不好看）","爸爸：\"你的袜子在阳台上晒太阳呢！\"（=袜子晒好了，快去收）","问：这件衣服贵吗？答：也就我一个月零花钱吧。（=很贵）","\"我等了你一个世纪！\"（=等了很久，别迟到了）","课文里：《杨氏之子》孔君平说杨梅“此是君家果”，孩子答“未闻孔雀是夫子家禽”（＝杨梅也不是我家的果）","课文里：晏子说“使狗国者，从狗门入。今臣使楚，不当从此门入”（＝你让我钻狗门，就等于承认楚国是狗国）","问：小明数学怎么样？答：他字写得很工整，上课从不迟到。（＝数学可能一般，违反“适量”和“相关”）","睡前妈妈说：“都九点了。”（＝该睡觉了，陈述句里藏着要求）","能收回：“有些同学交了作业”通常暗示“不是全部”，但老师补一句“其实全交了”也不算说错","成语：弦外之音、话里有话、旁敲侧击——都是不直说，让人自己体会","反例：问“几点了？”答“三点。”——直接回答，没有言外之意，别硬挖"],"深讲":"统编五年级下册《杨氏之子》里，孔君平指着杨梅逗九岁的杨家孩子：“此是君家果。”孩子马上回答：“未闻孔雀是夫子家禽。”他一个“不”字都没说，孔君平却听懂了：杨梅要是你杨家的果，孔雀就该是我孔家的鸟；既然孔雀不是我家的鸟，杨梅也就不是你家的果。这就是言外之意。\n\n英国哲学家格赖斯提出过“合作原则”：聊天时，我们默认对方在好好合作，说话会①真实（不说假话）、②适量（不多也不少）、③相关（扣着话题）、④清楚（不含糊、有条理）。如果一句话表面上违反了这些规矩，说话的人又不像在捣乱，听的人就会去找它背后的意思，这就是言外之意（也叫会话含义）。比如问“这道题难吗？”，回答“全班最高分60”。表面上没回答难不难，可我们相信对方在好好答，就能推出：很难。\n\n常见误区有三个。第一，过度解读：别人直说的话，不要硬挖弦外之音。第二，言外之意是推出来的，所以说话人可以收回。“有些同学交了作业”通常让人以为“不是全部”，老师补一句“其实全交了”也不算说错，所以推出来的意思只是“很可能”。第三，它和说谎、和转移话题都不一样：说谎是想让你相信假话；转移话题是故意躲开问题；言外之意是换一种方式回答，还盼着你听懂。\n\n读课文时，遇到人物答非所问、说反话、话说一半，就问一问：他为什么这样说？晏子说“使狗国者，从狗门入”，没有一个字骂楚国，楚王却不得不开大门。说话时，委婉拒绝、提醒别人可以用言外之意；可是遇到时间、地点、安全这类要紧事，一定要直说。","怎么认":["先听字面：他原话是什么意思？","再找违规：答非所问？反话？含糊其辞？客套话？","最后推真意：结合场合，他真正想说的是什么？"],"辨析":"言外之意和“说谎”不一样：说谎是想让你相信假话；言外之意是说话人默认你能听懂——“盘子很漂亮”不是骗你蛋糕好吃，是委婉告诉你“不好吃”。一个是骗，一个是暗示。","例句解析":[{"句":"问：蛋糕好吃吗？答：盘子很漂亮。（=不好吃）","析":"问蛋糕，答盘子——违反了“相关”规矩。故意不提蛋糕，就是在委婉说“蛋糕不好吃，不好意思直说”。"},{"句":"妈妈：\"你房间真'整洁'啊！\"（=乱得不行，反话）","析":"房间明明很乱，妈妈却说“整洁”——故意违反“说真话”规矩。反着说，就是要你听出“乱得不行，快收拾”。"},{"句":"课文里：《杨氏之子》孩子答“未闻孔雀是夫子家禽”","析":"孩子没有直接反驳，而是照着对方的思路造了一句：照你的说法，姓孔就该和孔雀是一家。孔君平自己就能推出“杨梅不是杨家果”。“未闻”比“不是”委婉，既机智又有礼貌。"},{"句":"问：小明数学怎么样？答：他字写得很工整，上课从不迟到。","析":"问的是数学，答的是写字和守时，说了不少，偏偏不提数学，违反了“适量”和“相关”。说话人不像在捣乱，听的人就能推出：数学大概不怎么样，只是不好意思直说。"},{"句":"能收回：“有些同学交了作业”通常暗示“不是全部”","析":"说“有些”会让人想到“不是全部”，因为如果全交了，说“全都交了”信息更足。不过这层意思可以被收回，所以言外之意只是“很可能”，要结合场合确认。"}],"易错":"别把所有话都听出言外之意：“改天请你吃饭”是客套，但“明天请你吃饭”就是真约——场合和说法决定有没有言外之意；直说的话，别硬找弦外之音。","练习":[{"q":"问：电影好看吗？答：还行。这句话的言外之意最可能是？","options":["电影很好看","电影一般，没直说不好看","电影还没上映"],"answer":1,"解析":"“还行”含糊其辞，没直说“好看”——违反“说清楚”规矩，真意是“一般”。"},{"q":"“你的袜子在阳台上晒太阳呢！”爸爸真正想说的是？","options":["袜子喜欢晒太阳","快去把袜子收回来","阳台阳光很好"],"answer":1,"解析":"这不是讲袜子，是提醒：袜子晒好了，快去收——暗示藏在陈述句里。"},{"q":"下面哪句是反话（言外之意和字面相反）？","options":["你房间真整洁啊（房间很乱时）","明天请你吃饭","我作业写完了"],"answer":0,"解析":"房间乱却说“整洁”，字面和真意相反，是反话；另外两句是直说。"},{"q":"《杨氏之子》里“未闻孔雀是夫子家禽”的言外之意是？","options":["孔雀是孔家养的鸟","杨梅也不是我杨家的果","孩子没听说过孔雀"],"answer":1,"解析":"照孔君平的说法，孔雀就该是孔家的鸟；孔雀不是，所以杨梅也不是杨家的果。"},{"q":"问“小明数学怎么样？”答“他字写得很工整，上课从不迟到。”言外之意最可能是？","options":["小明数学很好","小明数学可能一般，回答的人不好意思直说","小明字写得不好"],"answer":1,"解析":"答了很多却偏偏避开数学，违反了“适量”和“相关”，暗示数学一般。"},{"q":"言外之意和说谎的区别是？","options":["没有区别","说谎想让你相信假话；言外之意是盼你听懂没明说的真意","言外之意说的都是坏话"],"answer":1,"解析":"“盘子很漂亮”不是骗你蛋糕好吃，而是委婉地告诉你真意。"}],"决策树":"①先听字面：他原话是什么意思？→②再找违规：答非所问？反话？含糊其辞？客套话？→都没违规：按字面理解→有违规：结合场合推真意→③验证：真意符合说话人身份和场合吗？→符合：就是言外之意→不符合：重新推","前置知识":[],"来源":["Stanford Encyclopedia of Philosophy「Implicature」（格赖斯合作原则与量、质、关系、方式四条准则；会话含义可被取消）：https://plato.stanford.edu/entries/implicature/","统编五年级下册《杨氏之子》原文与教学设计（“未闻孔雀是夫子家禽”的言外之意）：https://www.yuwenmi.com/jiaoan/wunianji/5342265.html","统编五年级下册文言阅读训练（含《晏子使楚》节选“使狗国者，从狗门入”）：https://zy.21cnjy.com/20214003"]},{"name":"因果链：多米诺","lv":1,"讨论卡":{"问题":"“多吃一块糖所以长胖了”——这条链真的连上了吗？和家人一环一环问下去。","提示":"放大必须每环都真，不能为了效果硬推。"},"目标":"今天学会连续问五个为什么，一直找到根因。","类比":"因果就像多米诺骨牌：失了一颗铁钉，丢了一只马掌，亡了一个帝国。","图示":"<svg viewBox=\"0 0 640 240\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">少一颗铁钉</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">小原因</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">掉马掌→折战马→伤将军</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">环环相扣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">亡一个帝国</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大后果</text></g><text x=\"320\" y=\"220\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2c3328\" opacity=\"0\">因果链=多米诺：五个为什么问到底<animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.4s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/></text></svg>","练习":[{"q":"“忘带红领巾→被扣分→班级丢了流动红旗”这是？","options":["普通因果","多米诺（小因大果）","没有因果"],"answer":1,"解析":"起点只是忘带红领巾，终点却是全班丢红旗——小起因放大成大结果，是多米诺。"},{"q":"“每天读10分钟→一学期读完六本→作文有话写了”说明了什么？","options":["读书没用","小习惯顺着链条会放大","作文不用练"],"answer":1,"解析":"每天10分钟很小，顺着链条传下去，变成了一学期六本、作文有话写——好习惯的多米诺。"},{"q":"“我今天多吃了一块糖，所以长胖了”错在哪里？","options":["糖不能吃","一小因推不出大果，链条没连上","长胖写错了"],"answer":1,"解析":"一块糖和长胖之间没有连上的链条——硬放大就是错的，不是多米诺。"},{"q":"“多喝水→成绩变好”错在哪里？","options":["水喝得不够多","中间缺环节，链条不牢","成绩不能变好"],"answer":1,"解析":"喝水和成绩之间没有链条——缺了环节直接跳，就是断链。"},{"q":"“成绩下滑”用5个为什么找根因，第一步问什么？","options":["为什么成绩下滑","为什么要考试","为什么有学校"],"answer":0,"解析":"从结果往回问：为什么下滑？→没听懂→为什么没听懂？→上课困……一环一环问到底。"},{"q":"下面哪条是完整的因果链？","options":["早上没吃早饭→考试失利","多读书→词汇量大→作文好→语文高分","公鸡打鸣→天亮"],"answer":1,"解析":"读书→词汇→作文→高分，每环都经得起问为什么；A跳环，C是相关不是因果。"},{"q":"公鸡天亮前就打鸣，能说“公鸡打鸣让天亮了”吗？","options":["能，因为打鸣在先","不能，公鸡靠体内生物钟提前打鸣，天亮是地球自转造成的","能，因为每天都是这样"],"answer":1,"解析":"先后出现、天天一起出现，都不等于因果。"},{"q":"多米诺式因果链和滑坡谬误的区别是？","options":["没有区别","因果链每一环都确实成立；滑坡把每环的“可能”说成“必然”","滑坡的链条更短"],"answer":1,"解析":"区别不在链条长短，而在每一块牌是不是真的会推倒下一块。"}],"动画":{"steps":[{"tokens":["少了","一颗铁钉"],"note":"起点：小得不起眼"},{"tokens":["丢了","一只马掌"],"note":"连锁：铁钉→马掌"},{"tokens":["亡了","一个帝国"],"note":"终点：蝴蝶效应"}]},"讲解":"找因果要一环扣一环，每环都问\"为什么\"，连续问5次到根因。","口诀":"因果链条环环扣，五个为什么问到底","小测":[{"q":"\"因为他是北方人，所以思想守旧\"错在哪环？","options":["籍贯推不出思想","北方人确实守旧","没错"],"answer":0,"解析":"籍贯→思想这环因果不成立，是强加因果。"}],"例子":["完整链：少一颗铁钉→掉一只马掌→折一匹战马→伤一位将军→败一场战争→亡一个帝国","五问法：成绩下滑→为什么没听懂→为什么上课困→为什么熬夜→为什么玩手机→根因：缺自律","反例：公鸡打鸣→天亮（把\"相关\"当\"因果\"，还颠倒了）","反例：熬夜→考不上大学（跳了三环，链条不牢）","口诀应用：环环相扣+五个为什么问到底","小原因大后果：忘带红领巾→被扣分→班级丢了流动红旗→全班一周的努力白费","小习惯大变化：每天读10分钟→一个月读完一本书→一学期读完六本→作文有话写了","推倒第一块：早上赖床10分钟→赶不上校车→迟到→错过早读→一天都心慌","反例：只推倒一块牌，别的牌没动——\"我今天多吃了一块糖，所以长胖了\"（一小因推不出大果，链条没连上）","好习惯多米诺：整理书包→第二天不慌→上课专注→作业写得快→有空多读一本书","熬夜→上课犯困→听不懂→成绩下滑→考不上高中（每环都经得起问为什么）","多读书→词汇量大→作文好→语文高分（链条完整）","断链反例：早上没吃早饭→考试失利（中间缺环节，链条不牢）","写作：议论文\"因果论证\"就是摆出一条完整因果链","多运动→身体壮→不容易生病→少请假→功课不掉队（链条完整）","上课走神→笔记没记全→复习没材料→考试丢分（每环都问为什么）","断链反例：多喝水→成绩变好（中间缺环节：喝水和成绩没有链条）","五问法：字写不好→为什么？练得少→为什么练得少？没安排时间→为什么没安排？玩手机占了时间→根因：时间管理","古文里：扁鹊见蔡桓公，病从腠理到肌肤、肠胃、骨髓，一步步加深，最后无药可医（《韩非子·喻老》）","成语：千里之堤，溃于蚁穴（化用《韩非子·喻老》“千丈之堤，以蝼蚁之穴溃”）","名言：“勿以恶小而为之，勿以善小而不为”（刘备遗诏，见《三国志·蜀书·先主传》裴松之注）——小事会累积成大事","五问法（丰田大野耐一的例子）：机器停了→保险丝断了→轴承润滑不够→油泵抽油不足→泵轴磨损→没装过滤网，铁屑掉进去了（根因：装上过滤网）","好习惯的多米诺：《老子》“合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下”"],"深讲":"《韩非子·喻老》里有个故事：扁鹊见蔡桓公，说“君有疾在腠理”，桓公说“寡人无疾”。十天后病到了肌肤，又十天到了肠胃，桓公都不理。再过十天，病进了骨髓，扁鹊只好转身就走。韩非子总结说：“千丈之堤，以蝼蚁之穴溃。”小毛病不处理，就会一环推一环，变成大祸。西方也有一首老谚语：少了一颗钉子，掉了马掌；掉了马掌，丢了战马；丢了战马，失了骑手……富兰克林在1758年的《穷理查年鉴》里写下过它的长版本。\n\n因果链，就是“A导致B，B导致C……”一环接一环。顺着往下看，像推倒第一块多米诺骨牌，小原因可能放大成大结果。倒着往上追，就是“连问五个为什么”。丰田公司的大野耐一举过一个例子：机器为什么停了？保险丝断了。为什么断？轴承润滑不够。为什么不够？油泵抽油不足。为什么不足？泵轴磨损了。为什么磨损？没装过滤网，铁屑掉了进去。装上过滤网，问题才算真正解决。“五”不是死规定，问到能动手解决的根因就可以停。\n\n最要紧的是：每一环都必须真的成立。链条越长，只要每环都有一点“不一定”，整条链就越靠不住。常见的错有三种：一是跳环、断链，比如“多喝水→成绩变好”；二是把“一起出现”当成因果，比如公鸡打鸣和天亮，研究发现公鸡靠体内的生物钟，在天亮前两三个小时就开始叫，天是因为地球自转才亮的，不是公鸡叫亮的；三是把每一环的“可能”说成“必然”，这就成了滑坡谬误，比如“没吃早饭→考砸→考不上高中→这辈子完了”。\n\n写议论文用因果论证时，把链条一环环写出来，用“因为……所以……”“于是”“进而”连接，结尾可以落到“防微杜渐”。遇到问题，就用五问法找根因，从根上改。平时说话多用“可能会”“容易导致”，别把链条说死。","怎么认":["找第一块牌：最小的那个起因是什么？","顺着看：它推倒了什么？那一块又推倒了什么？","看到终点：小起因是不是变成了大结果？是，就是多米诺。","把事情写成一串：A→B→C→D。","对每一环问“为什么”：B真的是A造成的吗？","有一环答不上来，就是断链——结论不可靠。"],"辨析":"多米诺和普通因果链的区别在“放大”：普通因果链只要求环环相扣；多米诺还要求越传越大——小起因、大终点。如果起因和结果差不多大（多喝水→多上厕所），那只是因果链，不是多米诺。","例句解析":[{"句":"完整链：少一颗铁钉→掉一只马掌→折一匹战马→伤一位将军→败一场战争→亡一个帝国","析":"起点只是一颗铁钉，终点却是一个帝国——每一环都比前一环大，这就是多米诺的“放大”。"},{"句":"反例：公鸡打鸣→天亮（把\"相关\"当\"因果\"，还颠倒了）","析":"公鸡打鸣和天亮只是同时出现，不是因果；真要说，也是天亮在前、打鸣在后——相关≠因果，因果还说反了。"},{"句":"熬夜→上课犯困→听不懂→成绩下滑→考不上高中（每环都经得起问为什么）","析":"每环都能问“为什么”：为什么犯困？因为熬夜。为什么听不懂？因为犯困。一环扣一环，链条才牢。"},{"句":"断链反例：早上没吃早饭→考试失利（中间缺环节，链条不牢）","析":"没吃早饭和考试失利之间缺了好几环（饿→没精神→没发挥好），直接跳过去就是断链——不能这么推。"},{"句":"古文里：扁鹊见蔡桓公，病从腠理到肌肤、肠胃、骨髓，一步步加深","析":"每一环都有原因：不治，病就往深处走。每环都站得住，所以“小病要早治”的结论很有力。这就是“防微杜渐”。"},{"句":"对照（滑坡）：没吃早饭→考砸→考不上高中→这辈子完了","析":"每一环都只是“可能”，却被说成“一定”，连起来就成了滑坡谬误。真正的多米诺要求每块牌确实能推倒下一块。"}],"易错":"多米诺最容易犯的错是“硬放大”：一小因推不出大果时，链条其实没连上（“多吃一块糖所以长胖了”）。放大必须每环都真，不能为了效果硬推。","决策树":"①找第一块牌：最小的那个起因是什么？→②顺着看：它推倒了什么？那一块又推倒了什么？→③到终点：小起因变成大结果了吗？→是：多米诺成立→否：链条中断，找断点→④警惕：每环都必然吗？→有偶然环：多米诺夸大，降级为\"可能\"","前置知识":["因果复句"],"来源":["《韩非子·喻老》原文（维基文库）：“千丈之堤，以蝼蚁之穴溃”及扁鹊见蔡桓公：https://zh.wikisource.org/wiki/%E9%9F%93%E9%9D%9E%E5%AD%90/07","Wikipedia「For want of a nail」（乔治·赫伯特1640年收录；富兰克林1758年《穷理查年鉴》较长版本）：https://en.wikipedia.org/wiki/For_want_of_a_nail","Lean Enterprise Institute「5 Whys」（大野耐一机器停机例；“五”不是重点，问到根因为止）：https://www.lean.org/lexicon-terms/5-whys/","名古屋大学新闻稿 Cock-a-doodle-doo: No Need for an Alarm Clock（Shimmura & Yoshimura 2013，Current Biology：公鸡在天亮前2–3小时受生物钟控制打鸣）：https://en.nagoya-u.ac.jp/news/articles/aip_highlights_042/","《三国志·蜀书·先主传》裴松之注引《诸葛亮集》刘备遗诏“勿以恶小而为之，勿以善小而不为”：http://www.guoxue123.com/shibu/0101/00sgz/031.htm"]}]},{"id":"miuwu_lunzheng","name":"吵架时的逻辑陷阱","items":[{"name":"偷换概念","lv":2,"目标":"今天学会认出偷换概念：同一个词，前后悄悄换了意思，还被拿来推结论。","类比":"偷换概念像魔术师换牌：你一直盯着“同一张牌”，其实它半路已经被换掉了。字没变，意思变了。","讲解":"一段话里同一个词前后意思不一样，却被当成一样的意思来推理或反驳。","口诀":"一个词换了脸，前后对照就看穿","例子":["错例：鲁迅的作品不是一天能读完的，《孔乙己》是鲁迅的作品，所以《孔乙己》一天读不完。（前一个“作品”指他写的全部作品，后一个只指一篇）","改：鲁迅的全部作品一天读不完，但《孔乙己》这一篇，一天就能读完。","错例：老师说要“有个性”，所以我不交作业，这就是我的个性。（老师说的个性是有自己的想法和特长，不是不守规矩）","改：老师说的“有个性”是有自己的想法和特长；按时交作业和有个性一点也不冲突。","错例：我们班是“优秀班集体”，我是这个班的，所以我是优秀学生。（“优秀班集体”夸的是整个班，不等于班里每个人都优秀）","改：我们班被评为优秀班集体，是大家一起努力的结果；我自己优不优秀，要看我自己的表现。","笑话里：杰克说爸爸的座右铭是“给予胜于接受”，老师夸爸爸善良，结果爸爸是拳击运动员——“给予”从“送东西给人”变成了“给人一拳”。","课文里：惠子问庄子“你怎么（安）知道鱼快乐”，庄子最后答“我是在濠水桥上知道的”，把“安＝怎么”悄悄换成了“安＝在哪里”。","不算：同学上午说“这道题太难了”，下午说“现在不难了，我会了”——是事情变了（他学会了），不是偷换概念。","不算：妈妈说“这孩子真能吃”，又说“这个苹果坏了不能吃”——两句话各说各的，没拿来推结论，只是一个词有两种意思。"],"深讲":"一个词就像一个装着意思的盒子。讲道理的时候，同一个盒子里装的东西必须从头到尾不变，这叫同一律（同一次讨论里，一个词的意思要保持一样）。偷换概念的人，嘴上一直用同一个词，暗地里却把盒子里的东西换了。比如“作品”，一会儿指鲁迅写过的所有文章，一会儿只指其中一篇；“优秀班集体”，说的是整个班，却被拿来夸某一个人。因为字一模一样，听的人很容易被骗过去。识破它的办法很简单：把这个词在每一处的意思，用自己的话分别说出来，摆在一起比一比。意思一样，推理才算数；意思不一样，就是偷换了。吵架时对方说“这可是你自己说的呀”，先别急，问一句：我说的那个词，和你现在用的，是一个意思吗？","怎么认":["找出前后反复出现的那个关键词。","用自己的话分别说出它每一处的意思。","比一比：意思不一样，却被拿来推结论或反驳人，就是偷换概念。"],"辨析":"和“转移话题”比：偷换概念时话题看起来没变，变的是其中一个词的意思；转移话题是整个话题被换成了另一件事。和“自相矛盾”比：自相矛盾是同一个意思前后打架；偷换概念是同一个词前后根本不是一个意思。","例句解析":[{"句":"鲁迅的作品不是一天能读完的，《孔乙己》是鲁迅的作品，所以《孔乙己》一天读不完。","析":"第一个“作品”是“全部作品”这一大堆，第二个“作品”是其中一篇。一大堆读不完，不代表其中一篇也读不完。把两个“作品”的意思说清楚，错误就露出来了。"},{"句":"我们班是优秀班集体，我是这个班的，所以我是优秀学生。","析":"“优秀班集体”是给整个班的评价（集合概念：把一群当成一个整体来说），不能直接搬到每一个人身上。就像“森林很大”，不等于每一棵树都很大。"},{"句":"老师说要有个性，所以我不交作业就是有个性。","析":"老师的“个性”是有自己的想法和特长，小朋友把它换成了“想怎么样就怎么样”。同一个词，两个意思，结论自然站不住。"}],"易错":"一个词本来就可以有好几个意思（多义词），这很正常；只有把不同的意思当成同一个，拿来推结论或反驳别人，才是偷换概念。另外，事情本身变了（以前难、现在不难了）也不算偷换。","练习":[{"q":"“中国人是勤劳勇敢的，小明是中国人，所以小明一定勤劳勇敢。”问题出在哪？","options":["“中国人”前后意思变了：前面说整个民族，后面说某一个人","小明不是中国人","勤劳勇敢不是好品质"],"answer":0,"解析":"“中国人是勤劳勇敢的”是夸整个民族，不能直接推出每一个人都勤劳勇敢，这是把整体的说法偷换到个人身上。"},{"q":"下面哪句没有偷换概念？","options":["老师说要“节约”，所以我连作业本都不用了","这道题我上周不会，这周学会了","书上说“开卷有益”，所以考试时也可以翻书"],"answer":1,"解析":"B是自己的情况变了，词的意思没变。A把“节约”换成“什么都不用”；C把“开卷＝打开书读”换成了“考试开卷”。"},{"q":"识破偷换概念，最关键的一步是？","options":["看谁说话声音大","把反复出现的词每一处的意思分别说出来比一比","数一数句子有几个字"],"answer":1,"解析":"偷换概念藏在“字一样、意思不一样”里，把每一处的意思说出来一比，就看穿了。"}],"讨论卡":{"问题":"老师说“写作业要认真”，弟弟说“我认真玩了一下午，所以我是认真的孩子”。和家人一起找找：哪个词换了脸？","提示":"把两个“认真”各自指什么说出来：一个是认真做该做的事，一个是专心地玩。意思不同，就不能拿来推结论。"},"前置知识":["概念：定义与划分","四大逻辑规律"],"决策树":"①找出前后反复出现的关键词→②用自己的话分别写出每一处的意思→③意思一样吗？→一样：不是偷换概念，转查其他错误→不一样：④它被拿来推结论或反驳别人了吗？→是：偷换概念，先把词的意思说清楚再推→否：只是一个词有几种意思，各说各的，不算谬误","来源":["统编高中语文选择性必修上册第四单元「发现潜藏的逻辑谬误」备课资料·同一律、矛盾律、排中律（偷换概念/转移论题/林肯驳“不是黑就是白”）：http://www.yinruiwen.net/news/193795.htm","统编高中语文选择性必修上册《逻辑的力量》第2课时教学设计·发现潜藏的逻辑谬误（下）（“鲁迅的作品”偷换概念、“手指浸到汤里”偷换论题、庄子“安知鱼乐”）：http://www.yinruiwen.net/news/194568.htm","Stanford Encyclopedia of Philosophy「Fallacies」：https://plato.stanford.edu/entries/fallacies/"]},{"name":"稻草人谬误","lv":2,"目标":"今天学会认出稻草人谬误：先把对方的话改歪，再去打那个改歪了的假观点。","类比":"打不过真正的对手，就扎一个稻草人，给它贴上对手的名字，一拳打倒，还大喊“我赢了”——可真正的对手根本没被碰到。","讲解":"把对方的观点说得更极端、更离谱，或者加上他没说过的意思，然后反驳这个假观点。","口诀":"歪曲观点扎草人，打倒草人不算赢","例子":["错例：小美说“周末可以少看一会儿动画片”，小刚说“你是说一辈子都不许看动画片？那多没意思！”（小美说的是“少看”，被改成了“永远不许看”）","改：小刚说“少看多少合适呢？我觉得一天看一集还行。”","错例：妈妈说“玩具玩完要收好”，孩子说“你就是不想让我玩玩具！”（“收好”被改成了“不许玩”）","改：孩子说“好，我玩完就收，下次还能马上找到。”","错例：班会上小林说“值日可以按小组轮流”，小东说“小林就是想让别人替他干活！”（轮流是每组都干，被改成了“别人替他干”）","改：小东说“按小组轮流的话，人少的组会不会太累？我们再商量一下。”","家里：哥哥说“晚饭能不能少放点辣”，有人回“你就是嫌我做的饭难吃”——“少放辣”被扎成了“饭难吃”。","不算：小美说“周末少看动画片”，小刚说“我不同意，周末本来就是休息的，看两集也不影响学习”——小刚反驳的就是小美的原话，不是稻草人。","不算：“你的意思是每天只看一集吗？如果是，我觉得太少了。”——先问清楚、再说自己的看法，没有歪曲对方。","小诀窍：反驳之前，先把对方的话复述一遍，问一句“你是这个意思吗？”，就不容易扎出稻草人。"],"深讲":"吵架时，有人会偷偷用一招：不去反驳你真正说的话，而是先把你的话“加工”一下——说得更绝对、更夸张、更好笑，然后再去驳倒这个加工品。这就是稻草人谬误。比如你说“课间少追跑，注意安全”，他回“那你是想让大家课间都坐着不动吗？”。你明明没这么说，可旁边的人一听，好像你的主意很荒唐。这一招错在两个地方：第一，你根本没说过那句话；第二，就算那句夸张的话被驳倒了，你原来的话也一点没有被驳倒。所以遇到稻草人，不用生气，只要冷静地把原话再说一遍：“我说的是少追跑，不是不许动。”反过来，我们自己反驳别人时，也要先把对方的话听准、复述准，打真人，不打草人。","怎么认":["先找到对方的原话，一个字一个字看清楚。","再看反驳的人说对方“主张”的是什么。","两个一比：被说得更极端、更离谱，或加了对方没说的意思，就是稻草人。"],"辨析":"和“转移话题”比：稻草人还在谈同一件事，只是把对方的观点改歪了；转移话题是干脆聊到别的事上去了。和“诉诸人身”比：稻草人歪曲的是对方的“话”，诉诸人身攻击的是说话的“人”。","例句解析":[{"句":"小美：周末可以少看一会儿动画片。小刚：你是说一辈子都不许看动画片？","析":"小美的原话是“少看一会儿”，小刚说成“一辈子不许看”，观点被夸张到了极端。驳倒“一辈子不许看”很容易，可小美根本没这么说。"},{"句":"小林：值日可以按小组轮流。小东：小林就是想让别人替他干活！","析":"“轮流”的意思是每个小组都要干，小东却说成“别人替小林干”，给小林加上了他没说过、也没有的意思。这是把观点改歪了再攻击。"}],"易错":"不是所有“反驳得很厉害”的话都是稻草人。只要反驳的正是对方的原意，哪怕说得很直接，也不算稻草人。关键看：对方真的这么说、这么想了吗？","练习":[{"q":"爸爸说“吃饭时不要看平板”，女儿说“你就是想让我什么都不知道，跟不上同学！”女儿犯了什么错？","options":["稻草人谬误：把“吃饭时不看”改成了“什么都不让知道”","没有错，她说得有道理","循环论证"],"answer":0,"解析":"爸爸只说吃饭时不看，女儿把它夸张成“什么都不让你知道”，再去反对这个夸张的说法。"},{"q":"小红说“图书角的书看完要放回原处”。下面哪个回答没有扎稻草人？","options":["你就是不想让大家看书！","放回原处好是好，可书架太高，低年级够不着，能不能换个低一点的书架？","那以后谁都别碰图书角了！"],"answer":1,"解析":"B讨论的就是“放回原处”这件事本身，还提出了问题和办法；A和C都把小红的话改成了她没说过的极端意思。"},{"q":"遇到别人对你扎稻草人，最好的做法是？","options":["也给对方扎一个稻草人","冷静地把自己的原话再说清楚","不说话，认输"],"answer":1,"解析":"稻草人打倒的不是你的观点。把原话说清楚，讨论就能回到正轨。"}],"讨论卡":{"问题":"你有没有被别人“改歪”过自己的话？比如你说“想晚点睡”，却被说成“你想天天熬夜”。和家人演一演：怎么把话拉回原意？","提示":"先平静地复述原话，再说清楚自己没说的部分：“我说的是周五晚睡半小时，不是天天熬夜。”"},"前置知识":["常见谬误","言外之意"],"决策树":"①找出对方的原话→②找出反驳者说对方主张的是什么→③两者意思一样吗？→一样：不是稻草人，再看反驳的理由好不好→不一样：④是被说得更极端、更离谱，或者加了对方没说过的意思吗？→是：稻草人谬误，回到原话重新讨论→否：可能只是没听清，先问一句“你是这个意思吗？”","来源":["Joe Lau《批判性思考网》Critical Thinking Web · F06 List of fallacies：https://philosophy.hku.hk/think/fallacy/list.php","Stanford Encyclopedia of Philosophy「Fallacies」：https://plato.stanford.edu/entries/fallacies/","Internet Encyclopedia of Philosophy「Fallacies」：https://iep.utm.edu/fallacy/"]},{"name":"诉诸人身","lv":2,"目标":"今天学会认出诉诸人身（拿“这个人怎么样”当理由）：不管道理对不对，只盯着说话的人。","类比":"像裁判不看球进没进门，只看踢球的人顺不顺眼——球进了就是进了，跟谁踢的没关系。","讲解":"用对方的成绩、年龄、性格、过去或“他肯定有私心”来否定他的观点，却不去看观点本身对不对。","口诀":"揪着人不放，道理靠边站；对事不对人，理由才算真","例子":["错例：小明说“这道题应该先算括号里的”，小刚说“你上次才考70分，你说的不算！”（先算括号对不对，和小明考几分没关系）","改：小刚说“我们翻开数学书看看运算顺序，确认一下。”","错例：弟弟提醒“过马路要看红绿灯”，哥哥说“你才上一年级，懂什么！”（年纪小，不会让这句话变错）","改：哥哥说“你说得对，红灯停，绿灯行。”","错例：小红建议“图书角排一张借书登记表”，有人说“她就是想当图书管理员才这么说”。（猜动机，代替了讨论建议本身好不好）","改：大家讨论“登记表能不能让书少丢一点？登记会不会太麻烦？”","童话里：《皇帝的新装》里小孩说“他什么也没穿”，要是大人回一句“小孩子的话不能信”，就是诉诸人身——真话不会因为是小孩说的就变假。","不算：选值日组长时说“小李这学期常忘记值日，我觉得他暂时不适合当组长”——这次讨论的问题本来就是“这个人合不合适”，说他的表现正对题。","小心：“你说吃糖对牙不好，可你自己天天吃糖！”——这能说明他言行不一，但“吃糖对牙不好”这句话本身还是对的；拿这个来否定那句话，就成了诉诸人身。","好习惯：评价一个观点，先问三件事：说的是什么？理由是什么？证据在哪？——里面没有一件是“他是谁”。"],"深讲":"“诉诸”就是“拿……当理由”，“人身”就是“说话的这个人”。诉诸人身，就是不去碰观点，而是去攻击说观点的人。它有两种常见样子：一种是直接说对方不好——“你成绩差”“你年纪小”“你以前犯过错”；另一种是猜对方有私心——“他这么说，还不是为了自己”。可是，一句话对不对，要看它讲的事和它的理由。“2加3等于5”，不管是数学老师说的，还是一年级小朋友说的，都一样对。哲学书里举过一个例子：一个曾经犯过错的人，照样可能提出一个很好的计划。所以吵架时如果有人说“你凭什么说我”，你可以平静地回答：“我们先看看我说的这件事对不对，好吗？”把话题从“人”拉回到“事”上，讨论才有结果。","怎么认":["找出对方提出的观点是什么。","看反驳的话是冲着“观点和理由”，还是冲着“说话的人”。","冲着人，而且讨论的问题本来不是“这个人怎么样”，就是诉诸人身。"],"辨析":"和“稻草人谬误”比：稻草人是把对方的“话”改歪了再打；诉诸人身是干脆不碰对方的话，去攻击“人”。和“转移话题”比：诉诸人身也把大家的注意力引开了，但引向的是“说话的人”；转移话题引向的是另一件不相干的事。","例句解析":[{"句":"小明：这道题应该先算括号里的。小刚：你上次才考70分，你说的不算！","析":"小刚没有说“先算括号”哪里错，只说小明成绩不好。成绩和这条运算规则对不对毫无关系，所以这是诉诸人身。"},{"句":"小红：图书角可以排一张借书登记表。有人：她就是想当图书管理员。","析":"这是“猜动机”式的诉诸人身。就算小红真想当管理员，登记表好不好用，还是要看登记表本身。"},{"句":"选组长时：小李这学期常忘记值日，我觉得他暂时不适合当组长。","析":"这里讨论的问题就是“谁适合当组长”，说一个人的表现正好对题，不是诉诸人身。"}],"易错":"不是一提到人就是诉诸人身。当讨论的问题本来就是“这个人怎么样”（选班干部、评价谁守不守约），说他的表现是对题的。只有讨论的是“一个观点对不对”，却拿说话人的缺点来否定它，才是诉诸人身。","练习":[{"q":"“小华说要节约用水，可他上次把水龙头开了一下午，所以节约用水的说法不对。”错在哪？","options":["诉诸人身：用小华的过去否定“节约用水”这个观点","没有错","非黑即白"],"answer":0,"解析":"小华做得不好，说明他该改；但“节约用水”这个观点本身对不对，跟小华做没做到无关。"},{"q":"下面哪句没有诉诸人身？","options":["你是新来的，你的办法肯定不行","你的办法要多花一节课，时间不够，我建议换一个","你这么说，还不是想偷懒"],"answer":1,"解析":"B针对的是“办法”本身（要多花时间），给了理由；A攻击“新来的”身份，C猜对方动机。"},{"q":"诉诸人身里的“诉诸”是什么意思？","options":["告诉别人","拿……当理由","大声喊"],"answer":1,"解析":"诉诸人身＝拿“说话的人怎么样”当理由来否定他的观点。"}],"讨论卡":{"问题":"如果弟弟妹妹提醒你“出门要带钥匙”，你会因为他们年纪小就不听吗？聊一聊：为什么一句话对不对，和谁说的没关系？","提示":"试着把说话的人“遮住”，只看这句话本身和它的理由——它对不对，你还会改变看法吗？"},"前置知识":["常见谬误","强加因果"],"决策树":"①对方的观点是什么？→②反驳的话针对的是观点和理由，还是说话的人（成绩、年龄、性格、过去、动机）？→针对观点：不是诉诸人身，再看理由好不好→针对人：③讨论的问题本身是不是就是“这个人怎么样”（比如选组长）？→是：说人的表现正对题，不算谬误→不是：诉诸人身，把话题拉回观点和理由","来源":["Joe Lau《批判性思考网》Critical Thinking Web · F06 List of fallacies：https://philosophy.hku.hk/think/fallacy/list.php","Stanford Encyclopedia of Philosophy「Fallacies」：https://plato.stanford.edu/entries/fallacies/","Internet Encyclopedia of Philosophy「Fallacies」：https://iep.utm.edu/fallacy/"]},{"name":"非黑即白","lv":2,"目标":"今天学会认出非黑即白（也叫虚假两难：假装只有两条路）：明明有很多种可能，却只让你二选一。","类比":"像只发给你一支黑蜡笔和一支白蜡笔，告诉你世界只能画成黑或白——可窗外还有红的花、绿的树、蓝的天。","讲解":"把中间还有其他可能的两个选项，说成“只能二选一”，再逼人选一个或推出结论。","口诀":"黑白之间颜色多，只给两个要琢磨","例子":["错例：小刚说“你不跟我一起玩，就是讨厌我。”（也可能是今天想看书，或者已经约好了别人）","改：小刚说“你今天不想一起玩吗？那明天可以吗？”","错例：“这次考不到100分，就等于没学好。”（95分、90分，或者比上次进步，都不是“没学好”）","错例：小组讨论时有人说“要么全听我的，要么这个作业就别做了。”（还可以商量、投票、把两个方案合起来）","改：“我们把两个方案的优点合在一起试试？”","生活里：“不是第一名，就是失败者。”——第二名、第十名，跑完全程、比上次快，都不是失败。","读书时：“这个人物要么是好人，要么是坏人。”——很多故事里的人物既有优点也有缺点，不能只贴一张标签。","不算：“这道判断题，要么对，要么错。”——判断题本来就只有两个答案，是真正的二选一。","不算：“今天要么是星期六，要么不是星期六。”——“是”和“不是”中间没有第三种，这是真的二选一。","小诀窍：一听到“要么……要么……”“不是……就是……”，先问一句：“还有第三种可能吗？”"],"深讲":"两个词意思相反，不代表世界上只有这两种情况。高中语文课本里讲过：“黑”和“白”是反对关系（两个都不是也可以，比如红色）；整数里的“奇数”和“偶数”是矛盾关系（必有一个，也只能有一个）。非黑即白的毛病，就是把反对关系当成了矛盾关系。比如“每个人不是我的朋友，就是我的敌人”——其实大多数人只是普通同学、邻居，既不是好朋友，也不是敌人。说话的人这样做，常常是想逼你快点表态：不选A，就只能选B。识破它，只要多问一句“还有别的可能吗？”，然后把漏掉的选项一个个找回来：可以一半一半，可以先试试再说，可以两个都不选。世界是彩色的，想问题也别只用两支蜡笔。","怎么认":["找出说话人给的两个选项（常跟着“要么……要么……”“不是……就是……”）。","问：这两个选项之外，还有第三种、第四种可能吗？","有别的可能，却被说成只能二选一，就是非黑即白。"],"辨析":"和“自相矛盾”比：自相矛盾是自己的两句话打架；非黑即白是给别人摆出的选项太少。和“四大逻辑规律”里的排中律比：排中律只管“是／不是”这种真正没有中间的二选一，不管“黑／白”“朋友／敌人”这种中间还有很多可能的情况。","例句解析":[{"句":"你不跟我一起玩，就是讨厌我。","析":"“不一起玩”的原因有很多：想看书、累了、另有约定……“讨厌我”只是其中一种可能，却被说成唯一的可能。"},{"句":"这道判断题，要么对，要么错。","析":"判断题只有“对”和“错”两种答案，中间没有第三种，这是真正的二选一，不是谬误。"}],"易错":"不是所有“二选一”都是谬误。“是／不是”“对／错（判断题）”“奇数／偶数（整数里）”本来就只有两种，这时二选一是对的。要先问清楚：中间到底有没有第三种可能。","练习":[{"q":"“你不支持我当班长，就是反对我。”漏掉了什么？","options":["漏掉了“还没想好”“支持别人但不反对你”等其他态度","什么也没漏，说得对","漏掉了班长的名字"],"answer":0,"解析":"支持和反对中间，还有中立、还没决定、支持别的同学但并不反对你等很多态度。"},{"q":"下面哪句不是非黑即白？","options":["要么天天练琴，要么干脆别学","这个数要么是偶数，要么是奇数（整数范围内）","不是满分就是失败"],"answer":1,"解析":"整数不是偶数就是奇数，没有第三种，是真正的二选一。A还可以隔天练、周末多练；C还有很多好成绩。"},{"q":"识破非黑即白，最有用的一句话是？","options":["你说得对","还有第三种可能吗？","我选第一个"],"answer":1,"解析":"多问一句“还有第三种可能吗”，就能把被藏起来的选项找回来。"}],"讨论卡":{"问题":"家里人说“要么现在写作业，要么今天别出去玩了”。真的只有这两条路吗？一起想想还有哪些办法。","提示":"比如先写一半再出去、约好回来的时间再写……把漏掉的选项一个个找出来，再一起挑最合适的。"},"前置知识":["四大逻辑规律","概念：定义与划分"],"决策树":"①找出“要么……要么……”“不是……就是……”里的两个选项→②问：这两个选项之外还有第三种可能吗？→没有（像“是／不是”“奇数／偶数”）：真正的二选一，不是谬误→有：③说话人是不是拿这两个选项逼人选一个，或者推出结论？→是：非黑即白（虚假两难），把漏掉的选项补上→否：只是随口举两个例子，不算谬误","来源":["Joe Lau《批判性思考网》Critical Thinking Web · F06 List of fallacies：https://philosophy.hku.hk/think/fallacy/list.php","统编高中语文选择性必修上册第四单元「发现潜藏的逻辑谬误」备课资料·同一律、矛盾律、排中律（偷换概念/转移论题/林肯驳“不是黑就是白”）：http://www.yinruiwen.net/news/193795.htm","《发现潜藏的逻辑谬误》特级教师教学设计（概念的矛盾关系与反对关系，“黑”与“白”是反对关系）：http://www.yinruiwen.net/news/192348.htm"]},{"name":"循环论证","lv":3,"目标":"今天学会认出循环论证：拿结论自己来证明自己，说了一圈等于没证。","类比":"像小狗追自己的尾巴，转了一圈又一圈，累得气喘吁吁，还在原地。","讲解":"理由里已经偷偷藏着结论，或者理由要靠结论才能成立，绕一圈又回到起点。","口诀":"拿结论当理由，原地转圈不出头","例子":["错例：“这本书最好看，因为它比其他书都好看。”（“比其他书都好看”就是“最好看”，换了个说法而已）","错例：“我们队最强，因为没有哪个队比我们强。”（理由和结论是同一个意思）","改：“我们队很强，因为这学期八场比赛赢了七场。”","错例：“小明说他从不撒谎。我信他，因为从不撒谎的人说的话当然是真的。”（要证明的是“他不撒谎”，理由却先认定了“他不撒谎”）","改：“我信小明，因为这学期他说过的事，我们去核对，都是真的。”","绕大圈：甲：“这个故事是真的，因为书上写了。”乙：“你怎么知道这本书可靠？”甲：“因为它写的故事都是真的。”（转了一大圈，又回到“故事是真的”）","不算：“铜能导电，因为铜是金属，而金属都能导电。”——理由是另外两件可以核对的事，不是把结论换个说法。","不算：“正方形是四条边都相等、四个角都是直角的四边形。”——用别的词把意思说清楚了，不是循环。","亲戚：“学生就是学生”是循环定义（用要解释的词解释它自己），和循环论证是一家人。","小诀窍：把结论遮住，只看理由——如果理由就是结论换了身衣服，或者不先相信结论就没法相信理由，就是循环论证。"],"深讲":"讲道理就像过河：结论在对岸，理由是一块块踩着过去的石头。石头必须是本来就在河里、大家都能踩稳的，比如可以核对的事实。循环论证的人却说：“我就站在对岸，所以我能到对岸。”——他把要证明的结论，悄悄当成了理由。有的循环很短：“这本书最好看，因为它比其他书都好看”，两句话其实是一个意思。有的循环很长，要转好几圈才回来：“故事是真的，因为书上写的；书可靠，因为它写的都是真故事”，最后还是用“故事是真的”证明“故事是真的”。哲学家把这种毛病叫“窃取论题”：偷偷把要证明的东西先拿来用了。识破的办法是追问：“你的理由，离开你的结论，还站得住吗？”站不住，就请他换一块真正的石头——一个不靠结论、能核对的事实。","怎么认":["找出结论：他要证明什么？","找出理由：他用什么来证明？","比一比：理由是不是结论换了个说法，或者要先相信结论才能相信理由？是，就是循环论证。"],"辨析":"和“偷换概念”比：偷换概念是一个词前后意思变了；循环论证是意思一点没变，结论原封不动地绕回来当理由。和“概念：定义与划分”里的循环定义比：循环定义是解释一个词时用了它自己（学生就是学生）；循环论证是证明一个观点时用了它自己。","例句解析":[{"句":"这本书最好看，因为它比其他书都好看。","析":"“最好看”和“比其他书都好看”是同一个意思。理由没有给出任何新信息（比如情节、人物、读者评价），等于什么都没证明。"},{"句":"我信小明不撒谎，因为不撒谎的人说的话当然是真的。","析":"要证明的是“小明不撒谎”，理由里却已经把小明当成了“不撒谎的人”。先认定了结论，再拿它当理由，就是循环。换成“他说过的事核对后都是真的”，才是真正的理由。"},{"句":"铜能导电，因为铜是金属，而金属都能导电。","析":"这是三段论：理由是“金属导电”和“铜是金属”两件可以单独核对的事，不依赖结论，所以不是循环论证。"}],"易错":"不是“理由和结论有关系”就算循环——理由当然要和结论有关。只有理由“就是”结论（换了说法），或者理由必须先靠结论成立时，才是循环论证。","练习":[{"q":"“西瓜是夏天最解渴的水果，因为夏天没有哪种水果比西瓜更解渴。”犯了什么错？","options":["循环论证：理由只是把结论换了个说法","非黑即白","没有错"],"answer":0,"解析":"“最解渴”和“没有哪种比它更解渴”是一个意思，理由没有提供任何新的证据。"},{"q":"下面哪个不是循环论证？","options":["他是好人，因为他是个好人","这个办法最好，因为它比别的办法都好","这座桥很结实，因为工程师测试过，能承受十辆卡车的重量"],"answer":2,"解析":"C的理由（测试过、能承重）是可以核对的新事实；A和B的理由都只是结论换了个说法。"},{"q":"识破循环论证可以问哪句话？","options":["你说话声音能不能小一点？","你的理由离开你的结论，还站得住吗？","还有第三种可能吗？"],"answer":1,"解析":"循环论证的理由靠结论才成立，问这一句就能看穿。“还有第三种可能吗”是对付非黑即白的。"}],"讨论卡":{"问题":"有人说“这家店的包子最好吃，因为它是最好吃的包子店”。你会怎么请他换一个真正的理由？和家人一起想三个能核对的理由。","提示":"可以从看得见、能比较的地方找：馅料、价格、排队的人多不多、你们自己尝过的感受……"},"前置知识":["概念：定义与划分","三段论"],"决策树":"①找出结论（要证明什么）→②找出理由（用什么证明）→③理由是不是结论换了个说法？→是：循环论证→不是：④要不要先相信结论，才能相信这个理由？→要：循环论证（绕大圈），请他换一个不依赖结论、能核对的理由→不要：不是循环论证，再检查理由本身真不真","来源":["Joe Lau《批判性思考网》Critical Thinking Web · F06 List of fallacies：https://philosophy.hku.hk/think/fallacy/list.php","Stanford Encyclopedia of Philosophy「Fallacies」：https://plato.stanford.edu/entries/fallacies/","Internet Encyclopedia of Philosophy「Fallacies」：https://iep.utm.edu/fallacy/"]},{"name":"转移话题","lv":2,"目标":"今天学会认出转移话题（也叫红鲱鱼）：问的是这件事，回答却把大家引到另一件不相干的事上。","类比":"英文把它叫“红鲱鱼”——一种熏得发红、气味很冲的咸鱼。1807年，英国作家科贝特讲了个故事：小时候他拖着一条红鲱鱼满地跑，把追野兔的猎狗都引跑了。从此人们用“红鲱鱼”比喻把注意力引开的东西。（这个故事多半是他编来打比方的。）","讲解":"回答问题或争论时，突然扯出一件不相干的事，让大家忘了原来的问题。","口诀":"问东偏答西，拉回原题去","例子":["错例：老师问“你的作业为什么没交？”小明说“老师，我昨天帮奶奶浇花了，可勤快了！”（浇花是好事，但没回答作业为什么没交）","改：小明说“我昨天忘了把作业放进书包，今天放学前补交。”","错例：妈妈说“你把弟弟的积木弄倒了，要道个歉。”姐姐说“妈妈你看，我今天数学考了95分！”（考得好和该不该道歉无关）","错例：班会讨论“教室里要不要养金鱼”，小华说“金鱼的颜色可漂亮了，有红的、黑的、白的！”（金鱼漂亮，不能回答“周末谁来喂、能不能养好”）","改：小华说“养金鱼能让大家学着照顾小动物，但周末谁来喂？我们得先排好班。”","教材里：“服务员，你的手指浸到我的汤里了！”“没关系，汤不烫，我不痛。”——顾客说的是卫生，服务员答成了烫不烫，教材里叫“偷换论题”。","不算：老师问“作业为什么没交”，小明说“我昨天发烧去了医院，这是医院开的单子”——这是在直接回答原因，不是转移话题。","不算：讨论“春游去哪儿”时有人说“先看看天气预报，下雨就去博物馆”——天气和去哪儿有关，是有用的补充。","小诀窍：每听到一句回答，就问自己：“这句话能帮我们回答原来的问题吗？”","礼貌拉回：“你说的很有意思，不过我们先说回刚才的问题……”"],"深讲":"讨论问题就像一群猎狗追一只野兔：大家盯着同一个目标，才追得上。转移话题的人，就像在半路丢下一条气味很冲的红鲱鱼，大家的鼻子一下子就被引开了。这招很狡猾，因为丢出来的话常常是真的、甚至是好的：“我帮奶奶浇花了”“金鱼很漂亮”。听的人一边点头，一边就忘了原来问的是什么。可是，一句话再真、再好，如果和原来的问题没关系，就不能当成回答。识破它的办法是在心里记住“原来的问题”，每听一句就对一对：这句话能帮我们回答它吗？不能，就礼貌地拉回来：“这个我们待会儿聊，先说刚才那件事。”我们自己被问到不想回答的问题时，也要勇敢地正面回答，别丢红鲱鱼。","怎么认":["先说清楚：原来讨论的问题是什么？","看这句回答在说什么事。","对一对：它能帮助回答原来的问题吗？不能，而且换成了另一件事，就是转移话题。"],"辨析":"和“稻草人谬误”比：稻草人还盯着对方的观点，只是改歪了；转移话题是离开原来的话题，去谈另一件事。和“偷换概念”比：偷换概念是话题没变、一个词的意思变了；转移话题是整个话题都换了。","例句解析":[{"句":"老师：你的作业为什么没交？小明：我昨天帮奶奶浇花了，可勤快了！","析":"原来的问题是“作业为什么没交”。“帮奶奶浇花”是真事、也是好事，可它说的是另一件事，没有回答原因，大家的注意力却被引到“勤快”上去了。"},{"句":"顾客：你的手指浸到我的汤里了！服务员：汤不烫，我不痛。","析":"顾客关心的是卫生，服务员把话题偷偷换成“烫不烫、痛不痛”，躲开了真正的问题。"}],"易错":"不是说了别的事就算转移话题。如果新说的事能帮助回答原来的问题（比如“因为发烧去医院”回答了“为什么没交作业”），那就是正面回答。关键看：有没有关系、能不能帮忙回答原问题。","练习":[{"q":"爸爸问“房间为什么这么乱？”女儿说“爸爸，今天学校选我当升旗手了！”这是？","options":["转移话题：用一件好事把“房间为什么乱”引开了","正面回答了问题","循环论证"],"answer":0,"解析":"当升旗手是好消息，但和房间为什么乱没有关系，爸爸的问题没有得到回答。"},{"q":"讨论“下周的班级读书会读哪本书”，哪句话没有转移话题？","options":["我昨天看了一部很好看的电影","我推荐《夏洛的网》，篇幅不长，大家一周能读完","我们班的黑板报得了第一名"],"answer":1,"解析":"B直接推荐了书，还给了理由；A和C说的都是和读书会选书无关的事。"},{"q":"“红鲱鱼”为什么能用来比喻转移话题？","options":["因为它颜色是红的，很显眼","因为人们用“气味很冲的熏鱼把猎狗从野兔的方向引开”来打比方","因为鲱鱼会游泳"],"answer":1,"解析":"这个比喻来自一个“用熏鱼的气味把猎狗引开”的故事：转移话题就是把大家的注意力从原问题上引开。"}],"讨论卡":{"问题":"想一想：你被问到不想回答的问题时，有没有丢过“红鲱鱼”？和家人一起演一演，被问“为什么没收拾书包”时，怎样正面回答。","提示":"正面回答的样子是：先说原因，再说打算怎么做，比如“我看动画片忘了，现在马上去收”。"},"前置知识":["常见谬误","四大逻辑规律"],"决策树":"①先说清楚原来的问题或话题是什么→②看这句回答或反驳在说什么→③它能帮助回答原来的问题吗？→能：不是转移话题→不能：④它是不是把对方的观点改歪了再反驳？→是：稻草人谬误→否：⑤它是不是在攻击说话的人？→是：诉诸人身→否：转移话题（红鲱鱼），礼貌地把话拉回原题","来源":["Joe Lau《批判性思考网》Critical Thinking Web · F06 List of fallacies：https://philosophy.hku.hk/think/fallacy/list.php","统编高中语文选择性必修上册《逻辑的力量》第2课时教学设计·发现潜藏的逻辑谬误（下）（“鲁迅的作品”偷换概念、“手指浸到汤里”偷换论题、庄子“安知鱼乐”）：http://www.yinruiwen.net/news/194568.htm","Michael Quinion, World Wide Words「Red Herring Origin」（red herring 比喻义源自 1807 年 Cobbett 的故事）：https://www.worldwidewords.org/herring.html"]}]},{"id":"miuwu_xinli","name":"容易被说服的心理陷阱","items":[{"name":"诉诸众人：大家都这样","lv":2,"目标":"今天学会认出“诉诸众人”：只因为“大家都这样说、都这样做”，就认定它是对的。","类比":"像一群小鸭子排队过河：前面的往哪儿游，后面的就跟着游——可前面那只也可能游错了方向。","讲解":"诉诸众人（也叫诉诸公众、诉诸大众，就是“拿人多当证据”）：“大家都这样”只能说明人多，不能说明它是真的、是对的。","口诀":"人多不等于理多，先问证据在哪儿坐","例子":["错例：全班都说这道题选C，所以答案一定是C","错例：大家都说学校后面那口老井里住着妖怪，所以井里真有妖怪","错例：我们小区的小朋友都不戴头盔骑车，所以不戴头盔也没事","合理：很多同学各自动手做了“种子发芽”实验，都发现种子缺水就不发芽，可以初步相信（人多，但每个人都有自己的证据）","合理：大家约好上下楼梯靠右走，我们也靠右走（这是一起定的规矩，不是在争“谁对谁错”的事实）","改：“全班都说选C”→“我把题目再算一遍，看看C是不是真的对”","改：“大家都说井里有妖怪”→“有谁真的看见过？有没有别的解释，比如风吹井口的声音？”","《皇帝的新装》：满城的人都夸新衣裳漂亮，只有一个孩子说“他什么也没穿”——人再多，也改变不了事实","寓言“三人成虎”：街上本来没有老虎，可三个人都说有，听的人就信了"],"深讲":"安徒生童话《皇帝的新装》里，全城的人都夸那件“看不见的衣服”好看。为什么？因为别人都在夸，谁也不想当那个“不一样”的人。最后一个孩子大声说：“他什么也没穿呀！”大家才回过神来。这就是“大家都这样”的魔力：人一多，我们就容易不再自己检查。可是，一件事是不是真的，要看证据，不看举手的人数。人多有时是个“线索”，提醒我们值得去查一查；但它不能代替“查”。特别要分清两种“大家”：一种是很多人各自做过检验、拿得出证据，这样的“大家”值得参考；另一种只是你传我、我传他，谁也没亲眼见过，这样的“大家”再多也不算数。","怎么认":["找理由：这句话的理由是不是只有“大家都……”“人人都……”“没人这样”？","追证据：这些“大家”自己有没有证据？还是只是互相传、互相学？","换一换：假如只有一个人这样说，你还会信吗？如果不会，说明你信的只是人数。"],"辨析":"和“以偏概全”比：以偏概全是看了几个例子就说“全部都这样”，错在例子太少；诉诸众人是拿“很多人都相信/都在做”当成“它是对的”，错在把人数当证据。和“诉诸权威”比：诉诸权威靠的是“某个厉害的人说了”，诉诸众人靠的是“很多人说了”——一个比头衔，一个比人数。常见谬误专题里“诉诸大众”只点了个名，这里学会追问“这些人有没有证据”。","例句解析":[{"句":"错例：全班都说这道题选C，所以答案一定是C","析":"“全班都说”只告诉我们很多人选了C，并没有告诉我们为什么选C。答案对不对，要把题再算一遍才知道。"},{"句":"合理：很多同学各自动手做了“种子发芽”实验，都发现种子缺水就不发芽，可以初步相信（人多，但每个人都有自己的证据）","析":"这里的“很多同学”不是互相跟风，而是每个人都亲手做过实验、看到了结果。人多加上各自的证据，才值得参考。"}],"易错":"最容易把“约好的规矩”也当成谬误：靠右走、排队打饭是大家商量好的规则，跟着做不是诉诸众人。诉诸众人说的是：拿人多去证明一件事“是真的”“是对的”。","练习":[{"q":"“这个网络传言转发的人可多了，肯定是真的。”问题出在哪？","options":["转发的人太少","把转发的人数当成了证据","没有问题，人多就可信"],"answer":1,"解析":"转发多只说明传得广，不说明有人核实过。要看消息的来源和证据。"},{"q":"下面哪一句不是诉诸众人？","options":["大家都说这家店的面包最好吃，所以它最好吃","全班一起约定，课间在走廊里不追跑，我也遵守","大家都没交作业，所以不交作业是对的"],"answer":1,"解析":"一起约定的规矩，是大家商量好的做法，不是拿人数证明一件事是真的。另外两句都是拿“大家”当理由。"},{"q":"《皇帝的新装》里，那个孩子做对了什么？","options":["跟着大家一起夸衣服","相信自己的眼睛，不因为人多就改口","觉得人多的一边一定错"],"answer":1,"解析":"孩子看的是事实，不是人数。注意：也不能反过来认为“人多就一定错”，那同样是拿人数当标准。"}],"讨论卡":{"问题":"和家人聊聊：有没有一次，你因为“大家都这样”就跟着做了，后来发现不对？","提示":"可以想想：当时你看到证据了吗？下次遇到“大家都说”时，你可以先问哪一句话？"},"前置知识":["常见谬误","以偏概全"],"决策树":"①找理由：结论只靠“大家都……/人人都……”撑着吗？→否：不是诉诸众人，转查其他谬误→是：②这是大家约好的规矩（靠右走、排队），还是在说一件事“是真的/是对的”？→约好的规矩：不是谬误→说事实或对错：③这些“大家”各自有证据吗（亲眼看过、做过实验、查过资料）？→有：可以参考，但仍要看证据本身→没有，只是互相传、互相学：诉诸众人，改成“先去找证据”","来源":["Internet Encyclopedia of Philosophy「Fallacies」https://iep.utm.edu/fallacy/（Appeal to the People / Bandwagon 条：人多不必然可靠，但也有一定参考价值）","Stanford Encyclopedia of Philosophy「Fallacies」https://plato.stanford.edu/entries/fallacies/（第9–10条 ad populum）","香港大学 Critical Thinking Web「[F06] List of fallacies」https://philosophy.hku.hk/think/fallacy/list.php（ad populum 条）"]},{"name":"诉诸权威：名人说的就对？","lv":2,"目标":"今天学会分清：什么时候听专家的话是合理的，什么时候“名人说的”只是个头衔。","类比":"请教专家像问路：问住在这条街上的人很靠谱；可要是去问一位只是“很有名”、却从没来过这儿的人，他说得再响亮也可能指错路。","讲解":"诉诸权威（就是“搬出厉害的人来撑腰”）本身不一定错：问对了行家、他说的有依据，就合理；找错了行家、或只靠头衔不讲道理，就是谬误。","口诀":"名人不等于行家，问对了人还要查","例子":["错例：跑步冠军说，恐龙是被外星人消灭的，所以一定是这样（跑步冠军不是研究恐龙的行家）","错例：网上有人说“专家说了，每天吃十个鸡蛋最聪明”——哪位专家？依据是什么？都没说","错例：会画画的王叔叔说这种野蘑菇能吃，我们就采来吃吧（画画的行家不是认蘑菇的行家）","合理：查《新华字典》确定“血”字在“血液”里读xuè（字典就是专门管字音的权威）","合理：医生说发烧时要多喝水、好好休息，我们照着做（医生是看病的行家，而且医生们大都这样说）","合理：天文馆的讲解员告诉我们，月亮自己不发光，是反射太阳的光（这是天文学家普遍认同、有观测证据的知识）","改：“名人说的就对”→“他是不是这方面的行家？他给出了什么理由？”","改：“专家说的”→“是哪位专家？在哪儿说的？别的专家同意吗？”","小心“引错话”：老师说“读书要多思考”，被传成“老师说不用背书”——权威的话被改了，就不能再算他说的"],"深讲":"我们知道的很多东西，其实都来自权威：字怎么读，问字典；身体不舒服，问医生；星星离我们多远，听天文学家的。这没有错，因为一个人不可能什么都亲自去查。那问题出在哪儿呢？出在“请错了人”和“只看头衔”。一位很会跑步的冠军，讲起恐龙来就不比你懂得多；一句“专家说的”，如果说不出是谁、凭什么，就跟没说一样。判断能不能信一个权威，可以问四个问题：他是不是这一行的行家？这一行的行家们大体同意吗？他的话有没有被传错？他说这话有没有什么好处可拿？四个问题都过关，听他的就是聪明；有一个过不了关，就要多想一想。","怎么认":["找权威：这句话是靠“谁说的”来撑腰吗？他是谁？","对专业：他是不是正好研究这件事的行家？这一行的行家们意见一致吗？","查原话：他真这么说过吗？有没有理由或证据？——专业不对、说不出依据，或者被传错，就是诉诸权威的谬误。"],"辨析":"和“诉诸众人”比：诉诸权威靠的是“一个厉害的人说了”，诉诸众人靠的是“很多人说了”。和“道理论证”比：道理论证引用名言，是拿权威的话帮着讲清道理，后面还要自己分析；诉诸权威的谬误是把头衔当成唯一的理由，“他说的，所以对”。常见谬误专题只说了“不看论证看头衔”，这里重点学会分辨：哪些权威可以信。","例句解析":[{"句":"错例：跑步冠军说，恐龙是被外星人消灭的，所以一定是这样（跑步冠军不是研究恐龙的行家）","析":"跑步冠军在跑步上是权威，可恐龙怎么灭绝要问古生物学家（专门研究远古生物的科学家）。名气大不等于这件事上懂得多。"},{"句":"合理：查《新华字典》确定“血”字在“血液”里读xuè（字典就是专门管字音的权威）","析":"字典是专门研究字音字义的专家编的，而且大家公认。在字音这件事上听字典的，是问对了行家。"}],"易错":"两个坑：一是觉得“只要引用权威就是谬误”，其实问对行家是合理的；二是觉得“名气大就是权威”，其实要看他是不是这件事的行家。","练习":[{"q":"想知道一种蘑菇能不能吃，问谁最合适？","options":["很会唱歌的明星","研究菌类的植物学家","同学里最受欢迎的人"],"answer":1,"解析":"蘑菇能不能吃要问研究菌类的行家。注意：野外的蘑菇最好一律不采不吃。"},{"q":"“有专家说，看动画片会让人变笨。”最先该问什么？","options":["哪位专家？他凭什么这样说？","专家的名气大不大","说这话的人多不多"],"answer":0,"解析":"只说“有专家说”却不说是谁、凭什么，没法判断。先问清是谁、依据是什么。"},{"q":"下面哪一句是合理地引用权威？","options":["足球明星说这道数学题答案是8，所以是8","数学老师讲了解法，我照着验算也得到8，所以答案是8","网上一位名人说是8，所以是8"],"answer":1,"解析":"数学老师是这件事的行家，而且讲了解法、还能验算。另外两个人都不是这道题的行家，也没给理由。"}],"讨论卡":{"问题":"和家人一起想一想：家里遇到问题时，你们会去问谁？为什么觉得他靠得住？","提示":"可以用四个问题检查：是不是这一行的行家？行家们同意吗？话传错了没有？他说这话有没有好处可拿？"},"前置知识":["常见谬误","道理论证"],"决策树":"①找撑腰的人：结论主要靠“某某说的”撑着吗？→否：不是诉诸权威，转查其他谬误→是：②他是这件事的行家吗？→不是（跨行、只是有名）：诉诸权威的谬误→是：③同行的行家们大体同意吗？他给出依据了吗？原话有没有被传错？→都过关：合理引用权威，可以参考→有一条不过关（只说“专家说”不说是谁、行家们吵得厉害、话被改了）：诉诸权威的谬误，改成“查是谁、查依据、查原话”","来源":["Internet Encyclopedia of Philosophy「Fallacies」https://iep.utm.edu/fallacy/（Appeal to Authority 条：多数引用权威并不荒谬；不是该领域权威、权威意见分歧、引错原话时才是谬误）","Stanford Encyclopedia of Philosophy「Fallacies」https://plato.stanford.edu/entries/fallacies/（第9条 ad verecundiam：非专家冒充专家、权威分歧时只挑一方）"]},{"name":"滑坡谬误","lv":2,"目标":"今天学会认出滑坡谬误：把一连串“可能”说成“一定”，从一件小事一路滑到很可怕的结局。","类比":"像站在滑梯顶上，有人说：“你只要坐上去，就一定会滑进大海里！”其实滑梯中间有很多地方能停下来。","讲解":"滑坡谬误（就是“一步一步往下滑，滑到吓人的结局”）：第一步不一定导致第二步，第二步也不一定导致第三步，却被说成“一定会”。","口诀":"一步一个“可能”，连着说成“一定”，滑坡来了要叫停","例子":["错例：今天让你多看十分钟动画片，明天你就要看一小时，后天就天天不写作业，最后什么都学不会了","错例：你这次借了同桌的橡皮没还，以后就会拿别人的铅笔、书包，长大一定变成小偷","错例：要是允许大家在班里养一盆花，以后就会有人养乌龟、养小狗，最后教室会变成动物园","合理：不刷牙，牙齿上的细菌会变多，时间长了容易长蛀牙（每一步都有科学依据，而且说的是“容易”）","合理：今天的作业没写完就去玩，晚上可能要熬夜补，第二天上课可能会犯困（说的是“可能”，没有夸大）","改：“多看十分钟就会什么都学不会”→“我们说好只多看十分钟，到点就关，好吗？”（在第一步就能停住）","改：“借橡皮没还就会变成小偷”→“借了东西要记得还，这是守信用”（就事论事，不往下滑）","算一算：每一步就算有八成可能，连着三步，到终点只剩一半左右的可能（0.8×0.8×0.8≈0.51）","合理：过马路不看车，可能会有危险（只有一步，而且有依据，这是合理提醒，不是滑坡）"],"深讲":"有的大人担心孩子，会说一长串：“现在不好好吃饭，就会长不高，长不高就打不了篮球，打不了篮球就交不到朋友……”听起来一环扣一环，好像很有道理。可仔细看，每一环都只是“可能”，中间还有很多办法能停下来。滑坡的毛病就在这儿：它把每一步的“可能”悄悄换成了“一定”。还有一个数学小秘密：就算每一步都有八成的可能，连着走三步，到终点的可能只剩一半左右；步数越多，可能越小。所以听到一长串“然后就会……然后就会……”时，别被最后那个可怕的结局吓住，回头一环一环地问：这一步真的一定会发生吗？中间能不能停？","怎么认":["数台阶：从第一步到最后的结局，一共滑了几步？把每一步写下来。","每步一问：这一步是“一定”会发生，还是只是“可能”？中间有没有办法停下来？","看终点：有没有把很多“可能”连起来，说成结局“一定”会发生？是的话，就是滑坡谬误。"],"辨析":"和“因果链：多米诺”比：多米诺的每一环都扎实（推倒前一块，后一块真的会倒），结论站得住；滑坡的每一环都松（只是可能），却被说成必然。和“强加因果”比：强加因果是两件事本来没关系，硬说一件导致另一件，通常只有一步；滑坡是一长串台阶，每一步也许有点关系，但被夸大成“一定会”。常见谬误专题已经认识了滑坡的名字，这里学会“数台阶、每步一问”。","例句解析":[{"句":"错例：今天让你多看十分钟动画片，明天你就要看一小时，后天就天天不写作业，最后什么都学不会了","析":"多看十分钟不等于明天一定看一小时，更不等于天天不写作业。每一步都能停下来，却被说成一路滑到底。"},{"句":"合理：不刷牙，牙齿上的细菌会变多，时间长了容易长蛀牙（每一步都有科学依据，而且说的是“容易”）","析":"这条链子每一步都有依据，结论也没说死（“容易”而不是“一定”），所以是合理的提醒，不是滑坡。"}],"易错":"不是所有“一步接一步”的话都是滑坡。每一步都有依据、结论也说得有分寸，就是合理推测；只有把“可能”夸大成“一定”、还越滑越吓人，才是滑坡谬误。","练习":[{"q":"“你今天上课说了一句悄悄话，以后就会天天讲话，成绩一落千丈，最后考不上任何学校。”这是什么错误？","options":["滑坡谬误","自相矛盾","没有错误"],"answer":0,"解析":"说一句悄悄话不一定变成天天讲话，更不一定考不上学。把一串“可能”说成了“一定”。"},{"q":"下面哪一句不是滑坡谬误？","options":["让你吃一颗糖，你就会吃一整袋，然后牙全掉光","不按时睡觉，第二天容易没精神","养了一条金鱼，以后家里就会变成水族馆"],"answer":1,"解析":"“不按时睡觉，第二天容易没精神”只有一步，而且说的是“容易”，是合理推测。"},{"q":"每一步有八成可能，连着三步，到终点大约有几成可能？","options":["八成","五成左右","一定会"],"answer":1,"解析":"0.8×0.8×0.8≈0.51，大约一半。台阶越多，“一定会”越站不住。"}],"讨论卡":{"问题":"你有没有听过一串“然后就会……然后就会……”的话？和家人一起把它拆成台阶，每一步问一问“一定吗”。","提示":"找到最松的那一级台阶，想一想：在这一步，我们可以怎么停下来？"},"前置知识":["常见谬误","因果链：多米诺"],"决策树":"①数台阶：是不是从一个小开头，一步一步推到一个很吓人的结局？→否：不是滑坡，转查强加因果等→是：②每一步都有可靠依据、真的会发生吗？→每一步都扎实：是合理的因果链（多米诺），不是滑坡→有的步只是“可能”，中间能停：③结论有没有把“可能”说成“一定”？→说得有分寸（“容易”“可能”）：合理推测→说成“一定会”：滑坡谬误，改成“就事论事，在第一步想办法”","来源":["Internet Encyclopedia of Philosophy「Fallacies」https://iep.utm.edu/fallacy/（Slippery Slope 条：每步80%，三步后约50%；Domino 即滑坡的因果版）","香港大学 Critical Thinking Web「[F06] List of fallacies」https://philosophy.hku.hk/think/fallacy/list.php（Slippery slope 条：只有在接受第一步并不必然导致后面各步时才是谬误）","Stanford Encyclopedia of Philosophy「Fallacies」https://plato.stanford.edu/entries/fallacies/（第15条 slippery slope）"]},{"name":"相关不等于因果","lv":3,"目标":"今天学会：两件事总是一起变，不一定是谁造成了谁，背后可能藏着“第三个原因”。","类比":"像两只被同一根绳子牵着的风筝：一只往上飞，另一只也往上飞，不是它们互相拉，而是放风筝的人在拉同一根线。","讲解":"相关（两件事常常一起变多、一起变少）不等于因果（一件事真的造成另一件事）。一起变，可能是有第三个原因，可能是因果说反了，也可能只是碰巧。","口诀":"一起变，别乱连，先找背后第三员","例子":["错例：冰淇淋卖得越多，游泳溺水的人也越多，所以吃冰淇淋会让人溺水（真正的原因是天热：天热买冰淇淋的人多，下水游泳的人也多）","错例：下雨天，路上开雨刷的车越多，交通事故也越多，所以开雨刷会引起事故（第三个原因是下雨）","错例：家里空调开得越多的那几周，冰箱里的冷饮也吃得越快，所以开空调会让人想吃冷饮（第三个原因是夏天天热：天热空调开得多，冷饮也吃得多）","因果说反：消防车来得越多的地方，火灾损失越大——不是消防车造成损失，而是火越大，来的消防车越多","碰巧：我穿红袜子的那三天，班级篮球赛都赢了（次数太少，只是碰巧）","合理：做对比实验，两盆一样的豆芽，一盆浇水一盆不浇，别的条件都一样，只有浇水的长大了，说明“水”是原因（控制变量）","合理：先怀疑，再验证——发现两件事一起变，就去找第三个原因，或者做实验把别的条件控制住","改：“吃冰淇淋会溺水”→“天热时去游泳的人多，要注意安全”","改：“个子高的同学字认得多”→“高年级同学个子高，学的字也多，年级才是背后的原因”"],"深讲":"有人统计发现：冰淇淋卖得多的日子，游泳溺水的人也多。难道冰淇淋会让人溺水？当然不是。原来背后还有一个“看不见的手”——天气热。天热了，买冰淇淋的人多了；天热了，下水游泳的人也多了，出事的人自然也多了。冰淇淋和溺水像两只被同一根线牵着的风筝，一起动，却不是互相拉。科学家把这叫“相关不等于因果”。看到两件事一起变，有三种情况要想到：一是有第三个原因在同时推动它们；二是因果说反了，比如火越大来的消防车越多；三是碰巧，次数太少，凑到了一起。那怎么才能确定真正的原因？科学课上学过的“对比实验”就派上用场了：只改变一个条件，其他条件都保持一样，再看结果有没有变化。","怎么认":["看说法：是不是因为“两件事常常一起出现/一起变”，就说一件导致另一件？","三问：背后有没有第三个原因？会不会因果说反了？会不会只是碰巧？","想验证：能不能做个对比实验，只改一个条件，别的都不变，来检查？"],"辨析":"和“强加因果”比：强加因果是两件事本来没什么联系，只因为时间挨着或表面像，就硬说有因果（比如“他出生时飞沙走石，注定此生不凡”）；相关不等于因果是两件事确实常常一起变（有规律、有数据），但这个“一起变”不一定是谁造成谁，最常见的是有第三个原因。一句话：强加因果是“没关系硬说有”；相关不等于因果是“有关系，但不一定是因果”。和“因果链：多米诺”比：多米诺讲的是因果怎么一环推一环，这里讲的是怎么分辨“一起变”是不是真因果。","例句解析":[{"句":"错例：冰淇淋卖得越多，游泳溺水的人也越多，所以吃冰淇淋会让人溺水（真正的原因是天热：天热买冰淇淋的人多，下水游泳的人也多）","析":"冰淇淋和溺水确实一起变多，这是相关；但让它们一起变多的是第三个原因“天热”。把相关当成因果，就闹了笑话。"},{"句":"因果说反：消防车来得越多的地方，火灾损失越大——不是消防车造成损失，而是火越大，来的消防车越多","析":"这里不是第三个原因，而是因果方向弄反了：是“火大”导致“消防车多”，不是“消防车多”导致“损失大”。"},{"句":"合理：做对比实验，两盆一样的豆芽，一盆浇水一盆不浇，别的条件都一样，只有浇水的长大了，说明“水”是原因（控制变量）","析":"对比实验只改变“浇不浇水”这一个条件，把阳光、土、温度都保持一样，就排除了第三个原因，才能说水是原因。"}],"易错":"别把“相关”一律当成“没关系”。两件事一起变，可能真有因果，只是光凭“一起变”还不能确定，要找第三个原因、查因果方向、做对比实验来验证。","练习":[{"q":"“冰淇淋卖得多的日子，溺水的人也多。”背后的“第三个原因”最可能是？","options":["冰淇淋太甜","天气炎热","游泳池太大"],"answer":1,"解析":"天热时，买冰淇淋的人多，去游泳的人也多，所以两者一起变多。"},{"q":"“消防车来得越多，火灾损失越大。”这属于哪种情况？","options":["因果说反了","有第三个原因","只是碰巧"],"answer":0,"解析":"是火越大，来的消防车才越多。原因和结果的方向弄反了。"},{"q":"想知道“阳光是不是豆芽长绿的原因”，哪种做法最好？","options":["只看一盆晒太阳的豆芽","两盆一样的豆芽，一盆晒太阳一盆不晒，别的都一样","问问大家觉得是不是"],"answer":1,"解析":"对比实验只改变一个条件（晒不晒太阳），别的都保持一样，才能看出阳光是不是原因。"}],"讨论卡":{"问题":"和家人一起找一找：生活里有哪两件事总是一起出现？它们是谁造成了谁，还是背后有第三个原因？","提示":"试试三问：有没有第三个原因？会不会说反了？会不会只是碰巧？"},"前置知识":["强加因果","因果链：多米诺"],"决策树":"①看说法：是凭“两件事常常一起变/一起出现”就说一件造成另一件吗？→否：不是这个陷阱（若两件事本来就没联系、只是时间挨着，转查强加因果）→是：②背后有没有第三个原因同时推动两件事？→有：相关不等于因果（如冰淇淋和溺水背后是天热）→没有：③会不会因果说反了？→是：因果倒置→否：④次数够多吗？会不会只是碰巧？→可能是碰巧：不能下结论→⑤用对比实验验证：只改一个条件，结果跟着变，才能确定是因果","来源":["维基百科「相關不蘊涵因果」（冰淇淋销量与溺水人数同因气温升高）https://zh.wikipedia.org/wiki/相關不蘊涵因果","Internet Encyclopedia of Philosophy「Fallacies」https://iep.utm.edu/fallacy/（Common Cause 条：雨刷使用与车祸同因下雨；Post Hoc 条）","统编高中语文选择性必修上册 第四单元「逻辑的力量」学习活动一（教材原文转载）https://chinese.bdfzer.com/cover3/%E7%AC%AC%E5%9B%9B%E5%8D%95%E5%85%83（任务2 强加因果例：“他出生时天昏地暗、飞沙走石，注定此生不凡”，用于辨析）"]},{"name":"幸存者偏差","lv":3,"目标":"今天学会认出幸存者偏差：只看到“留下来的、成功的”，看不到“消失了的、失败的”，结论就会偏。","类比":"像只看到钓鱼的人晒出来的大鱼照片，就以为这条河里条条都是大鱼——没钓到的人，从来不会晒空桶。","讲解":"幸存者偏差（“幸存者”就是经过筛选留下来的那些）：我们能看到的，往往是被筛选后留下来的；那些被筛掉的、失败的、不出声的，也很重要，却被忘了。","口诀":"只看留下的，忘了消失的，结论准会歪","例子":["错例：爷爷说，以前的老家具都特别结实，用了几十年都没坏，所以以前的家具都比现在的好（不结实的早就坏了、扔了，留下来的当然是结实的）","同理：传到今天的老歌首首好听，不代表以前的歌都好听——不好听的老歌早就没人唱了，留下来的是精挑细选过的","错例：钓鱼群里大家晒的全是大鱼，所以这条河很容易钓到大鱼（没钓到的人不会发照片）","错例：信鸽比赛结束后，飞回来的鸽子个个都很强壮，所以说这种鸽子都很强壮（没飞回来的鸽子，我们根本看不到）","合理：想知道兴趣班好不好，不光问坚持下来的同学，也去问问中途退出的同学为什么不学了","合理：作文比赛展出的都是获奖作品，我们知道这些是挑出来的好作文，不会以为全班作文都这么好","改：“老家具都很结实”→“能留到今天的老家具很结实，可当年也有很多不结实的，早就坏了”","改：“钓鱼群里全是大鱼”→“只有钓到大鱼的人才爱晒照片，我得问问大家一共去了几次、钓到几次”","先问一句：我看到的这些，是全部，还是被“筛”过、只剩下来的那一部分？"],"深讲":"爷爷常说：“以前的家具才叫结实，你看这张老木桌，用了四十年都没坏！”听起来很有道理。可是想一想：四十年前，家家户户也有不结实的桌子，它们早就坏了、扔了，今天我们根本看不到。能留到现在的，本来就是最结实的那一批。这就是幸存者偏差：我们看到的，常常是经过“筛选”后留下来的。传到今天的老歌首首好听，因为不好听的早就没人唱了；钓鱼群里晒的全是大鱼，因为空手而归的人不会晒空桶。这些“消失的那一半”不出声，却同样重要。统计学家把它们叫作“沉默的证据”。所以看到一堆成功的例子时，要多问一句：那些被筛掉的、失败的、不出声的，在哪里？把它们也找回来，才能看到事情的全貌。","怎么认":["看来源：我看到的这些例子，是不是经过了“筛选”（留下来的、成功的、愿意说话的）？","找消失的：那些被筛掉的、失败的、不出声的，我看到了吗？","补全再判断：把“消失的那一半”也算上，结论还成立吗？不成立，就是幸存者偏差。"],"辨析":"和“以偏概全”比：以偏概全是例子太少，看了几个就说“全部”；幸存者偏差是例子被“筛”过——哪怕你看到一千个成功的例子，只要失败的都被筛掉、看不到，结论照样会歪。所以多找几个例子救不了幸存者偏差，要去找“消失的那一半”。和“相关不等于因果”比：相关不等于因果是没想到第三个原因；幸存者偏差是没看到被筛掉的那些。","例句解析":[{"句":"错例：爷爷说，以前的老家具都特别结实，用了几十年都没坏，所以以前的家具都比现在的好（不结实的早就坏了、扔了，留下来的当然是结实的）","析":"今天还能看到的老家具，是经过几十年“筛选”留下来的。当年那些不结实的家具早就坏了，我们看不到，就误以为以前的家具都结实。"},{"句":"错例：信鸽比赛结束后，飞回来的鸽子个个都很强壮，所以说这种鸽子都很强壮（没飞回来的鸽子，我们根本看不到）","析":"能飞回来的鸽子是经过“比赛筛选”留下来的，没飞回来的那些我们见不到。只拿飞回来的说事，就以为所有鸽子都强壮。"}],"易错":"以为“例子多就可靠”。幸存者偏差里例子可以很多，问题不在多少，而在“被筛选过”。要问的是：失败的、消失的那些去哪儿了？","练习":[{"q":"“能留到今天的老房子都很结实，所以以前盖的房子都很结实。”问题出在哪？","options":["老房子太少","不结实的老房子早就拆了、倒了，我们看不到","现在的房子更结实"],"answer":1,"解析":"能留下来的是经过筛选的结实房子，不结实的已经消失，不能拿留下来的代表全部。"},{"q":"想知道一个兴趣班好不好，最好问谁？","options":["只问坚持下来的同学","坚持下来的和中途退出的同学都问问","只看兴趣班的宣传照片"],"answer":1,"解析":"坚持下来的人往往觉得好，退出的人也有他们的理由。两边都问，才不会只听到“幸存者”的声音。"},{"q":"下面哪一句犯了幸存者偏差？","options":["作文展上的都是获奖作文，所以全班作文都写得这么好","我们班有三个同学喜欢画画","这次考试全班平均分是85分"],"answer":0,"解析":"作文展上的是挑出来的获奖作品，没获奖的没展出。拿挑出来的代表全班，就是幸存者偏差。"}],"讨论卡":{"问题":"和家人聊一聊：大人常说“以前的东西质量好”，你觉得这里面有没有幸存者偏差？","提示":"想一想：以前那些质量不好的东西去哪儿了？我们还看得到吗？"},"前置知识":["以偏概全","常见谬误"],"决策树":"①看来源：我看到的例子是不是经过了筛选（留下来的、成功的、获奖的、愿意晒出来的）？→没有筛选（随机看的、全体都统计了）：不是幸存者偏差（若只是例子太少，转查以偏概全）→有筛选：②被筛掉的那些（失败的、消失的、不出声的）我看到了吗？→看到了、也算进去了：结论可以考虑→没看到：③把“消失的那一半”补上，结论还成立吗？→不成立或说不清：幸存者偏差，改成“去找消失的那一半再下结论”","来源":["维基百科「Survivorship bias」（定义：只关注通过筛选的对象而忽略未通过者；“沉默的证据”silent evidence）https://en.wikipedia.org/wiki/Survivorship_bias","Internet Encyclopedia of Philosophy「Fallacies」https://iep.utm.edu/fallacy/（Hasty Generalization 条，用于与以偏概全辨析）"]},{"name":"赌徒谬误","lv":2,"目标":"今天学会认出赌徒谬误：以为前面连着出了很多次一样的结果，下一次就“该轮到”另一种了。","类比":"硬币没有记性：它不记得自己刚才是正面还是反面，每一次抛起来，都像第一次一样。","讲解":"赌徒谬误（以为“老天会把运气补回来”）：硬币、骰子这类每次互不影响的事，叫独立事件（这一次的结果不受上一次影响）。前面出了什么，都不会改变下一次的机会。","口诀":"硬币没记性，每次重新算，连出正面也一半","例子":["错例：硬币已经连着五次正面了，下一次一定是反面","错例：玩飞行棋，我连着三次都没掷出6，下一次肯定该掷出6了","错例：抛了四次硬币都是反面，这次我猜正面，因为正面“攒”了好久了","合理：一枚正常的硬币，不管前面出了什么，下一次正面的机会还是一半","合理：袋子里有3个红球、3个蓝球，摸出来不放回去，已经摸走3个红球，剩下的一定是蓝球（不放回，前面会影响后面，这不是赌徒谬误）","合理：一枚硬币连着抛出二十次正面，可以怀疑这枚硬币是不是被做了手脚（这时不是“该出反面了”，而是“它可能本来就偏向正面”）","改：“连着五次正面，下次一定反面”→“下次正面和反面的机会还是一样，各一半”","改：“三次没掷出6，这次该6了”→“每一次掷出6的机会都是六分之一，不会因为前面没出就变大”","小心反过来：“我连赢三局，手气正旺，下一局也一定赢”——同样是把独立的事当成了有记性"],"深讲":"抛硬币，连着出了五次正面。这时候你会不会觉得：“下一次总该是反面了吧？”很多人都这么想，好像硬币心里有个账本，要把正反面“摆平”。可硬币没有记性，它不知道自己刚才落成什么样。只要它是一枚正常的硬币，每一次抛出去，正面和反面的机会都各占一半。有个有趣的事实：在开始抛之前，“连着六次正面”和“五次正面再来一次反面”出现的机会其实一模一样，都是六十四分之一。所以前面五次已经发生了，第六次还是一半对一半。要注意两种不一样的情况：一是摸球不放回，前面摸走的会改变袋子里剩下的，这时候前面确实影响后面；二是硬币出了二十次正面，聪明的做法是怀疑硬币有问题，而不是等着“该出反面”。","怎么认":["看理由：是不是因为“前面连着出了很多次某个结果”，就说下一次“该轮到”另一个（或者“还会接着来”）？","问独立：每一次之间会互相影响吗？（抛硬币、掷骰子不会；摸球不放回会）","下判断：每次互不影响，却以为前面的结果会改变下一次的机会，就是赌徒谬误。"],"辨析":"和“以偏概全”比：以偏概全是看了几次就给“全部”下结论；赌徒谬误是对“下一次”乱猜，以为前面的结果会把下一次“扳回来”。和“相关不等于因果”比：那里是两件不同的事一起变；这里是同一件事一次次重复，每一次本来就互不影响。常见谬误专题里有“连输五把，下一把肯定赢”的例子，这里学会分清“独立事件”和“摸球不放回”这类会互相影响的事。","例句解析":[{"句":"错例：硬币已经连着五次正面了，下一次一定是反面","析":"硬币不记得前五次的结果。第六次抛出去，正面、反面的机会还是各一半，不会因为前面全是正面就偏向反面。"},{"句":"合理：袋子里有3个红球、3个蓝球，摸出来不放回去，已经摸走3个红球，剩下的一定是蓝球（不放回，前面会影响后面，这不是赌徒谬误）","析":"球被拿走了，袋子里剩下的就变了。这种情况前面确实影响后面，所以推出“剩下的是蓝球”是对的。"}],"易错":"两个坑：一是把“摸球不放回”也当成赌徒谬误，其实那时前面真的会影响后面；二是以为只有“该轮到另一种了”才算，其实“手气正旺，还会接着赢”也是同样的错。","练习":[{"q":"一枚正常的硬币连着抛出四次反面，第五次是正面的机会是？","options":["比一半大","还是一半","比一半小"],"answer":1,"解析":"每次抛硬币互不影响，第五次正面的机会还是一半。"},{"q":"下面哪一种情况，前面的结果真的会影响后面？","options":["掷骰子","抛硬币","从袋子里摸球，摸出来不放回去"],"answer":2,"解析":"摸球不放回，袋子里剩下的球变了，后面的机会也跟着变。掷骰子、抛硬币每次都重新开始。"},{"q":"玩飞行棋时小明说：“我连着五次没掷出6，下一次肯定是6！”你怎么回答他？","options":["对，该轮到你了","每一次掷出6的机会都是六分之一，前面没出不会让它变大","你下一次肯定还掷不出6"],"answer":1,"解析":"骰子没有记性，每一次掷出6的机会都是六分之一。说“肯定还掷不出”同样是乱猜。"}],"讨论卡":{"问题":"和家人一起抛硬币，每人抛二十次，记下结果。找一找：有没有连着出好几次正面的时候？下一次是什么？","提示":"连着出好几次一样的，在随机的事里很常见。看看连续正面之后，下一次是不是正反都有可能。"},"前置知识":["常见谬误","推理三兄弟：演绎/归纳/类比"],"决策树":"①看理由：是不是凭“前面连着出了某个结果”，来猜下一次“该轮到另一个”或“还会接着来”？→否：不是赌徒谬误，转查其他谬误→是：②每一次之间会互相影响吗？→会（摸球不放回、东西被用掉了）：不是赌徒谬误，前面确实影响后面→不会（抛硬币、掷骰子，每次重新开始）：③硬币、骰子是正常的吗？→连着出了特别多次（如二十次正面）：该怀疑它不正常，而不是等“该轮到”→正常：赌徒谬误，改成“每一次的机会都一样”","来源":["香港大学 Critical Thinking Web「[F06] List of fallacies」https://philosophy.hku.hk/think/fallacy/list.php（Gambler's fallacy 条：公平硬币连续五次正面后，下一次并不更可能是反面）","Internet Encyclopedia of Philosophy「Fallacies」https://iep.utm.edu/fallacy/（Gambler's 条：前提是“公平硬币”；若一直出正面，应怀疑硬币不公平）"]}]},{"id":"tuili_youxi","name":"推理侦探课","items":[{"name":"排除法：列表格破案","lv":2,"目标":"今天学会用排除法（把不可能的一个个划掉）列表格破案：一行或一列只剩一格，答案就是它。","类比":"排除法像侦探排查嫌疑人：有不在场证明的，一个个划掉；名单上只剩一个人没被划掉，要找的就是他。","讲解":"把所有可能列成表格，每条线索只在“不可能”的格子里打×；某一行（或一列）只剩一格没打×，那格就是答案。","口诀":"先列表，再打叉，剩下一格就是它","例子":["小明、小红、小华各养一只猫、狗、兔（各不相同）。小明不养猫也不养狗→小明这一行只剩“兔”，小明养兔","接上：小红不养猫，兔已经归小明→小红只剩“狗”；最后剩下的猫归小华","乐乐、丁丁、豆豆分别参加合唱、足球、画画小组：丁丁不参加足球也不参加画画→丁丁参加合唱","接上，看“足球”这一列：乐乐×、丁丁×，只剩豆豆→豆豆踢足球，乐乐就去画画（一列也能只剩一格）","连锁反应：一格打了√，同一行、同一列的其他格都要打×——因为一人只选一样，一样只给一人","四人坐1～4号座位：甲不坐1号也不坐4号；乙紧挨着坐在甲的右边（号码比甲大1）；丙也不坐1号和4号→甲3号、乙4号、丙2号、丁1号","错例：只有“小明不养猫”一条线索，就宣布“小明养狗”（小明那行还剩狗和兔两格，没排到只剩一格，不能下结论）","错例：题目没说“各不相同”，就照样打×（如果两个人可以养同一种动物，一格打√后，同一列就不能跟着全打×）","错例：表格只列了猫和狗，漏了兔，排到最后“只剩狗”其实是假象——可能没列全，排除就不可靠","课文里的排除：初中课文《河中石兽》里，人们先在原处水里找，又往下游找了十几里，都没有；老河兵还讲清了道理：水流把石兽迎水那一面下方的沙冲成坑，石兽一次次倒进坑里，就往上游“走”了——最后果然在上游找到"],"深讲":"大侦探福尔摩斯有句话，大意是：把不可能的都排除掉，剩下的那个，哪怕再出人意料，也是真相。排除法就是这样破案的。它要两样工具：一张把所有可能都列出来的表格，和一条条可靠的线索。每条线索只做一件小事——在不可能的格子里打×。等某一行只剩一格，就能打√；打了√，同一列别人的那一格又能打×，于是又有新的行只剩一格……一条线索常会引发一串连锁反应，像推倒一排多米诺骨牌。不过排除法有两个前提：可能性要列全，人和选项要一一对应。漏了一种可能，最后“只剩一个”就可能是假象。学完可以去游戏区玩《斑马谜题格》，亲手打×过过瘾。","怎么认":["先把人和选项列成表格，确认两件事：可能性列全了吗？每人只对应一样、各不相同吗？","每读一条线索，只在“不可能”的格子里打×；没把握的格子先空着，别凭感觉打√。","找只剩一格的行或列，打√，再把同行同列其他格打×，一路连锁推下去，直到表格填满。"],"辨析":"排除法和“选言推理：不是A就是B”是一家人：选言推理讲的是一句“或者”里的去掉一个留一个；排除法是把这个办法在一整张表格上反复使用。它和“真话假话题”也不同：排除法里的每条线索都是真的，可以放心打×；真话假话题里的话有真有假，得先假设再检验。","例句解析":[{"句":"小明、小红、小华各养一只猫、狗、兔（各不相同）。小明不养猫也不养狗→小明养兔","析":"小明那一行有猫、狗、兔三格，两条线索划掉了猫和狗，只剩兔一格，所以小明养兔。注意题目说了“各不相同”，接下来“兔”这一列小红、小华的格子都可以打×。"},{"句":"四人坐1～4号：甲不坐1号也不坐4号；乙紧挨在甲右边；丙也不坐1号和4号","析":"甲只能坐2或3号。若甲坐2号，乙就坐3号，丙不能坐1、4号，2、3号又被占了，丙没地方坐——矛盾。所以甲坐3号、乙坐4号，丙只能坐2号，剩下1号给丁。"},{"句":"错例：只有“小明不养猫”一条线索，就宣布“小明养狗”","析":"划掉猫以后，小明那行还剩狗和兔两格，排除还没做完。必须等到只剩一格，才能打√。"}],"易错":"两个坑最常见：一是只划掉一格就急着下结论，没等到“只剩一格”；二是没检查可能性有没有列全、是不是一一对应，结果“只剩一个”是假象。","练习":[{"q":"乐乐、丁丁、豆豆分别参加合唱、足球、画画小组（每人一个，各不相同）。乐乐不参加足球；丁丁既不参加足球也不参加画画。豆豆参加的是？","options":["合唱","足球","画画"],"answer":1,"解析":"丁丁那行只剩合唱；“足球”这一列乐乐、丁丁都打了×，只剩豆豆，所以豆豆踢足球，乐乐画画。"},{"q":"每人只养一只、各不相同。表格里“小华”这一行，猫、狗两格都打了×，只剩“兔”。说明什么？","options":["小华养兔","还不能确定","小华什么也不养"],"answer":0,"解析":"每人一定养一只，一行只剩一格，那一格就是答案：小华养兔。"},{"q":"红、黄、蓝三个盒子分别装糖果、饼干、巧克力（各不相同）。红盒不是糖果；黄盒既不是糖果也不是饼干。蓝盒里是？","options":["糖果","饼干","巧克力"],"answer":0,"解析":"黄盒只剩巧克力；红盒不是糖果，巧克力又给了黄盒，红盒只剩饼干；最后蓝盒装糖果。"}],"讨论卡":{"问题":"和家人玩一局：三个人各选猫、狗、兔中的一种（不重复），只用“谁不是什么”这样的线索让对方猜。最少要给几条线索，对方才一定能猜出来？","提示":"三人三样一共有6种排法，每条“不是”线索最多划掉其中2种，所以至少要3条；试着自己出一套3条就能猜中的线索。也可以去游戏区玩《斑马谜题格》练手。"},"前置知识":["推理三兄弟：演绎/归纳/类比"],"决策树":"①可能性列全了吗？每人只对应一样吗？→没有：先补全表格或条件→有：②逐条读线索，只在不可能的格子打×→③有没有只剩一格的行或列？→有：打√，同行同列其他格打×，回到③→没有：再找线索，或者换用假设法试一试","来源":["统编高中语文选择性必修上册第四单元「逻辑的力量·二 运用有效的推理形式」学习资料（排除法、选言推理、归纳/类比推理）：https://www.ixuehai.cn/html/1776.html","Wikipedia「Zebra Puzzle」（斑马谜题的原题与逐步排除解法）：https://en.wikipedia.org/wiki/Zebra_Puzzle"]},{"name":"真话假话题：假设法","lv":2,"目标":"今天学会解“只有一人说真话”这类题：逐个假设答案，数一数真话有几句，和题目条件对上的才是答案。","类比":"像一把一把试钥匙：先假设是甲、再假设是乙……哪把钥匙插进去刚好能转动（真话数和条件对上），哪个就是答案。","讲解":"题目会悄悄给一个条件：只有一句真话（或只有一句假话）。逐个假设答案，把每句话标真或假，数一数，对上条件的才是答案。","口诀":"一个一个去假设，真话数数对不对","例子":["花瓶打碎了。甲：“是乙打的。”乙：“不是我。”丙：“不是我。”只有一人说真话→假设是丙：甲假、乙真、丙假，正好一句真，所以是丙","接上，把别的也试一遍：假设是甲，乙真、丙真，两句真，不对；假设是乙，甲真、丙真，两句真，不对。只有丙对得上","蛋糕被偷吃。小猫：“是小狗吃的。”小狗：“小猫在说谎。”小兔：“我没吃。”只有一句真话→小兔吃的","快捷招：找“唱反调”的一对。小狗说“小猫在说谎”，两句话正好相反，必定一真一假，真话名额就被它俩用掉了","寻宝：红、黄、蓝、绿四个盒子只有一个有宝。红：“宝不在这里。”黄：“宝在红盒。”蓝：“宝不在绿盒。”绿：“宝不在蓝盒，也不在黄盒。”只有一句假话→宝在红盒","比名次（三人名次各不相同）：甲：“我是第一。”乙：“我不是第一。”丙：“我是第二。”只有一人说假话→甲第一、乙第二、丙第三（丙说了假话）","忘关窗户：A：“是B忘的。”B：“是D忘的。”C：“不是我。”D：“B在乱说。”只有一句真话→B、D两句相反必有一真，A、C都是假话，“不是我”是假的→C忘的","错例：乙说“不是我”，就认定不是乙——忘了题目说只有一人说真话，乙这句话可能正是假话","错例：假设出一个答案后，只看了一两句话就停下，没把每句话都标真假、数一遍","错例：把“只有一人说真话”读成“只有一人说假话”，条件一反，答案全错"],"深讲":"真话假话题像一场小小的审案：几个人各说一句话，题目又悄悄透露一个秘密条件——只有一个人说了真话。你不知道谁可信，怎么办？方法一叫“逐个假设”：先假设“是甲干的”，把每句话都标上真或假，数一数真话有几句；对不上条件，就换下一个假设。答案只有几个可能，挨个试，一定能找到。方法二是找“唱反调”的一对：如果两句话正好相反，比如“小猫说是小狗”和“小狗说小猫在说谎”，那它们不能都真、也不能都假，一定一真一假——这正是“四大逻辑规律”里矛盾律和排中律在帮忙。找到这一对，名额先用掉一个，剩下的话真假立刻就清楚了。最后别忘了回头验算：把答案代回去，每句话再数一遍。","怎么认":["先圈出题目的秘密条件：是“只有一句真话”，还是“只有一句假话”？","找有没有正好相反的一对话；有的话，它俩必定一真一假，先占掉一个名额。","逐个假设答案，给每句话标真或假，数一数是否和条件对上；最后代回去整体验算一遍。"],"辨析":"真话假话题和“骑士与无赖”最容易混：真话假话题是按“句数”来数——题目只告诉你一共有几句真话；骑士与无赖是按“人”来判——骑士说的每句都真，无赖说的每句都假，身份决定了话的真假。和“排除法”比：排除法的线索全都可信，可以直接打×；真话假话题的线索有真有假，必须先假设再检验。","例句解析":[{"句":"花瓶打碎了。甲：“是乙打的。”乙：“不是我。”丙：“不是我。”只有一人说真话","析":"逐个试：是甲→乙、丙两句真；是乙→甲、丙两句真；是丙→只有乙一句真。只有“是丙”和“只有一人说真话”对得上，所以是丙打碎的。"},{"句":"蛋糕被偷吃。小猫：“是小狗吃的。”小狗：“小猫在说谎。”小兔：“我没吃。”只有一句真话","析":"小狗的话就是“小猫的话是假的”，两句正好相反，一定一真一假，唯一的真话名额被它俩用了。所以小兔说的是假话，“我没吃”是假的——小兔吃的。验算：小猫假、小狗真、小兔假，正好一句真。"},{"句":"错例：乙说“不是我”，就认定不是乙","析":"题目说只有一人说真话，谁的话都可能是假的。不能先挑一句当真，要逐个假设、整体数一数。"}],"易错":"最常见的两个坑：把条件读反（“只有一句真话”看成“只有一句假话”）；假设一个答案后没有把每句话都检查完就下结论。","练习":[{"q":"花瓶打碎了。甲：“是乙打的。”乙：“不是我。”丙：“不是我。”只有一人说真话。是谁打碎的？","options":["甲","乙","丙"],"answer":2,"解析":"假设是丙：甲假、乙真、丙假，正好一句真。假设是甲或乙，都会有两句真，不对。"},{"q":"小猫说：“是小狗吃的。”小狗说：“小猫在说谎。”这两句话的关系是？","options":["可以同时是真的","一定一真一假","可以同时是假的"],"answer":1,"解析":"小狗的话等于“小猫那句是假的”，两句正好相反，不能都真也不能都假，所以一定一真一假。"},{"q":"甲：“我是第一。”乙：“我不是第一。”丙：“我是第二。”三人名次各不相同，只有一人说了假话。丙是第几名？","options":["第一","第二","第三"],"answer":2,"解析":"试一试：甲第一、乙第二、丙第三时，甲真、乙真、丙假，正好一句假。其余排法假话都不是一句。"}],"讨论卡":{"问题":"“只有一个人说真话”和“只有一个人说假话”，哪种题更好解？和家人各出一道题互相考一考。","提示":"解法都是逐个假设、数真话。出题的人要先把每个可能的答案都试一遍，确认只有一个答案对得上，题才算出好了。"},"前置知识":["四大逻辑规律","排除法：列表格破案"],"决策树":"①圈出条件：几句真话？几句假话？→②有正好相反的一对话吗？→有：它俩一真一假，先占一个名额，再判其余的话→没有：③逐个假设答案，每句标真假并计数→④对上条件的只有一个吗？→是：这就是答案，代回验算→不止一个或一个都没有：重读题目条件","来源":["统编高中语文选择性必修上册第四单元「逻辑的力量·二 运用有效的推理形式」学习资料（排除法、选言推理、归纳/类比推理）：https://www.ixuehai.cn/html/1776.html","Wikipedia「Knights and Knaves」（Smullyan 1978《What Is the Name of This Book?》命名；“无人能说自己是无赖”等经典解法）：https://en.wikipedia.org/wiki/Knights_and_Knaves"]},{"name":"骑士与无赖","lv":3,"目标":"今天学会解骑士与无赖谜题：骑士句句真，无赖句句假，用“假设—检验”判断每个人的身份。","类比":"像拼拼图：先假设A是骑士，把他的话当真往下拼；拼到某块对不上（出现矛盾），说明假设错了，换成“A是无赖”重新拼。","讲解":"岛上只有两种人：骑士永远说真话，无赖永远说假话。假设某人的身份，再看他的话和身份配不配：骑士的话必须真，无赖的话必须假。","口诀":"骑士句句真，无赖句句假；假设配一配，矛盾就翻案","例子":["A说：“我们俩都是无赖。”→骑士说这句就成了假话，所以A是无赖；他的话是假的，“两人都是无赖”不成立，B是骑士","岛上谁也说不出“我是无赖”：骑士说了是假话，无赖说了反倒是真话，都不行","A说：“我是骑士。”——骑士会这么说，无赖也会这么说，所以光凭这句话判断不出A是谁","A说：“我们是同一类。”B说：“我们不是同一类。”两句正好相反，必有一真，所以两人一骑士一无赖——这正是B说的，B是骑士，A是无赖","A说：“B是无赖。”B说：“A和我是同一类。”→A是骑士，B是无赖（假设A是无赖会推出矛盾）","A说：“我们俩中至少有一个是无赖。”→如果A是无赖，这句话反而成了真话，矛盾；所以A是骑士，话为真，B是无赖","A说：“B是骑士。”B说：“我们俩不是同一类。”→两人都是无赖","错例：A说“我是骑士”，就认定A是骑士——无赖也会这么说","错例：假设A是骑士后推出了矛盾，就说“题目错了”——矛盾恰恰说明这个假设错了，应该改成A是无赖再推","错例：无赖A说“我们俩都是骑士”，就以为真相是“我们俩都是无赖”——这句话的反面是“至少有一个不是骑士”，不一定两个都是无赖"],"深讲":"在一座想象的小岛上，住着两种人：骑士从不说谎，无赖从不说真话。这类谜题因逻辑学家斯穆里安（Smullyan）的书《这本书叫什么？》而出名。解题的办法像科学家做实验：先提出一个假设——“A是骑士”，然后把A的话当真，一步步推下去；如果推出了自相矛盾的结果，就说明假设错了，A只能是无赖。两种身份都试过，只有一种不矛盾，答案就出来了。这里有两个好用的小发现：第一，岛上谁也说不出“我是无赖”这句话；第二，无赖的话要“整句取反”，“我们都是骑士”的反面是“至少有一个不是骑士”，而不是“我们都是无赖”。最后要记住：有的话骑士和无赖都会说，比如“我是骑士”，这种话就判断不出身份。","怎么认":["把每个人说的话写下来，标好是谁说的。","假设第一个人是骑士，把他的话当真往下推；再假设他是无赖，把他的话整句取反往下推。","哪种假设推出矛盾就排除；只剩一种不矛盾的身份组合，就是答案。"],"辨析":"骑士与无赖和“真话假话题”最像，区别在于：骑士与无赖按“人”判——身份定了，这个人的每句话都跟着定了真假；真话假话题按“句数”数——题目只说一共几句真话，不管是谁说的。另外，无赖的话取反要取整句的反面，这一点和“四大逻辑规律”里的矛盾关系紧紧相连。","例句解析":[{"句":"A说：“我们俩都是无赖。”","析":"假设A是骑士，那他的话为真，他自己就是无赖——自相矛盾。所以A是无赖，他的话是假的，也就是“两人都是无赖”不成立；A已经是无赖了，那B只能是骑士。"},{"句":"A说：“B是无赖。”B说：“A和我是同一类。”","析":"假设A是骑士：B是无赖，B说“同一类”应该是假话——两人确实不同类，假话对上了，不矛盾。假设A是无赖：B是骑士，B说“同一类”应该是真话——可两人一无赖一骑士并不同类，矛盾。所以A是骑士，B是无赖。"},{"句":"错例：无赖A说“我们俩都是骑士”，就以为“我们俩都是无赖”","析":"“都是骑士”是假的，只能说明“至少有一个不是骑士”。A自己是无赖，这已经让那句话变假了，B是骑士还是无赖，光凭这一句判断不出来。"}],"易错":"两个坑：一是给无赖的话取反时只取一半（“都是骑士”的反面不是“都是无赖”）；二是推出矛盾就慌了——矛盾是好消息，它告诉你哪个假设该扔掉。","练习":[{"q":"A说：“我们俩都是无赖。”A和B分别是？","options":["A骑士，B无赖","A无赖，B骑士","两人都是无赖"],"answer":1,"解析":"骑士不会说自己是无赖，所以A是无赖；他的话为假，“两人都是无赖”不成立，B是骑士。"},{"q":"A说：“我们俩中至少有一个是无赖。”A和B分别是？","options":["A骑士，B无赖","A无赖，B骑士","两人都是骑士"],"answer":0,"解析":"若A是无赖，这句话因为他自己就成真了，矛盾；所以A是骑士，话为真，B是无赖。"},{"q":"下面哪句话，岛上任何人都说不出口？","options":["我是骑士","我是无赖","我旁边的人是无赖"],"answer":1,"解析":"骑士说“我是无赖”是假话，无赖说它又是真话，所以谁都不能说。“我是骑士”两种人都能说；第三句要看旁边是谁。"}],"讨论卡":{"问题":"如果你在岛上遇到一个人，只能问一个“是或不是”的问题，就要知道他是骑士还是无赖，你会问什么？","提示":"问一个答案大家都知道的问题，比如“你是一只树蛙吗？”骑士会答“不是”，无赖会答“是”。"},"前置知识":["四大逻辑规律","真话假话题：假设法"],"决策树":"①写下每个人的话→②假设第一个人是骑士，把他的话当真往下推→③出现矛盾吗？→有：假设错，改成无赖（话整句取反）再推→没有：也试一试另一种身份→④只有一种身份组合不矛盾：这就是答案；两种都不矛盾：信息不够，判断不出","来源":["Wikipedia「Knights and Knaves」（Smullyan 1978《What Is the Name of This Book?》命名；“无人能说自己是无赖”等经典解法）：https://en.wikipedia.org/wiki/Knights_and_Knaves","香港大学 Critical Thinking Web「Knights and knaves puzzles」：https://philosophy.hku.hk/think/logic/knights.php","Raymond Smullyan《What Is the Name of This Book?》（1978，中译《这本书叫什么？》）骑士与无赖一章——经上面 Wikipedia 条目转引，未直接翻阅原书"]},{"name":"归纳的强与弱","lv":2,"目标":"今天学会给归纳（从许多例子总结出规律）打分：看样本多不多、像不像全体；并记住一个反例就能推翻“所有……都……”。","类比":"归纳像尝汤：只舔一下勺子边就说整锅都咸，不靠谱；搅匀了多尝几口才更有把握。可只要捞到一块没熟的土豆，“全都煮熟了”这句话就破了。","讲解":"归纳是从“看到的这些”推到“全部”，结论只是“很可能”对：例子越多、越能代表全体，归纳越强；而一个反例就能推翻“所有……都……”。","口诀":"例子多又全，归纳才有力；反例只一个，全称就倒地","例子":["较强：从全校每个年级、每个班随机各问几位同学，一共问了100人，大多数吃早饭→“我们学校大多数同学吃早饭”比较靠得住","较弱：只问了同桌和好朋友两个人，都爱吃香菜，就说全班都爱吃香菜（样本太少）","较弱：只在篮球场上问了10个同学，都说最喜欢体育课，就说全校同学最喜欢体育课（样本是挑过的，不像全体）","反例：人们见过的天鹅都是白的，就说“所有天鹅都是白的”；后来在澳大利亚发现了黑天鹅，一只就推翻了","找规律：1、3、5、7、9、11、13……看起来每个奇数不是质数就是平方数，可15=3×5，两样都不是——一个反例，规律就破了","规律不唯一：2、4、8，下一个是几？可以是16（每次乘2），也可以是14（依次加2、加4、加6）。例子太少，几条规律都说得通","初中挑战：算式n×n+n+41，n从0试到39，结果全是质数；可n=40时得1681=41×41，不是质数。试对40次，第41次翻车","归纳会被新信息改变：看到乌云就带伞是合理的归纳；可如果又知道“这片云很快会被风吹走”，下雨的可能就小多了","错例：我吃过的三家店的饺子都是猪肉白菜馅，所以饺子都是猪肉白菜馅（三个例子推全部，一盘韭菜鸡蛋馅就推翻）","错例：这道数学题我验算了5个数都成立，所以已经证明它对所有数都成立（例子只能支持，证明要靠演绎）"],"深讲":"归纳是我们天天在用的推理：尝了几颗葡萄都很甜，就猜这一串都甜；连着几天七点出门都不堵车，就觉得明天七点也不堵。但归纳和演绎不一样：演绎只要前提真，结论一定真；归纳前提再真，结论也只是“很可能”，而且有强有弱，像温度计一样分程度。给归纳打分，看三样：一看样本多不多，问两个人和问一百个人差别很大；二看样本像不像全体，只在篮球场问，问到的多半是爱运动的人；三看有没有反例。最后记住一个“不对称”：要证明“所有天鹅都是白的”，看一万只白天鹅也不够；要推翻它，一只黑天鹅就够。所以聪明的人会主动去找反例，而不是只收集支持自己的例子。","怎么认":["先找结论：它说的是“所有/一定”，还是“大多数/很可能”？","再看样本：数量多不多？是不是只挑了某一处、某一类？","最后找反例：想一想有没有不符合的例子——找到一个，“所有”就站不住了。"],"辨析":"和“以偏概全”比：以偏概全是归纳弱到出错时的“病名”，从挑错的角度看；本专题教的是怎样给归纳打分、怎样用反例检验，是看病之前的“体检方法”。和“推理三兄弟：演绎/归纳/类比”比：那里认识归纳是什么，这里学它为什么只是“很可能”、怎样判断强弱。","例句解析":[{"句":"只在篮球场上问了10个同学，都说最喜欢体育课，就说全校同学最喜欢体育课","析":"毛病不只是人数少，更在于样本挑过了：在篮球场的同学本来就多半爱运动，代表不了全校。想让结论更强，要到各个年级、各个班随机去问。"},{"句":"算式n×n+n+41，n从0试到39全是质数，n=40时得1681=41×41","析":"前面40个例子都对，看起来像铁律，可第41个就是反例。这说明再多的例子也只能让归纳变强，不能变成证明；而一个反例就足以推翻“对所有n都成立”。"},{"句":"错例：我吃过的三家店的饺子都是猪肉白菜馅，所以饺子都是猪肉白菜馅","析":"只有三个样本，却推到“所有饺子”，结论说得太满。随便找到一种别的馅，就是反例。"}],"易错":"两个坑：把“很多例子都对”当成“已经证明”；以为反例要找很多个才算数——其实推翻“所有”，一个就够。","练习":[{"q":"想知道全校同学最喜欢哪门课，哪种调查最靠得住？","options":["只问自己的同桌","在篮球场上问10个同学","从全校每个班随机各问5个同学"],"answer":2,"解析":"样本多，又分布到各个班，最能代表全校；前两种要么太少，要么只挑了某一类人。"},{"q":"有人说“所有的鸟都会飞”。要推翻这句话，至少要找到几种不会飞的鸟？","options":["一种就够","至少十种","要找到一半以上"],"answer":0,"解析":"全称的“所有”，一个反例就能推翻，比如企鹅。"},{"q":"2、4、8，下一个数是几？下面说法最恰当的是？","options":["一定是16","一定是14","只给三个数，16和14都说得通"],"answer":2,"解析":"乘2的规律得16，依次加2、4、6的规律得14。例子太少，规律不唯一。"}],"讨论卡":{"问题":"家里有人说“下雨天堵车最厉害”。你们能设计一个小调查来检验吗？要记多少天？怎样记才公平？","提示":"样本要够多，晴天、雨天都要记；比较时最好是同一个时间段、同一段路。再想一想：有没有下雨却不堵的日子？那就是值得注意的反例。"},"前置知识":["推理三兄弟：演绎/归纳/类比","以偏概全"],"决策树":"①结论说的是“所有/一定”吗？→是：去找反例，找到一个就推翻→②样本太少吗？→是：归纳弱，结论要说得保守→③样本只挑了某一处、某一类吗？→是：不具代表性，归纳弱→④都过关：是比较强的归纳，但结论仍只是“很可能”，遇到新信息要随时修正","来源":["香港大学 Critical Thinking Web「A08 Inductive Reasoning」（归纳强度是程度问题、可被新信息削弱）：https://philosophy.hku.hk/think/arg/induction.php","Wikipedia「Faulty generalization」（草率归纳、样本不具代表性、奇数“质数或平方数”反例15）：https://en.wikipedia.org/wiki/Faulty_generalization","统编高中语文选择性必修上册第四单元「逻辑的力量·二 运用有效的推理形式」学习资料（排除法、选言推理、归纳/类比推理）：https://www.ixuehai.cn/html/1776.html"]},{"name":"类比的好与坏","lv":3,"目标":"今天学会判断类比推理（因为两样东西有些地方像，就推它们另一处也像）靠不靠得住：关键看相似点和结论有没有关系。","类比":"类比像借钥匙：邻居家的锁和你家是同一款（和“能不能打开”有关），借他的钥匙才有希望；两家门只是颜色一样（和开锁无关），钥匙照样打不开。","讲解":"类比推理：A和B在一些地方相似，A有某个特点，所以B可能也有。好类比要过三关：真的像；像的地方和结论有关；没有关键的不同点。","口诀":"像在哪里先看清，跟结论有关才算数；再找关键不同处，类比好坏心有数","例子":["较好：姐姐的自行车和我的是同一品牌同一型号，姐姐的车骑了一年链条松了，所以我的车骑久了也要留意链条（型号相同和零件磨损有关）","较好（课文）：《邹忌讽齐王纳谏》里，妻子偏爱邹忌、妾怕他、客人有求于他，所以都夸他比徐公美；齐王身边的人也偏爱他、怕他、有求于他，所以齐王受的蒙蔽更厉害——相似点正是“说好话”的原因","相关的相似点越多越强：两家面馆用同一家的面粉、同一种汤底，还是同一位师傅掌勺——推“这家也好吃”更有把握","关键不同点会削弱类比：两家面馆什么都一样，可这家刚换了新厨师——这个不同点和“好不好吃”关系很大","类比能启发、不能代替证明：传说鲁班被带齿的草叶划破手，想到做带齿的锯；点子从类比来，锯好不好用还得做出来试","科学里的类比：火星和地球都是绕太阳转的岩石行星，火星上也找到过液态水流过的痕迹，所以科学家猜火星上可能有过简单生命——这只是“可能”，还要靠探测器去找证据","较好：同一位老师教的两个班，用的是同一套复习方法，一班用了以后进步明显，二班照着做也可能进步（老师和方法都和成绩有关）","错例：这本书和那本书封面都是绿色的，那本很无聊，所以这本也无聊（封面颜色和内容无关）","错例：大树要多浇水才长得好，所以仙人掌也要天天浇水（都是植物，可“需要多少水”恰恰是它们最不一样的地方）","错例：“这篇小说1000字，写得流畅，得了奖；你这篇也是1000字、也流畅，所以一定能得奖”（字数和得奖关系不大，“一定”又说得太满）"],"深讲":"类比是“由此及彼”：不是从一般到个别，也不是从个别到一般，而是从这一个推到那一个。任何两样东西总能找到一点像的地方——麻雀和汽车都会动，洗衣机和学校都有很多“零件”——所以“像”本身不值钱，值钱的是“像在哪里”。判断类比，问三个问题：第一，真的像吗？第二，像的地方和要推的结论有没有关系？这是最要紧的一问。封面颜色和书好不好看没关系，同型号和链条会不会松就有关系。第三，有没有关键的不同点？两家店什么都一样，换了厨师就不一样了。课文里邹忌的类比之所以有力，是因为相似点（偏爱、害怕、有求）正是“爱说好话”的原因。类比很会帮人想点子、讲道理，但要真正证明，最好把背后的道理直接说出来。","怎么认":["找出是拿哪两样东西比，它们被说成在哪些地方相似。","问一句：这些相似点和要推出的结论有没有关系？没关系，类比就站不住。","再找一找有没有关键的不同点；结论如果说成“一定”，要降成“可能”。"],"辨析":"和“推理三兄弟：演绎/归纳/类比”比：那里认识类比是什么，这里学怎样判断它好不好。和修辞里的比喻比：比喻只是让话更形象（“月亮像小船”），并不要推出什么结论；类比推理要推出“B也有某个特点”，就得接受“相似点有没有关系”的检查。和“归纳的强与弱”比：归纳是从许多个推到全部，类比是从一个推到另一个。","例句解析":[{"句":"这本书和那本书封面都是绿色的，那本很无聊，所以这本也无聊","析":"两本书确实都是绿封面，第一关“真的像”过了；可封面颜色和书的内容无关，第二关就没过，类比不成立。"},{"句":"齐王身边的人也偏爱他、怕他、有求于他，所以齐王受的蒙蔽更厉害","析":"邹忌拿自己家和朝廷比，挑的相似点正是让人说好话的三个原因，和结论“受蒙蔽”紧紧相关；而且齐王身边这样的人更多，结论也就更进一步。这是一个好类比。"},{"句":"错例：大树要多浇水才长得好，所以仙人掌也要天天浇水","析":"大树和仙人掌都是植物，这个相似点是真的；但在“需要多少水”这件事上，两者恰好有关键的不同，所以类比不成立。"}],"易错":"两个坑：只数相似点有多少，不问它们和结论有没有关；把类比当铁证，说成“一定”。","练习":[{"q":"下面哪个类比最靠得住？","options":["两个同学都戴眼镜，一个会弹钢琴，另一个也会","同一棵树上、同一天摘的两个苹果，一个很甜，另一个也可能很甜","两本书都很厚，一本是童话，另一本也是童话"],"answer":1,"解析":"同一棵树、同一天摘，和“甜不甜”有关；戴眼镜和弹钢琴、书厚和是不是童话，都没关系。"},{"q":"“这本书和那本书都是绿封面，那本很无聊，所以这本也无聊。”毛病出在？","options":["两本书其实不是绿封面","相似点和结论没有关系","结论说得太谦虚"],"answer":1,"解析":"封面颜色是真的相同，但和内容好坏无关，相似点不相关，类比不成立。"},{"q":"判断一个类比好不好，最要紧的一问是？","options":["两样东西有几个相似点","相似点和结论有没有关系","两样东西的名字像不像"],"answer":1,"解析":"相似点再多，和结论无关也没用；相关性是第一位的。"}],"讨论卡":{"问题":"有人说：“学习就像跑马拉松，所以要一直匀速，不能冲刺。”这个类比哪里像、哪里不像？和家人聊一聊。","提示":"先找像的地方（都很长、都要坚持），再找和结论有关的不同点（比如考试前集中复习算不算“冲刺”？），想一想结论还站不站得住。"},"前置知识":["推理三兄弟：演绎/归纳/类比"],"决策树":"①说的是哪两样东西、在哪些地方相似？→②这些相似点是真的吗？→不是：类比不成立→是：③相似点和结论有关系吗？→没有：不当类比→有：④有没有和结论有关的关键不同点？→有：类比变弱，结论要打折扣→没有：是较好的类比，但结论仍只是“可能”","来源":["香港大学 Critical Thinking Web「A11 Analogical Arguments」（类比评估：真实性、相关性、数量、多样性、不相似点）：https://philosophy.hku.hk/think/arg/analogy.php","Stanford Encyclopedia of Philosophy「Analogy and Analogical Reasoning」§2–3（相似点须与结论相关）：https://plato.stanford.edu/entries/reasoning-analogy/","统编高中语文选择性必修上册第四单元「逻辑的力量·二 运用有效的推理形式」学习资料（排除法、选言推理、归纳/类比推理）：https://www.ixuehai.cn/html/1776.html"]},{"name":"选言推理：不是A就是B","lv":3,"目标":"今天学会选言推理（用“或者”“要么”列出几种可能来推理）：排除一个，肯定剩下的；同时检查选项列全了没有、能不能同时成立。","类比":"像走岔路口：路牌说“去公园要么走左边，要么走右边”，左边封路了，那就走右边。可如果其实还有一条中间小路，路牌没写，你的结论就可能错。","讲解":"“A或者B；不是A；所以是B”是有效的推理，前提是A、B已经把可能列全了。如果A和B可以同时成立（相容），那么肯定了A，推不出“不是B”。","口诀":"去掉一个留一个，先看选项全不全；能否同时都成立，肯定一个别乱删","例子":["数学书要么在书包里，要么在课桌里（只可能放在这两处）；书包里翻遍了没有→在课桌里","运动会上小林报了跑步、跳远、跳高中的一项；他没报跑步，也没报跳远→他报了跳高（选项多也一样，去掉的只剩一个）","不相容（只能有一个）：这场比赛要么红队赢，要么蓝队赢（规定不能平局）；红队赢了→蓝队没赢","相容（可以同时成立）：小明或者喜欢画画，或者喜欢唱歌（也可能都喜欢）；小明不喜欢画画→他喜欢唱歌（否定一个、肯定另一个，照样有效）","传话出错：“或者你说错了，或者我听错了”；我没听错→是你说错了。但“你说错了，所以我没听错”不成立——可能两人都错了","高中课文《拿来主义》也用了这个办法：先说明“闭关”“送去”“等人送来”都不行，最后只剩“自己去拿”（给哥哥姐姐和家长看）","错例（相容当不相容）：小明或者喜欢画画，或者喜欢唱歌；他喜欢画画→所以他不喜欢唱歌（两样可以都喜欢）","错例（选项没列全，叫“假二择一”）：“今晚你不来接我，我就只能露宿街头。”——还可以坐公交、打车、请别的亲友帮忙","班长要么是小东，要么是小西（老师只提名了他俩）；后来知道小东没当选→班长是小西","错例：这道题做错了，或者是算错，或者是抄错题；我发现算错了→所以没有抄错题（两种错可能同时发生）"],"深讲":"“或者”这个小词里，藏着一种很有用的推理。课本把它叫选言推理：先列出几种可能，再排除掉一部分，剩下的就是答案——“要么在书包，要么在课桌；书包里没有，那就在课桌里”。用好它要过两道检查。第一道：选项列全了吗？“你不来接我，我就只能露宿街头”，看起来只有两条路，其实还有公交、出租车……漏掉了别的可能，就叫“假二择一”，也就是常说的非黑即白。第二道：选项能不能同时成立？“喜欢画画或者喜欢唱歌”，两样可以都喜欢，这叫相容，只能“去掉一个、留下另一个”，不能“肯定一个、就删掉另一个”；“红队赢或者蓝队赢（不能平局）”只能有一个，叫不相容，两个方向都能推。","怎么认":["找出“或者”“要么……要么……”“不是……就是……”列出的几个选项。","检查选项列全了没有：有没有第三条路被漏掉？漏了就是假二择一。","看推理方向：“否定一个→肯定剩下的”总是对的；“肯定一个→否定另一个”只有在选项不能同时成立时才对。"],"辨析":"和“常见谬误”里的非黑即白比：非黑即白是选言推理的前提出了毛病——选项没列全；本专题先学正确的推理形式，再用“列全没有”去检查它。和“排除法：列表格破案”比：排除法是把“去掉一个留一个”在一整张表格上反复使用，选言推理是它最小的一块积木。","例句解析":[{"句":"数学书要么在书包里，要么在课桌里（只可能放在这两处）；书包里没有→在课桌里","析":"括号里的话保证了选项列全；否定了“书包”，就肯定剩下的“课桌”。这是有效的选言推理。"},{"句":"错例：小明或者喜欢画画，或者喜欢唱歌；他喜欢画画→所以他不喜欢唱歌","析":"画画和唱歌可以都喜欢，这两个选项是相容的。肯定了一个，推不出另一个是假的。能推出的只有：如果他不喜欢画画，那他喜欢唱歌。"},{"句":"错例：“今晚你不来接我，我就只能露宿街头。”","析":"说话人只摆出两条路，好像非此即彼，其实还有公交、出租车、请亲友帮忙等别的选择。选项没列全，这就是假二择一。"}],"易错":"两个坑：一是不检查选项是否列全，被“不是……就是……”牵着走；二是把相容的选项当成只能选一个，肯定了一个就去否定另一个。","练习":[{"q":"“这把钥匙要么是爸爸的，要么是妈妈的（家里只有他俩有这种钥匙）；它不是妈妈的。”结论是？","options":["是爸爸的","不是爸爸的","不能确定"],"answer":0,"解析":"选项已经列全，否定一个，就肯定剩下的：是爸爸的。"},{"q":"“小明或者喜欢画画，或者喜欢唱歌（也可能都喜欢）；小明喜欢画画。”能推出什么？","options":["小明不喜欢唱歌","小明喜欢唱歌","推不出小明喜不喜欢唱歌"],"answer":2,"解析":"两个选项可以同时成立，肯定了画画，唱歌喜欢不喜欢都有可能。"},{"q":"“这件衣服你不是喜欢，就是讨厌。”这句话的毛病在哪？","options":["推理形式错了","漏掉了别的可能，比如觉得一般","喜欢和讨厌可以同时成立"],"answer":1,"解析":"还可能“觉得一般”“无所谓”，选项没列全，是假二择一。"}],"讨论卡":{"问题":"想一想，有没有人对你说过“你要么……，要么……”这样的话？其实还有没有第三条路？","提示":"先问选项列全了没有，再问它们能不能同时成立。找到第三条路，往往就找到了更好的办法。"},"前置知识":["四大逻辑规律","常见谬误","排除法：列表格破案"],"决策树":"①找出“或者/要么/不是……就是……”列出的选项→②选项列全了吗？→没有：假二择一（非黑即白），结论不可靠→有：③推理方向是“否定一个→肯定剩下的”吗？→是：有效→不是，是“肯定一个→否定另一个”：④选项能同时成立吗？→能（相容）：无效→不能（不相容）：有效","来源":["统编高中语文选择性必修上册第四单元「逻辑的力量·二 运用有效的推理形式」学习资料（排除法、选言推理、归纳/类比推理）：https://www.ixuehai.cn/html/1776.html","维基百科「选言三段论」（P或Q，非P，所以Q；相容与不相容析取）：https://zh.wikipedia.org/wiki/选言三段论","Wikipedia「False dilemma」（假二择一：选言前提漏掉了其他可能）：https://en.wikipedia.org/wiki/False_dilemma"]}]},{"id":"pipan_siwei","name":"像科学家一样思考","items":[{"name":"事实还是观点","lv":2,"讨论卡":{"问题":"吃饭时和家人比一比：“今天的菜很咸”和“今天的菜放了两勺盐”有什么不同？哪一句能查证？","提示":"一句说的是感受（观点），一句能拿勺子数一数（事实）。感受不同不用吵，事实不同去查证据。"},"目标":"今天学会分辨一句话是“事实”（能拿证据查出真假的话）还是“观点”（说出感受、评价或主张的话）。","类比":"事实像尺子量出来的身高，谁来量都一样；观点像每个人心里的“最好吃”，各有各的口味。","讲解":"事实能查证真假（企鹅不会飞）；观点表达看法（企鹅最可爱）。","口诀":"能数能量能查证，是事实；好坏喜欢和应该，是观点","例子":["事实：我们班有42名同学（可以点名数一数）","观点：我们班是全校最团结的班级（“最团结”是评价）","事实：在标准大气压下，水加热到100℃会沸腾（可以做实验验证）","观点：夏天比冬天好玩（每个人感受不同）","事实：《小蝌蚪找妈妈》里，小蝌蚪最后找到了青蛙妈妈（翻课文就能核对）","观点：《小蝌蚪找妈妈》是最有趣的童话（“最有趣”是感受）","事实：昨天最高气温28℃（查天气记录）；观点：昨天热得受不了","错例：“冰淇淋是用牛奶做的，所以是最好吃的甜品”整句当成事实（前半句是事实，后半句“最好吃”是观点，混在一起了）","错例：同学说“地球是方的”，你回答“那是你的观点，我尊重”（这是一句能查证的事实性说法，只是说错了，应该拿证据纠正）","错例：“这道题明明很难！”“不对，这道题就是简单！”两人吵了半天（“难”“简单”是感受，吵不出对错；可以改问“全班有几个人做对”）"],"深讲":"操场边，两个同学在聊天。一个说：“这棵大树有五层楼高。”另一个说：“这棵大树真漂亮。”第一句可以拿卷尺、对照教学楼去核对，量出来多高就是多高——这叫事实性的说法（能用证据查出真假的话）。第二句说的是心里的感受，你觉得漂亮，他可能觉得一般，没有标准答案——这叫观点（表达感受、评价、主张的话）。这里有两个小秘密：第一，事实性的说法也可能是错的，“这棵树有五十层楼高”就是一句错的事实说法，拿证据一量就能纠正；第二，观点虽然没有唯一答案，但好的观点会拿事实当理由，比如“这棵树值得保护，因为它已经长了一百年”。分清这两种话，争论时就知道：争事实，去查证据；争观点，先听听对方的理由。","怎么认":["问一问：这句话能不能用数一数、量一量、查一查、做实验来核对？能，就是事实性说法。","找信号词：“最”“好看”“应该”“我觉得”“真棒”多半是观点；具体的数字、时间、地点多半是事实。","一句话里可能两样都有：拆开前后半句，分别判断。"],"辨析":"和“举例论证”比：议论文里，论点是观点，用来支撑它的事例、数据多是事实——举例论证就是“用事实撑观点”。另外，“事实”不等于“真话”：事实性说法也会说错；“观点”也不等于“胡说”：好观点要有理由。","例句解析":[{"句":"我们班有42名同学，是全校最团结的班级。","析":"前半句点名就能数清楚，是事实；后半句“最团结”是评价，没法用尺子量，是观点，需要拿理由（比如拔河比赛大家齐心协力）来支持。"},{"句":"错例：同学说“地球是方的”，你回答“那是你的观点，我尊重”","析":"“地球是方的”能用卫星照片、环球航行等证据核对，它是一句说错了的事实性说法，不是口味问题。把能查证的事当成“各有看法”，就放过了错误。"},{"句":"事实：昨天最高气温28℃（查天气记录）；观点：昨天热得受不了","析":"28℃有气象记录，谁查都一样；“热得受不了”是感受，怕热的人觉得热，怕冷的人可能觉得刚好。你不能用“才28℃”去证明别人“不热”。"}],"易错":"两个坑最常见：一是以为“事实”就等于“正确的话”，其实事实性说法也可能说错，关键看能不能查证；二是一句话里事实和观点混在一起，没有拆开看，就把后半句的评价也当成了事实。","练习":[{"q":"下面哪句是观点？","options":["长城位于中国北方","长城是世界上最壮观的建筑","长城是古代修建的"],"answer":1,"解析":"“最壮观”是评价，每个人感受不同；另外两句能查资料核对，是事实。"},{"q":"“这本书一共有200页”属于什么？","options":["事实","观点","都不是"],"answer":0,"解析":"翻到最后一页就能核对，是事实性说法。"},{"q":"同桌说“数学课最无聊”，你说“我觉得数学课最有趣”。这场争论最好怎么办？","options":["去查书看谁说的是真的","这是观点不同，可以听听彼此的理由","谁声音大谁就对"],"answer":1,"解析":"“无聊”“有趣”是感受，查不出唯一答案；说说各自的理由，互相理解就好。"}],"前置知识":[],"决策树":"①这句话能用数、量、查、做实验来核对吗？→能：事实性说法（再用证据查它对不对）→不能：②它在说喜欢、好坏、应该吗？→是：观点（问问理由是什么）→③一句话里两样都有：拆开前后半句，分别判断","来源":["https://www.thepaper.cn/newsDetail_forward_22153070 （Fact 能被证明真假、Opinion 表达信念感受；信号词）","https://philosophy.hku.hk/think/chi/basic-logic.php （陈述句与事实相符为真、不符为假）","http://alfred-sun.github.io/tuliangblog/asking-the-right-questions-a-guide-to-critical-thinking/ （布朗&基利《学会提问》各章要点：论题和结论、理由、假设、证据效力）"]},{"name":"证据够不够","lv":2,"讨论卡":{"问题":"同学说“我们小区的猫都怕狗”。你想问他哪些问题，才能判断这话靠不靠谱？","提示":"三问：你是听说的还是亲眼看到的？看到了几只猫？这些猫是不是都在同一个地方、同一种情况下？"},"目标":"今天学会给证据“打分”：听说、亲眼看见、记录下来的数据哪个更靠得住；看数据时还要问样本（被调查的那一部分）够不够多、像不像整体。","类比":"证据像过河的木板：一块小薄板（听说一次）踩上去就晃，很多块结实的木板（多次观察、大量公平的数据）才撑得住结论。","讲解":"一般来说：听说＜亲眼看见＜认真记录的数据；数据还要问：人数够多吗？挑得公平吗？","口诀":"听说打个问号，眼见还要再瞧；数据先看样本，又多又全才好","例子":["听说：“同桌说隔壁班明天放假”——二手消息，要去问老师核实","亲眼看见：“我看到小猫爬上了树”——比听说可靠，但天黑时也可能看错","数据：“科学课上全班记录了30天的天气，其中下雨8天”——有记录、能复查","样本太小：只问了2个同学都喜欢跳绳，就说“全校都爱跳绳”","样本挑偏：只在篮球场问“你喜欢篮球吗”，结果当然大多数说喜欢","好样本：从每个年级、每个班随机抽同学来问，样本更像全校","错例：“我爷爷从不刷牙也没蛀牙，所以刷牙没用”（一个人的经历撑不起结论）","错例：“网上有人说吃糖能变聪明”（来源不明的听说，不能当证据）","错例：“在图书馆问了50个同学，48个爱读书，所以全校96%的同学爱读书”（在图书馆问，样本挑偏了）","更好的说法：“从全校每个班随机问了200个同学，150个说每周都读课外书”——人数多、挑得公平"],"深讲":"侦探破案，从不只凭一句话。证据也有好有坏。“听说”是别人转告的二手消息，传一次就可能走样一次，就像传话游戏；“亲眼看见”可靠一些，但人也会看走眼，最好还有别人一起看到，或者拍了照片；“数据”是认真数过、记下来的结果，别人可以复查，通常更有分量。不过数据也有陷阱，要问两件事：第一，样本（被调查的那一部分）够不够多？只看两个苹果就说整箱都甜，太着急了。第二，样本像不像整体？在图书馆门口调查“爱不爱读书”，碰到的多半本来就爱读书，结果自然偏高。所以听到一个结论，先问三句：证据从哪儿来？有多少？挑得公不公平？","怎么认":["问来源：这是听说的、亲眼看到的，还是记录下来的数据？","问数量：证据有几个？只有一两个例子就要小心。","问代表性：被调查的人或东西，是不是只挑了某一部分特殊的？"],"辨析":"和“以偏概全”比：以偏概全是下结论那一步出错（拿部分当全部）；“证据够不够”是更早一步，先给证据本身打分——来源靠谱吗、样本够多够全吗。证据不够硬，往往就会导致以偏概全。和“诉诸权威”比：名人的话也只是一种证词，要看他是不是这方面的行家、有没有拿出数据。","例句解析":[{"句":"错例：“我爷爷从不刷牙也没蛀牙，所以刷牙没用”（一个人的经历撑不起结论）","析":"这是一个个例。爷爷可能牙齿天生好，或者别的原因。要知道刷牙有没有用，得看很多很多人的情况，而不是一个人的故事。"},{"句":"错例：“在图书馆问了50个同学，48个爱读书，所以全校96%的同学爱读书”（在图书馆问，样本挑偏了）","析":"50人不算少，毛病出在“挑在哪里问”：去图书馆的人本来就更爱读书，他们不像全校。应该从每个班随机抽人问。"},{"句":"亲眼看见：“我看到小猫爬上了树”——比听说可靠，但天黑时也可能看错","析":"亲眼看见是一手证据，比传话可靠；可如果光线暗、离得远，也许是只松鼠。有同伴一起看到或拍了照，就更有把握。"}],"易错":"两个坑：一是以为“亲眼看见的一定对”，其实眼睛也会看错；二是以为“有数字就一定科学”——数字背后的样本可能太少，或者挑得不公平。","练习":[{"q":"哪个证据最靠得住？","options":["小红说她表哥说的","我昨天偶然看到一次","科学课上全班连续记录了一个月的数据"],"answer":2,"解析":"有记录、时间长、能复查的数据最有分量；听说是二手消息，偶然一次可能是巧合。"},{"q":"只在篮球场调查“喜不喜欢篮球”，问题出在哪？","options":["人数太多","样本挑偏了，不像全校同学","调查时间太长"],"answer":1,"解析":"在篮球场的人本来就更爱篮球，他们不能代表全校。"},{"q":"想知道全校同学最喜欢什么水果，怎么调查最好？","options":["只问自己的好朋友","从每个班随机抽一些同学来问","只问一个同学，问得特别仔细"],"answer":1,"解析":"每个班都抽、随机挑，样本才像全校；只问朋友或只问一个人，样本太偏或太少。"}],"前置知识":["事实还是观点","以偏概全"],"决策树":"①证据从哪来？→听说/网上传言：先打问号，去找原始来源→亲眼看见：有没有别人或照片能印证→记录的数据：②样本够多吗？→太少：结论不稳→③样本像整体吗（挑得公平吗）？→挑偏了：结论不能推广到全体→都过关：证据比较有力","来源":["https://philosophy.hku.hk/think/chi/stat.php （§3 抽樣統計：隨機抽樣、偏差樣本、樣本數目越大抽樣誤差越小）","https://philosophy.hku.hk/think/stat/samples.php （Samples and biases：靠近工业区捞鱼的偏差样本）","http://alfred-sun.github.io/tuliangblog/asking-the-right-questions-a-guide-to-critical-thinking/ （布朗&基利《学会提问》各章要点：论题和结论、理由、假设、证据效力）"]},{"name":"控制变量：公平的实验","lv":2,"讨论卡":{"问题":"你想知道冷水还是热水化糖更快，在家怎么设计一个公平的实验？","提示":"只让水温不同；糖一样多、水一样多、杯子一样、搅拌方法一样。用热水请大人在旁边帮忙。"},"目标":"今天学会设计公平的对比实验：想研究哪个条件，每次就只改变这一个，其他条件都保持一样（控制变量）。","类比":"像赛跑比谁快：大家要站同一条起跑线、跑同样长的跑道，只比“人”不同；要是有人少跑50米，赢了也不算数。","讲解":"想知道某个条件有没有影响，就只改这一个，其余全都相同，再比结果。","口诀":"只改一个看变化，其余条件都不动它","例子":["研究水对种子发芽的影响：两组种子一样多、同样的土和温度，只有一组浇水、一组不浇","研究摆锤轻重会不会影响摆的快慢：线长、拉开的角度都不变，只换摆锤","纸飞机比赛：想比机翼长短，就用同样的纸、同样的力气，只改机翼长度","溶解实验：想知道水温的影响，糖一样多、搅拌方法一样，只改水温","错例：一盆豆芽放在温暖有阳光的窗台，另一盆放在阴冷的角落（温度和阳光两个条件都变了，说不清是谁起作用）","错例：同时把摆线加长、又换了更重的摆锤，发现摆慢了，就说“重的摆更慢”（改了两个条件）","错例：比哪种纸巾吸水多，A纸巾用一张，B纸巾用三张（纸巾数量也不同，不公平）","我们故意改变的那个条件，科学上叫“自变量”；观察它带来什么结果，那个结果叫“因变量”","保持不变的那些条件叫“控制变量”，它们保证比赛公平","每组不止用一粒种子、实验多做几次，结果更可靠"],"深讲":"小科想知道：种子发芽需要水吗？他准备了两个杯子，一杯放在暖和的窗台天天浇水，一杯放进冰箱也不浇水。一周后，窗台那杯发芽了，冰箱那杯没发芽。他能说“发芽需要水”吗？不能！因为两杯除了水，温度也不一样，到底是缺水还是太冷，说不清。这就像一个人在平地跑、一个人在沙地跑，赢了也不知道谁跑得快。科学家的办法叫控制变量：想研究哪个条件，就只改变这一个，其余的——种子多少、土、温度、光照——全部保持一样。这样，结果有差别，才能放心地说是这个条件造成的。每次只问一个问题，一个一个查，这就是公平的实验。","怎么认":["先说清楚：这个实验想研究的是哪一个条件？","数一数：两组之间一共有几处不同？","只有要研究的那一处不同，才公平；多出别的不同，就要改实验。"],"辨析":"和“强加因果”比：强加因果是把没关系的两件事硬说成因果；控制变量是科学家用来“检查”因果的工具——只改一个条件，结果跟着变了，才有资格说它是原因。没控制变量就下结论，很容易变成强加因果。","例句解析":[{"句":"错例：一盆豆芽放在温暖有阳光的窗台，另一盆放在阴冷的角落（温度和阳光两个条件都变了，说不清是谁起作用）","析":"想研究温度，却把阳光也一起改了。豆芽长得不一样，可能是因为暖和，也可能是因为有光。应该让两盆都晒到同样的光，只改温度。"},{"句":"研究摆锤轻重会不会影响摆的快慢：线长、拉开的角度都不变，只换摆锤","析":"只换摆锤，结果发现快慢几乎没变，这就说明摆锤轻重不影响摆的快慢。小学科学课做过这个实验：真正决定快慢的是摆线长度。"},{"句":"错例：比哪种纸巾吸水多，A纸巾用一张，B纸巾用三张（纸巾数量也不同，不公平）","析":"三张当然可能比一张吸得多。要比的是“哪种纸巾”，那么数量、大小、泡水时间都得一样。"}],"易错":"只记得“改一个条件”，却没检查其他条件是不是真的一样（种子数量、杯子大小、浇水时间）；还有每组只用一粒种子、只做一次，偶然性太大。","练习":[{"q":"研究“光照对绿豆芽生长的影响”，哪个条件应该不同？","options":["浇水量","光照","绿豆品种"],"answer":1,"解析":"要研究光照，就只让光照不同；浇水量、品种都要保持一样。"},{"q":"小明比哪种球弹得高：篮球从1米高放下，皮球从2米高放下。问题在哪？","options":["球的颜色不同","放下的高度也不同，改了两个条件","实验做太多次了"],"answer":1,"解析":"高度不同本身就会影响弹多高，应该从同样高度放下。"},{"q":"摆的实验中，只换更重的摆锤，快慢没变，说明什么？","options":["摆锤重量不影响摆的快慢","摆线长度不影响摆的快慢","实验一定做错了"],"answer":0,"解析":"只改了重量、结果没变，说明重量不是原因；摆线长度这次没改，不能对它下结论。"}],"前置知识":["证据够不够","强加因果"],"决策树":"①这个实验想研究哪个条件？→②两组之间除了它，还有别的不同吗？→有：不公平，先把别的条件改成一样→没有：③每组是不是太少、只做了一次？→是：多放几份、多做几次→否：这是公平的对比实验，可以谨慎地下结论","来源":["https://www.bbc.co.uk/bitesize/articles/zssccmn （BBC Bitesize KS2：fair test、三类变量）","https://www.makid.cn/gainian/bai （小学科学「摆的快慢」：每次只改一个条件）"]},{"name":"学会提问：论点和理由","lv":3,"讨论卡":{"问题":"家里有人说“周末应该去爬山”。请你用“理由是什么？”“理由靠得住吗？”两个问题和他聊一聊。","提示":"先请对方说出理由（锻炼身体、天气好），再一起查查天气预报、算算时间够不够——这就是在“敲桌腿”。"},"目标":"今天学会拆开一段话：找出论点（也叫结论，对方想让你相信什么）和理由（他凭什么这样说），再追问理由靠不靠得住。","类比":"论证像一张桌子：桌面是论点，桌腿是理由。先看有几条腿，再敲一敲每条腿结不结实。","讲解":"论证＝论点＋理由。先问“理由是什么”，再问“理由靠得住吗、撑得住论点吗”。","口诀":"先找论点再找由，理由靠谱才点头","例子":["“我们应该多种树（论点），因为树能挡风沙、让空气更清新（理由）”","“今天应该带伞（论点），因为天气预报说下午有雨（理由）”","找理由的信号词：因为、由于、毕竟、原因是……","找论点的信号词：所以、因此、可见、我认为、应该……","只有论点没有理由：“小狗是最好的宠物！”——这只是一句观点，还算不上论证","追问理由：“天气预报说有雨”——是气象台发布的吗？是今天的预报吗？","错例：“这部动画片好看，因为它很好看”（理由只是把论点又说了一遍，等于没给理由）","错例：“我们班应该去动物园春游，因为我最喜欢动物园”（理由只说了一个人的喜好，撑不起全班的决定）","错例：“这条路最近，因为我表哥说的”（理由只是听说，没讲清路到底近在哪）","追问三连：你想让我相信什么？你的理由是什么？理由是真的吗、和论点有关系吗？"],"深讲":"有一本写给大人看的书叫《学会提问》，它把读文章比作淘金：不是别人说什么都像海绵一样吸进去，而是一边读一边问问题。第一个问题：“他想让我相信什么？”这就是论点，也叫结论。第二个问题：“他凭什么这么说？”这就是理由。论点加理由，合起来才叫一个论证；只有论点没有理由，只是一句光秃秃的观点。找到理由后还要追问：理由本身是真的吗？比如“天气预报说下午有雨”，要看是不是今天正规的预报。理由和论点有关系吗？比如“我最喜欢动物园”，能说明全班都该去动物园吗？不太能。会提问的人不是爱抬杠，而是想把道理弄清楚，再决定信不信。","怎么认":["找论点：借助“所以、应该、我认为”等词，问“他想让我相信什么？”","找理由：借助“因为、由于、毕竟”等词，问“他凭什么这么说？”","敲桌腿：理由是真的吗？理由和论点有关系、够不够撑起它？"],"辨析":"和“举例论证”比：举例论证是用事例当理由的一种写法；“学会提问”是读别人的话时的一套追问方法，不管理由是事例、道理还是数据，都要问它靠不靠得住。统编教材说的“论点—论据—论证”里，这里的“理由”大致相当于论据。","例句解析":[{"句":"“我们应该多种树（论点），因为树能挡风沙、让空气更清新（理由）”","析":"“应该多种树”是他想让我们相信的，是论点；“能挡风沙、让空气清新”回答了“凭什么”，是理由。两条理由都能查到依据，也和论点有关，这张桌子比较稳。"},{"句":"错例：“我们班应该去动物园春游，因为我最喜欢动物园”（理由只说了一个人的喜好，撑不起全班的决定）","析":"理由是真的（他确实喜欢），但和论点关系太弱：全班的决定要看大多数人的意见、路程、安全、费用。这条桌腿太细，撑不住。"},{"句":"错例：“这部动画片好看，因为它很好看”（理由只是把论点又说了一遍，等于没给理由）","析":"桌腿和桌面是同一块板——理由就是论点本身。可以改成“这部动画片好看，因为故事有很多反转，画面也很细致”。"}],"易错":"一是把理由当成论点：“因为天气预报说有雨”是理由，“应该带伞”才是论点；二是以为有“因为”就一定是好理由——还得检查理由真不真、和论点相不相关。","练习":[{"q":"“我们应该节约用水，因为地球上能直接用的淡水很少。”论点是？","options":["地球上能直接用的淡水很少","我们应该节约用水","水很重要"],"answer":1,"解析":"他想让我们相信的是“应该节约用水”；“淡水很少”是撑起它的理由。"},{"q":"下面哪句只有论点、没有理由？","options":["我喜欢春天，因为能放风筝","春天是最好的季节！","应该早睡，因为睡够了第二天有精神"],"answer":1,"解析":"第二句只喊出看法，没说“凭什么”，还算不上论证。"},{"q":"“这条路最近，因为我表哥说的。”最该追问什么？","options":["表哥几岁了","表哥是怎么知道的？有没有量过或比过？","路边有没有商店"],"answer":1,"解析":"理由只是听说，要问它从哪来、靠不靠得住；表哥的年龄和商店与论点无关。"}],"前置知识":["事实还是观点","举例论证"],"决策树":"①他想让我相信什么？（找论点）→找不到：先请他说清楚→②他给理由了吗？→没有：只是观点，不急着信→有：③理由是真的吗？→拿不准：去查证据→④理由和论点有关、够撑住吗？→不够：论证很弱→都过关：可以考虑接受","来源":["http://alfred-sun.github.io/tuliangblog/asking-the-right-questions-a-guide-to-critical-thinking/ （布朗&基利《学会提问》各章要点：论题和结论、理由、假设、证据效力）","https://namejlt.github.io/posts/reading/note/book/learn-ask/ （《学会提问》读书笔记：论证＝结论＋理由、证据类型评估）","https://philosophy.hku.hk/think/chi/arg-analysis.php （好的論證：前題有充份証據支持、前題與結論相關）"]},{"name":"隐含前提","lv":3,"讨论卡":{"问题":"同学说“这本书很厚，所以一定很难读”。你能把他心里没说出来的那句话找出来，再举一个反例吗？","提示":"藏着的那句是“厚的书都难读”。反例：很厚的绘本合集、字很大的故事书。"},"目标":"今天学会找出话里没说出来、却被推理偷偷依靠的假设（隐含前提），并检查它站不站得住。","类比":"像冰山：说出来的理由只是露出水面的一角，水下还藏着一大块没说的假设，船撞上的往往是水下那块。","讲解":"从理由到结论中间缺的那一句，就是隐含前提；把它补出来，再问“它对吗？”","口诀":"话里藏着一句话，挖出来再查一查","例子":["“小明戴眼镜，所以他学习一定好”——隐含前提：戴眼镜的人学习都好（不成立）","“这个苹果是红的，所以一定很甜”——隐含前提：红苹果都甜（不一定）","“鲸是哺乳动物，所以鲸用肺呼吸”——隐含前提：哺乳动物都用肺呼吸（成立）","“明天要考试，我今晚早点睡”——隐含前提：睡得好，第二天精神好（大体合理）","“他是班长，所以他说的一定对”——隐含前提：班长说的话都对（不成立）","“这家包子铺门口排长队，所以包子一定最好吃”——隐含前提：排队人最多的就最好吃（不一定，也可能是便宜或刚开业）","错例：同学说“你没举手，所以你不会这道题”，你只顾着争“我会！”，却没发现他偷偷假设了“不举手就是不会”","错例：认为“小华上四年级，所以她一定十岁”是必然的（隐含前提“四年级学生都十岁”不成立）","错例：以为隐含前提都是错的——“铜是金属，所以铜导电”里藏着“金属都导电”，它是对的","找法：问自己“要让这个结论成立，还必须相信哪句话？”"],"深讲":"妈妈说：“外面在下雨，带上伞。”这句话里其实藏着一句没说的话：“打伞能挡雨。”因为大家都同意，所以不用说出来。这种话里没说、推理却偷偷依靠的假设，就叫隐含前提。很多时候它没问题，可有时候毛病就藏在这里。比如有人说：“小明戴眼镜，所以他学习一定好。”把藏着的那句补出来——“戴眼镜的人学习都好”——一看就知道不对。香港大学的批判性思考网教了一个好办法：先看理由能不能直接推出结论；推不出，就补上一句让它推得出的话，这句就是隐含前提，然后再问它是什么意思、该不该接受。把水下的冰山挖出来，很多看似有理的话就现了原形。","怎么认":["找出结论和理由。","问：光凭这个理由，结论一定成立吗？中间缺了哪一句？","把缺的那句补出来，再问：这句话对吗？能不能找到反例？"],"辨析":"和“言外之意”比：言外之意是说话人想让你听出来的意思（“好冷啊”可能是请你关窗）；隐含前提是推理中缺的那一步，是结论成立必须依靠的假设。和“三段论”比：把隐含前提补上，往往就是三段论里被省掉的大前提。","例句解析":[{"句":"“小明戴眼镜，所以他学习一定好”——隐含前提：戴眼镜的人学习都好（不成立）","析":"理由“戴眼镜”推不出“学习好”，中间必须加上“戴眼镜的人学习都好”。这句很容易找到反例：有人因为看太多电视而近视。前提倒了，结论也就靠不住。"},{"句":"“鲸是哺乳动物，所以鲸用肺呼吸”——隐含前提：哺乳动物都用肺呼吸（成立）","析":"补出来的前提是对的，这个推理就站得住。可见找隐含前提不是为了挑刺，而是为了看清推理到底靠什么撑着。"},{"句":"“这家包子铺门口排长队，所以包子一定最好吃”——隐含前提：排队人最多的就最好吃（不一定，也可能是便宜或刚开业）","析":"排队可能是因为好吃，也可能因为便宜、刚开业、做得慢。补出的前提有很多反例，所以“一定最好吃”下得太早。"}],"易错":"一是以为隐含前提都是错的——其实很多是对的，只是没说；二是补出来的那句要刚好能把理由和结论连起来，别补成一句不相干的话，也别把方向补反（“乌鸦是黑的”≠“黑鸟都是乌鸦”）。","练习":[{"q":"“这只鸟是黑色的，所以它是乌鸦。”藏着的前提是？","options":["乌鸦是黑色的","黑色的鸟都是乌鸦","这只鸟会飞"],"answer":1,"解析":"要从“黑色”推出“乌鸦”，必须假设“黑色的鸟都是乌鸦”——这显然不对，八哥、黑天鹅也是黑的。“乌鸦是黑色的”方向反了。"},{"q":"“他是体育委员，所以他跑步一定最快。”藏着的假设是？","options":["体育委员跑步都最快","他喜欢跑步","跑步对身体好"],"answer":0,"解析":"补上“体育委员跑步都最快”，推理才连得上；这句话并不成立。"},{"q":"下面哪个隐含前提是成立的？","options":["红苹果都甜","会游泳的动物都是鱼","哺乳动物都用肺呼吸"],"answer":2,"解析":"哺乳动物（包括鲸、海豚）都用肺呼吸；青苹果也能很甜，会游泳的狗不是鱼。"}],"前置知识":["学会提问：论点和理由","三段论"],"决策树":"①找出理由和结论→②光凭理由能推出结论吗？→能：没有关键的隐含前提→不能：③补一句让它推得出的话（隐含前提）→④这句话对吗？有反例吗？→对：推理站得住→有反例：隐含前提不成立，结论靠不住","来源":["https://philosophy.hku.hk/think/arg/hidden.php （先判断是否对确，不对确就补上使之对确的前提，再问其意义与是否该接受）","https://philosophy.hku.hk/think/chi/arg-analysis.php （隱含前題）","http://alfred-sun.github.io/tuliangblog/asking-the-right-questions-a-guide-to-critical-thinking/ （布朗&基利《学会提问》各章要点：论题和结论、理由、假设、证据效力） （描述性假设：理由与结论之间的联接）"]},{"name":"复杂问语","lv":3,"讨论卡":{"问题":"和家人玩个游戏：轮流编一个“藏钩子”的问题，让对方找出钩子藏在哪儿，再想想该怎么回答。","提示":"钩子就是问题里被偷偷当真的那句话。拆出来，问它是不是真的；不是，就先指出来再回答。"},"目标":"今天学会识破“复杂问语”（问题里偷偷塞进一个没被证明的说法，答“是”答“否”都像承认了它），并学会先拆问题再回答。","类比":"像一个只有两扇门的房间，问你“走左门还是右门”，可两扇门后面是同一个坑；聪明的做法是说“我根本不进这个房间”。","讲解":"“你还在偷懒吗？”答“是”“不是”都等于承认以前偷懒；先拆出藏着的说法再回应。","口诀":"问里藏钩子，先拆不上钩","例子":["“你还在偷懒吗？”——藏着：你以前偷懒过","“你把我的橡皮藏到哪里去了？”——藏着：橡皮是你藏的","“你是从什么时候开始讨厌数学的？”——藏着：你讨厌数学","“你以后还抄作业吗？”——藏着：你抄过作业","拆穿的回答：“我没有偷懒过，所以谈不上‘还在’。”","正常的问题：“你今天的作业写完了吗？”——今天确实留了作业，没有偷塞有争议的说法","正常的问题：“你昨天几点睡的？”——每个人都要睡觉，这个前提没争议","错例：被问“你还在偷懒吗？”，急着回答“没有，我已经不偷懒了！”（反而承认了以前偷懒）","错例：同学问“你的铅笔是在哪儿买的？”，你说他在设陷阱（你确实有这支铅笔，前提是真的，这是正常问题）","错例：被问“你是从什么时候开始讨厌数学的？”，你认真回答“三年级吧”（其实你并不讨厌数学，却顺着问题承认了）"],"深讲":"有个问题很狡猾：“你还在偷懒吗？”如果答“是”，等于承认现在在偷懒；如果答“不是”，听起来像“以前偷懒，现在不了”。怎么答都掉进坑里，因为问题里偷偷塞了一句没被证明的话：“你以前偷懒过。”这种问题在逻辑书里叫“复杂问语”（也叫复合问题）。香港大学的批判性思考网举过类似的例子：“你已经不再犯傻了吗？”不管回答是或否，都等于承认自己犯过傻。破解办法很简单：先别急着答是或否，把藏着的那句话拆出来，说“我没有偷懒过，所以这个问题不成立”。不过也别草木皆兵：要是藏着的那句话是真的、大家都同意，比如“你今天的作业写完了吗”，那就是正常的问题。","怎么认":["先别急着答，问：这个问题有没有把某件事当成“已经发生”或“已经是真的”？","把藏着的那句话说出来（比如“你以前偷懒过”），看它是真的、大家都同意吗？","如果它没被证明或者不是真的，就先指出来，再回答。"],"辨析":"和“非黑即白”比：非黑即白是只给两个选项、漏掉别的可能；复杂问语是问题里藏着一个没被证明的说法，不管给几个选项，回答都等于承认它。和“隐含前提”比：隐含前提藏在推理里，复杂问语藏在问题里。","例句解析":[{"句":"“你还在偷懒吗？”——藏着：你以前偷懒过","析":"“还在”两个字就是钩子：它默认你偷懒过。答“是”“不是”都咬了钩。正确做法是先摘钩：“我没有偷懒过。”"},{"句":"“你把我的橡皮藏到哪里去了？”——藏着：橡皮是你藏的","析":"问“藏到哪里”之前，先认定了“是你藏的”。如果没有证据，应该先问“我的橡皮不见了，有人看到吗？”"},{"句":"错例：同学问“你的铅笔是在哪儿买的？”，你说他在设陷阱（你确实有这支铅笔，前提是真的，这是正常问题）","析":"这个问题也有前提（你有铅笔），但前提是真的、没争议，所以是正常提问。只有藏着的说法没被证明或不对时，才是复杂问语。"}],"易错":"一是急着答“是/不是”，直接掉进坑；二是把所有带前提的问题都当陷阱——藏着的那句如果是真的、大家都同意，就是正常提问。","练习":[{"q":"“你为什么总是迟到？”这个问题藏着什么说法？","options":["你从来不迟到","你总是迟到","学校很远"],"answer":1,"解析":"“为什么总是迟到”先认定了“你总是迟到”；如果这不是事实，就要先指出来。"},{"q":"你从没玩过弟弟的玩具车，却被问“你还在玩弟弟的玩具车吗？”最好怎么回答？","options":["不玩了","还在玩","我从来没玩过他的玩具车"],"answer":2,"解析":"答“不玩了”等于承认玩过；先拆掉藏着的说法才对。"},{"q":"哪个是复杂问语？","options":["你今天吃早饭了吗","你把偷吃的饼干藏哪儿了","你喜欢什么颜色"],"answer":1,"解析":"它先认定“你偷吃了饼干”，再问藏在哪；另外两个问题没有偷塞有争议的说法。"}],"前置知识":["隐含前提","常见谬误"],"决策树":"①问题里有没有把某件事当成已经发生、已经是真的？→没有：正常问题，直接回答→有：②这件事是真的、大家都同意吗？→是：正常问题→不是或没被证明：复杂问语→③先拆出藏着的那句话并指出来，再回答","来源":["https://philosophy.hku.hk/think/fallacy/ip.php （Inappropriate presumption：“Have you stopped being an idiot?” 无论答是或否都承认）","https://iep.utm.edu/fallacy/ （Complex Question、Small Sample、Anecdotal Evidence 条目）"]}]}]},"reading":{"categories":[{"id":"tongyong","items":[{"name":"三遍阅读法","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">第一遍泛读</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">抓体裁、抓主旨</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">第二遍精读</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">析结构、圈关键句</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">第三遍跳读</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">带着题目找答案区</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">泛读只看标题+首尾段，1分钟定体裁</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">精读圈出过渡句、抒情议论句</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">跳读</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">题干关键词→原文定位→前后三句找答案</text></g></svg>","例子":["第一遍泛读：抓体裁、抓主旨","第二遍精读：析结构、圈关键句","第三遍跳读：带着题目找答案区","泛读只看标题+首尾段，1分钟定体裁","精读圈出过渡句、抒情议论句（主旨常藏这里）","跳读：题干关键词→原文定位→前后三句找答案"],"口诀":"泛读抓主旨，精读析结构，跳读找答案","易错":"切忌没读完文章就匆忙答题","讲解":"中考阅读的标准流程，先整体后局部","怎么认":["第一遍通读：不查生词、不纠结细节，3分钟内读完，标出自然段号，心里回答'这篇文章讲了什么事'。","第二遍带题读：读题干、圈题眼，带着问题回原文找答案，关键句下画线。","第三遍验证读：写完答案后，把每个答案代回原文，检查'题干问的'和'我答的'是不是一回事。"],"例句解析":[{"句":"题：'三遍阅读法'中，第二遍读的主要任务是什么？","析":"走三遍流程：第一遍已通读全文知道大意；第二遍的关键是'带题'——读题干、圈题眼（如'主要任务'），回原文定位到讲第二遍的段落；第三遍验证：答案'带着题目找答案、圈画关键句'与原文'先整体后局部'的第二步一致，确认无误。"}],"前置知识":[]},{"name":"找中心句","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">开头总起句、结尾总结句</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">段落首句尾句</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">议论文开头</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"勤奋是成功之母\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">记叙文结尾</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"这就是我的母亲\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">抒情议论句多是中心句，叙事句一般不是</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">独立成段的句子，常是中心句或过渡句</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["开头总起句、结尾总结句","段落首句尾句","议论文开头：\"勤奋是成功之母\"（开门见山亮观点）","记叙文结尾：\"这就是我的母亲\"（点题+抒情）","抒情议论句多是中心句，叙事句一般不是","独立成段的句子，常是中心句或过渡句"],"口诀":"开头结尾重点看，首尾常把中心担","易错":"中心句多是议论抒情句，不是叙事句","讲解":"中心句常出现在开头结尾、段落首尾，多为概括性语句","怎么认":["先看段首和段尾：中心句八成藏在这两个位置，先读这两句。","找总结性词语：'总之''可见''因此''归根结底'后面的句子多半是中心句。","做减法验证：删掉举例、数据、细节描写，剩下的主干如果能概括全段，就是中心句。"],"例句解析":[{"句":"段落：'春天来了。小草探出头来，柳树抽出新芽，燕子从南方飞回来。总之，大自然在春天苏醒了。'中心句是哪句？","析":"按步骤找：先看段首段尾——段尾'总之，大自然在春天苏醒了'；再看标志词——'总之'是典型总结词；做减法验证——删掉小草、柳树、燕子三个例子，剩下的'大自然在春天苏醒了'正好概括全段。三步都指向最后一句，确认。"}],"前置知识":["主语","谓语"]},{"name":"语境意识","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">词语含义到上下文中找</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答案组织紧扣文章中心</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">\\\"他'火'了\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">语境是演出→走红，不是着火</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"这个人很'冷'\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">语境是待人→冷漠，不是温度</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">答题引用原文，别自己编</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">开放题也要先扣文本再引申</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["词语含义到上下文中找","答案组织紧扣文章中心","\"他'火'了\"：语境是演出→走红，不是着火","\"这个人很'冷'\"：语境是待人→冷漠，不是温度","答题引用原文，别自己编","开放题也要先扣文本再引申"],"口诀":"词不离句，句不离段，段不离篇","易错":"脱离文本的过度推断是丢分主因","讲解":"一切答案以文本为依据，联系上下文","怎么认":["词语题先把词放回原句，连读三遍，不许脱离上下文猜词义。","看前后句的逻辑关系：是转折（但是）、因果（所以）、并列（同时）？关系决定词义方向。","用全文主旨做终审：凡是和主旨矛盾的理解，一律排除。"],"例句解析":[{"句":"'他这个人很冷，但心肠极热。'中'冷'是什么意思？","析":"走语境三步：放回原句读——'冷'后紧跟转折'但心肠极热'；看逻辑关系——'但'表转折，'冷'与'热'相反，'冷'应指外表冷漠；用主旨终审——全句褒扬此人，'冷'不能解作'心寒、恶劣'。答案：外表冷淡、不热情。"}],"前置知识":[]},{"name":"关键句定位","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">关键句定位</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开头句、结尾句、过渡句、抒情议论句常藏着主旨</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">读题干圈题眼：人名、时间、关键词，带着题眼去原文'扫描'。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">锁定四类句子优先看：开头句、结尾句、过渡句、抒情议论句，主旨多藏在这里。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">逐字核对：把题干的每个词和原文对应句比对，偷换概念的最爱玩'差不多'游戏。</text></g></svg>","例子":["体现作者立场的句子，常在开头、结尾或段落末尾","过渡句、抒情议论句、比喻句，常承载主旨","“总之”“因此”后面的句子常是总结句","独立成段的一句话，常起强调或过渡作用","反问句“难道这不是……吗？”往往是立场句","开头设问后自答的地方，常是全文纲领"],"口诀":"立场过渡抒情议论，比喻连问要留神","易错":"独立成段的句子常有特殊作用","讲解":"开头句、结尾句、过渡句、抒情议论句常藏着主旨","怎么认":["读题干圈题眼：人名、时间、关键词（如'第一次'），带着题眼去原文'扫描'。","锁定四类句子优先看：开头句、结尾句、过渡句、抒情议论句，主旨多藏在这里。","逐字核对：把题干的每个词和原文对应句比对，偷换概念的最爱玩'差不多'游戏。"],"例句解析":[{"句":"题：'作者在开头写那是一个寒冷的冬天有什么作用？'如何定位？","析":"三步定位：圈题眼——'开头''冬天'；锁定句子类型——开头句，属'四类关键句'之首；逐字核对——'寒冷的冬天'是环境描写，对应'开头：奠定感情基调/渲染气氛'。答案：渲染悲凉气氛，为下文做铺垫。"}],"前置知识":["找中心句"]}],"name":"通用阅读方法"},{"id":"tixing","items":[{"name":"概括内容","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">模式</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">什么人＋在什么情况下＋做什么事＋什么结果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">如</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">本文记叙了小明在雨天坚持上学的故事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">要素法</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间+地点+人物+起因+经过+结果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">合并段意</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">每段小标题→连成一句话</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">摘录法</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">找中心句，稍加改造</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">只写\\\"本文写了一件事\\\"</text></g></svg>","例子":["模式：什么人＋在什么情况下＋做什么事＋什么结果","如：本文记叙了小明在雨天坚持上学的故事","要素法：时间+地点+人物+起因+经过+结果（记叙文）","合并段意：每段小标题→连成一句话","摘录法：找中心句，稍加改造","忌：只写\"本文写了一件事\"（缺要素=白答）"],"口诀":"人物事件加结果，要素齐全才算数","易错":"必须包括“人物+事情”两要素","讲解":"要素归纳法/合并段意法/摘录中心句","怎么认":["分段：按时间、地点、情节转折把文章切成2-4块。","每段一句话：套'谁＋做了什么＋结果如何'，删掉修饰和细节。","合并同类项：把各段一句话连起来，删重复、留主干，字数压到题干要求内。"],"例句解析":[{"句":"概括《小巷深处》讲了一个什么故事？（限30字）","析":"走三步：分段——'我'被领养→长大后嫌弃养母→养母为'我'付出→'我'醒悟；每段一句话——'养女嫌弃养母'是主干；合并——'养女由嫌弃养母到理解感恩'（14字）。检查：要素齐（谁+转变+结果），30字内，确认。"}],"前置知识":["找中心句","三遍阅读法"]},{"name":"标题赏析","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">为什么以“灯”为题？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">①本义②深层③线索/主旨作用</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">《背影》</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">本义父亲的背影+深层父爱+线索</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">《春》</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">本义春天+深层对未来的希望+开篇点题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">标题是人名的</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">多以人物为线索</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">赞美人物</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：为什么以“灯”为题？","答：①本义（文章写的是什么）②深层（象征或寓意）③作用（线索、点题、中心）","标题可能是人名、物件、景物或情感，类型不同，角度不同","线索型标题：文中反复出现，串起材料","象征型标题：一语双关，看它与中心情感的关系","答题套路：本义加深层，再加结构作用"],"口诀":"本义深层两层皮，线索主旨不能离","讲解":"标题是文眼：概括情节、作线索、点明中心、象征义","怎么认":["先判标题类型：是线索（贯穿全文的物）、象征（一语双关）、悬念（设问反常），还是直白概括？","数它在文中出现几次：反复出现的标题多半是线索或象征。","量它与中心的距离：标题是'文眼'，赏析最后必须落到'点明中心/深化主旨'上。"],"例句解析":[{"句":"赏析标题《背影》。","析":"三步走：判类型，“背影”既写父亲的形象，又寄托父爱，兼具象征和线索的作用；数出现，文中多次写到背影，把全文串起来；量距离，背影凝聚父爱，标题点明“父子深情”的中心。答案：以“背影”为线索和象征，点明父子之情，含蓄感人。"}],"前置知识":["比喻","找中心句"]},{"name":"词句赏析","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">赏析“小草偷偷地钻出来”</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">①拟人手法②写出小草的生机与春天的气息③表达作者对春天的喜爱</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">\\\"月光如水\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">比喻+写月光皎洁+烘托宁静</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"他攥紧了拳头\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">动作描写+写紧张愤怒+为下文爆发铺垫</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">万能三步</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">手法→内容→情感</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">主旨</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：赏析“小草偷偷地钻出来”","答：①拟人手法②写出小草的生机与春天的气息③表达作者对春天的喜爱","\"月光如水\"：比喻+写月光皎洁+烘托宁静","\"他攥紧了拳头\"：动作描写+写紧张愤怒+为下文爆发铺垫","万能三步：手法→内容→情感","“主旨”：赏析的落脚点是文章的主旨，最后要回到主旨上","忌：只说\"用了比喻\"不分析（=没答）"],"口诀":"手法内容加主旨，三步走完是满分","易错":"只答手法不分析内容，或只谈内容不扣主旨","讲解":"万能三步：手法判定→内容解析→情感/主旨升华","怎么认":["先判定：是修辞（比喻/拟人/排比）还是锤炼过的动词/形容词？先给它'定性'。","再解内容：这个手法/这个词，把什么写成了什么样？（本体+喻体+特征）","最后升华：这个效果服务于什么情感或主旨？赏析不点主旨等于没答完。"],"例句解析":[{"句":"赏析'小草偷偷地从土里钻出来'。","析":"走万能三步：判定——'偷偷''钻'是拟人；解内容——把小草写成调皮的孩子，写出春草破土时的轻盈与生命力；升华——表达作者对春天的喜爱之情。检查：手法+内容+情感三件套齐了。"}],"前置知识":["比喻","拟人","语境意识"]},{"name":"结构作用","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">中间段落的作用？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">承上启下；内容上深化主题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">塑造形象</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">开头</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开篇点题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">设置悬念</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">埋伏笔</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：中间段落的作用？","答：承上启下；内容上深化主题","塑造形象","开头：开篇点题","设置悬念","埋伏笔","奠定感情基调","结尾：总结全文","升华主旨","首尾呼应","戛然而止留余味","中间：承上启下","插叙补背景","为下文铺垫","公式：结构（承上启下）+内容（写了什么）+主旨（对中心的作用）"],"口诀":"结构内容两分说","易错":"开头段还可能是设置悬念、埋伏笔","讲解":"开头：开篇点题/设置悬念；中间：承上启下；结尾：总结/升华/首尾呼应","怎么认":["先看位置：开头、中间、结尾，三种位置各有一套固定答法。","开头三选一：开篇点题/设置悬念/渲染气氛奠定基调；中间认准'承上启下'（过渡）；结尾三选一：总结全文/升华主旨/首尾呼应。","套'内容+结构+主旨'：先说这段写了什么，再说结构作用，最后点对主旨的贡献。"],"例句解析":[{"句":"'文章结尾写道：这就是我的母亲。'有什么作用？","析":"三步：看位置——结尾；选答法——结尾三选一中'总结全文+点明中心'最贴切；套三件套——内容上总结对母亲的回忆，结构上收束全文，主旨上点明'母爱伟大'的中心。答案：总结全文，点明中心，升华情感。"}],"前置知识":["三遍阅读法"]},{"name":"推断题","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">推断题</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">基于原文信息的适度推理，不夸大不缩小</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">先排除：凡是原文直接能找到原话的，那是信息题不是推断题，先划掉。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">找逻辑链：A→B→C，每一环都必须能在原文找到依据，链条断了就不能选。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">防'过度'：选项的说法比原文多出一层意思，一律不选。</text></g></svg>","例子":["三步：定位依据→适度推理→验证选项","依据必须在原文，不能靠常识脑补","排除\"原文原话\"项（那不是推断）","排除\"过度推断\"项（原文没给这么多）","排除\"逻辑矛盾\"项（与原文冲突）"],"口诀":"回到原文找依据，适度推理不臆断","易错":"排除“原文直接出现”（不是推断）、“过度推断”、“逻辑矛盾”项","讲解":"基于原文信息的适度推理，不夸大不缩小","怎么认":["先排除：凡是原文直接能找到原话的，那是信息题不是推断题，先划掉。","找逻辑链：A→B→C，每一环都必须能在原文找到依据，链条断了就不能选。","防'过度'：选项的说法比原文多出一层意思（'一定''必然''所有'），一律不选。"],"例句解析":[{"句":"原文：'他每天提前一小时到校，从不间断。'可推断出什么？A.他热爱学习 B.他家离学校很远 C.他一定是班长","析":"走三步：排除——三项原文都没直说；找逻辑链——'提前一小时+从不间断'→自律→A'热爱学习'有依据，B'家远'无依据（也可能是起得早）；防过度——C'一定是班长'超出信息量。答案：A。"}],"前置知识":["因果链","关键句定位"]},{"name":"开放探究","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">问</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">你认同作者的观点吗？为什么？</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">答</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">观点明确+文本支撑+联系实际</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">先亮观点，别绕弯子</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">理由必须引原文，不能空表态</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">联系实际举一例</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">言之成理即可，角度自选但要自圆其说</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["问：你认同作者的观点吗？为什么？","答：观点明确（我认为……）+文本支撑（引用原文）+联系实际","先亮观点，别绕弯子","理由必须引原文，不能空表态","联系实际举一例（生活/名人事例）","言之成理即可，角度自选但要自圆其说"],"口诀":"观点明确，文本支撑，联系实际","易错":"只表态不给理由，或理由脱离文本","讲解":"立场+论据（原文）+引申，言之成理即可","怎么认":["先亮观点：第一句就表明赞成/反对/辩证，不许模棱两可。","找依据：2个从原文找（引用原句），1个从生活或课外知识找，三足鼎立才站得稳。","控分寸：语言'有理有据有度'，不偏激、不跑题，结尾回扣原文。"],"例句解析":[{"句":"'你赞成文中主人公的做法吗？为什么？'","析":"三步走：亮观点——'我赞成'；找依据——原文'他把机会让给了更需要的人'（依据1）、'事后他说帮人就是帮己'（依据2），生活中'让座'现象类似（依据3）；控分寸——'这种利他行为值得提倡，但也要量力而行'，回扣原文。"}],"前置知识":["概括内容"]}],"name":"常考题型与答题公式"},{"id":"wenti","items":[{"name":"记叙文","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">六要素</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间地点人物，起因经过结果</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">线索</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">人物</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">事件</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">情感</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">物品</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">人称</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">第一人称亲切，第二人称抒情，第三人称客观</text></g></svg>","例子":["六要素：时间、地点、人物、起因、经过、结果","线索可以是人物、事件、情感或物品","人称：第一人称亲切，第二人称抒情，第三人称客观","顺序：顺叙、倒叙（设悬念）、插叙（补背景）","详略：详写与主旨相关的内容，略写次要内容","结尾常抒情议论，点明中心"],"口诀":"六要素加线索，记叙文不迷路","易错":"只抓事件、不抓线索和情感变化，会把文章结构看乱","讲解":"以叙事写人为核心，抓线索理思路","怎么认":["找六要素：时间、地点、人物、起因、经过、结果，先搭骨架。","抓线索：时间线/物件（如'一枚戒指'）/情感变化，看哪条线把材料穿起来。","品细节：细节描写（动作/神态/语言）都是为刻画人物、表达主旨服务的，赏析时点出来。"],"例句解析":[{"句":"判断文体并说出线索：《风筝》全文围绕'风筝'展开，写'我'由毁筝到愧悔。","析":"三步：六要素齐（儿时/故乡/'我'与弟弟/毁筝/愧悔），是记叙文；抓线索——'风筝'贯穿始终，是物件线索；品细节——'我'毁筝时的动作细节，刻画了年少无知，为后文愧悔做铺垫。"}],"前置知识":["三遍阅读法"]},{"name":"议论文","图示":"<svg viewBox=\"0 0 640 300\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">议论文</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">观点+材料+证明方法</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">找论点：看标题、开头、结尾，旗帜最鲜明、能'一句话概括全文'的就是论点。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">分论据：道理论据和事实论据，看作者摆了哪些'证据'。</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">怎么认</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">辨方法：举例论证/道理论证/对比论证/比喻论证，对号入座。</text></g></svg>","例子":["论点：中心论点常在标题、开头或结尾，是全文的观点","论据：事实论据（事例、数据）与道理论据（名言、道理）各有分工","论证方法：举例论证、道理论证、对比论证、比喻论证，看到举例就想到“用事实说话”","标志词：“总之”“由此可见”后面多是结论，别漏读","概括事实论据时只写要点，不照抄原文长段"],"口诀":"论点论据论证，三要素要分清","易错":"中心论点常在标题或开头结尾","讲解":"观点+材料+证明方法","怎么认":["找论点：看标题、开头、结尾，旗帜最鲜明、能'一句话概括全文'的就是论点。","分论据：道理论据（名言/原理/公理）和事实论据（事例/数据），看作者摆了哪些'证据'。","辨方法：举例论证/道理论证/对比论证/比喻论证，对号入座。"],"例句解析":[{"句":"分析《谈骨气》的论证思路。","析":"三步：找论点——开头'我们中国人是有骨气的'；分论据——文天祥/闻一多事例（事实论据）+'富贵不能淫'名言（道理论据）；辨方法——举例+道理+对比（三个事例层层递进）。思路：提出论点→举例证明→总结。"}],"前置知识":["举例论证","道理论证"]},{"name":"说明文","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">说明对象+说明方法</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">说明顺序</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">时间</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">空间</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">逻辑</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">语言</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">准确平实，\\\"大约\\\"\\\"可能\\\"表估计</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">下定义 vs 作诠释</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">前者严谨，后者通俗</text></g></svg>","例子":["说明对象：标题与首段第一句常直接点明","说明方法：举例子、列数字、打比方、作比较、下定义、作诠释","说明顺序：时间、空间、逻辑（总分、主次、由现象到本质）","语言特点：准确平实，“大约”“可能”表示估计，删掉就不准确","下定义严谨（“……是……”），作诠释通俗易懂"],"口诀":"对象方法加顺序","易错":"说明方法判断是高频考点","讲解":"介绍事物事理，语言准确平实","怎么认":["抓对象：标题+首段，第一句常直接点出说明对象。","理顺序：时间顺序（发展过程）、空间顺序（由外到内）、逻辑顺序（总分/主次）。","辨方法：下定义/举例子/列数字/打比方/作比较，看到'比如''例如''据统计'就圈出来。"],"例句解析":[{"句":"“这座桥全长约五十米，像一道彩虹横在河上。”这句用了哪些说明方法？","析":"三步：抓对象，句中的“桥”就是说明对象；辨方法，“约五十米”是列数字，“像一道彩虹”是打比方；看作用，数字让桥的长度具体，比喻让桥的样子形象。两种方法合用，说明既准确又生动。"}],"前置知识":["三遍阅读法"]},{"name":"散文","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">形散神聚</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">线索串材料</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">借景抒情、托物言志</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">线索</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">情感/游踪/物品</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">语言优美，善用修辞和意象</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">主旨含蓄</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">读出言外之意，别只看表面</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">托物言志</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">《爱莲说》以莲喻君子</text></g></svg>","例子":["形散神聚：线索串材料","借景抒情、托物言志","线索：情感/游踪/物品（《背影》以背影为线索）","语言优美，善用修辞和意象","主旨含蓄：读出言外之意，别只看表面","托物言志：《爱莲说》以莲喻君子"],"口诀":"线索串珠，情感是魂","易错":"散文主旨常含蓄，要读出言外之意","讲解":"抒情性强，意境优美","怎么认":["找'神'：形散神聚，先问'作者贯穿全文的情感/哲理是什么'，这就是'神'。","看意象：作者选了哪些物象（如'荷''月''柳'），每个意象寄托了什么情。","品语言：散文语言含蓄，慢读，圈出反复出现的词，那就是情感密码。"],"例句解析":[{"句":"《荷塘月色》中“荷”的意象寄托了什么？","析":"三步：找“神”，全文情绪淡雅、略带惆怅，这是贯穿全篇的内核；看意象，月下的荷叶与荷花清雅可人，可以理解为作者借它寄托对洁净、超脱之境的向往；品语言，作者用舞女的裙、明珠、星星等比喻写荷，画面清丽。注意：“出淤泥而不染”出自周敦颐《爱莲说》，不是《荷塘月色》的原文，答题时不能当作依据。"}],"前置知识":["比喻","记叙文"]}],"name":"文体辨识与策略"}],"module":"阅读理解方法技巧库","标准":"综合中考语文阅读题型与课标阅读要求整理","说明":"覆盖通用阅读方法、六大常考题型答题公式、四大文体策略，与语法库的修辞/句式知识联动"},"writing":{"categories":[{"id":"shenti","items":[{"name":"抓题眼","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">《那盏灯》</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“灯”是题眼，引申为希望</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">指引</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">《温暖》</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">“温暖”是情感核心</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">《第一次》</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"第一次\\\"是题眼，写人生初体验</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">《风景》</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">可实写自然风景，可虚写\\\"心灵风景\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">《礼物》</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"礼物\\\"可实物可抽象</text></g></svg>","例子":["《那盏灯》：“灯”是题眼，引申为希望","指引","《温暖》：“温暖”是情感核心","《第一次》：\"第一次\"是题眼，写人生初体验","《风景》：可实写自然风景，可虚写\"心灵风景\"","《礼物》：\"礼物\"可实物可抽象（教诲也是礼物）","方法：圈出题目中最能决定立意的词"],"口诀":"瞻前顾后一字不漏，题眼就是开门钥匙","易错":"跑题多因没审清题眼","讲解":"精细审题第一步：圈关键词，找准题目核心词（题眼）","怎么认":["圈关键词：把题目中最关键的1-2个词圈出来，多为动词或形容词（如'最美''那一刻'）。","问限制：这个词限制了什么？对象（写谁）、范围（哪件事）、情感（什么态度），三问定边界。","全程回扣：写每段前自查'这段扣题眼了吗'，结尾必须点题眼。"],"例句解析":[{"句":"题目《那一刻，我长大了》，题眼是什么？","析":"三步：圈关键词——'那一刻''长大了'；问限制——'那一刻'限制了时间（一个瞬间）、'长大了'限制了内容（成长感悟）；全程回扣——选材必须是一个瞬间的顿悟，结尾点'长大'。题眼：'那一刻'（时间）+'长大了'（成长）。"}],"前置知识":[]},{"name":"辨题型","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">命题作文</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">按题目写；材料作文：抓关键句立意</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">半命题</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">先补题再写</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">命题作文</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">题目即要求，一个字别改</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">半命题</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">《___，我的最爱》先补题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">材料作文</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">读懂材料倾向，别断章取义</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">话题作文</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">话题≠题目，自拟标题更出彩</text></g></svg>","例子":["命题作文：按题目写；材料作文：抓关键句立意","半命题：先补题再写","命题作文：题目即要求，一个字别改","半命题：《___，我的最爱》先补题（补具体事物）","材料作文：读懂材料倾向，别断章取义","话题作文：话题≠题目，自拟标题更出彩"],"口诀":"文题类型先分清，含义文体都要明","易错":"材料作文最忌断章取义、只抓局部","讲解":"注意文题类型、含义、文体类别、选材指向、立意信息","怎么认":["看形式：命题（一个字不能改）、半命题（先补题）、材料（先读懂材料）、话题（范围最宽）。","看文体要求：'文体不限'可写记叙/议论；'写一篇记叙文'必须记叙。","定开篇策略：命题开门见山点题；材料作文先概述材料再亮观点。"],"例句解析":[{"句":"题目《____，我的最爱》（半命题），如何下手？","析":"三步：看形式——半命题，先补题（如'读书，我的最爱'）；看文体——无限制，选最拿手的记叙；定开篇——补题后开门见山，'读书，是我的最爱'，直接点题。"}],"前置知识":["抓题眼"]},{"name":"审题六审","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一审文题类型，二审文题含义，三审题眼，四</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">审文体</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">让写记叙文就别写成议论文</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">审选材指向</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"校园生活\\\"就别写家庭琐事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">审立意信息</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">题目情感倾向</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">六审漏一审，跑题风险翻倍</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["一审文题类型，二审文题含义，三审题眼，四审文体，五审选材指向，六审立意信息","审文体：让写记叙文就别写成议论文","审选材指向：\"校园生活\"就别写家庭琐事","审立意信息：题目情感倾向（\"珍惜\"→正面）","六审漏一审，跑题风险翻倍"],"口诀":"类型含义题眼，文体选材立意","易错":"只看题目字面，忽略文体、人称和选材要求，是跑题的常见原因","讲解":"常见的审题步骤，可以拆成六个检查项","怎么认":["一审题眼：圈核心词；二审体裁：记叙/议论/不限；三审人称：第一/第三人称。","四审范围：时间/空间/对象限制；五审重点：题目侧重写什么；六审要求：字数、'不少于600字'等硬杠。","列清单：把六审结果写在草稿纸上，动笔前逐项打勾。"],"例句解析":[{"句":"用六审分析《我的初中生活》（600字以上，文体不限）。","析":"走六审：题眼'初中生活'；体裁不限→选记叙；人称第一人称'我'；范围锁定初中三年；重点在'生活'（事）而非'感想'；要求600字以上。清单列完，选材'军训''运动会'等，动笔。"}],"前置知识":["抓题眼","辨题型"]}],"name":"审题"},{"id":"liyi","items":[{"name":"立意三标准","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">正确</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">集中</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">深刻</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">正确</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">不能宣扬作弊、报复等负能量</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">集中</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">一篇只讲一个道理，贪多嚼不烂</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">深刻</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">从\\\"妈妈很辛苦\\\"挖到\\\"理解与感恩\\\"</text></g></svg>","例子":["正确（价值观端正）","集中（一个中心）","深刻（有思考）","正确：不能宣扬作弊、报复等负能量","集中：一篇只讲一个道理，贪多嚼不烂","深刻：从\"妈妈很辛苦\"挖到\"理解与感恩\""],"口诀":"中心是灵魂，正确集中深","易错":"立意贪多求全是大忌","讲解":"确立文章中心思想，犹如文章灵魂","怎么认":["先求正确：符合主流价值观，不偏激、不消极，正确是底线。","再求深刻：透过现象看本质，多问一个“为什么”。","最后求集中：一篇文章只讲一个道理，中心要单一。"],"例句解析":[{"句":"题目《感动》，三个立意：A.陌生人帮我指路 B.母亲深夜陪我复习 C.环卫工凌晨扫街，对比优劣。","析":"用三标准检验：A正确但浅；B正确、有真情实感，深刻度中等；C正确，且'平凡岗位的不平凡坚守'比B更深刻、新颖。排序：C＞B＞A。选C。"}],"前置知识":["审题六审"]},{"name":"立意八类","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">生命意义</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">生活感悟的滋味</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">自然景物</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">对周遭世界的感悟</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">情感体验</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">珍藏的人和事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">享受幸福</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">温暖与智慧的情节</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">成功成长</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">花季酸甜苦辣</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">道德修养</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">诚信</text></g></svg>","例子":["生命意义：从生活中体会人生的滋味","自然景物：从身边的草木风物中有所感悟","情感体验：珍藏的人与事","幸福生活：温暖与智慧的瞬间","成长奋进：酸甜苦辣里的进步","道德修养：诚信、勇敢、善良等品质","哲理品悟：从生活细节中提炼规律","告别珍藏：值得回味的过往"],"口诀":"生命自然情感，幸福成长道德，哲理告别","易错":"8类有交叉，按题目选最贴切的一类","讲解":"一种常见的立意分类，便于给素材归类。它不是考试标准，灵活使用即可","怎么认":["先熟悉八类：生命意义、自然景物、情感体验、幸福生活、成长奋进、道德修养、哲理品悟、告别珍藏。","审题时对号入座：题目往哪一类靠，就调用哪一类的素材。","一题多立：同一题目试着往两三类上靠，选最新颖、最深刻的那一类。"],"例句解析":[{"句":"题目《坚守》，如何选立意类别？","析":"三步：熟悉八类，“坚守”可往成长奋进（坚持下来的过程）或道德修养（守住的品质）靠；对号入座，“坚守”最贴近成长奋进；一题多立，还能写情感体验（为某人守候），但张力不如成长奋进。选成长奋进。"}],"前置知识":["立意三标准"]},{"name":"审题立意方法（材料作文）","图示":"<svg viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">抓关键句法、主旨倾向法、由果溯因法、求同</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">抓关键句</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">材料中的议论句多是\\\"题眼\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">由果溯因</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">从结果倒推原因找立意</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">求同存异</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">多则材料找共同点</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">辩证分析</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">看到\\\"失去\\\"也想到\\\"得到\\\"</text></g></svg>","例子":["抓关键句法、主旨倾向法、由果溯因法、求同分析法、辩证分析法","抓关键句：材料中的议论句多是\"题眼\"","由果溯因：从结果倒推原因找立意","求同存异：多则材料找共同点","辩证分析：看到\"失去\"也想到\"得到\""],"口诀":"全面分析抓关键，辩证因果多角度","易错":"过多纠缠局部细节会偏题","讲解":"高考常用：先整体把握材料，再抓关键词句作突破口，用辩证/因果/对比等思维多角度审视","怎么认":["整体把握：先读懂材料讲了一个什么事/什么理，不急于下结论。","抓关键词句：材料中反复出现、议论性强的句子，就是立意突破口。","多角度审视：用辩证（正反两面）、因果（为什么会这样）、对比（古今/中外）三种思维各想一遍，选最深的。"],"例句解析":[{"句":"材料：'小树问大树：为什么你长这么高？大树说：我把根扎得更深。'如何立意？","析":"三步：整体把握——讲根基与成长的关系；抓关键词——'根扎得更深'是突破口；多角度——因果思维：因为根深所以长高→立意'打好基础才能走得更远'；辩证思维：高与深、表与里的统一。定：'基础决定高度'。"}],"前置知识":["审题六审","立意三标准"]}],"name":"立意"},{"id":"xuancai","items":[{"name":"选材三原则","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">熟悉</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">动情</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">独特</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">熟悉</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">写亲身经历，细节才真实</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">动情</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">自己没感动，读者不会感动</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">独特</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">大家都写\\\"雨中送伞\\\"，你写\\\"雨后初晴\\\"就跳出来</text></g></svg>","例子":["熟悉（亲身经历）","动情（真体验真感受）","独特（与众不同）","熟悉：写亲身经历，细节才真实","动情：自己没感动，读者不会感动","独特：大家都写\"雨中送伞\"，你写\"雨后初晴\"就跳出来"],"口诀":"熟悉动情加独特，第一人称最稳妥","易错":"考场瞎编乱造易出纰漏","讲解":"选自己最熟悉、最动情的生活来写，用第一人称写亲身经历","怎么认":["选最熟悉的：写自己亲身经历的，细节才真实，编的故事一读就假。","选最动情的：自己写的时候有感觉（想哭/想笑），读者才会有感觉。","用第一人称：'我'的视角最有代入感，除非题目要求第三人称。"],"例句解析":[{"句":"题目《难忘的一件事》，三个备选：A.编的救火故事 B.奶奶教我包饺子 C.看过的电影情节。选哪个？","析":"用三原则检验：A是编的，细节必假，排除；C是别人的故事，无真情实感，排除；B亲身经历、最熟悉，包饺子时奶奶的手、面粉的香都记得，真情实感。选B。"}],"前置知识":["立意三标准"]},{"name":"素材积累","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">8个立意范畴各备1个典型题材</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">平时记录</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">春花秋月、校园草木、家庭琐事</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">每类备1个\\\"万能素材\\\"</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">建素材本</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">按\\\"人物</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">事件</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">金句\\\"分类记</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["每类准备一个“万能素材”，如“外婆的灶台”可套亲情、成长、乡愁","平时记录：校园里的草木、家庭琐事、一次感动","建素材本：按人物、事件、金句分类记录","从课文找：《背影》可以化用为父爱题材","从时事找：航天发射可以套奋斗、家国等立意","素材卡要写具体细节，只写结论没有用"],"口诀":"8类题材常备，观察生活常记","易错":"素材要服务立意，与主题无关的材料堆在一起，会显得生硬","讲解":"把8个立意范畴各准备一个生动题材，考场直接调用","怎么认":["建素材库：按立意类别（如亲情、成长、哲理）各准备1个最生动的题材，写成100字左右的小卡片。","一材多用：同一个素材，换角度能套不同题目（如“拼搏”的故事可以套坚守、团结）。","考场调用：审题定立意后，直接从素材库提取对应卡片，改头换面用。"],"例句解析":[{"句":"素材卡'母亲雨中送伞'，能套哪些题目？","析":"三步：建卡——亲情类素材卡'母亲雨中送伞（100字）'；一材多用——《感动》（母爱）、《那一刻我长大了》（懂事瞬间）、《爱》（亲情之爱）都能套；考场调用——题目《温暖》→提取此卡→开头'雨点砸在伞面上，也砸在我心里'，直接用。"}],"前置知识":[]},{"name":"细节描写","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">写人</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">外貌</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">动作</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">神态</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">语言</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">心理</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">写事</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">细节+环境描写</text></g></svg>","例子":["写人：外貌、动作、神态、语言、心理","写事：细节加环境描写","动作链：“抓起书包—冲出门—跳上车”（连续动词）","神态加心理：“他低头抠着衣角，心里像打翻了调料瓶”","环境烘托：“蝉鸣聒噪”衬托烦躁，“细雨如丝”衬托忧愁","忌：流水账，“然后……然后……”没有细节，就没有画面"],"口诀":"人物六描写，事件抓细节","易错":"没有细节的叙事是流水账","讲解":"细节是记叙文的生命，环境描写烘托气氛","怎么认":["找'特写镜头'：把最动人的瞬间定格，写动作/神态/语言（如'她的手在抖'胜过'她很激动'）。","用环境烘托：人物心情好写'阳光'，心情差写'阴雨'，环境是心情的外衣。","删空话：'非常''很''十分'删掉，换成具体可感的细节。"],"例句解析":[{"句":"把'妈妈很辛苦'升级为细节描写。","析":"三步：找特写——'妈妈鬓角的白发在灯下格外刺眼，她揉了揉发酸的腰'；环境烘托——'窗外夜已深，只有厨房的灯还亮着'；删空话——删掉'很辛苦'三字，辛苦已在细节里。升级完成。"}],"前置知识":["选材三原则"]}],"name":"选材"},{"id":"jiegou","items":[{"name":"总分总结构","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">开头点题→中间分述→结尾升华</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">记叙文可用1-3-1或1-4-1</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">开头</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开门见山点题，别绕三圈</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">中间</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">3-4个小片段</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">分论点，各成一段</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">结尾</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">回扣标题+升华</text></g></svg>","例子":["开头点题，亮出观点","中间分述：3-4个分论点，各成一段","结尾升华：回扣标题，抒情或议论","记叙文可用1-3-1或1-4-1结构（开头1段、中间3-4段、结尾1段）","开头：开门见山点题，别绕三圈","忌“大肚子”：中间一段写半页，头尾各两行"],"口诀":"总分总最稳，六七段最顺","易错":"忌“大肚子作文”（中间一段超长）/大头/大尾巴","讲解":"考场最保险的结构；六七百字配六七段，视觉协调","怎么认":["总起：开头1段，点题+亮观点（50字内）。","分述：中间4-5段，每段一个分论点/一个事例，段首句就是小标题。","总结：结尾1段，重申观点+升华，首尾呼应。六七百字配六七段。"],"例句解析":[{"句":"用总分总结构安排《论坚持》（议论文）。","析":"三步：总起——'坚持是成功的基石'（点题）；分述——分论点1'坚持需要目标'（事例：马拉松）、分论点2'坚持需要方法'（事例：庖丁解牛）、分论点3'坚持需要心态'（事例：爱迪生）；总结——'坚持到底，方见彩虹'，呼应开头。6段650字。"}],"前置知识":[]},{"name":"一线穿珠","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">以人物品质为主线，串起几个典型片段</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">如《我的老师》</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">线索可是物品</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">《背影》以\\\"背影\\\"串起四次相见</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">线索可是情感</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">从\\\"讨厌\\\"到\\\"理解\\\"母亲</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">线索可是时间</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">童年—少年—现在</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">每个\\\"珠子\\\"都要扣住这根线</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g></svg>","例子":["以人物品质为主线，串起几个典型片段，如《我的老师》","线索可以是物品：《背影》以“背影”贯穿全文","线索可以是情感：从“讨厌”到“理解”母亲","线索可以是时间：童年、少年、现在","每个“珠子”（片段）都要扣住这根线"],"口诀":"一线串珠不旁逸","易错":"片段各自为政、与线索无关，文章就散了","讲解":"无贯穿中心事件时，以人物活动/品质为主线组织材料","怎么认":["定主线：没有一个中心事件时，找一条线——人物（如'奶奶'）、物件（如'老照片'）、情感（如'愧疚'）。","选珍珠：围绕主线选3-4个材料，每个材料独立成段。","穿起来：开头点线，中间每段扣线，结尾收线，一线到底。"],"例句解析":[{"句":"用一线穿珠写《奶奶的味道》。","析":"三步：定主线——'奶奶做的饭菜香'为线；选珍珠——珍珠1'饺子香'（除夕）、珍珠2'粥香'（生病时）、珍珠3'粽子香'（端午）；穿起来——开头'奶奶的味道，是我记忆的线'，每段以香味过渡，结尾'线断了，香还在'。"}],"前置知识":["记叙文"]},{"name":"开头技巧","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一句话开头</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">直接交代时间地点人物事件</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">悬念开头</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">名句开头</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">排比开头</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">名句开头</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"长风破浪会有时\\\"→引出\\\"追梦\\\"主题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">排比开头</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"母爱是伞，父爱是山…\\\"→排比造势</text></g></svg>","例子":["一句话开头：直接交代时间、地点、人物、事件","悬念开头：用反常或疑问开篇，勾住读者","名句开头：引用诗词名句，引出主题，如“长风破浪会有时”","排比开头：用排比造势，如“母爱是伞，父爱是山”","忌：开头超过5行还不见主题"],"口诀":"开头不过5行，开门见山最行","易错":"开头玩技巧过长会喧宾夺主","讲解":"开篇两三句点出记叙要点或明确主题，简洁洗练","怎么认":["开门见山：第一句就点题（如'那是我最难忘的一天'），不绕弯子。","设悬念：用反常/疑问开篇（如'谁也没想到，那场雨改变了我'），勾住读者。","控字数：开头两三句、50字内必须入题，考场不许'千呼万唤始出来'。"],"例句解析":[{"句":"为《第一次坐过山车》写两种开头并点评。","析":"三步：开门见山版——'第一次坐过山车，我差点哭出来。'（点题快）；设悬念版——'如果再给我一次机会，我绝不上那辆车。'（勾人）；控字数——两版都在30字内入题。考场推荐悬念版，更抓人。"}],"前置知识":[]},{"name":"结尾技巧","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">抒情结尾</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">升华情感</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">议论结尾</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">点明哲理、照应标题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">首尾呼应</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开头\\\"灯\\\"，结尾\\\"这盏灯，至今照着我\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">名句收束</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"会当凌绝顶\\\"→升华\\\"进取\\\"主题</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">戛然而止</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">故事停在高潮，余味悠长</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">结尾另起新话题</text></g></svg>","例子":["抒情结尾：升华情感","议论结尾：点明哲理、照应标题","首尾呼应：开头\"灯\"，结尾\"这盏灯，至今照着我\"","名句收束：\"会当凌绝顶\"→升华\"进取\"主题","戛然而止：故事停在高潮，余味悠长","忌：结尾另起新话题（跑题前兆）"],"口诀":"结尾抒情或议论，照应标题点中心","易错":"结尾忌另起新话题","讲解":"记叙文结尾抒情+哲理，议论文结尾重申论点","怎么认":["记叙文：抒情+哲理（如'那一刻我明白，成长就是学会承担'），忌喊口号。","议论文：重申论点+升华（如'让坚持成为习惯，成功自会敲门'）。","首尾呼应：结尾的关键词与开头呼应，形成闭环。"],"例句解析":[{"句":"为《那一刻，我长大了》写结尾（开头：'雨下得很大，我站在校门口不知所措。'）。","析":"三步：记叙文用抒情+哲理——'雨还在下，但我心里已放晴。原来，长大就是在无人撑伞时，学会为自己撑伞。'；首尾呼应——'雨'呼应开头，'撑伞'升华；检查：无口号，有哲理。"}],"前置知识":["开头技巧"]}],"name":"结构"},{"id":"yuyan","items":[{"name":"短句为主","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一个句子主谓宾定状补齐了，就用句号</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌一逗到底</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">长句拆短</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"他跑进教室放下书包拿出课本\\\"→\\\"他跑进教室。放下书包，拿出课本。\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">短句有节奏感</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">适合写紧张场面</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">一逗到底最易犯语病</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">长短结合</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">叙事用短句，抒情可偶用长句</text></g></svg>","例子":["一个句子主谓宾定状补齐了，就用句号","忌一逗到底","长句拆短：\"他跑进教室放下书包拿出课本\"→\"他跑进教室。放下书包，拿出课本。\"","短句有节奏感：适合写紧张场面","一逗到底最易犯语病（成分残缺/搭配不当）","长短结合：叙事用短句，抒情可偶用长句"],"口诀":"短句有力，长句易病","易错":"长句最易犯语病（呼应语法库病句）","讲解":"句子短促有力，节奏好且不易出错","怎么认":["一切两行：凡是超过两行的长句，拆成两个短句。","多用句号：'。'越多，节奏越明快，也越不容易病句。","长短结合：三五个短句后，来一个长句收束，有节奏感。"],"例句解析":[{"句":"把长句'因为当时天已经很晚了而且还下着很大的雨所以我就决定还是先在同学家住一晚明天再回去'改短。","析":"三步：切两行——'天很晚了。雨很大。我决定在同学家住一晚。'；多用句号——4个句号，节奏明快；长短结合——'明天再回去。'收束。改后无病句，节奏好。"}],"前置知识":["主语","谓语"]},{"name":"修辞点缀","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">比喻拟人排比设问，点缀2-3处即可</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">比喻</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"父爱如山\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">排比</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">开头</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">结尾各一组，气势立现</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\"></text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">设问自答</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"什么是勇敢？勇敢是…\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">忌</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">为修辞而修辞，堆砌成\\\"油腻文\\\"</text></g></svg>","例子":["比喻拟人排比设问，点缀2-3处即可","比喻：\"父爱如山\"（2-3处，多了就腻）","排比：开头","结尾各一组，气势立现","设问自答：\"什么是勇敢？勇敢是…\"","忌：为修辞而修辞，堆砌成\"油腻文\""],"口诀":"修辞2-3处，语言即出彩","易错":"堆砌修辞会油腻","讲解":"呼应语法库8种修辞，恰当使用让语言出彩","怎么认":["每段一修辞：记叙文每段至少用一个比喻/拟人/排比，不许'白开水'。","点到为止：修辞是'点缀'不是'堆砌'，一处用好胜过三处用滥。","呼应语法库：比喻/拟人/夸张/排比/对偶/反复/设问/反问，8种轮着用。"],"例句解析":[{"句":"给'天上的星星很多'加修辞点缀。","析":"三步：每段一修辞——用比喻：'天上的星星，像撒在黑布上的碎钻'；点到为止——一句即可，不再加排比；呼应语法库——这是'比喻'，本体星星、喻体碎钻。点缀完成。"}],"前置知识":["比喻","拟人","排比"]},{"name":"描写升级","图示":"<svg viewBox=\"0 0 640 420\" xmlns=\"http://www.w3.org/2000/svg\" style=\"max-width:100%\"><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"0.5s\" fill=\"freeze\"/><rect x=\"20\" y=\"15\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"35\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">动作描写</text><text x=\"40\" y=\"58\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">连续动词</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.2s\" fill=\"freeze\"/><rect x=\"20\" y=\"75\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"95\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">语言描写</text><text x=\"40\" y=\"118\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">神态+潜台词</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"1.9s\" fill=\"freeze\"/><rect x=\"20\" y=\"135\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b8892e22\" stroke=\"#b8892e\" stroke-width=\"1\"/><text x=\"40\" y=\"155\" text-anchor=\"start\" font-size=\"14\" fill=\"#b8892e\" font-weight=\"bold\">环境描写</text><text x=\"40\" y=\"178\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">烘托人物心情</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"2.5999999999999996s\" fill=\"freeze\"/><rect x=\"20\" y=\"195\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#b85a5222\" stroke=\"#b85a52\" stroke-width=\"1\"/><text x=\"40\" y=\"215\" text-anchor=\"start\" font-size=\"14\" fill=\"#b85a52\" font-weight=\"bold\">\\\"讲故事\\\"变\\\"演故事\\\"</text><text x=\"40\" y=\"238\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">别说\\\"他很生气\\\"，写\\\"他攥紧拳头，指节发白\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"3.3s\" fill=\"freeze\"/><rect x=\"20\" y=\"255\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a5922\" stroke=\"#4a7a59\" stroke-width=\"1\"/><text x=\"40\" y=\"275\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a59\" font-weight=\"bold\">五感调动</text><text x=\"40\" y=\"298\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">写雨不只写\\\"大\\\"，写\\\"砸在伞上的脆响\\\"</text></g><g opacity=\"0\"><animate attributeName=\"opacity\" values=\"0;1\" dur=\"0.3s\" begin=\"4s\" fill=\"freeze\"/><rect x=\"20\" y=\"315\" width=\"600\" height=\"50\" rx=\"8\" fill=\"#4a7a8c22\" stroke=\"#4a7a8c\" stroke-width=\"1\"/><text x=\"40\" y=\"335\" text-anchor=\"start\" font-size=\"14\" fill=\"#4a7a8c\" font-weight=\"bold\">动静结合</text><text x=\"40\" y=\"358\" text-anchor=\"start\" font-size=\"13\" fill=\"#2c3328\">\\\"蝉鸣\\\"动+\\\"树影\\\"静</text></g></svg>","例子":["动作描写：连续动词","语言描写：神态+潜台词","环境描写：烘托人物心情","\"讲故事\"变\"演故事\"：别说\"他很生气\"，写\"他攥紧拳头，指节发白\"","五感调动：写雨不只写\"大\"，写\"砸在伞上的脆响\"","动静结合：\"蝉鸣\"动+\"树影\"静","忌：通篇叙述无描写=嚼蜡"],"口诀":"写人要有动作语言，写事要有细节环境","易错":"描写要服务于人物和主题，堆满形容词会显得拖沓","讲解":"描写是把“讲故事”变成“演故事”的关键","怎么认":["五感全开：视觉+听觉+嗅觉+味觉+触觉，能调动几种调动几种。","动静结合：静态描写（'湖面如镜'）+动态描写（'鱼跃起'），有动有静。","删'讲'留'演'：'他很生气'是讲，'他一拳砸在桌上，茶杯跳了起来'是演，删讲留演。"],"例句解析":[{"句":"把'公园很美'升级为描写。","析":"三步：五感全开——'桂花香飘过来（嗅觉），鸟叫声此起彼伏（听觉），湖面闪着碎金（视觉）'；动静结合——'柳枝垂着不动（静），一只蜻蜓点水而过（动）'；删讲留演——删掉'很美'二字，美已在描写里。升级完成。"}],"前置知识":["细节描写","修辞点缀"]}],"name":"语言"}],"module":"写作技巧库","标准":"综合中高考作文指导（审题/立意/选材/结构/语言）与课标写作要求整理","说明":"覆盖考场作文全流程：审题→立意→选材→结构→语言，与语法库（病句/修辞/句式）联动"}};
